t.guides["forever/alliance/02-westfall"] = (function() return {
		["Back north past {area:918} to the mine: Kobold Diggers work inside."] = "Volte ao norte, passando por {area:918}, até a mina: Escavadores Kobold trabalham lá dentro.",
		["Back to {area:108}"] = "De volta a {area:108}",
		["Defias Pathstalkers and Knuckledusters walk {area:20}; Highwaymen (level 17) patrol the hills south and east of it in pairs: pull them apart. {area:1581} entrance in the smithy is a group dungeon."] = "Tocaiantes e Rufiões Défias andam por {area:20}; Bandoleiros (nível 17) patrulham em duplas as colinas ao sul e a leste: puxe-os separados. A entrada de {area:1581}, na ferraria, é uma masmorra de grupo.",
		["Defias Pillagers and Looters hold the farms west of {area:108}, between the coast road and {area:20}."] = "Pilhadores e Gatunos Défias ocupam as fazendas a oeste de {area:108}, entre a estrada do litoral e {area:20}.",
		["Fill the vial at the farm's well"] = "Encha o frasco no poço da fazenda",
		["Fill the vial at the well"] = "Encha o frasco no poço",
		["Fly or ride to {zone:1453}. Trainers: {object:2100} (Warriors, Rogues), the Cathedral (Paladins, Priests), the {object:2101} (Mages, Warlocks), the Park (Druids)."] = "Voe ou cavalgue até {zone:1453}. Instrutores: {object:2100} (guerreiros, ladinos), a Catedral da Luz (paladinos, sacerdotes), {object:2101} (magos, bruxos), o Parque (druidas).",
		["Fly or ride to {zone:1453}. {npc:376} is in the Cathedral of Light."] = "Voe ou cavalgue até {zone:1453}. {npc:376} está na Catedral da Luz.",
		["Fly or ride to {zone:1453}. {npc:5480} trains warriors in {object:2100}; {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug."] = "Voe ou cavalgue até {zone:1453}. {npc:5480} treina guerreiros em {object:2100}; {npc:6089} e {npc:6090} ficam juntos perto de {object:2152}, ali. {npc:6090} luta com você pela caneca dele.",
		["Follow the road north. {npc:233} stands outside, {npc:235} in the house, {npc:253395} in the barn to the west."] = "Siga a estrada para o norte. {npc:233} fica do lado de fora, {npc:235} dentro da casa e {npc:253395} no celeiro a oeste.",
		["For {npc:11026} in {zone:1453}'s {object:28027}"] = "Para {npc:11026} em {object:28027}, {zone:1453}",
		["For {npc:266} in {area:69}, Redridge"] = "Para {npc:266} em {area:69}, Montanhas Cristarrubra",
		["Further north along the road. The Furlbrows sit by their burned farm. Collect the oats from the Sacks of Oats in the fields as you go."] = "Mais ao norte pela estrada. Os Taturana estão sentados junto à fazenda incendiada. No caminho, colete a aveia dos Sacos de Aveia nos campos.",
		["Gnoll Paws"] = "Patas de Gnoll",
		["Harvest Watchers"] = "Guarda-colheitas",
		["Hearthstone on cooldown? Follow the road north-east."] = "Pedra de Regresso em recarga? Siga a estrada para o nordeste.",
		["Kobold Diggers"] = "Escavadores Kobold",
		["Level 12, 14 and 16 spells"] = "Feitiços de nível 12, 14 e 16",
		["Longshore Murloc Gills"] = "Barbatanas de Murloc da Praia Grande",
		["Murloc Coastrunners and Raiders line the beach north of the mine. They flee at low health: pull one at a time."] = "Murlocs Correcosta e Murlocs Saqueadores ocupam a praia ao norte da mina. Eles fogem com pouca vida: puxe um de cada vez.",
		["North of Molsen Farm. Defias Trappers and Smugglers camp outside the mine. {object:290} stands by the ruined house east of the mine."] = "Ao norte da Fazenda dos Peçanha. Coureadores e Contrabandistas Défias acampam do lado de fora da mina. {object:290} fica junto à casa em ruínas a leste da mina.",
		["Only if you looted a {item:1972} in Elwynn: right-click it"] = "Só se você saqueou uma {item:1972} na Floresta de Elwynn: clique nela com o botão direito",
		["Ride to {zone:1453}. It has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back for the boat."] = "Cavalgue até {zone:1453}. Lá não há instrutor de xamãs: pegue o {area:2257} em {object:28027} até {zone:1455}, treine com {npc:258098} e volte de metrô para pegar o barco.",
		["Riverpaw Gnolls and Scouts roam the hills between the coast and the {area:916}."] = "Gnolls e Batedores Pata Molhada vagam pelas colinas entre o litoral e o {area:916}.",
		["Riverpaw Miners"] = "Mineradores Pata Molhada",
		["Sacks of Oats"] = "Sacos de Aveia",
		["Shaman training"] = "Treinamento de xamã",
		["South-west to the coast, west of {area:918}. Riverpaw Miners work the quarry."] = "Para sudoeste, até o litoral, a oeste de {area:918}. Mineradores Pata Molhada trabalham na pedreira.",
		["The gnoll hills"] = "As colinas dos gnolls",
		["The north coast"] = "O litoral norte",
		["The western farms"] = "As fazendas do oeste",
		["The {area:113}"] = "{area:113}",
		["West of Saldean's. Harvest Watchers and Golems work the fields; they drop the isosprings, gyrostabilizers, {item:732} and sometimes a {item:255155}. {npc:573}, a level 20 rare, walks here: leave it alone. Keep killing Goretusks and Fleshrippers on every leg of this loop."] = "A oeste da fazenda Saldanha. Guarda-colheitas e Golens Colheiteiros trabalham nos campos; eles soltam as isomolas, os giroestabilizadores, {item:732} e às vezes um {item:255155}. {npc:573}, um raro de nível 20, anda por aqui: deixe-o em paz. Continue matando Goretuscos e Ripa-carnes em cada trecho deste circuito.",
		["Young Goretusks and Fleshrippers roam the fields around the farm: start on livers and the stew's meat on the way back."] = "Goretuscos Jovens e Ripa-carnes vagam pelos campos ao redor da fazenda: comece a juntar fígados e a carne do ensopado na volta.",
		["{area:20} and the Defias hills"] = "{area:20} e as colinas Défias",
		["{item:2449} for Gathering the Cure (6123) in {zone:1439}: {npc:1313}, Alchemy Supplies; herbalists pick it there instead"] = "{item:2449} para Colhendo a cura (6123) em {zone:1439}: {npc:1313}, Suprimentos de Alquimia; herbalistas a colhem lá mesmo",
		["{item:254676}, from the crates around {area:20}"] = "{item:254676}, dos caixotes ao redor de {area:20}",
		["{item:6529}, from {npc:5494}"] = "{item:6529}, de {npc:5494}",
		["{item:729}: Fleshrippers"] = "{item:729}: Ripa-carnes",
		["{npc:234} and {npc:821} stand at the top of the stone tower. {npc:491} is in the tower, {npc:878} on the south side of the hill, next to the inn and {npc:523} the gryphon master."] = "{npc:234} e {npc:821} ficam no alto da torre de pedra. {npc:491} está na torre; {npc:878}, no lado sul do morro, junto à estalagem e a {npc:523}, o mestre de grifos.",
		["{npc:253092}, beside {npc:878}"] = "{npc:253092}, ao lado de {npc:878}",
		["{npc:523}; skip the free flight it offers"] = "{npc:523}; pule o voo grátis que ele oferece",
		["{npc:5494} sells fishing supplies along the canal just west of the {object:2096}; {npc:267118} fishes at the harbor, on the way to the boat."] = "{npc:5494} vende suprimentos de pesca junto ao canal, logo a oeste de {object:2096}; {npc:267118} pesca no porto, a caminho do barco.",
		["{npc:5497}, Wizard's Sanctum: {quest:1861}"] = "{npc:5497}, no Sacrário dos Teurgos: {quest:1861}",
		["{quest:153}: every Defias drops them"] = "{quest:153}: todos os Défias as soltam",
} end)()
t.guides["forever/alliance/03-darkshore"] = (function() return {
		["At the {area:2362}"] = "Em {area:2362}",
		["Back north-east into the mountains to the crystal."] = "Volte para nordeste, pelas montanhas, até o cristal.",
		["Back south"] = "De volta ao sul",
		["Back to {npc:11802}"] = "De volta a {npc:11802}",
		["Back to {npc:11802} in {area:2361}, then fly to {area:702} (by way of {area:442})."] = "Volte a {npc:11802} em {area:2361} e depois voe para {area:702} (passando por {area:442}).",
		["Bears and the Blackwood camp"] = "Ursos e o acampamento Bosquenero",
		["Blackwood Pathfinders and Windtalkers hold the camp south-east of {area:442}."] = "Desbravadores Bosqueneros e Vozes-do-vento Bosqueneros ocupam o acampamento a sudeste de {area:442}.",
		["Blackwood furbolgs"] = "Furbolgs Bosqueneros",
		["Boat to {zone:1453}"] = "Barco para {zone:1453}",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}. Shrine Baubles lie in the containers on the floor of {area:656}, below {area:2361}: take one to the {area:2362} in the north-west, use it there and speak to {npc:11799}. Then fly back to {area:442} from {area:2361}."] = "Lance {spell:18960}. {npc:11802} está em {area:2361}. Adornos de Altar ficam nos recipientes no fundo de {area:656}, abaixo de {area:2361}: leve um até {area:2362} a noroeste, use-o lá e fale com {npc:11799}. Depois voe de volta para {area:442} a partir de {area:2361}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; learn the flight path there if you do not have it."] = "Lance {spell:18960}. {npc:11802} está em {area:2361}; aprenda a rota de voo de lá se ainda não a tiver.",
		["Climb the eastern mountains east of {area:447}; the {object:175524} sits on a ledge."] = "Suba as montanhas a leste de {area:447}; o {object:175524} fica numa saliência.",
		["Crawler Legs"] = "Patas de Rastejante",
		["Escort her out of the glaive; Therysil takes the turn-in in {zone:1440}"] = "Escolte-a para fora da glaive; Therysil recebe a entrega em {zone:1440}",
		["Fill the tube at the moonwell in the village"] = "Encha o tubo no poço lunar do vilarejo",
		["Fine Moonstalker Pelts"] = "Pelagens de Espreitaluna Finas",
		["Fly from {area:442} to {area:702} and take the portal up to {npc:4217} in the {area:1658}."] = "Voe de {area:442} para {area:702} e pegue o portal para subir até {npc:4217} em {area:1658}.",
		["Follow the coast north-east to the {area:443}. {quest:951} lie among the ruins; Stormscale Myrmidons, Sorceresses and Warriors hold them, and Stormscale Beastmistresses walk the shore."] = "Siga a costa para nordeste até {area:443}. {quest:951} estão entre as ruínas; Mirmidões Skamatrom, Feiticeiras Skamatrom e Guerreiros Skamatrom as ocupam, e Senhoras das Feras Skamatrom andam pela costa.",
		["Follow the coast south past {area:447}: one {quest:4728} lies on the shore west of the Grove, another further south near {area:450}. Three more remains lie further south-west among Greymist Oracles and Tidehunters (18-20): the guide leaves them for the last loop, when you are closer to their level."] = "Siga a costa para o sul passando por {area:447}: uma {quest:4728} está na costa a oeste do Bosque, outra mais ao sul perto de {area:450}. Mais três restos estão mais a sudoeste, entre Oráculos e Caçamarés Brumagris (18-20): o guia os deixa para a última volta, quando você estiver mais perto do nível deles.",
		["Follow the hills north to the {area:456} and up to the falls. Two more beached remains lie on the north shore: near the {area:443} and north of {quest:954}."] = "Siga as colinas para o norte até {area:456} e suba até as cachoeiras. Mais dois restos encalhados estão na costa norte: perto de {area:443} e ao norte de {quest:954}.",
		["Follow the road north."] = "Siga a estrada para o norte.",
		["Follow the road south. {quest:948} is the ancient at the Grove; {npc:270269} and {npc:11218} sleep beside him."] = "Siga a estrada para o sul. {quest:948} é o anciente do Bosque; {npc:270269} e {npc:11218} dormem ao lado dele.",
		["Grell Earrings"] = "Brincos de Capeta",
		["Grizzled Scalps"] = "Escalpos Grisalhos",
		["Grizzled Thistle Bears roam the hills around the Grove; {quest:1003} stands west of it among them."] = "Ursocardos Grisalhos vagam pelas colinas ao redor do Bosque; {quest:1003} fica a oeste dele, no meio deles.",
		["Hearth to {area:442}"] = "Pedra de Regresso para {area:442}",
		["Hearthstone on cooldown? Follow the coast road back south."] = "Pedra de Regresso em recarga? Volte para o sul pela estrada costeira.",
		["Highborne Relics"] = "Relíquias dos Altaneiros",
		["Kill Rabid Thistle Bears in the hills east of {area:442}, then walk up to the furbolg camp south-east of them: nothing to kill yet."] = "Mate Ursocardos Raivosos nas colinas a leste de {area:442} e depois suba até o acampamento furbolg a sudeste deles: nada para matar ainda.",
		["Moonstalker Fangs"] = "Presas de Espreitaluna",
		["Moonstalker Sires prowl the woods around the glaive. The {object:10076} and the {object:12666} sit at the bottom of the crater; {npc:3584} stands on its north side."] = "Espreitalunas Machos rondam a mata ao redor da glaive. {object:10076} e {object:12666} ficam no fundo da cratera; {npc:3584} fica no lado norte.",
		["Moonstalkers prowl the hills between {quest:954} and the tower. {quest:1002} stands on the hill west of the tower."] = "Espreitalunas rondam as colinas entre {quest:954} e a torre. {quest:1002} fica na colina a oeste da torre.",
		["Night Elves fly from {area:442} to {area:702}; Skyborne take the boat from the {area:442} dock and learn the Rut'theran flight path there. Take the portal up to {npc:4217} in the {area:1658}."] = "Elfos Noturnos voam de {area:442} para {area:702}; Celonatos pegam o barco na doca de {area:442} e aprendem lá a rota de voo. Pegue o portal para subir até {npc:4217} em {area:1658}.",
		["North along the hills. {npc:3650} waits in the ruins of {quest:954}; Wild Grells and Vile Sprites fill them, Deth'ryll Satyrs the eastern edge. {quest:1001} stands by the road west of the ruins; a {quest:4723} lies on the shore on the way to him."] = "Siga as colinas para o norte. {npc:3650} espera nas ruínas de {quest:954}; Capetas Selvagens e Duendes Torpes as enchem, e Sátiros Deth'ryll a borda leste. {quest:1001} fica junto à estrada a oeste das ruínas; uma {quest:4723} está na costa no caminho até ele.",
		["Only if a Disciple or Thug dropped {item:5352}: right-click it"] = "Só se um Discipulo ou Capanga tiver deixado cair {item:5352}: clique com o botão direito nele",
		["Plagued bears"] = "Ursos empestados",
		["Rabid Thistle Bears roam the hills just east of {area:442}. Use {quest:2139} on one and lead it back to him."] = "Ursocardos Raivosos vagam pelas colinas logo a leste de {area:442}. Use {quest:2139} em um e leve-o de volta até ele.",
		["Read the {object:17188}"] = "Leia {object:17188}",
		["Read the {object:17189}"] = "Leia {object:17189}",
		["Scaber Stalks"] = "Galhos de Piolho",
		["She gives you the {item:15826}"] = "Ela lhe dá o {item:15826}",
		["Take the portal up to {npc:4217}, then fly back to {area:442} for the boat to {zone:1453}."] = "Pegue o portal para subir até {npc:4217} e depois voe de volta para {area:442} para o barco para {zone:1453}.",
		["The Lunar Fungal Blooms grow in the moonkin caves in the hills just east of {area:442}; the moonkin there are irritable. {item:2449} needs {skill:182}: herbalists pick it all over {zone:1439}, anyone else brings it from {zone:1453} ({npc:1313}) or the Auction House."] = "Os Brotos Fúngicos Lunares crescem nas cavernas dos luniscantes nas colinas logo a leste de {area:442}; os luniscantes de lá são irritadiços. {item:2449} exige {skill:182}: herbalistas o colhem por toda {zone:1439}, os demais o trazem de {zone:1453} ({npc:1313}) ou da casa de leilões.",
		["The WANTED poster"] = "O cartaz de PROCURA-SE",
		["The WANTED poster outside the inn"] = "O cartaz de PROCURA-SE em frente à estalagem",
		["The bay wrecks"] = "Os naufrágios da baía",
		["The beach"] = "A praia",
		["The boat docks west of the village. The flight master stands on the hill south of the inn; the quest givers are spread along the main street."] = "O barco atraca a oeste do vilarejo. O mestre de voo fica na colina ao sul da estalagem; os recrutadores de missões estão espalhados pela rua principal.",
		["The cave and the {npc:6788}"] = "A caverna e a {npc:6788}",
		["The cave lies south of the falls: Scaber Stalks grow all through it, the {item:5270} at the very back. The {npc:6788} lairs in the hills south of the falls; {object:177624} lies at the satyr camp north of her."] = "A caverna fica ao sul das cachoeiras: Galhos de Piolho crescem por toda ela, e o {item:5270} bem no fundo. A {npc:6788} se entoca nas colinas ao sul das cachoeiras; {object:177624} está no acampamento de sátiros ao norte dela.",
		["The flame burns in the south of {area:447}."] = "A chama arde no sul de {area:447}.",
		["The half pendants lie in {zone:1439} and {zone:1436}: later on the route"] = "As metades do pingente ficam em {zone:1439} e {zone:1436}: mais adiante na rota",
		["The naga"] = "Os nagas",
		["The red crystal"] = "O cristal vermelho",
		["The relics of the Barrow Dens"] = "As relíquias dos Templos de Tempesfúria",
		["The skeletal turtle"] = "A tartaruga esquelética",
		["The southern beaches"] = "As praias do sul",
		["The {area:443}"] = "{area:443}",
		["The {area:448}"] = "{area:448}",
		["The {object:10076}"] = "{object:10076}",
		["The {object:12666}"] = "{object:12666}",
		["The {object:16393}"] = "{object:16393}",
		["Thresher Eyes"] = "Olhos de Mangual",
		["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "Maretiscos correm pela costa abaixo do vilarejo; {quest:983} fica na praia logo ao sul das docas. Manguais da Costa Negra nadam nas águas rasas. A {object:175207} está na costa logo ao sul do vilarejo.",
		["Two wrecks lie on the sea floor in the bay north of {area:442}; each holds a lockbox. Reef Crawlers and Encrusted Tide Crawlers line this shore."] = "Dois naufrágios estão no fundo do mar na baía ao norte de {area:442}; cada um guarda um cofre. Tiscorais e Maretiscos Incrustados ocupam esta costa.",
		["{area:450} lies on the coast south of {npc:10323}'s beach. Protect the prospector while he searches for the fossil."] = "{area:450} fica na costa ao sul da praia de {npc:10323}. Proteja o garimpeiro enquanto ele procura o fóssil.",
		["{item:12238}: fish from the pier"] = "{item:12238}: pesque no píer",
		["{item:12289}, on the beach west of the docks"] = "{item:12289}, na praia a oeste das docas",
		["{item:12349}, at the waterfall"] = "{item:12349}, na cachoeira",
		["{item:12355}, in {object:177624}"] = "{item:12355}, em {object:177624}",
		["{item:15845}: at the mouth of the cave by the falls"] = "{item:15845}: na entrada da caverna junto às cachoeiras",
		["{item:15851} and {item:2449}"] = "{item:15851} e {item:2449}",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}, de um {object:177785} no lago",
		["{item:15883}: the {object:177792} under the water off the north coast, west of the ruins"] = "{item:15883}: o {object:177792} debaixo d'água na costa norte, a oeste das ruínas",
		["{item:279279}: Twilight Disciples and Thugs"] = "{item:279279}: Discipulos do Crepúsculo e Capangas do Crepúsculo",
		["{item:5338}: Deth'ryll Satyrs"] = "{item:5338}: Sátiros Deth'ryll",
		["{item:5348}: Dark Strand Fanatics"] = "{item:5348}: Fanáticos da Linhagem das Trevas",
		["{npc:10216}, on the pier: only with {skill:356}"] = "{npc:10216}, no píer: só com {skill:356}",
		["{npc:10323} camps on the beach west of the glaive: kill the murlocs at the camp fire; he comes in the third wave with his hound. Three beached remains lie on the beaches west and south-west of {area:450}."] = "{npc:10323} acampa na praia a oeste da glaive: mate os murlocs na fogueira; ele vem na terceira onda com seu cão. Três restos encalhados estão nas praias a oeste e a sudoeste de {area:450}.",
		["{npc:10323}'s beach"] = "A praia de {npc:10323}",
		["{npc:11218}: his escort to {area:413} is done on the {zone:1440} leg"] = "{npc:11218}: a escolta dele até {area:413} é feita no trecho de {zone:1440}",
		["{npc:11802}: the welcome from Sheldras"] = "{npc:11802}: as boas-vindas de Sheldras Lunárvore",
		["{npc:12298}: use the {item:15826} on them; they roam all of {zone:1439}"] = "{npc:12298}: use o {item:15826} neles; vagam por toda {zone:1439}",
		["{npc:3616}, at the Grove"] = "{npc:3616}, no Bosque",
		["{npc:3639} stands at the north edge of the ruins. Cursed, Writhing and {npc:2178} haunt them; {npc:3667}'s ghost walks among them, {npc:270196} the owl circles east of them. The two tablets lie in the ruins; a {quest:4722} lies on the shore west of them."] = "{npc:3639} fica na borda norte das ruínas. Altaneiras Amaldiçoadas, Altaneiros Contorcidos e {npc:2178} assombram o lugar; o fantasma de {npc:3667} caminha entre eles, e a coruja {npc:270196} circula a leste. As duas tábuas estão nas ruínas; uma {quest:4722} está na costa a oeste delas.",
		["{npc:3644}, on the pier"] = "{npc:3644}, no píer",
		["{npc:3649}, north end of the village"] = "{npc:3649}, no extremo norte do vilarejo",
		["{npc:3649}: for {npc:1646} in {zone:1453}"] = "{npc:3649}: para {npc:1646} em {zone:1453}",
		["{npc:3661} hides at the foot of the tower among the Dark Strand Fanatics. Keep his letter for Delgren in {zone:1440}."] = "{npc:3661} se esconde ao pé da torre entre os Fanáticos da Linhagem das Trevas. Guarde a carta dele para Dinis, o Purificador, em {zone:1440}.",
		["{npc:3666}, by the inn"] = "{npc:3666}, junto à estalagem",
		["{npc:3692} hides in the hills east of the {area:449}. Help him back to the road; he fights on his way out."] = "{npc:3692} se esconde nas colinas a leste de {area:449}. Ajude-o a voltar à estrada; ele luta no caminho.",
		["{npc:3694}: for {npc:3691} in {area:415}, on the later {zone:1440} leg"] = "{npc:3694}: para {npc:3691} em {area:415}, no trecho posterior de {zone:1440}",
		["{npc:6667} hides on the little island off the ruins. The key pieces drop from Giant Foreststriders (top), Greymist murlocs (middle) and Raging Reef Crawlers (bottom)."] = "{npc:6667} se esconde na ilhota em frente às ruínas. As partes da chave caem de Florestruzes Gigantes (topo), murlocs Brumagris (meio) e Tiscorais Furiosos (base).",
		["{quest:6122}: fill the sampler at {area:445}"] = "{quest:6122}: encha o amostrador em {area:445}",
		["{quest:87760}: {npc:10219} offers it once all nine beached remains are handed in"] = "{quest:87760}: {npc:10219} a oferece depois que os nove restos encalhados forem entregues",
		["{quest:98394} (Night Elves) and the {npc:272054} (Skyborne) wait in southern {area:493}. The three relics lie in the {area:2363}, east of them. Reports from the first weeks say a relic gives no loot while another player is looting it: wait a moment and try again."] = "{quest:98394} (Elfos Noturnos) e o {npc:272054} (Celonatos) esperam no sul de {area:493}. As três relíquias ficam em {area:2363}, a leste deles. Relatos das primeiras semanas dizem que uma relíquia não dá saque enquanto outro jogador a saqueia: espere um pouco e tente de novo.",
} end)()
t.guides["forever/alliance/04-redridge-mountains"] = (function() return {
		["Back to {area:69}"] = "De volta a {area:69}",
		["Cross the long bridge north into town. {npc:341} and {npc:382} stand at the north end of the bridge, {npc:900} in the town hall, {npc:381} and {npc:266} on the docks, {npc:343} at the inn, {npc:342} in her garden at the west end."] = "Atravesse a ponte comprida para o norte até a vila. {npc:341} e {npc:382} ficam na ponta norte da ponte, {npc:900} na prefeitura, {npc:381} e {npc:266} nas docas, {npc:343} na estalagem, {npc:342} na horta dela, no extremo oeste.",
		["East past the mill and across the river. Shadowhide gnolls fill the valley; {npc:703} (26, well above you) leads them at its north end: clear his escort first and fight him at full health. Stay out of {area:2099} to the south: its orcs are elite."] = "A leste, passe o moinho e atravesse o rio. Gnolls Umbrapele enchem o vale; {npc:703} (26, bem acima de você) os lidera no extremo norte: elimine a escolta dele primeiro e lute com ele com a vida cheia. Fique longe de {area:2099} ao sul: os orcs de lá são elite.",
		["Fly to {area:108} and ride north-west to the coast: the {object:177790} lies on the sea floor off the shore. Then ride east along the road through Elwynn to Redridge."] = "Voe até {area:108} e cavalgue para noroeste até a costa: o {object:177790} está no fundo do mar perto da praia. Depois cavalgue a leste pela estrada, por Elwynn, até Cristarrubra.",
		["Follow the road along the south shore of {area:68} to the gryphon master. {npc:1070} and {npc:903} stand by the road next to her."] = "Siga a estrada pela margem sul do {area:68} até a mestre de grifos. {npc:1070} e {npc:903} ficam na estrada ao lado dela.",
		["For {npc:3649}, on the return to {area:442} (06-ashenvale)"] = "Para {npc:3649}, na volta a {area:442} (06-ashenvale)",
		["Gnolls toward {area:1002}"] = "Gnolls rumo a {area:1002}",
		["Greater Tarantulas crawl on the slopes around the mill north-east of the lake; Blackrock Renegades hold the mill itself."] = "Grandes Tarântulas rastejam nas encostas em volta do moinho a nordeste do lago; Renegados Rocha Negra ocupam o próprio moinho.",
		["Head north out of {area:69} up the {area:95} to {area:997}. Blackrock Champions camp in the valley."] = "Saia de {area:69} rumo ao norte, subindo os {area:95} até o {area:997}. Campeões Rocha Negra acampam no vale.",
		["Keeshan hides at the very north end of the valley, by the {zone:1428} border. Escort him down to {area:69}; Blackrock orcs ambush you on the way."] = "Keeshan se esconde no extremo norte do vale, na divisa com {zone:1428}. Escolte-o até {area:69}; orcs Rocha Negra emboscam vocês no caminho.",
		["Lake murlocs"] = "Murlocs do lago",
		["Level 18 and 20 spells"] = "Feitiços de nível 18 e 20",
		["Murloc Flesheaters and Tidecallers line the south shore east of the bridge. Any of them can carry a {item:1467} or a fin."] = "Carniceiros Murloc e Chamarés ocupam a margem sul a leste da ponte. Qualquer um deles pode levar um {item:1467} ou uma barbatana.",
		["Redridge Mongrels and other gnolls hold the hills east of {area:1002}, north of the road; Redridge Thrashers prowl among them, Poachers camp south of the road. Dire Condors and Great Goretusks roam the same hills."] = "Mestiços de Cristarrubra e outros gnolls ocupam as colinas a leste de {area:1002}, ao norte da estrada; Espancadores de Cristarrubra rondam entre eles, Caçadores Ilegais acampam ao sul da estrada. Condores Hediondos e Grandes Goretuscos vagam pelas mesmas colinas.",
		["Shaman training"] = "Treino de xamã",
		["Swim east from the bridge into {area:68}; the chest lies on the lake bed."] = "Nade a leste da ponte para dentro do {area:68}; o baú está no fundo do lago.",
		["The Wanted poster by the inn: {npc:703}, in {area:1000}"] = "O cartaz de PROCURA-SE perto da estalagem: {npc:703}, em {area:1000}",
		["The road from Elwynn enters Redridge at {area:1002}. {npc:464} stands where the roads to Redridge and {zone:1431} meet."] = "A estrada de Elwynn entra em Cristarrubra em {area:1002}. {npc:464} fica onde se encontram as estradas para Cristarrubra e {zone:1431}.",
		["The {area:442} boat docks at {area:17203}. Walk up into the city for training and {npc:1646}, then leave by the main gate and follow the road east through {zone:1429}."] = "O navio de {area:442} atraca em {area:17203}. Suba até a cidade para treinar e falar com {npc:1646}, depois saia pelo portão principal e siga a estrada a leste por {zone:1429}.",
		["{item:1075}: any Shadowhide gnoll"] = "{item:1075}: qualquer gnoll Umbrapele",
		["{item:15882}: the {object:177790}"] = "{item:15882}: o {object:177790}",
		["{item:280911}: Redridge Thrashers"] = "{item:280911}: Espancadores de Cristarrubra",
		["{item:3014}: the Blackrock Renegades at the mill"] = "{item:3014}: os Renegados Rocha Negra do moinho",
		["{npc:1646}: Thundris' letter from {area:442}"] = "{npc:1646}: a carta de Trovejius de {area:442}",
		["{npc:266}, by the docks"] = "{npc:266}, nas docas",
		["{npc:332} is at SI:7 in {object:2100}, {npc:6122} in the {object:2164}'s cellar in the {object:2101}, {npc:376} in the Cathedral of Light."] = "{npc:332} está na SI:7 em {object:2100}, {npc:6122} no porão do {object:2164} no {object:2101}, {npc:376} na Catedral da Luz.",
		["{npc:332}: {npc:7024} in {zone:1436} takes it, at the end of {zone:1431}"] = "{npc:332}: {npc:7024} em {zone:1436} a recebe, no fim de {zone:1431}",
		["{npc:341}: after {quest:89}"] = "{npc:341}: depois de {quest:89}",
		["{npc:344}, in the town hall"] = "{npc:344}, na prefeitura",
		["{npc:345} (level 24) roots around the pen just west of {area:69}. Pull him away from the other boars and fight at full health."] = "{npc:345} (nível 24) fuça em volta do chiqueiro logo a oeste de {area:69}. Afaste-o dos outros javalis e lute com a vida cheia.",
		["{npc:376}: {npc:11401} in {zone:1457} takes it, later"] = "{npc:376}: {npc:11401} em {zone:1457} a recebe, mais tarde",
		["{npc:376}: {npc:11406} in {zone:1455} takes it, later"] = "{npc:376}: {npc:11406} em {zone:1455} a recebe, mais tarde",
		["{npc:376}: {npc:258785} in {zone:1455} takes it, later"] = "{npc:376}: {npc:258785} em {zone:1455} a recebe, mais tarde",
		["{npc:6122}: {npc:6244} in the {zone:1413} takes it, later"] = "{npc:6122}: {npc:6244} em {zone:1413} a recebe, mais tarde",
		["{npc:903}, by the gryphons south of the bridge"] = "{npc:903}, junto aos grifos ao sul da ponte",
		["{zone:1431} is next: follow the road west to {area:1002}, then south to {area:42}."] = "{zone:1431} é a próxima: siga a estrada a oeste até {area:1002}, depois ao sul até {area:42}.",
		["{zone:1453} class quests"] = "Missões de classe em {zone:1453}",
		["{zone:1453} has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back."] = "{zone:1453} não tem instrutor de xamã: pegue o {area:2257} no {object:28027} até {zone:1455}, treine com {npc:258098} e volte de metrô.",
} end)()
t.guides["forever/alliance/05-duskwood"] = (function() return {
		["/lay down beside {npc:7207}"] = "/lay down ao lado de {npc:7207}",
		["Back to {area:42}"] = "De volta a {area:42}",
		["Continue west to {area:94}. The {object:673515} glows by the ruined house south of the road."] = "Continue para o oeste até {area:94}. {object:673515} brilha junto à casa em ruínas ao sul da estrada.",
		["Every ghoul of the {area:492}'s northern half can drop a rib: Flesh Eaters, Bone Chewers, Plague Spreaders and Brain Eaters."] = "Qualquer carniçal da metade norte de {area:492} pode deixar cair uma costela: Comedores de Carne, Mastigossos, Vetores da Peste e Devora-Cérebros.",
		["Follow the road north-west past the cemetery to {npc:311}'s camp on the far west edge of the forest. {npc:893} stands beside {npc:311}."] = "Siga a estrada para noroeste, passando o cemitério, até o acampamento de {npc:311}, no extremo oeste da floresta. {npc:893} fica ao lado de {npc:311}.",
		["Follow the road south from {area:1002} into {zone:1431}; {area:42} lies on the east side of the forest."] = "Siga a estrada para o sul a partir de {area:1002} até {zone:1431}; {area:42} fica no lado leste da floresta.",
		["Ghoul Ribs"] = "Costelas de Carniçal",
		["Her house stands on the hill south-east of {area:42}, above the {area:121}."] = "A casa dela fica na colina a sudeste de {area:42}, acima de {area:121}.",
		["Level 22 and 24 spells"] = "Feitiços dos níveis 22 e 24",
		["Next: {zone:1453} for training, then the boat from {area:17203} to {area:442} for {zone:1440}."] = "A seguir: {zone:1453} para treinar, depois o barco de {area:17203} para {area:442}, rumo a {zone:1440}.",
		["Rabid Dire Wolves roam the woods around the cemetery and {npc:289}, Starving Dire Wolves the hills north-east of him. Pygmy Venom Web Spiders crawl east of the cemetery and drop the venom. Every ghoul of the cemetery's northern half can drop a fang."] = "Lobos Hediondos Raivosos vagam pela mata ao redor do cemitério e de {npc:289}; Lobos Hediondos Famintos, pelas colinas a nordeste dele. Veneracnas Pigmeias rastejam a leste do cemitério e deixam cair o veneno. Qualquer carniçal da metade norte do cemitério pode deixar cair uma presa.",
		["Ride back east along the road to the {area:245}."] = "Volte para o leste pela estrada até {area:245}.",
		["Ride back east to {area:42}."] = "Volte para o leste até {area:42}.",
		["Ride north through Elwynn to {zone:1453}; Mathias Shaw is at SI:7 in {object:2100}."] = "Siga para o norte pela Floresta de Elwynn até {zone:1453}; Mathias Shaw fica no SI:7, em {object:2100}.",
		["Ride west along the road once more."] = "Siga para o oeste pela estrada mais uma vez.",
		["Ride west along the road out of {area:94} into {zone:1436}. {npc:7024} watches {npc:7053}'s tower from the hills just inside the border. The {npc:7051} (level 23) guarding the tower carries its key; Klaven's journal is in the chest at the top."] = "Siga para o oeste pela estrada, saindo de {area:94} para {zone:1436}. {npc:7024} vigia a torre de {npc:7053} das colinas logo depois da fronteira. {npc:7051} (nível 23) que guarda a torre leva a chave; o diário de Filipe está no baú lá no alto.",
		["Ride west to the hermit once more."] = "Siga para o oeste até o eremita mais uma vez.",
		["Rot Blossoms"] = "Flores do Mal",
		["Shaman training"] = "Treinamento de xamã",
		["Skeletal Horrors walk the hillside between {area:42} and the {area:121}, south-east of town; they drop the Rot Blossoms."] = "Horrores Descarnados andam pela encosta entre {area:42} e {area:121}, a sudeste da cidade; eles deixam cair as Flores do Mal.",
		["Skeletal Warriors and Skeletal Mages walk among the graves south-east of {area:42}, below {npc:302}'s house on the hill. Every skeleton in {zone:1431} can drop a {item:2378}."] = "Guerreiros Descarnados e Magos Descarnados andam entre os túmulos a sudeste de {area:42}, abaixo da casa de {npc:302} na colina. Qualquer esqueleto de {zone:1431} pode deixar cair {item:2378}.",
		["The cemetery lies north of the village. Skeletal Horrors and Skeletal Fiends walk its southern half. {npc:522}, an elite, wanders the graves: keep away from him."] = "O cemitério fica ao norte do vilarejo. Horrores Descarnados e Malévolos Descarnados andam pela metade sul. {npc:522}, um elite, vaga entre os túmulos: fique longe dele.",
		["The hermit's shack stands in the woods north-east of the {area:492}."] = "O barraco do eremita fica na mata a nordeste de {area:492}.",
		["The mound of loose dirt lies south of the farmhouse, by the old stump."] = "O monte de terra solta fica ao sul da casa da fazenda, junto ao velho toco.",
		["Train in {zone:1453}, north through {zone:1429}. Then take the boat from {area:17203} to {area:442}."] = "Treine em {zone:1453}, ao norte, passando por {zone:1429}. Depois pegue o barco de {area:17203} para {area:442}.",
		["Wolves, spiders and ghouls"] = "Lobos, aranhas e carniçais",
		["{area:492}, south"] = "{area:492}, sul",
		["{item:281046}, from the {object:673515}"] = "{item:281046}, de {object:673515}",
		["{item:3372}: {npc:1313}, Alchemy Supplies"] = "{item:3372}: {npc:1313}, Suprimentos de Alquimia",
		["{item:4371}, from {npc:3133}: limited stock. Sold out? {npc:1448} in {area:150} sells it too."] = "{item:4371}, de {npc:3133}: estoque limitado. Esgotado? {npc:1448}, em {area:150}, também vende.",
		["{item:7908}, in the chest"] = "{item:7908}, no baú",
		["{npc:2409}, at the north end of town"] = "{npc:2409}, no extremo norte da cidade",
		["{npc:264}, in the town hall"] = "{npc:264}, na prefeitura",
		["{npc:265}, in her house by the tavern"] = "{npc:265}, na casa dela, ao lado da taverna",
		["{npc:267}, in the town hall"] = "{npc:267}, na prefeitura",
		["{npc:268}, in the house behind the town hall"] = "{npc:268}, na casa atrás da prefeitura",
		["{npc:273}, in the tavern"] = "{npc:273}, na taverna",
		["{npc:276}'s house stands at the east end of town. {npc:3133} sells engineering goods in the house beside it."] = "A casa de {npc:276} fica no extremo leste da cidade. {npc:3133} vende artigos de engenharia na casa ao lado.",
		["{npc:288} hides in the house at the west end of {area:94}."] = "{npc:288} se esconde na casa no extremo oeste de {area:94}.",
		["{npc:332}: Poisons, and {item:18160}"] = "{npc:332}: Venenos e {item:18160}",
		["{npc:633}, at the south end of town"] = "{npc:633}, no extremo sul da cidade",
		["{npc:6790}, Scarlet Raven Tavern"] = "{npc:6790}, Taberna Corvo Escarlate",
		["{npc:888} stands south of the road, at the {area:245}."] = "{npc:888} fica ao sul da estrada, em {area:245}.",
		["{quest:2607}: {npc:7207}, in the cellar of the Barracks"] = "{quest:2607}: {npc:7207}, no porão do Quartel",
		["{quest:337}: a rare drop from {zone:1431}'s mobs"] = "{quest:337}: saque raro dos monstros de {zone:1431}",
		["{zone:1453} has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455}, train with {npc:258098}, then ride the tram back for the {area:442} boat."] = "{zone:1453} não tem instrutor de xamã: pegue o {area:2257} no {object:28027} até {zone:1455}, treine com {npc:258098} e volte de metrô para pegar o barco de {area:442}.",
} end)()
t.guides["forever/alliance/06-ashenvale"] = (function() return {
		["Back to the Cathedral of Light: {npc:928} stands inside."] = "De volta à Catedral da Luz: {npc:928} fica lá dentro.",
		["Black Oozes"] = "Gosmas Pretas",
		["Black Oozes creep through the marsh north of the {area:1025} road, west of {npc:2093}'s camp. Any ooze may hold {npc:2111}'s bag."] = "Gosmas Pretas rastejam pelo pântano ao norte da estrada da {area:1025}, a oeste do acampamento de {npc:2093}. Qualquer gosma pode ter a bolsa de {npc:2111}.",
		["Boat to {area:150}"] = "Navio para {area:150}",
		["Cathedral of Light"] = "Catedral da Luz",
		["Cave Stalkers and Leech Stalkers fill {area:1021}, the cave south-east of the excavation site."] = "Espreitadoras da Caverna e Espreitadoras Sanguessugas enchem {area:1021}, a caverna a sudeste do sítio de escavação.",
		["Dragonmaw camp"] = "Acampamento Presa do Dragão",
		["Escort Kerlonian to {area:413} in {zone:1440}."] = "Escolte Kerlonian até {area:413} em {zone:1440}.",
		["Fen Creepers"] = "Rastejantes do Pântano",
		["Fen Creepers hide in the marsh pools north-west of the {area:1025}."] = "Rastejantes do Pântano se escondem nas poças do pântano a noroeste da {area:1025}.",
		["Follow the coast north out of Menethil. Bluegill Murlocs fill the marsh; {npc:1259} walks with a pack in the middle of it."] = "Siga a costa para o norte saindo de Menethil. Murlocs Guelrazul enchem o pântano; {npc:1259} anda com um bando no meio dele.",
		["Follow the coast north to the {area:414}. {npc:3846} camps on the beach; Wrathtail nagas fill the shore."] = "Siga a costa para o norte até a {area:414}. {npc:3846} acampa na praia; nagas Iracauda enchem a margem.",
		["Follow the road east to the {area:419}; {npc:3916} stands by the moonwell."] = "Siga a estrada para leste até o {area:419}; {npc:3916} fica junto ao poço lunar.",
		["Follow the road east. Young Wetlands Crocolisks lurk in the pools north of the excavation site."] = "Siga a estrada para leste. Crocoliscos do Pantanal Jovens espreitam nas poças ao norte do sítio de escavação.",
		["Follow the road north to {area:205}, at the foot of the {area:881}. {npc:1071} stands in the dwarves' camp."] = "Siga a estrada para o norte até {area:205}, ao pé da {area:881}. {npc:1071} fica no acampamento dos anões.",
		["Follow the road south-east to {area:415}, on the island in the lake."] = "Siga a estrada para sudeste até {area:415}, na ilha do lago.",
		["For Bolvar Fordragon in {object:2117}: keep it"] = "Para Bolvar Fordragon na {object:2117}: guarde-o",
		["For the giant crocolisks of the north coast, on your next visit"] = "Para os crocoliscos gigantes da costa norte, na sua próxima visita",
		["For {npc:2228} in {area:271}: keep it"] = "Para {npc:2228} em {area:271}: guarde-o",
		["From {area:17203} take the boat to {area:442}; {npc:3649} stands at the north end of the village. Then ride south along the road through {zone:1439}."] = "De {area:17203}, pegue o navio até {area:442}; {npc:3649} fica no extremo norte da vila. Depois cavalgue para o sul pela estrada através de {zone:1439}.",
		["Hearth to Menethil"] = "Regressar para Menethil",
		["Hearthstone on cooldown? Ride back north through the {area:1276}."] = "Pedra de Regresso em recarga? Volte para o norte pela {area:1276}.",
		["Kerlonian sleeps at the {area:448} in southern {zone:1439}. Use the {item:13536} to wake him and lead him south along the road into {zone:1440} to {npc:11219} at {area:413}; blow the horn again whenever he falls asleep."] = "Kerlonian dorme no {area:448}, no sul de {zone:1439}. Use a {item:13536} para acordá-lo e leve-o para o sul pela estrada até {zone:1440}, até {npc:11219} em {area:413}; toque a trombeta de novo sempre que ele adormecer.",
		["Kill the elementals for 5 Intact Elemental Bracers, then use the {item:5456}"] = "Mate os elementais por 5 Braçadeiras Elementais Intactas e depois use o {item:5456}",
		["Mosshide Fenrunners and Mistweavers roam the riverbanks just west and south of {npc:1244}; almost every one drops flint."] = "Corre-charcos Pelemusgo e Tecebrumas vagam pelas margens do rio logo a oeste e ao sul de {npc:1244}; quase todos deixam cair pederneira.",
		["Mosshide Gnolls and Mongrels hold the hills south-east of the {area:1025}."] = "Gnolls Pelemusgo e Mestiços ocupam as colinas a sudeste da {area:1025}.",
		["Mottled Raptors and Screechers roam the hills west of the excavation site."] = "Raptores Mosqueados e Guinchadores vagam pelas colinas a oeste do sítio de escavação.",
		["Next: fly to {area:42}."] = "Próximo: voe até {area:42}.",
		["North of Maestra's Post, plant bundles lie around the ruins of {area:411}. Dark Strand cultists hold the ruins just south of them: any of them can drop the {item:5366}."] = "Ao norte do Entreposto de Maestra, há feixes de plantas em volta das ruínas de {area:411}. Sectários da Linhagem das Trevas ocupam as ruínas logo ao sul deles: qualquer um pode deixar cair a {item:5366}.",
		["Only if you looted {quest:337} in {zone:1431}"] = "Só se você saqueou {quest:337} em {zone:1431}",
		["Only with {item:5352} from {zone:1439}: {npc:2786}, the {object:32383}"] = "Só com o {item:5352} de {zone:1439}: {npc:2786}, na {object:32383}",
		["Raptor valley"] = "Vale dos raptores",
		["Ride east along the {zone:1437} road, south through {area:836} into {zone:1432} and west through the tunnel into {zone:1426} to {area:1537}."] = "Cavalgue para leste pela estrada do {zone:1437}, para o sul por {area:836} até {zone:1432} e para oeste pelo túnel até {zone:1426}, até {area:1537}.",
		["Ride south past {area:421} into the {area:1276} tunnel; it comes out in Stonetalon's {area:461}. {npc:4080} and {npc:4077} camp on the {area:1076} south-west of the crag."] = "Cavalgue para o sul, passando o {area:421}, até o túnel da {area:1276}; ele sai no {area:461}, na Cordilheira das Torres de Pedra. {npc:4080} e {npc:4077} acampam na {area:1076}, a sudoeste do penhasco.",
		["Ride west to the shore of {area:441}. Teronis lies among the Saltspittle murlocs; any murloc can drop the {item:5463}."] = "Cavalgue para oeste até a margem do {area:441}. O cadáver de Teronis está entre os murlocs Babassal; qualquer murloc pode deixar cair a {item:5463}.",
		["South of the murlocs, {npc:3585} waits at the {area:416}."] = "Ao sul dos murlocs, {npc:3585} espera no {area:416}.",
		["Take the boat from {area:17203} to {area:442} and fly to {area:702}; {npc:11401} is in the Temple of the Moon. Then fly back to {area:442}."] = "Pegue o navio de {area:17203} até {area:442} e voe até {area:702}; {npc:11401} está no Templo da Lua. Depois voe de volta a {area:442}.",
		["Take the boat from {area:17203} to {area:442}. Join the two half pendants into the {item:15885} and cast {spell:18960}: {npc:11802} is in {area:2361}. Then fly to {area:702} (by way of {area:442})."] = "Pegue o navio de {area:17203} até {area:442}. Junte as duas metades do pingente no {item:15885} e lance {spell:18960}: {npc:11802} está em {area:2361}. Depois voe até {area:702} (passando por {area:442}).",
		["Take the portal up to the {area:1658}, then fly back to {area:442}."] = "Pegue o portal até o {area:1658} e depois voe de volta a {area:442}.",
		["Take the {area:2257} from {object:171524} to {zone:1453}'s {object:28027}, then walk to the {object:2098}."] = "Pegue o {area:2257} em {object:171524} até o {object:28027} de {zone:1453}, depois ande até a {object:2098}.",
		["The Bluegill hovels"] = "As choças Guelrazul",
		["The Dragonmaw camp lies south of the road, just west of the {area:1025}: Raiders, Swamprunners and Bonewarders. {npc:2092}'s quest in {zone:1426} needs level 28."] = "O acampamento Presa do Dragão fica ao sul da estrada, logo a oeste da {area:1025}: Saqueadores, Corre-brejos e Guarda-ossos. A missão de {npc:2092} em {zone:1426} requer nível 28.",
		["The Foulweald"] = "Os Torpeflora",
		["The Foulweald furbolgs live in the woods south of the road, south-east of {area:415}. The Den Watcher and the Ursas guard the den."] = "Os furbolgs Torpeflora vivem na mata ao sul da estrada, a sudeste de {area:415}. O Vigia do Covil Torpeflora e os Ursinos Torpeflora guardam o covil.",
		["The Mosshide gnolls"] = "Os gnolls Pelemusgo",
		["The Venture Co. clear the forest of {area:461}. Loggers and Deforesters work all over it; the Operators run the shredders and one carries the blueprints."] = "A Empreendimentos S.A. desmata a floresta do {area:461}. Madeireiros e Desmatadores trabalham por toda parte; os Operadores pilotam os retalhadores e um deles leva as plantas.",
		["The bigger raptors hunt in the valley just west of the dig."] = "Os raptores maiores caçam no vale logo a oeste da escavação.",
		["The excavation site sits on the hill south of the road."] = "O sítio de escavação fica na colina ao sul da estrada.",
		["The raptor hills"] = "As colinas dos raptores",
		["The tears glow on the small isle east of {area:415}."] = "As lágrimas brilham na ilhota a leste de {area:415}.",
		["Three containers in the murloc hovels, south to north: the {object:261}, then the {object:142151}, then the {object:259} at the north end."] = "Três recipientes nas choças dos murlocs, de sul a norte: o {object:261}, depois o {object:142151}, depois o {object:259} no extremo norte.",
		["Timber and iron piles lie around the keep and along the harbor's walls."] = "Pilhas de madeira e de ferro estão em volta da fortaleza e ao longo das muralhas do porto.",
		["To {area:150}"] = "Até {area:150}",
		["Venture Co. loggers"] = "Madeireiros da Empreendimentos S.A.",
		["West of Mystral Lake, the stardust bushes grow among the ruins."] = "A oeste do Lago Mistral, os arbustos de poeira estelar crescem entre as ruínas.",
		["Young crocolisks"] = "Crocoliscos jovens",
		["grind on Dragonmaw Raiders and Swamprunners at the Dragonmaw camp, {zone:1437}"] = "farme Saqueadores Presa do Dragão e Corre-brejos no acampamento Presa do Dragão, {zone:1437}",
		["{item:15885}: join the two halves"] = "{item:15885}: junte as duas metades",
		["{item:5424}, in the ruins on the shore"] = "{item:5424}, nas ruínas da margem",
		["{npc:11406} and {npc:258785} are in the {object:32386}, in the {object:32362}."] = "{npc:11406} e {npc:258785} estão no {object:32386}, na {object:32362}.",
		["{npc:1239}, in the inn"] = "{npc:1239}, na estalagem",
		["{npc:1242}, on the pier north of the inn"] = "{npc:1242}, no píer ao norte da estalagem",
		["{npc:1242}: for {npc:2104} in the keep"] = "{npc:1242}: para {npc:2104} na fortaleza",
		["{npc:1440}, in the Royal Library"] = "{npc:1440}, na Biblioteca Real",
		["{npc:1444}, in the {object:2098}"] = "{npc:1444}, na {object:2098}",
		["{npc:1573}, in the {object:32372}"] = "{npc:1573}, na {object:32372}",
		["{npc:2086}, by the keep"] = "{npc:2086}, perto da fortaleza",
		["{npc:2093} camps by the road; {npc:1244} stands farther east, by the river."] = "{npc:2093} acampa junto à estrada; {npc:1244} fica mais a leste, junto ao rio.",
		["{npc:2094}, by the north gate"] = "{npc:2094}, perto do portão norte",
		["{npc:2096}, by the north gate"] = "{npc:2096}, perto do portão norte",
		["{npc:2097}, by the north gate"] = "{npc:2097}, perto do portão norte",
		["{npc:2104} stands in {area:2103}, a short walk from {npc:1242}."] = "{npc:2104} fica na {area:2103}, a uma curta caminhada de {npc:1242}.",
		["{npc:3649}: Alexston's reply"] = "{npc:3649}: a resposta de Alexston",
		["{npc:3664} and his voidwalkers hold the {area:412} south of the shrine. Pull his guards first."] = "{npc:3664} e seus emissários do caos ocupam as {area:412} ao sul do santuário. Atraia os guardas dele primeiro.",
		["{npc:3691}, in the inn"] = "{npc:3691}, na estalagem",
		["{npc:3885} stands at the {area:420} on the east shore of {area:421}; {npc:210995} camps on its west shore. Befouled Water Elementals wade in the lake between them."] = "{npc:3885} fica no {area:420}, na margem leste do {area:421}; {npc:210995} acampa na margem oeste. Elementais da Água Contaminados vagam pelo lago entre eles.",
		["{npc:3987} (25) leads the Thistlefur gnolls at the camp north of {area:415}. Clear his guards first, one at a time."] = "{npc:3987} (25) lidera os gnolls Pelocardo no acampamento ao norte de {area:415}. Elimine os guardas dele primeiro, um de cada vez.",
		["{npc:4201}, in the hut north of them"] = "{npc:4201}, na cabana ao norte deles",
		["{npc:4276} mines in the {area:2160} at the east end of the crag. Talk to him and fend off the Venture Co. raiders while he mines."] = "{npc:4276} minera na {area:2160}, no extremo leste do penhasco. Fale com ele e afaste os atacantes da Empreendimentos S.A. enquanto ele minera.",
		["{npc:482}, the cheese shop in the {object:2096}"] = "{npc:482}, a loja de queijos no {object:2096}",
		["{npc:4959} and {npc:482}"] = "{npc:4959} e {npc:482}",
		["{npc:4982}, in the Cathedral of Light"] = "{npc:4982}, na Catedral da Luz",
		["{object:2164} is in the {object:2101}."] = "{object:2164} fica no {object:2101}.",
		["{quest:1009} walks the northern tip of the {area:414} with Wrathtail guards."] = "{quest:1009} anda pela ponta norte da {area:414} com guardas Iracauda.",
		["{quest:1010}, from the plant bundles"] = "{quest:1010}, dos feixes de plantas",
		["{zone:1455} priests"] = "Sacerdotes de {zone:1455}",
} end)()
t.guides["forever/alliance/07-thousand-needles"] = (function() return {
		["Back to Menethil"] = "De volta a Menethil",
		["Back to {area:42}"] = "De volta a {area:42}",
		["Bluegill Raiders"] = "Saqueadores Guelrazul",
		["Dragonmaw camp"] = "Acampamento Presa do Dragão",
		["Follow the canyons east to the salt flats. The goblins and gnomes of the {area:2240} are neutral and give quests to both factions."] = "Siga os cânions para o leste até as planícies de sal. Os goblins e gnomos de {area:2240} são neutros e dão missões às duas facções.",
		["Follow the coast north to the wrecked ship. Cursed Sailors walk the beach, Cursed Marines the deck; {npc:1159} stands on the beach by the bow. Giant Wetlands Crocolisks lurk on the coast just north of it."] = "Siga a costa para o norte até o navio naufragado. Marinheiros Amaldiçoados andam pela praia, Fuzileiros Amaldiçoados pelo convés; {npc:1159} fica na praia, junto à proa. Crocoliscos do Pantanal Gigantes espreitam na costa logo ao norte.",
		["Follow the coast north-east past the wreck: the Bluegill Raiders hold the marsh beyond the Giant Crocolisks."] = "Siga a costa para nordeste, passando o naufrágio: os Saqueadores Guelrazul dominam o brejo depois dos Crocoliscos Gigantes.",
		["Follow the road east to the excavation site."] = "Siga a estrada para o leste até o Sítio de Escavação de Whelgar.",
		["For the Dragonmaw catapult, on the {zone:1437} loop of the next guide"] = "Para a catapulta dos Presa do Dragão, na volta por {zone:1437} do próximo guia",
		["For {npc:1212} in {zone:1453}, in the next guide"] = "Para {npc:1212}, em {zone:1453}, no próximo guia",
		["For {npc:1284} in {zone:1453}, in the next guide"] = "Para {npc:1284}, em {zone:1453}, no próximo guia",
		["For {npc:4048} in {zone:1444}, much later"] = "Para {npc:4048}, em {zone:1444}, bem mais tarde",
		["For {npc:482} in {zone:1453}, in the next guide"] = "Para {npc:482}, em {zone:1453}, no próximo guia",
		["For {quest:5762} in Stranglethorn, later"] = "Para {quest:5762}, na Selva do Espinhaço, mais tarde",
		["From Theramore follow the road west out of Dustwallow into the {zone:1413} and south along it; give {area:378} a wide berth. {area:485} at the {zone:1413}' south end takes you down into {zone:1441}. The journal lies at the foot of the lift."] = "De Theramore, siga a estrada para o oeste, saindo do Pântano Vadeoso para {zone:1413}, e desça para o sul por ela; mantenha distância de {area:378}. {area:485}, no extremo sul de {zone:1413}, leva você para baixo, até {zone:1441}. O diário fica ao pé do elevador.",
		["From {npc:352} in {zone:1453}"] = "De {npc:352}, em {zone:1453}",
		["Her house stands on the hill south-east of {area:42}."] = "A casa dela fica na colina a sudeste de {area:42}.",
		["Nightbane Dark Runners"] = "Corretrevas Nocturnos",
		["Nightbane Shadow Weavers"] = "Tece-sombras Nocturnos",
		["Nightbane Vile Fangs and the {npc:511}"] = "Presas Torpes Nocturnos e {npc:511}",
		["No {item:4371} for {quest:174}? {npc:3133} sells it in the house beside {npc:276}, in limited stock; {npc:1448} in {area:150} sells it too."] = "Sem {item:4371} para {quest:174}? {npc:3133} vende na casa ao lado de {npc:276}, em estoque limitado; {npc:1448}, em {area:150}, também vende.",
		["On the road south through the {zone:1413}, {npc:6244} camps east of the road, north-east of {area:378}; come in from the east and keep clear of the Horde guards."] = "Na estrada para o sul por {zone:1413}, {npc:6244} acampa a leste da estrada, a nordeste de {area:378}; chegue pelo leste e fique longe dos guardas da Horda.",
		["Only if a {npc:272273} dropped {quest:96138}: right-click it"] = "Só se um {npc:272273} deixou cair {quest:96138}: clique com o botão direito nele",
		["Plague Spreaders"] = "Vetores da Peste",
		["Ride back west along the road to {area:150}."] = "Volte para o oeste pela estrada até {area:150}.",
		["Ride east again to the Dragonmaw camp. The four sets of Attack Plans lie in the {area:1036}; {npc:2091}, an elite, stands in the camp too."] = "Cavalgue de novo para o leste até o acampamento dos Presa do Dragão. Os quatro conjuntos de planos de ataque estão em {area:1036}; {npc:2091}, um elite, também fica no acampamento.",
		["Ride east to the ogre mound. {object:119} sits in the camp at its entrance; Splinter Fist ogres guard it."] = "Siga para o leste até a Gruta de Vul'Gol. {object:119} está no acampamento da entrada; ogros Punhalasca o guardam.",
		["Ride west along the road; the hermit's shack stands north-east of the {area:492}."] = "Siga para o oeste pela estrada; o barraco do eremita fica a nordeste de {area:492}.",
		["Skeletal Raiders, Healers and Warders hold the west part of the cemetery, just east of {npc:311}'s camp."] = "Saqueadores, Curandeiros e Guardadores Descarnados dominam a parte oeste do cemitério, logo a leste do acampamento de {npc:311}.",
		["Take the boat from Menethil's pier to {area:513} in {zone:1445}."] = "Pegue o barco no píer de Menethil até {area:513}, em {zone:1445}.",
		["The Dark Runners prowl the woods south of the road, west of {area:42}."] = "Os Corretrevas rondam a mata ao sul da estrada, a oeste de {area:42}.",
		["The Defias camp lies in the south-west of {zone:1431}, south of {area:94} near the {zone:1436} border. The strongbox stands among the tents."] = "O acampamento dos Défias fica no sudoeste de {zone:1431}, ao sul de {area:94}, perto da fronteira com {zone:1436}. A caixa-forte fica entre as barracas.",
		["The Dragonmaw orcs camp east of the excavation site. Raiders and Swamprunners carry the war banners."] = "Os orcs Presa do Dragão acampam a leste do sítio de escavação. Saqueadores e Corre-brejos carregam os estandartes de guerra.",
		["The Plague Spreaders walk the northern half of the {area:492}. {npc:522}, an elite, wanders the graves: keep away from him."] = "Os Vetores da Peste andam pela metade norte de {area:492}. {npc:522}, um elite, vaga entre os túmulos: fique longe dele.",
		["The captain walks the deck of the wrecked ship; his strongbox sits in the hold."] = "O capitão anda pelo convés do navio naufragado; a caixa-forte dele fica no porão.",
		["The dig and {npc:1353}"] = "A escavação e {npc:1353}",
		["The relics lie in the dig itself. {npc:1353}, a big Razormaw, prowls the raptor valley just west of it."] = "As relíquias ficam na própria escavação. {npc:1353}, um Rasgaqueixo grande, ronda o vale dos raptores logo a oeste.",
		["The salt flats"] = "As planícies de sal",
		["The strongest worgen roam the woods south of {area:42}, west and south of the {area:121}. The {npc:511} hides in the small crypt by the cemetery."] = "Os worgens mais fortes vagam pela mata ao sul de {area:42}, a oeste e ao sul de {area:121}. {npc:511} se esconde na pequena cripta junto ao cemitério.",
		["The worgen hold the woods of Brightwood, west of {area:42} and north of the road. Pull them one at a time."] = "Os worgens dominam a mata do Bosque Brilhante, a oeste de {area:42} e ao norte da estrada. Puxe um de cada vez.",
		["The wreck of the Third Fleet"] = "O naufrágio da Terceira Frota",
		["To Theramore"] = "Para Theramore",
		["Wait a moment, then speak with her again"] = "Espere um momento e fale com ela de novo",
		["{area:492}, west"] = "{area:492}, oeste",
		["{item:2594}, from {npc:1464}"] = "{item:2594}, de {npc:1464}",
		["{item:2661}: the {object:331}"] = "{item:2661}: {object:331}",
		["{item:4371}, from {npc:3133}, if you have none"] = "{item:4371}, de {npc:3133}, se não tiver nenhum",
		["{npc:1078} and Whelgar"] = "{npc:1078} e Whelgar",
		["{npc:1217}, upstairs in the inn"] = "{npc:1217}, no andar de cima da estalagem",
		["{npc:1239}, in the inn"] = "{npc:1239}, na estalagem",
		["{npc:2104}, by the keep"] = "{npc:2104}, junto à fortaleza",
		["{npc:2104}, in {area:2103}"] = "{npc:2104}, em {area:2103}",
		["{npc:263}, in the town hall"] = "{npc:263}, na prefeitura",
		["{npc:267}, in the town hall"] = "{npc:267}, na prefeitura",
		["{npc:268}, in the house behind the town hall"] = "{npc:268}, na casa atrás da prefeitura",
		["{npc:276}, at the east end of town"] = "{npc:276}, no extremo leste da cidade",
		["{npc:311}'s Camp"] = "Acampamento do {npc:311}",
		["{npc:4454}: for Martek in the {zone:1418}, later"] = "{npc:4454}: para Martek, em {zone:1418}, mais tarde",
		["{npc:661}, by {npc:633}'s house"] = "{npc:661}, junto à casa de {npc:633}",
		["{npc:663}, by the town hall"] = "{npc:663}, junto à prefeitura",
		["{npc:6790}, Scarlet Raven Tavern"] = "{npc:6790}, Taberna Corvo Escarlate",
		["{npc:840}, at the north entrance of town"] = "{npc:840}, na entrada norte da cidade",
		["{object:19868} lies all over the flats. Scorpid Reavers, Sparkleshell Tortoises and Saltstone Basilisks roam the north half, Crystalhides, Scorpid Terrors and Snappers the middle, and the Gazers (34-35, five levels above you: one at a time) the far south. Vultures circle over all of it."] = "{object:19868} está espalhado por toda a planície. Aniquiladores Escorpídeos, Tartarugas Quelobrilho e Basiliscos Sal-gema vagam pela metade norte; Cristaldermes, Terrores Escorpídeos e Tartaliscas, pelo meio; e os Observadores (34-35, cinco níveis acima de você: um de cada vez), pelo extremo sul. Abutres sobrevoam tudo.",
		["{quest:1738}: in {zone:1440}, on the way to {zone:1443}"] = "{quest:1738}: em {zone:1440}, no caminho para {zone:1443}",
		["{quest:65602}: the incubus, beside the succubus; the {item:190309} is near the {quest:1738}"] = "{quest:65602}: o íncubo, ao lado da súcubo; {item:190309} fica perto de {quest:1738}",
		["{quest:98221}: {quest:465} comes after it on Forever"] = "{quest:98221}: no Forever, {quest:465} vem depois dela",
} end)()
t.guides["forever/alliance/30-40/01-hillsbrad-foothills"] = (function() return {
		["A new {item:279996}, for the four titan watchers around the {zone:1437}"] = "Uma nova {item:279996}, para os quatro vigias titânicos espalhados por {zone:1437}",
		["A report for {object:2117}"] = "Um relatório para {object:2117}",
		["Back south down the road to the excavation site."] = "Volte para o sul pela estrada até o sítio de escavação.",
		["Back to the same murlocs; not every one drops a head."] = "Volte aos mesmos murlocs; nem todos soltam uma cabeça.",
		["Boat to {area:271}"] = "Barco para {area:271}",
		["Cathedral of Light"] = "Catedral da Luz",
		["Daggerspine naga"] = "Nagas Espinhadaga",
		["Druid training"] = "Treinamento de druida",
		["Farren"] = "Fárrio",
		["Fly to {zone:1453}"] = "Voe para {zone:1453}",
		["Follow the road east to {area:118}."] = "Siga a estrada para o leste até {area:118}.",
		["Follow the road north-east into the {area:1025}: {npc:270637} camps beside it, {npc:1244} a short way east."] = "Siga a estrada para o nordeste até a {area:1025}: {npc:270637} acampa ao lado dela; {npc:1244}, um pouco a leste.",
		["For King Magni in {zone:1455}, at the end of this guide"] = "Para o Rei Magni em {zone:1455}, no fim deste guia",
		["For {npc:2916} in {zone:1455}, at the end of this guide"] = "Para {npc:2916} em {zone:1455}, no fim deste guia",
		["From {npc:2432} in {area:271}"] = "Com {npc:2432} em {area:271}",
		["Level 30 and 32 spells"] = "Feitiços de nível 30 e 32",
		["Murloc heads"] = "Cabeças de murloc",
		["North along the road to {area:205}. {npc:271460} stands in the ruins (use the {item:279996}); the {npc:271481} is held on the west side: lead it out to {npc:1072}."] = "Para o norte pela estrada até {area:205}. {npc:271460} fica nas ruínas (use a {item:279996}); {npc:271481} está preso no lado oeste: leve-o até {npc:1072}.",
		["Pick up everything in town before heading out. Off the boat, {npc:251493} is the first you meet, north-west of the flight master; {npc:2381} and {npc:2438} stand between the flight master and the inn, Farren and {npc:2366} at the inn, Maleb in the town hall."] = "Pegue tudo na cidade antes de sair. Ao desembarcar, {npc:251493} é o primeiro que você encontra, a noroeste do mestre de voo; {npc:2381} e {npc:2438} ficam entre o mestre de voo e a estalagem; Fárrio e {npc:2366}, na estalagem; Maleb, na prefeitura.",
		["Red whelps fill the hills west of the gates, Maddened Rotclaws the {area:1025}, Razormaws the northern slopes; {npc:271458} stands in the north-east (use the {item:279996}).\n{quest:98283} is elite: grouping up is advised."] = "Dragonetes Vermelhos enchem as colinas a oeste dos portões; {npc:271334}, a {area:1025}; Rasgaqueixos, as encostas do norte. {npc:271458} fica no nordeste (use a {item:279996}).\n{quest:98283} é elite: recomenda-se formar um grupo.",
		["Snapjaws"] = "Mordeliscas",
		["South to the Dragonmaw's {area:1036}: the first catapult stands on the way, and the {object:671518} lies in the camp."] = "Para o sul, até {area:1036}, dos Presa do Dragão: a primeira catapulta fica no caminho, e {object:671518} está no acampamento.",
		["Syndicate camp"] = "Acampamento da Camarilha",
		["Take the {area:2257} from the {object:28027} to {zone:1455}."] = "Pegue o {area:2257} em {object:28027} até {zone:1455}.",
		["The Goaz Warders stand just west of Whelgar's camp: use the {item:279996} he gave you beside one."] = "Os Goaz Warders ficam logo a oeste do acampamento de Whelgar: use a {item:279996} que ele lhe deu ao lado de um deles.",
		["The Snapjaw turtles bask along the river east of {area:271}, south of {area:272} (Horde)."] = "As tartarugas Mordeliscas tomam sol ao longo do rio a leste de {area:271}, ao sul de {area:272} (Horda).",
		["The Syndicate camp sits on the Alterac border in northern {area:287}, west of {area:272} (Horde); the documents lie in the camp."] = "O acampamento da Camarilha fica na divisa com as Montanhas de Alterac, no norte de {area:287}, a oeste de {area:272} (Horda); os documentos estão no acampamento.",
		["The Torn Fin murlocs crowd the {area:295}, south-west of {area:271}."] = "Os murlocs Rancapina lotam {area:295}, a sudoeste de {area:271}.",
		["The Villards"] = "Os Villard",
		["The cheese shop in the {object:2096}."] = "A loja de queijos em {object:2096}.",
		["The naga hold the shore south-east of {area:271}."] = "As nagas ocupam a costa a sudeste de {area:271}.",
		["The next step, Defeat Nek'rosh, pits you against an elite chieftain: skip it."] = "A etapa seguinte, Derrotar Nek'rosh, coloca você contra um chefe elite: pule-a.",
		["The yetis live in the cave in the hills north of {area:271}, on your way back south."] = "Os yetis vivem na caverna nas colinas ao norte de {area:271}, no caminho de volta para o sul.",
		["Torn Fin murlocs"] = "Murlocs Rancapina",
		["West along the road to Menethil."] = "Para o oeste pela estrada até o Porto de Menethil.",
		["West to the farms of {area:287}: place the {item:279386} on the bookkeeping table in the town hall, where {npc:2335} and the councilmen stand."] = "Para o oeste, até as fazendas de {area:287}: coloque {item:279386} na mesa de contabilidade da prefeitura, onde ficam {npc:2335} e os conselheiros.",
		["Whelps, raptors and {npc:271458}"] = "Dragonetes, raptores e {npc:271458}",
		["Yeti cave"] = "Caverna dos yetis",
		["{area:287} town hall"] = "Prefeitura de {area:287}",
		["{area:287}'s town hall"] = "Prefeitura de {area:287}",
		["{item:3713}, from {npc:2381}"] = "{item:3713}, de {npc:2381}",
		["{npc:1244}: {quest:98283}, an elite raptor"] = "{npc:1244}: {quest:98283}, um raptor elite",
		["{npc:2104} stands in {area:2103}; {npc:2094} stands by the north gate."] = "{npc:2104} fica em {area:2103}; {npc:2094} fica perto do portão norte.",
		["{npc:2104}: for {npc:270637}"] = "{npc:2104}: para {npc:270637}",
		["{npc:2366}, in the inn: for {area:35} (04-stranglethorn-vale)"] = "{npc:2366}, na estalagem: para {area:35} (04-stranglethorn-vale)",
		["{npc:2382}: the lions come later"] = "{npc:2382}: os leões ficam para depois",
		["{npc:2438} also wants a {item:3719}, a {item:2997} and {item:2321}: crafted or bought; the cloak is turned in when you are back in {area:271} later."] = "{npc:2438} também quer um {item:3719}, um {item:2997} e {item:2321}: fabricados ou comprados; o manto é entregue quando você voltar a {area:271} mais tarde.",
		["{npc:2708} is in the {object:2164}; {npc:211033} near the canal; {npc:5081} south of the {object:2101}."] = "{npc:2708} está em {object:2164}; {npc:211033}, perto do canal; {npc:5081}, ao sul de {object:2101}.",
		["{npc:2711}: his trail leads to Arathi"] = "{npc:2711}: a pista dele leva ao Planalto Arathi",
		["{npc:271462} stands in the south-eastern hills: use the {item:279996} beside it."] = "{npc:271462} fica nas colinas do sudeste: use a {item:279996} ao lado dele.",
		["{npc:2784}, the {object:171709}"] = "{npc:2784}, {object:171709}",
		["{npc:4961} waits in the Pig and Whistle tavern in {object:2100}; he and his two thugs fight you, but stop once beaten."] = "{npc:4961} espera na Taberna do Javatusco Saltitante, em {object:2100}; ele e seus dois capangas lutam com você, mas param quando derrotados.",
		["{npc:5479} trains warriors in {object:2100}, beside the Pig and Whistle. {npc:6236} waits on {area:720} in the {zone:1413}, on the way to {area:392} much later (40-50/01)."] = "{npc:5479} treina guerreiros em {object:2100}, ao lado da Taberna do Javatusco Saltitante. {npc:6236} espera em {area:720}, em {zone:1413}, no caminho para {area:392}, bem mais tarde (40-50/01).",
		["{npc:5683} waits north of {area:205} by the {area:881}; {npc:271322} a short walk further north-east."] = "{npc:5683} espera ao norte de {area:205}, perto de {area:881}; {npc:271322}, um pouco mais a nordeste.",
		["{object:671518}: for {npc:2104}"] = "{object:671518}: para {npc:2104}",
		["{zone:1455} has no druid trainer: train with {npc:5504} in {zone:1453} before the tram."] = "{zone:1455} não tem instrutor de druidas: treine com {npc:5504} em {zone:1453} antes do metrô.",
} end)()
t.guides["forever/alliance/30-40/02-desolace"] = (function() return {
		["Escort the caravan"] = "Escolte a caravana",
		["Escort {npc:5644}"] = "Escolte {npc:5644}",
		["Follow the road west past {area:460} (Horde) and south-west through the {area:465} into {zone:1443}; {area:608} stands at the top of the pass."] = "Siga a estrada para o oeste, passando por {area:460} (Horda), e para o sudoeste por {area:465} até {zone:1443}; {area:608} fica no alto do desfiladeiro.",
		["From {area:415} head south-west to the {area:1276}, a tunnel through the mountains into Stonetalon."] = "De {area:415}, siga para o sudoeste até {area:1276}, um túnel pelas montanhas até a Cordilheira das Torres de Pedra.",
		["From {area:415} ride north-west into the hills: the {quest:1738} is a glowing tree north of the road to {area:413}. If you took {quest:65602}, the {item:190309} lies in a house among the trees north of {area:413} (26.6,22.0). Then back past {area:415} to the {area:1276}."] = "De {area:415}, cavalgue para o noroeste até as colinas: {quest:1738} é uma árvore brilhante ao norte da estrada para {area:413}. Se você pegou {quest:65602}, {item:190309} está numa casa entre as árvores ao norte de {area:413} (26.6,22.0). Depois volte, passando por {area:415}, até {area:1276}.",
		["From {zone:1455}'s {npc:1573}"] = "Com {npc:1573}, em {zone:1455}",
		["Her brother {npc:5643} (36) walks the fortress with the Burning Blade cultists (30-33): pull him alone. The {npc:13019} keeps the sceptre in the fortress's main building."] = "O irmão dela, {npc:5643} (36), anda pela fortaleza com os sectários da Lâmina Ardente (30-33): puxe-o sozinho. {npc:13019} guarda o cetro no prédio principal da fortaleza.",
		["Lead {npc:5644} out of the fortress; she walks off once you are clear of it. {npc:5642} takes the turn-in at {area:608} at the end of the guide."] = "Leve {npc:5644} para fora da fortaleza; ela vai embora quando vocês saírem. {npc:5642} recebe a entrega em {area:608}, no fim do guia.",
		["Malem chest"] = "Baú de Malem",
		["Out of Thunder Axe Fortress"] = "Para fora da Fortaleza Machado do Trovão",
		["Scorpashi venom"] = "Peçonha de Scorpachi",
		["Take the boat to {area:442} from Menethil's docks."] = "Pegue o barco para {area:442} nas docas do Porto de Menethil.",
		["The Gizelton Caravan waits at {area:2407}."] = "A caravana dos Gizelton espera em {area:2407}.",
		["The Hatefury satyrs hold the ruins of {area:603}, east of {area:608}."] = "Os sátiros Furiódio ocupam as ruínas de {area:603}, a leste de {area:608}.",
		["The Kolkar roam the plains around {area:609}; their ears are for {npc:5752}."] = "Os Kolkar vagam pelas planícies ao redor de {area:609}; as orelhas deles são para {npc:5752}.",
		["The Scorpashi scorpids hunt the hills around {area:2407} on the road south."] = "Os escorpídeos Escorpachi caçam nas colinas ao redor de {area:2407}, na estrada para o sul.",
		["The chest lies in the ruins south-west of {area:608}."] = "O baú está nas ruínas a sudoeste de {area:608}.",
		["Use {npc:11596}'s {item:13892} on an {npc:4700} and walk the tamed kodo back to his camp, five times; Aged Kodos also drop the hides."] = "Use o {item:13892} de {npc:11596} num {npc:4700} e leve o kodo domado até o acampamento dele, cinco vezes; Kodos Idosos também soltam os pelegos.",
		["Walk with the caravan south past {area:609}; Kolkar ambushers jump it on the way. Stay close until it stops at {area:2617}. The ambushers are 34-35 and come in waves: skip it if you are below 33."] = "Acompanhe a caravana para o sul, passando por {area:609}; Emboscadores Kolkar a atacam no caminho. Fique perto até ela parar em {area:2617}. Os emboscadores são de nível 34-35 e vêm em ondas: pule se você estiver abaixo do 33.",
		["{item:190309}, north of {area:413}"] = "{item:190309}, ao norte de {area:413}",
		["{npc:11596}'s camp is on the road south of {area:609}, by the {area:596}."] = "O acampamento de {npc:11596} fica na estrada ao sul de {area:609}, perto de {area:596}.",
		["{npc:11863}'s tower stands on the hill west of {area:599}: take his quest first, the sceptre he wants is in the fortress."] = "A torre de {npc:11863} fica no morro a oeste de {area:599}: pegue a missão dele primeiro; o cetro que ele quer está na fortaleza.",
		["{npc:5643} and the Seer"] = "{npc:5643} e o Vidente",
		["{npc:5644} hides inside the Burning Blade's fortress south-west of {area:608}."] = "{npc:5644} se esconde na fortaleza da Lâmina Ardente, a sudoeste de {area:608}.",
} end)()
t.guides["forever/alliance/30-40/03-ashenvale"] = (function() return {
		["Dartol's Rod"] = "Bastão de Transformação de Dartol",
		["Follow the road east to the satyr camps of {area:429}; {npc:3920} hides at their edge."] = "Siga a estrada para leste até os acampamentos de sátiros de {area:429}; {npc:3920} se esconde na borda deles.",
		["Follow the road west out of {area:415}; {area:413} lies north of it."] = "Siga a estrada para oeste saindo de {area:415}; {area:413} fica ao norte dela.",
		["From {area:608}"] = "De {area:608}",
		["Insane druids"] = "Druidas insanos",
		["Lightforge Ingots"] = "Lingotes da Forja de Luz",
		["Melyria and {npc:3901}"] = "Melyria e {npc:3901}",
		["Rusty chests lie around the Shadethicket furbolg camps west of the Forsaken; open them until one holds the pommel."] = "Baús Enferrujados ficam em volta dos acampamentos furbolgs Umbrárvore a oeste dos Renegados; abra-os até um conter o Castão de Ferro.",
		["Take the boat to {area:150} from {area:442}'s docks."] = "Pegue o barco para {area:150} nas docas de {area:442}.",
		["Take the tunnel into the {area:419}; the tome lies in the ruins at its west end."] = "Pegue o túnel para {area:419}; o tomo está nas ruínas no extremo oeste.",
		["The Bluegill murlocs on the beach south-west of Menethil carry the ingots."] = "Os murlocs Guelrazul na praia a sudoeste de Menethil carregam os lingotes.",
		["The Crazed and Withered Ancients north of the moonwell carry the {item:5475}; the worn chest it opens stands among them."] = "Os Ancientes Enlouquecidos e Ancientes Fenescidos ao norte do poço lunar carregam a {item:5475}; o baú gasto que ela abre fica entre eles.",
		["The Forsaken's camp lies in the woods south of {area:2358}."] = "O acampamento dos Renegados fica na mata ao sul de {area:2358}.",
		["The moonwell lies in the hills north-east of {area:415}."] = "O poço lunar fica nas colinas a nordeste de {area:415}.",
		["The second {object:19901} lies in the valley of {area:428}, on the way west."] = "O segundo {object:19901} fica no vale de {area:428}, no caminho para oeste.",
		["The shrine sits on the hill just south-east of the moonwell; follow the winding path up."] = "O santuário fica na colina logo a sudeste do poço lunar; suba pela trilha sinuosa.",
		["The three druids stand together at the Forsaken camp south of {area:2358}."] = "Os três druidas ficam juntos no acampamento dos Renegados ao sul de {area:2358}.",
		["The two stand together at the western end of the road."] = "As duas ficam juntas no extremo oeste da estrada.",
		["The wreck of the Flying Osprey lies in the shallows south of the keep."] = "O navio naufragado está nas águas rasas ao sul da fortaleza.",
		["The {npc:3931} walks the shore of {quest:1035}, south-west of the chests; the {object:669176} lies north of the lake, on the way."] = "O {npc:3931} anda pela margem de {quest:1035}, a sudoeste dos baús; o {object:669176} está ao norte do lago, no caminho.",
		["The {object:19901} stands in the satyr camp of {area:430}, further east along the road."] = "{object:19901} fica no acampamento de sátiros de {area:430}, mais a leste pela estrada.",
		["{area:2358}, the Night Elf outpost at the eastern end of the road: {npc:3848} stands there."] = "{area:2358}, o posto avançado dos elfos noturnos no extremo leste da estrada: {npc:3848} fica lá.",
		["{npc:1217} stands on the upper floor of Menethil's keep."] = "{npc:1217} fica no andar de cima da fortaleza de Menethil.",
		["{npc:3696} and his guards camp just east of {npc:3897}."] = "{npc:3696} e seus guardas acampam logo a leste de {npc:3897}.",
		["{npc:3897}, a furbolg untouched by the corruption, sits south of the road below {area:421}."] = "{npc:3897}, um furbolg intocado pela corrupção, fica ao sul da estrada abaixo de {area:421}.",
		["{npc:3970}: for {npc:1480} in Menethil, at the end of this guide"] = "{npc:3970}: para {npc:1480} em Menethil, no fim deste guia",
		["{npc:4619} leads the {area:429} satyrs; he carries the branch."] = "{npc:4619} lidera os sátiros de {area:429}; ele carrega o galho.",
		["{npc:5082}, {npc:4963} and Tapoke Jahn are all at Menethil's inn; {npc:4962} fights you when you talk to {npc:4963}, but gives up once beaten. {npc:1480} stands a short walk north-east of the inn."] = "{npc:5082}, {npc:4963} e {npc:4962} estão todos na estalagem de Menethil; Tapoke luta com você quando você fala com {npc:4963}, mas desiste quando derrotado. {npc:1480} fica a uma curta caminhada a nordeste da estalagem.",
		["{object:669176}: for {npc:3961} in {area:415}"] = "{object:669176}: para {npc:3961} em {area:415}",
} end)()
t.guides["forever/alliance/30-40/04-stranglethorn-vale"] = (function() return {
		["Back south past Nesingwary: Panthers and Stranglethorn Raptors run in the clearings west of the camp toward the coast; the elder tigers hold the hills south-west."] = "De volta ao sul, passando Rosarães: Panteras e Raptores-do-espinhaço correm nas clareiras a oeste do acampamento, rumo à costa; os tigres anciões dominam as colinas a sudoeste.",
		["Bloodscalp trolls"] = "Trolls Sanguescalpo",
		["Both roam the grass around the camp and along the road north."] = "Os dois vagam pelo capim ao redor do acampamento e ao longo da estrada para o norte.",
		["Down to {area:35}"] = "Descendo até {area:35}",
		["Druid training"] = "Treinamento de druida",
		["Fly from {area:150} to {area:1537} and train."] = "Voe de {area:150} para {area:1537} e treine.",
		["Fly to {area:42}: {npc:1573} in {area:1537}'s {object:32372}, or {npc:352} in {zone:1453}'s {object:2096}."] = "Voe para {area:42}: {npc:1573}, em {object:32372} de {area:1537}, ou {npc:352}, em {object:2096} de {zone:1453}.",
		["Follow the main road south the length of the jungle, past the {object:3202} turn-off, to {area:35} on the southern cape."] = "Siga a estrada principal para o sul por toda a selva, passando o desvio para {object:3202}, até {area:35}, no cabo ao sul.",
		["Follow the west coast north; the haunted island lies off the shore west of Nesingwary's camp. Just reach it."] = "Siga a costa oeste para o norte; a ilha assombrada fica perto da praia, a oeste do acampamento de Rosarães. Basta chegar lá.",
		["For Archmage Ansirem in {zone:1416}"] = "Para o Arquimago Ansirem, em {zone:1416}",
		["From {zone:1431} take the road south into Stranglethorn; the hunters' tents stand just west of the road past the {area:99} turn-off."] = "De {zone:1431}, pegue a estrada para o sul até a Selva do Espinhaço; as barracas dos caçadores ficam logo a oeste da estrada, depois do desvio para {area:99}.",
		["Gluggle, a rare murloc on the coast west of camp, drops the {item:4614}: take it if you meet him"] = "Glubglub, um murloc raro na costa a oeste do acampamento, deixa cair {item:4614}: pegue se encontrá-lo",
		["Gyll, on the top floor by the docks"] = "Gyll, no último andar, junto às docas",
		["Headshrinkers stand deeper in the compound; the Commandos lurk stealthed around it and in the cave. Pick up Green Hills pages as they drop."] = "Os Encolhedores de Cabeças ficam mais para dentro do complexo; as Tropas de Choque espreitam furtivas ao redor dele e na caverna. Pegue as páginas de Grande Espinhaço: Veredas que caírem.",
		["Herod's records lie in a hut on the compound's west side; his strongbox sits farther east, by the cave mouth."] = "Os registros de Herodes ficam numa cabana no lado oeste do complexo; o cofre dele fica mais a leste, junto à entrada da caverna.",
		["Loop through the troll ruins of the north and centre: each holds one stone tablet of the troll legends. Shadowmaw Panthers prowl stealthed in the jungle around them; the Venture Co. camp on {area:37} carries the Tumbled Crystals."] = "Percorra as ruínas trolls do norte e do centro: cada uma guarda uma tabuleta de pedra das lendas trolls. Panteras Umbragorja rondam furtivas na selva ao redor; o acampamento da Empreendimentos S.A. em {area:37} carrega os Cristais Rolados.",
		["Panthers, raptors and elder tigers"] = "Panteras, raptores e tigres anciões",
		["River Crocolisks swim the river by the {area:99}."] = "Crocoliscos do Rio nadam no rio junto a {area:99}.",
		["River crocolisks"] = "Crocoliscos do Rio",
		["Skullsplitter trolls"] = "Trolls Rachacrânio",
		["Snapjaw Crocolisks"] = "Crocoliscos Arapuca",
		["Snapjaw Crocolisks bask on the shore and islands along the coast north of {area:35}."] = "Crocoliscos Arapuca tomam sol na praia e nas ilhas ao longo da costa ao norte de {area:35}.",
		["Stranglethorn Tigers"] = "Tigres-do-espinhaço",
		["Take the road north; {npc:738} patrols it, the camp sits in the hills to the west."] = "Pegue a estrada para o norte; {npc:738} patrulha nela, e o acampamento fica nas colinas a oeste.",
		["The Bloodscalp trolls hold the ruins on the coast west of Nesingwary's camp."] = "Os trolls Sanguescalpo dominam as ruínas na costa a oeste do acampamento de Rosarães.",
		["The Kurzen rebels hold the camp east of the {area:99}; work its outer edge, where Jungle Fighters and Medicine Men stand, and loot the supply crates by the tents."] = "Os rebeldes de Kurzen dominam o complexo a leste de {area:99}; trabalhe pela borda externa, onde ficam os Guerrilheiros da Selva e os Curandeiros, e saqueie os caixotes de suprimentos junto às barracas.",
		["The Skullsplitter trolls hold the ruins east of the road between Nesingwary and {object:3202}."] = "Os trolls Rachacrânio dominam as ruínas a leste da estrada, entre Rosarães e {object:3202}.",
		["The adult tigers prowl the hills just south and west of the camp."] = "Os tigres adultos rondam as colinas logo ao sul e a oeste do acampamento.",
		["The elder tigers come later, on the way back from the {area:99}"] = "Os tigres anciões ficam para depois, na volta de {area:99}",
		["The haunted island"] = "A ilha assombrada",
		["The jungle ruins"] = "As ruínas da selva",
		["The ore drops from Drywhisker kobolds in {zone:1417}"] = "O minério cai dos kobolds Bigodesseco em {zone:1417}",
		["Thorsen patrols the road north of camp, toward the {area:99}."] = "Turgo patrulha a estrada ao norte do acampamento, rumo a {area:99}.",
		["Walk back north; the {area:310} lies west of the road in the middle of the jungle. The Crystal Spine Basilisks there drop the shards."] = "Volte para o norte; {area:310} fica a oeste da estrada, no meio da selva. Os Basiliscos da Serra dos Cristais de lá deixam cair os fragmentos.",
		["Young tigers and panthers"] = "Tigres e panteras jovens",
		["{area:1537} has no druid trainer: take the {area:2257} from {object:171524} to {zone:1453} and train with {npc:5504}."] = "{area:1537} não tem instrutor de druida: pegue o {area:2257} em {object:171524} até {zone:1453} e treine com {npc:5504}.",
		["{item:2634}, from a {object:263} crate"] = "{item:2634}, de um caixote de {object:263}",
		["{npc:2495}, by the bank"] = "{npc:2495}, junto ao banco",
		["{npc:2496}, upstairs in the tavern"] = "{npc:2496}, no andar de cima da taberna",
		["{npc:2832}, in the {object:56910}"] = "{npc:2832}, na {object:56910}",
		["{npc:469}, in the hut"] = "{npc:469}, na cabana",
		["{npc:715}, from {zone:1441}"] = "{npc:715}, de {zone:1441}",
		["{npc:716} collects the {item:2755}: the pages drop from almost every humanoid in the jungle. Turn the pages into chapters as you go."] = "{npc:716} coleciona {item:2755}: as páginas caem de quase todo humanoide da selva. Transforme as páginas em capítulos pelo caminho.",
		["{npc:729} and the Lashtail raptors"] = "{npc:729} e os raptores Batecauda",
		["{npc:729}, the great tiger, lairs on the hilltop south-west of the camp; Lashtail Raptors run south of it, along the way to {area:35}."] = "{npc:729}, o grande tigre, tem seu covil no alto da colina a sudoeste do acampamento; Raptores Batecauda correm ao sul dele, no caminho para {area:35}.",
		["{npc:737}, in the tavern"] = "{npc:737}, na taberna",
		["{npc:770}: for {npc:773} in {area:35}"] = "{npc:770}: para {npc:773}, em {area:35}",
		["{npc:773}, in the tavern"] = "{npc:773}, na taberna",
		["{quest:201}: just look around the hunters' camp"] = "{quest:201}: basta olhar em volta do acampamento dos caçadores",
} end)()
t.guides["forever/alliance/30-40/05-arathi-highlands"] = (function() return {
		["A {npc:2434} lurks unseen on the edge of {area:271}; kill him and read the contract he carries."] = "Um {npc:2434} espreita invisível na borda de {area:271}; mate-o e leia o contrato que ele carrega.",
		["Back west through {zone:1430} to {area:42}."] = "De volta para oeste por {zone:1430} até {area:42}.",
		["Crushridge ogres"] = "Ogros Massacristas",
		["Each key lies at one of the Highlands' standing-stone circles: east of the shards, near {area:320} and in the west. The {object:2702} stands west of {area:320}."] = "Cada chave está num dos círculos de menires do Planalto: a leste dos estilhaços, perto do {area:320} e no oeste. A {object:2702} fica a oeste do {area:320}.",
		["East along the road to the {area:76}. {npc:256028} mobs drop the crystals; Noboru walks the ruins and drops his cudgel."] = "Para leste pela estrada até o {area:76}. Os {npc:256028} deixam cair os cristais; Noboru anda pelas ruínas e deixa cair sua borduna.",
		["Ebenezer Rustlocke"] = "Ebenezer Ferratranca",
		["Escort the professor to the beach north of the cove and guard him while he works; naga attack in waves."] = "Escolte o professor até a praia ao norte da enseada e proteja-o enquanto ele trabalha; os nagas atacam em ondas.",
		["Fly to {area:271}"] = "Voar para {area:271}",
		["Fly to {area:42}"] = "Voar para {area:42}",
		["Fly to {zone:1453}"] = "Voar para {zone:1453}",
		["Follow the road east out of {area:287} over {area:1057} to {area:320}."] = "Siga a estrada para leste saindo de {area:287}, passando a {area:1057}, até o {area:320}.",
		["Follow the road north out of {area:271} into the mountains. Mountain lions roam the slopes; the Syndicate in {area:280} wear the signet rings, and {npc:2306} walks the manor grounds on the north side of town."] = "Siga a estrada para o norte saindo de {area:271} até as montanhas. Leões da montanha vagam pelas encostas; a Camarilha em {area:280} usa os anéis de sinete, e {npc:2306} anda pelos terrenos do solar no lado norte da cidade.",
		["Follow the road north to the draenei of the {area:657}."] = "Siga a estrada para o norte até os draeneis do {area:657}.",
		["Follow the road south over the bridge to {area:205} at the {zone:1437} end, where {npc:1075} waits."] = "Siga a estrada para o sul pela ponte até {area:205}, no lado do {zone:1437}, onde {npc:1075} espera.",
		["For {npc:1440} in {zone:1453}: keep it"] = "Para {npc:1440} em {zone:1453}: guarde-o",
		["For {npc:2487} in {area:35}: keep it"] = "Para {npc:2487} em {area:35}: guarde-o",
		["For {npc:2542} in {area:35}: keep it"] = "Para {npc:2542} em {area:35}: guarde-o",
		["For {npc:2711} in {area:271}"] = "Para {npc:2711} em {area:271}",
		["From {area:42} follow the road east through {zone:1430} into the {zone:1435}; Biggs guards the road junction just inside it. {npc:217412} stands a short way north of him."] = "De {area:42}, siga a estrada para leste por {zone:1430} até o {zone:1435}; Biggs vigia o cruzamento logo na entrada. {npc:217412} fica um pouco ao norte dele.",
		["From {zone:1455} take the tunnel east through {zone:1426} into {zone:1432} and follow the road to {area:144}."] = "De {zone:1455}, pegue o túnel para leste por {zone:1426} até {zone:1432} e siga a estrada até {area:144}.",
		["Gyll, {area:35}"] = "Gyll, {area:35}",
		["Head north past {area:314}; the shards glitter on the hill by the {area:333}."] = "Siga para o norte, passando a {area:314}; os estilhaços brilham na colina junto ao {area:333}.",
		["Only if Gluggle gave you the pendant in Stranglethorn"] = "Só se Glubglub lhe deu o pingente no Espinhaço",
		["Phizzlethorpe"] = "Bruzundanga",
		["Ride back north-east past {area:320}; {npc:2712} and {npc:2713} camp in the hills north of {area:314}."] = "Cavalgue de volta para nordeste, passando o {area:320}; {npc:2712} e {npc:2713} acampam nas colinas ao norte da {area:314}.",
		["Shaman training"] = "Treino de xamã",
		["South-east along the loch to the dig site."] = "Para sudeste ao longo do lago até o sítio de escavação.",
		["South-west to the Kirin Tor camp on the lake shore west of {area:279}, just over the border into {zone:1421}: the {npc:269127} stands there. Archmage Ansirem stands south-east of it, by the dome."] = "Para sudoeste até o acampamento do Kirin Tor na margem do lago a oeste de {area:279}, logo depois da divisa com {zone:1421}: a {npc:269127} fica lá. O Arquimago Ansirem fica a sudeste dela, junto à cúpula.",
		["Stay with {npc:2713} while she sneaks into {area:314} and back; Horde orcs jump you on the way."] = "Fique com {npc:2713} enquanto ela entra às escondidas na {area:314} e volta; orcs da Horda atacam vocês no caminho.",
		["Subdue the succubus"] = "Subjugue a súcubo",
		["The Crushridge ogres hold the hills north of {area:280}. Farther north, a worn wooden chest holds the {item:3706}; {npc:2320} of the {quest:537} stands right by it."] = "Os ogros Massacristas ocupam as colinas ao norte de {area:280}. Mais ao norte, um baú de madeira gasto guarda o {item:3706}; {npc:2320}, do {quest:537}, fica bem ao lado.",
		["The Drywhisker kobolds dig in the gorge east of {area:321} (Horde); skirt the town to the north. They drop both the motes and Krazek's ore."] = "Os kobolds Bigodesseco cavam no desfiladeiro a leste de {area:321} (Horda); contorne a cidade pelo norte. Eles deixam cair tanto as partículas quanto o minério de Krazek.",
		["The Syndicate hold the farm north-west of {area:320}. A {npc:217589} crawls about the farm: catch one with {npc:217412}'s Entomology Starter Kit, then tick it off."] = "A Camarilha ocupa a fazenda a noroeste do {area:320}. Um {npc:217589} rasteja pela fazenda: capture um com o kit de entomologia de {npc:217412} e depois marque-o.",
		["The Witherbark trolls live in the hills south of {area:314}; Witch Doctors stand in the village, Shadow Hunters guard the far end of the valley."] = "Os trolls Cascasseca vivem nas colinas ao sul da {area:314}; os Mandingueiros ficam na aldeia, os Caçadores Sombrios guardam o fundo do vale.",
		["The courier walks the road west of {area:314} with two guards; pull them off the road."] = "A mensageira anda pela estrada a oeste da {area:314} com dois guardas; atraia-os para fora da estrada.",
		["The shards lie at the far end of {area:318}."] = "Os estilhaços estão no fundo do {area:318}.",
		["The tomes lie in the ruined keep west of {area:280}; Argus Shadow Mages hold the ruins."] = "Os tomos estão na fortaleza em ruínas a oeste de {area:280}; Magos das Sombras Argus ocupam as ruínas.",
		["The two wrecks lie in the bay west of the cove. The charts and logs are inside them; the gems lie on the sea floor around them. Daggerspine naga swim the whole bay."] = "Os dois naufrágios ficam na baía a oeste da enseada. As cartas náuticas e os diários estão dentro deles; as gemas estão no fundo do mar em volta. Nagas Espinhadaga nadam pela baía inteira.",
		["The western swamp"] = "O pântano oeste",
		["The wrecked caravan lies off the road near Biggs."] = "A caravana destruída fica fora da estrada, perto de Biggs.",
		["The wrecks"] = "Os naufrágios",
		["Walk back onto the span: Ebenezer lies under its Arathi end."] = "Volte para a ponte: Ebenezer está embaixo da ponta do lado de Arathi.",
		["West along the coast to the goblins' cove; Lolo keeps watch on the rocks above it."] = "Para oeste pela costa até a enseada dos goblins; Lolo vigia das pedras acima dela.",
		["Young crocolisks, Sorrow Spinners and Swamp Jaguars all roam the swamp around the road."] = "Crocoliscos jovens, Tece-mágoas e Jaguares do Pântano vagam pelo pântano em volta da estrada.",
		["{item:2321} for {npc:2438}'s cloak, from {npc:2381}, if you have none"] = "{item:2321} para o manto de {npc:2438}, de {npc:2381}, se você não tiver",
		["{item:3658}: Crushridge ogres"] = "{item:3658}: ogros Massacrista",
		["{item:3659}: the {object:1760}"] = "{item:3659}: {object:1760}",
		["{npc:1141}, {area:17203} road"] = "{npc:1141}, na estrada do {area:17203}",
		["{npc:12336}, Cathedral of Light"] = "{npc:12336}, Catedral da Luz",
		["{npc:1440}, the Royal Library in the keep"] = "{npc:1440}, na Biblioteca Real da fortaleza",
		["{npc:185335}, at the same circle"] = "{npc:185335}, no mesmo círculo",
		["{npc:217412}: three critters to catch in Arathi, {zone:1443} and Stranglethorn"] = "{npc:217412}: três bichinhos para capturar em Arathi, {zone:1443} e no Espinhaço",
		["{npc:217589}: catch it, for {quest:93176}"] = "{npc:217589}: capture-o, para {quest:93176}",
		["{npc:2712} and {npc:2713}"] = "{npc:2712} e {npc:2713}",
		["{npc:2713}'s errand"] = "A tarefa de {npc:2713}",
		["{npc:2793}, an ogre mage, holds the cave at the southern end of the Witherbark valley."] = "{npc:2793}, um ogro mago, ocupa a caverna no extremo sul do vale Cascasseca.",
		["{npc:5391} is caged at the north end of the sanctuary. Free him and keep him alive on the walk out; his strongbox waits by the road afterwards."] = "{npc:5391} está preso numa jaula no extremo norte do santuário. Liberte-o e mantenha-o vivo na saída; o cofre dele aparece depois junto à estrada.",
		["{npc:6122} binds the incubus to you"] = "{npc:6122} vincula o íncubo a você",
		["{npc:6122} waits in the {object:2164}'s cellar, in the {object:2101}. Use the {item:6913} at the summoning circle there and defeat the succubus it calls. If you took {quest:65602}, hand him the {item:190309} too, place it at the same circle and defeat the incubus."] = "{npc:6122} espera no porão do {object:2164}, no {object:2101}. Use o {item:6913} no círculo de evocação de lá e derrote a súcubo que ele chama. Se você pegou {quest:65602}, entregue também a {item:190309} a ele, coloque-a no mesmo círculo e derrote o íncubo.",
		["{quest:65602}, if you took it"] = "{quest:65602}, se você a pegou",
		["{zone:1453} has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455} and train with {npc:258098}. {npc:1573} in the {object:32372} flies to {area:271} too."] = "{zone:1453} não tem instrutor de xamã: pegue o {area:2257} no {object:28027} até {zone:1455} e treine com {npc:258098}. {npc:1573}, na {object:32372}, também voa para {area:271}.",
} end)()
t.guides["forever/alliance/30-40/06-badlands"] = (function() return {
		["Fly to Theramore"] = "Voe para a Ilha Theramore",
		["Follow the road north to {area:608}."] = "Siga a estrada para o norte até {area:608}.",
		["Follow the road south to {area:2407}."] = "Siga a estrada para o sul até {area:2407}.",
		["Follow the road west across the north of {zone:1443} to the ruins of {area:2405}. {npc:11863}'s tower stands on the hill there, on the way to the wreck."] = "Siga a estrada para o oeste pelo norte de {zone:1443} até as ruínas de {area:2405}. A torre de {npc:11863} fica no morro dali, a caminho do naufrágio.",
		["Greater Rock Elementals"] = "Elementais Maiores da Rocha",
		["Lesser Rock Elementals"] = "Elementais Inferiores da Rocha",
		["Maraudine centaurs"] = "Centauros Maraudinos",
		["Ogres and buzzards"] = "Ogros e urubus",
		["Ride back west to the road and follow it south out of {zone:1432} through the pass into the {zone:1418}. {npc:2910} and {npc:2860} camp side by side at the dig."] = "Volte a oeste até a estrada e siga por ela para o sul, saindo de {zone:1432} pelo desfiladeiro até {zone:1418}. {npc:2910} e {npc:2860} acampam lado a lado na escavação.",
		["Ride north-east to the abandoned dig; the supply crate lies there among the Dustbelcher ogres."] = "Cavalgue para o nordeste até a escavação abandonada; o caixote de suprimentos está lá, entre os ogros Arrota-pó.",
		["Ride north-east to the dwarven ruins in the north of the {zone:1418}; the chest sits among the Shadowforge dwarves. {npc:2745} nearby is elite: give him room."] = "Cavalgue para o nordeste até as ruínas anãs no norte de {zone:1418}; o baú fica entre os anões de Umbraforja. {npc:2745}, ali perto, é elite: mantenha distância.",
		["Ride south to {area:345}."] = "Cavalgue para o sul até {area:345}.",
		["Ride west into the {area:1878}; {npc:2921} works by his machines in the middle of it."] = "Cavalgue para o oeste até {area:1878}; {npc:2921} trabalha junto às máquinas dele, no meio da área.",
		["Rock Elementals"] = "Elementais da Rocha",
		["Ryedol's next errand goes into {area:1517}: skip it."] = "A próxima tarefa de Ryedol é em {area:1517}: pule.",
		["Shadowforge camp"] = "Acampamento de Umbraforja",
		["Take the boat to Theramore from the far pier."] = "Pegue o barco para a Ilha Theramore no píer mais distante.",
		["The Dustbelcher ogres camp just south of the valley; any of them drops scrap. Buzzards circle the plain to the east."] = "Os ogros Arrota-pó acampam logo ao sul do vale; qualquer um deles solta sucata. Urubus sobrevoam a planície a leste.",
		["The Greater Rock Elementals (level 42) walk the far south-west corner below {area:342}; pull them one at a time. The Dustbelcher Wyrmhunters and Maulers at {area:342} also drop scrap."] = "Os Elementais Maiores da Rocha (nível 42) andam no extremo sudoeste, abaixo de {area:342}; puxe um de cada vez. Os Caçadores de Serpes e Espancadores Arrota-pó em {area:342} também soltam sucata.",
		["The Lesser Rock Elementals wander the {area:1878} west of {npc:2921}."] = "Os Elementais Inferiores da Rocha vagam por {area:1878}, a oeste de {npc:2921}.",
		["The Maraudine centaurs hold the {area:607} west of the graveyard; every kind drops the totems."] = "Os centauros Maraudinos ocupam {area:607}, a oeste do cemitério; todos os tipos soltam os totens.",
		["The Rock Elementals roam south-east of {npc:2921}; Giant Buzzards and Elder Crag Coyotes share the plain to their west."] = "Os Elementais da Rocha vagam a sudeste de {npc:2921}; Urubus Gigantes e Coiotes Anciões do Rochedo dividem a planície a oeste deles.",
		["The Shadowforge dwarves camp just north of the digsite; the crumpled map lies among their tents. Tunnelers and Darkweavers carry Ryedol's pick. Crag Coyotes roam the slopes around it."] = "Os anões de Umbraforja acampam logo ao norte da escavação; o Mapa Amassado está entre as barracas. Escavadores e Tecetrevas carregam a picareta de Ryedol. Coiotes do Rochedo vagam pelas encostas ao redor.",
		["The battered skeleton lies just east of the ogres, at the edge of the Stonevault trogg camp; the Bonesnappers and Shamans around it drop the flakes. Theldurin sits by the ruined camp further south."] = "O esqueleto danificado fica logo a leste dos ogros, na beira do acampamento dos troggs da Abóbada de Pedra; os Quebraossos e Xamãs ao redor soltam as lascas. Theldurin está sentado junto ao acampamento em ruínas, mais ao sul.",
		["The clams lie on Stranglethorn's north-west coast, in the next guide: keep it"] = "Os mariscos ficam no litoral noroeste da Selva do Espinhaço, no próximo guia: guarde-a",
		["The demons gather at the {area:602} in southern {zone:1443}: felhounds (Mana Eaters, Mage and Ley Hunters), Nether Maidens and Sisters, and Doomwarder Captains around the pit."] = "Os demônios se reúnem em {area:602}, no sul de {zone:1443}: canisvis (Manávoros, Caça-magos e Caçadores do Meridiano), Donzelas e Irmãs do Éter e Capitães dos Guardiões da Ruína ao redor do fosso.",
		["The excavation crate"] = "O caixote da escavação",
		["The flight master stands by the gate of {area:514}; {npc:5083} and {npc:4964} are inside the citadel."] = "O mestre de voo fica junto ao portão de {area:514}; {npc:5083} e {npc:4964} estão dentro da cidadela.",
		["The next guide starts in Theramore."] = "O próximo guia começa na Ilha Theramore.",
		["The skeleton's next task, Murdaloc, waits until the later {zone:1418} guide at 43."] = "A próxima tarefa do esqueleto, Murdaloc, fica para o guia posterior de {zone:1418}, no nível 43.",
		["The wrecked ship's chest lies on the shore just west of {npc:11863}'s tower."] = "O baú do navio naufragado está na praia, logo a oeste da torre de {npc:11863}.",
		["The {area:2657}"] = "{area:2657}",
		["The {object:126260}"] = "{object:126260}",
		["Theramore"] = "Ilha Theramore",
		["Undead Ravagers roam the bone fields south of the Magram village, east of the Coven; at the far south-east, use the {item:15848} to draw the Magrami Spectres."] = "Assoladores Mortos-vivos vagam pelos campos de ossos ao sul da Aldeia Magram, a leste das Ruínas de Mannoroc; no extremo sudeste, use o {item:15848} para atrair os Espectros Magrami.",
		["escort {npc:12277} back toward the graveyard"] = "escolte {npc:12277} de volta ao cemitério",
		["for the Dustwallow loop in the next guide"] = "para o circuito do Pântano Vadeoso no próximo guia",
		["for {npc:2786} in {zone:1455}: keep it"] = "para {npc:2786} em {zone:1455}: guarde-a",
		["for {npc:3980} in {area:271}: keep it"] = "para {npc:3980} em {area:271}: guarde-a",
		["for {npc:4454} in the {area:439}: the {zone:1446} guide crosses them at 45, keep it"] = "para {npc:4454} em {area:439}: o guia de {zone:1446} passa por lá no nível 45; guarde-a",
		["for {npc:5637} in {zone:1455}: keep it"] = "para {npc:5637} em {zone:1455}: guarde-a",
		["only if you carry {item:2868} (a blacksmith's craft)"] = "só se você tiver {item:2868} (feitas por ferreiros)",
		["{npc:11626}'s caravan stops on the road east of {area:606}. Take the quest and walk with the kodos past the {area:602}, killing the demons that jump them; talk to {npc:11596} at his camp east of the {area:596} afterwards."] = "A caravana de {npc:11626} para na estrada a leste de {area:606}. Pegue a missão e acompanhe os kodos, passando por {area:602} e matando os demônios que os atacam; depois fale com {npc:11596} no acampamento dele, a leste de {area:596}.",
		["{npc:12277} is held in the centaur camp west of the graveyard. Free her and keep her alive on the walk out; she stops by the graveyard."] = "{npc:12277} está presa no acampamento centauro a oeste do cemitério. Liberte-a e mantenha-a viva na saída; ela para perto do cemitério.",
		["{npc:12369}, a centaur chieftain, camps on the north-west coast, north of {npc:11863}'s tower."] = "{npc:12369}, um chefe centauro, acampa no litoral noroeste, ao norte da torre de {npc:11863}.",
		["{npc:1470}, in the inn"] = "{npc:1470}, na estalagem",
		["{npc:217590}: catch it, for My Little Friends"] = "{npc:217590}: capture-o, para My Little Friends",
		["{npc:2920}, beside {npc:2921}"] = "{npc:2920}, ao lado de {npc:2921}",
		["{npc:2921}'s next test needs crafted gear: skip it."] = "O próximo teste de {npc:2921} exige equipamento fabricado: pule.",
		["{npc:4618} and {npc:2817} camp together in the {area:1877}, in the middle of the {zone:1418}."] = "{npc:4618} e {npc:2817} acampam juntos em {area:1877}, no meio de {zone:1418}.",
		["{npc:5638}'s next task, {item:6245}, is a drop on the far coast: skip it."] = "A próxima tarefa de {npc:5638}, {item:6245}, é um saque no litoral distante: pule.",
		["{npc:6019} stands at the edge of the {area:596}, south-west of {area:2407}; {object:176751} lie among the skeletons. A {npc:217590} crawls about the graveyard: catch one with the Entomology Starter Kit, then tick it off."] = "{npc:6019} fica na beira de {area:596}, a sudoeste de {area:2407}; {object:176751} estão entre os esqueletos. Um {npc:217590} rasteja pelo cemitério: capture um com o Entomology Starter Kit e depois marque o objetivo.",
} end)()
t.guides["forever/alliance/40-50/01-stranglethorn-vale"] = (function() return {
		["\"Stinky\" Ignatz"] = "Inácio \"Cascão\"",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. No Skyborne riding trainer is known; the Forever client files {spell:1285849} under the one Riding skill, so {npc:4732} at {area:88} in eastern {zone:1429}, the nearest trainer to {zone:1453}, should teach it (unconfirmed). The Galestriders are sold by {npc:265756} in {area:16638} on Zephras Isle; Collectibles, Mounts · Level 40 lists them."] = "No nível 40, com 100 de ouro, você pode aprender a montar, e aprender lhe dá uma montaria. Não se conhece instrutor de montaria celonato; o cliente Forever coloca {spell:1285849} sob a mesma perícia de Montaria, então {npc:4732}, em {area:88} no leste de {zone:1429}, o instrutor mais perto de {zone:1453}, deve ensiná-la (não confirmado). Os Vagaventos são vendidos por {npc:265756} em {area:16638}, na Ilha de Zefras; Colecionáveis, Montarias · Nível 40 lista todos.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4732} teaches Humans at {area:88} in eastern {zone:1429}, beside {npc:384}'s horses. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "No nível 40, com 100 de ouro, você pode aprender a montar, e aprender lhe dá uma montaria. {npc:4732} ensina Humanos em {area:88}, no leste de {zone:1429}, ao lado dos cavalos de {npc:384}. O Forever talvez deixe qualquer raça aprender com qualquer instrutor de montaria (não confirmado). Colecionáveis, Montarias · Nível 40 lista todas as cores.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4753} teaches Night Elves in {zone:1457}, beside {npc:4730}'s sabers: the boat from {area:17203} to {area:442}, then the flight to {area:702}. Forever may let any race learn from any riding trainer (unconfirmed), such as {npc:4732} at {area:88} in {zone:1429}. Collectibles, Mounts · Level 40 lists every colour."] = "No nível 40, com 100 de ouro, você pode aprender a montar, e aprender lhe dá uma montaria. {npc:4753} ensina Elfos Noturnos em {zone:1457}, ao lado dos sabres de {npc:4730}: o barco de {area:17203} para {area:442}, depois o voo até {area:702}. O Forever talvez deixe qualquer raça aprender com qualquer instrutor de montaria (não confirmado), como {npc:4732}, em {area:88}, {zone:1429}. Colecionáveis, Montarias · Nível 40 lista todas as cores.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:4772} teaches Dwarves at {area:803}, east of {area:131} on the road to {zone:1432}, beside {npc:1261}'s rams. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "No nível 40, com 100 de ouro, você pode aprender a montar, e aprender lhe dá uma montaria. {npc:4772} ensina Anões em {area:803}, a leste de {area:131}, na estrada para {zone:1432}, ao lado dos carneiros de {npc:1261}. O Forever talvez deixe qualquer raça aprender com qualquer instrutor de montaria (não confirmado). Colecionáveis, Montarias · Nível 40 lista todas as cores.",
		["At 40 with 100 gold you can learn to ride, and learning it gives you a mount. {npc:7954} teaches Gnomes at {area:189}, just east of {area:131}, beside {npc:7955}'s mechanostriders. Forever may let any race learn from any riding trainer (unconfirmed). Collectibles, Mounts · Level 40 lists every colour."] = "No nível 40, com 100 de ouro, você pode aprender a montar, e aprender lhe dá uma montaria. {npc:7954} ensina Gnomos em {area:189}, logo a leste de {area:131}, ao lado dos mecanostriders de {npc:7955}. O Forever talvez deixe qualquer raça aprender com qualquer instrutor de montaria (não confirmado). Colecionáveis, Montarias · Nível 40 lista todas as cores.",
		["Back in Theramore: Tervosh waits with Lady Jaina in the tower of {area:514}."] = "De volta a Theramore: Tervosh espera com a Grã-senhora Jaina na torre de {area:514}.",
		["Bloodsail camp"] = "Acampamento da Vela Sangrenta",
		["Bloodsail pirates"] = "Piratas da Vela Sangrenta",
		["Boat to {area:35}"] = "Barco para {area:35}",
		["Cold Eye Basilisks"] = "Basiliscos Olho Frio",
		["Defeat the challengers and {npc:6238}"] = "Derrote os desafiantes e {npc:6238}",
		["Every Bloodsail drops Snuff and one of them carries {npc:2493}'s eye; the Swashbucklers walk the shore just north of town. The charts and orders lie in the pirate camp on the {area:43}, south of {area:35}."] = "Todo pirata da Vela Sangrenta deixa cair Rapé, e um deles leva o olho de {npc:2493}; os Espadachins andam pela praia logo ao norte da cidade. As cartas náuticas e as ordens estão no acampamento pirata em {area:43}, ao sul de {area:35}.",
		["Every Zanzil follower can drop the mixture; {npc:2537} walks the south of the camp."] = "Qualquer seguidor de Zanzil pode deixar cair o preparado; {npc:2537} anda pelo sul do acampamento.",
		["Fly to {area:42} and ride east through {zone:1430} into the {zone:1435}; {npc:5476} stands by the road just past the border."] = "Voe para {area:42} e siga para o leste por {zone:1430} até {zone:1435}; {npc:5476} fica junto à estrada, logo depois da fronteira.",
		["Follow the road east back to Theramore. Tervosh, Lady Jaina and the officers are in the tower and {area:514}."] = "Siga a estrada para o leste de volta a Theramore. Tervosh, a Grã-senhora Jaina e os oficiais estão na torre e em {area:514}.",
		["Follow the road north-east to the Venture Co. camp at the {area:310}; the miners, surveyors and foremen drop the crystals."] = "Siga a estrada para nordeste até o acampamento da Empreendimentos S.A. em {area:310}; os mineradores, topógrafos e encarregados deixam cair os cristais.",
		["Follow the road north-west out of Theramore to the watchtower at {area:503}. Mudrock Burrowers roam the marsh around it."] = "Siga a estrada para noroeste, saindo de Theramore, até a torre de vigia em {area:503}. Toqueiras Pedralama vagam pelo brejo ao redor.",
		["Galestriders: {npc:265756}, in {area:16638} on Zephras Isle."] = "Vagaventos: {npc:265756}, em {area:16638}, na Ilha de Zefras.",
		["Gorilla hills"] = "Colinas dos gorilas",
		["Hand in the fangs and stay: three waves of gorillas come, {npc:1514} last. Fight at full health."] = "Entregue as presas e fique: vêm três ondas de gorilas, {npc:1514} por último. Lute com a vida cheia.",
		["Leave town by the tunnel and follow the coast north; the letter lies in the Bloodsail camp on the beach, where \"Pretty Boy\" Duncan walks."] = "Saia da cidade pelo túnel e siga a costa para o norte; a carta está no acampamento da Vela Sangrenta, na praia, onde anda Duncan \"Bonitão\".",
		["MacKinley's next task sends you after elite ogres: skip it."] = "A próxima tarefa de MacKinley manda você atrás de ogros elite: pule-a.",
		["Mirefin murlocs"] = "Murlocs Lamapina",
		["Mudrock tortoises"] = "Quelônios Pedralama",
		["Naga Explorers"] = "Exploradores Nagas",
		["On the ride north to {area:392}, {area:720} lies off the {area:391} south of the town: wade over the sand bar shallows. {npc:6236} sends four challengers and then {npc:6238} (level 33) at you, one at a time."] = "No caminho para o norte até {area:392}, {area:720} fica perto de {area:391}, ao sul da cidade: atravesse a pé o banco de areia. {npc:6236} manda quatro desafiantes e depois {npc:6238} (nível 33) contra você, um de cada vez.",
		["Paladin: {quest:1661}"] = "Paladino: {quest:1661}",
		["Ride back down to town; Shaky stands at the tunnel mouth."] = "Volte para a cidade; Sacode fica na entrada do túnel.",
		["Ride back west along the road; {npc:217412} stands a short way north of Biggs."] = "Volte para o oeste pela estrada; {npc:217412} fica um pouco ao norte de Biggs.",
		["Ride east; the Tangled Horrors along the way also drop the essays. Search the edge of the {area:74}, where the temple's ruins break the water."] = "Siga para o leste; os Horrores Emaranhados no caminho também deixam cair os ensaios. Procure na borda de {area:74}, onde as ruínas do templo saem da água.",
		["Ride from Theramore west along the Dustwallow road into the {zone:1413} and north to {area:392} on the coast. Learn the flight path from {npc:16227}, then take the boat to {area:35} from the dock."] = "Siga de Theramore para o oeste pela estrada do Pântano Vadeoso até {zone:1413} e depois para o norte até {area:392}, na costa. Aprenda a rota de voo com {npc:16227} e pegue o barco para {area:35} no cais.",
		["Ride inland to the Mistvale gorilla hills. Elder Mistvale Gorillas drop the giblets; {npc:1449} sits among them."] = "Siga para o interior até as colinas dos gorilas do Vale da Névoa. Gorilas Anciões do Vale da Névoa deixam cair os miúdos; {npc:1449} fica entre eles.",
		["Ride north to the hills west of the road. {npc:2535} and {npc:2536} stand together just north of Zanzil's village."] = "Siga para o norte até as colinas a oeste da estrada. {npc:2535} e {npc:2536} ficam juntos, logo ao norte da aldeia de Zanzil.",
		["Ride north-east past Nesingwary's camp and follow the road north to the camp at the top of the vale. On the way, an {npc:217588} crawls in the jungle south-east of Nesingwary's camp: catch one with the Entomology Starter Kit, then tick it off."] = "Siga para nordeste, passando o acampamento de Rosarães, e pegue a estrada para o norte até o acampamento no alto do vale. No caminho, uma {npc:217588} rasteja na selva a sudeste do acampamento de Rosarães: capture uma com o Entomology Starter Kit e marque-a.",
		["Ride north-west from the mine to the bay on the north-west coast. The Giant Clams lie on its floor and hold the pearls; {npc:2624} swims among them and drops the {item:4034}."] = "Siga para noroeste a partir da mina até a baía na costa noroeste. Os Mariscos Gigantes ficam no fundo dela e guardam as pérolas; {npc:2624} nada entre eles e deixa cair {item:4034}.",
		["Ride south to the giant's hut in the middle of the marsh."] = "Siga para o sul até a cabana do gigante, no meio do pântano.",
		["Riding at 40"] = "Montaria no nível 40",
		["Seahorn's next errand goes back to Arathi: skip it."] = "A próxima tarefa de Chifre do Mar volta para Arathi: pule-a.",
		["Skullsplitter ruins"] = "Ruínas Rachacrânio",
		["Stinky waits west of the manor, in the marsh below {area:504}. Lead him to his Bogbean leaves and keep the swamp creatures off him."] = "Cascão espera a oeste do casarão, no brejo abaixo de {area:504}. Leve-o até as folhas de trevo aquático e afaste as criaturas do pântano dele.",
		["Take the road north to the ruined manor; Jarl lives in the shack beside it and the loose dirt is at the corner of the house."] = "Pegue a estrada para o norte até o casarão em ruínas; Zé mora no barraco ao lado, e a terra solta fica no canto da casa.",
		["Take the {area:2257} from the {object:28027}. {npc:5637} is in the Reclaimers' hall by the {object:32356}, {npc:1356} in the hall itself, {npc:2786} in the {object:32383}. The next guide flies on to {area:144}."] = "Pegue o {area:2257} no {object:28027}. {npc:5637} fica no salão da Recuperação Ilimitada, junto a {object:32356}; {npc:1356}, no próprio salão; {npc:2786}, em {object:32383}. O próximo guia voa até {area:144}.",
		["The Bloodsail captains"] = "Os capitães da Vela Sangrenta",
		["The Cold Eye Basilisks lie on the rocks west of the mine."] = "Os Basiliscos Olho Frio ficam nas rochas a oeste da mina.",
		["The Darkmist spiders nest around the cavern in the north-west of the marsh; every spider drops eyes."] = "As aranhas Névoa Negra fazem ninho ao redor da caverna no noroeste do pântano; toda aranha deixa cair olhos.",
		["The Mirefin murlocs crowd the north coast past {area:497}; finish the tongues on the tortoises beside them."] = "Os murlocs Lamapina lotam a costa norte depois de {area:497}; complete as línguas nos quelônios ao lado deles.",
		["The Mudrock Tortoises and Spikeshells sun themselves on the shore north-east of the manor."] = "Os Quelônios Pedralama e as Espicascas tomam sol na praia a nordeste do casarão.",
		["The Skullsplitter trolls hold the ruins just east of the mine; any of them can drop tusks, their panthers always do."] = "Os trolls Rachacrânio dominam as ruínas logo a leste da mina; qualquer um deles pode deixar cair presas, e suas panteras sempre deixam.",
		["The burned inn stands on the road west, toward the {zone:1413}; the guard's badge lies in the ashes and the hoofprints are in the mud beside the inn."] = "A estalagem queimada fica na estrada para o oeste, rumo a {zone:1413}; a insígnia do guarda está nas cinzas, e as pegadas de casco, na lama ao lado da estalagem.",
		["The captains stand on the ships anchored off the {area:43}, each with a crew of 42-45 pirates: Stillwater (45) and Keelhaul (46) on the nearer decks, {npc:2546} (48) on the flagship. At 42 this is a fight for a group or for the end of the guide; clear each deck first if you go. Cortello's scroll lies on the wreck by the shore."] = "Os capitães ficam nos navios ancorados perto de {area:43}, cada um com uma tripulação de piratas de nível 42-45: Tranquiláguas (45) e Querena (46) nos conveses mais próximos, {npc:2546} (48) na nau capitânia. No nível 42 é luta para grupo ou para o fim do guia; se for, limpe cada convés antes. O pergaminho de Cortello está no naufrágio junto à praia.",
		["The deserters camp south of the road, west of {npc:4503}'s hut."] = "Os desertores acampam ao sul da estrada, a oeste da cabana de {npc:4503}.",
		["The driftwood washes up along the eastern shore."] = "A madeira flutuante chega à praia ao longo da margem leste.",
		["The naga comb the beaches north of the Bloodsail camp; they drop the reeds."] = "Os nagas vasculham as praias ao norte do acampamento da Vela Sangrenta; eles deixam cair os juncos.",
		["The north-west coast"] = "A costa noroeste",
		["The riddle's next scroll lies in western Dustwallow: skip it."] = "O próximo pergaminho da charada fica no oeste do Pântano Vadeoso: pule-o.",
		["The scroll lies in the marsh north of Biggs. The Swampwalkers north of it can drop Khadgar's essays."] = "O pergaminho fica no brejo ao norte de Biggs. Os Errantes do Pântano ao norte dele podem deixar cair os ensaios de Hadggar.",
		["The sunken temple"] = "O templo submerso",
		["Theramore"] = "Theramore",
		["Unbagwa's ritual"] = "O ritual de Unbagwa",
		["Warlock: {quest:3631}"] = "Bruxo: {quest:3631}",
		["Zanzil's village"] = "Aldeia de Zanzil",
		["for Stoley in {zone:1446}: keep it"] = "para Esmirno, em {zone:1446}: guarde",
		["for the {zone:1435} later"] = "para {zone:1435}, mais tarde",
		["for {area:1438}: keep it"] = "para {area:1438}: guarde",
		["for {npc:2616} in Theramore: keep it"] = "para {npc:2616}, em Theramore: guarde",
		["for {npc:5635} at {area:348}: keep it"] = "para {npc:5635}, em {area:348}: guarde",
		["for {npc:770} at the {area:99}, on the northern loop"] = "para {npc:770}, em {area:99}, no circuito norte",
		["only if you carry a {item:3853} (a blacksmith's craft)"] = "só se você tiver uma {item:3853} (criação de ferreiro)",
		["with the spices from Theramore"] = "com os temperos de Theramore",
		["{item:3713}, for \"Swamp Eye\" Jarl"] = "{item:3713}, para Zé \"Olho de Lama\"",
		["{npc:1141} cooks in the {object:2169}; {npc:5384} is in the {object:28027}."] = "{npc:1141} cozinha em {object:2169}; {npc:5384} fica em {object:28027}.",
		["{npc:1261}: other colours, 20g"] = "{npc:1261}: outras cores, 20g",
		["{npc:1356}: for {npc:1344} in {zone:1432}, keep it"] = "{npc:1356}: para {npc:1344}, em {zone:1432}, guarde",
		["{npc:1440}, the Royal Library in {object:2117}"] = "{npc:1440}, na Biblioteca Real, em {object:2117}",
		["{npc:217412}: {quest:93176}, from 30-40/05-arathi-highlands"] = "{npc:217412}: {quest:93176}, de 30-40/05-arathi-highlands",
		["{npc:217588}: catch it, for {quest:93176}"] = "{npc:217588}: capture-a, para {quest:93176}",
		["{npc:2487}, top floor"] = "{npc:2487}, último andar",
		["{npc:2498}'s next Zanzil errand starts in {zone:1441}: skip it."] = "A próxima tarefa de {npc:2498} sobre Zanzil começa em {zone:1441}: pule-a.",
		["{npc:2535} and {npc:2536}"] = "{npc:2535} e {npc:2536}",
		["{npc:2624} swims off the north-west coast, on the northern loop"] = "{npc:2624} nada perto da costa noroeste, no circuito norte",
		["{npc:384}: other colours, 20g"] = "{npc:384}: outras cores, 20g",
		["{npc:461}, in the {object:2164}: {npc:6251} in {area:392} takes it at the end of the next guide"] = "{npc:461}, em {object:2164}: {npc:6251}, em {area:392}, recebe no fim do próximo guia",
		["{npc:4730}: other colours, 20g"] = "{npc:4730}: outras cores, 20g",
		["{npc:4966} holds the tower with a few deserters. He turns on you: beat him until he yields."] = "{npc:4966} ocupa a torre com alguns desertores. Ele se volta contra você: bata nele até ele se render.",
		["{npc:5694}: for {area:1438}, keep it"] = "{npc:5694}: para {area:1438}, guarde",
		["{npc:6171}, in the Cathedral of Light"] = "{npc:6171}, na Catedral da Luz",
		["{npc:6236} offers The Windwatcher next (1791): the Whirlwind weapon chain, with an elite at the end, is in the Warrior class guide Whirlwind Weapon."] = "Em seguida, {npc:6236} oferece O vigia dos ventos (1791): a série da arma de Redemoinho, com um elite no fim, está no guia de classe de Guerreiro Arma do redemoinho.",
		["{npc:773}: for {quest:2864} in {zone:1446}, keep it"] = "{npc:773}: para {quest:2864}, em {zone:1446}, guarde",
		["{npc:7955}: other colours, 20g"] = "{npc:7955}: outras cores, 20g",
		["{object:56910} is the tall building over the harbour; most of the quest givers are on its floors or the docks below."] = "{object:56910} é o prédio alto sobre o porto; a maioria dos recrutadores de missões fica nos andares dele ou nas docas abaixo.",
		["{quest:1260} stands near the inn; {npc:4897}, a trade supplier a few steps south, sells the spices Jarl wants."] = "{quest:1260} fica perto da estalagem; {npc:4897}, um fornecedor de comércio alguns passos ao sul, vende os temperos que Zé quer.",
		["{zone:1453} has no shaman trainer"] = "{zone:1453} não tem instrutor de xamã",
} end)()
t.guides["forever/alliance/40-50/02-badlands"] = (function() return {
		["Blue Pearls from Stranglethorn"] = "Pérolas Azuis da Selva do Espinhaço",
		["Fly to {area:392}; {npc:6251} teaches in the house by the bank. Fly back to Theramore afterwards."] = "Voe para {area:392}; {npc:6251} ensina na casa junto ao banco. Depois volte voando para a Ilha Theramore.",
		["Fly to {area:608}, ride south through {zone:1443} into {zone:1444} and follow the road to the dock on the {area:1108}; the boat crosses to {area:1116}, where the next guide starts."] = "Voe para {area:608}, cavalgue para o sul por {zone:1443} até {zone:1444} e siga a estrada até o cais em {area:1108}; o barco atravessa até {area:1116}, onde começa o próximo guia.",
		["On to Feathermoon"] = "Rumo a Plumaluna",
		["Raleigh's next errand is in the {area:796}: skip it."] = "A próxima tarefa de Raul é em {area:796}: pule.",
		["Ride back east to {area:1898}."] = "Volte a leste até {area:1898}.",
		["Ride north to {area:144} and fly to {area:271}. {npc:3980} preaches by the inn."] = "Cavalgue para o norte até {area:144} e voe para {area:271}. {npc:3980} prega junto à estalagem.",
		["Ride north-east out of {area:271} on the road into the {zone:1425}; {area:348} sits just past the border. {npc:5635} holds court at the top, {quest:1450} tends the aviary and {npc:7884} stands by the inn."] = "Saia de {area:271} para o nordeste pela estrada até as {zone:1425}; {area:348} fica logo depois da divisa. {npc:5635} recebe a corte no alto, {quest:1450} cuida do aviário e {npc:7884} fica junto à estalagem.",
		["Ride south out of {zone:1432} through the pass into the {zone:1418}; {npc:2860} camps at the dig."] = "Cavalgue para o sul, saindo de {zone:1432} pelo desfiladeiro até {zone:1418}; {npc:2860} acampa na escavação.",
		["Ride west across the {zone:1418} to the Dustbelcher camp at {area:342}. {npc:2944} stands in its middle with Wyrmhunters and Maulers around him."] = "Cavalgue para o oeste por {zone:1418} até o acampamento Arrota-pó em {area:342}. {npc:2944} fica no meio, cercado de Caçadores de Serpes e Espancadores.",
		["Ride west to the {area:1877} in the middle of the {zone:1418}; {npc:2817} camps beside Martek."] = "Cavalgue para o oeste até {area:1877}, no meio de {zone:1418}; {npc:2817} acampa ao lado de Martek.",
		["Take the boat to Theramore from the far pier."] = "Pegue o barco para a Ilha Theramore no píer mais distante.",
		["Talonaxe's next task waits for a later {zone:1425} guide."] = "A próxima tarefa de Garra-de-acha fica para um guia posterior das {zone:1425}.",
		["The Scalding Whelps nest in the ravine east of {npc:2888}; leave the Scorched Guardians (elite) alone. The {item:4612} drops rarely: take it if it comes while you grind."] = "Os Dragonetes Escaldantes fazem ninho na ravina a leste de {npc:2888}; deixe os Guardiões Flâmeos (elite) em paz. {item:4612} cai raramente: pegue se aparecer enquanto você farma.",
		["The battered skeleton lies at the edge of the Stonevault trogg camp; {quest:739}, Agmond's killer, walks among the Bonesnappers."] = "O esqueleto danificado fica na beira do acampamento dos troggs da Abóbada de Pedra; {quest:739}, o assassino de Agmundo, anda entre os Quebraossos.",
		["The first two cages stand together in the Witherbark village south of {npc:5634}; the third is in the next village to the east. Every Witherbark troll can drop a necklace."] = "As duas primeiras jaulas ficam juntas na aldeia Cascasseca ao sul de {npc:5634}; a terceira está na aldeia seguinte, a leste. Qualquer troll Cascasseca pode soltar um colar.",
		["Theramore"] = "Ilha Theramore",
		["Warlock: {quest:3631}"] = "Bruxo: {quest:3631}",
		["Witherbark villages"] = "Aldeias Cascasseca",
		["grind on {npc:2725} at {area:339}, {zone:1418}"] = "farme {npc:2725} em {area:339}, {zone:1418}",
		["{npc:1573}, the {object:32372}"] = "{npc:1573}, {object:32372}",
		["{npc:2616} stands on the docks where the boat lands."] = "{npc:2616} fica nas docas onde o barco atraca.",
		["{npc:2817}'s next quest pays no experience: skip it."] = "A próxima missão de {npc:2817} não dá experiência: pule.",
		["{npc:2888} camps by himself in {area:1898}, south-east of the digsite."] = "{npc:2888} acampa sozinho em {area:1898}, a sudeste da escavação.",
		["{npc:2888}'s next task is an elite hunt: skip it."] = "A próxima tarefa de {npc:2888} é uma caçada elite: pule.",
		["{npc:5634} camps on the road east of {area:348}."] = "{npc:5634} acampa na estrada a leste de {area:348}.",
		["{npc:5634}'s cocktail needs parts from Kalimdor: skip it."] = "O coquetel de {npc:5634} precisa de ingredientes de Kalimdor: pule.",
		["{npc:5636}, beside the flight master at the top"] = "{npc:5636}, ao lado do mestre de voo, no alto",
		["{npc:7884} keeps paying for necklaces: hand in any extras"] = "{npc:7884} continua pagando pelos colares: entregue os que sobrarem",
} end)()
t.guides["forever/alliance/40-50/03-feralas"] = (function() return {
		["Back to the {area:1117}. Every Hatecrest naga there can drop scales."] = "Volte a {area:1117}. Todo naga Cristafúria de lá pode deixar cair escamas.",
		["Boat to the {area:1108} and ride east across {zone:1444} to the Grimtotem camp north of the road. {npc:7956} waits outside it; free the Sprite Darters from the pen in the middle and keep {npc:7956} and at least six of them alive."] = "Barco para {area:1108} e cavalgue para leste por {zone:1444} até o acampamento Temível Totem ao norte da estrada. {npc:7956} espera do lado de fora; liberte os Dardejantes do cercado no meio e mantenha {npc:7956} e pelo menos seis deles vivos.",
		["Boat to the {area:1108} and ride east into {area:1105}. {npc:14637}'s quests on the coast need level 45."] = "Barco para {area:1108} e cavalgue para leste até {area:1105}. As missões de {npc:14637} na costa exigem nível 45.",
		["From Theramore, fly to {area:608} and ride south out of {zone:1443} into {zone:1444}; the road leads west to the {area:1108} dock, where the boat crosses to Feathermoon on {area:1120}."] = "De Theramore, voe para {area:608} e cavalgue para o sul, saindo de {zone:1443} para {zone:1444}; a estrada leva a oeste até a doca de {area:1108}, onde o barco atravessa para o Domínio de Plumaluna em {area:1120}.",
		["Giants and elementals"] = "Gigantes e elementais",
		["Gordunni ogres"] = "Ogros Gordunni",
		["Grimtotem camp"] = "Acampamento Temível Totem",
		["Grimtotem tauren"] = "Taurens Temível Totem",
		["Grind to 45"] = "Farme até o 45",
		["Hatecrest naga"] = "Nagas Cristafúria",
		["Hearth to Feathermoon."] = "Pedra de Regresso para o Domínio de Plumaluna.",
		["Rage Scar yetis"] = "Yetis Cortifúria",
		["Ride back north-west to the {area:1108} dock and take the boat to the island."] = "Volte cavalgando para noroeste até a doca de {area:1108} e pegue o barco para a ilha.",
		["Ride back to the {area:1108}; the goblin stands by the dock."] = "Volte cavalgando para {area:1108}; o goblin fica junto à doca.",
		["Ride back west along the road, then north into the Rage Scar hills. Every yeti here can drop a hide; one may drop a {quest:7735}, which {npc:7852} pays for too."] = "Volte para oeste pela estrada e depois para o norte até as colinas dos Yetis Cortifúria. Todo yeti daqui pode deixar cair um couro; um pode deixar cair um {quest:7735}, que {npc:7852} também paga.",
		["Ride east to the Gordunni camp in the hills south-east of the yeti valley: Warlocks and Shaman hold the camp, Brutes wander the slopes around it and further north."] = "Cavalgue para leste até o acampamento Gordunni nas colinas a sudeste do vale dos yetis: Bruxos Gordunni e Xamãs Gordunni ocupam o acampamento, Brutamontes Gordunni vagam pelas encostas ao redor e mais ao norte.",
		["Ride north into the yeti valley. Every Feral Scar yeti can drop a thick hide; {npc:5346} (level 48) prowls the middle."] = "Cavalgue para o norte até o vale dos yetis. Todo Yeti Abominável pode deixar cair um couro grosso; {npc:5346} (nível 48) ronda o meio.",
		["Ride north-east to the night elf outpost on the {zone:1441} border."] = "Cavalgue para nordeste até o posto avançado dos elfos noturnos na fronteira de {zone:1441}.",
		["Ride south-east to the Woodpaw gnolls; the courier's backpacks lie in their southern camp, and a parcel inside them starts a delivery to {area:489}. The Zukk'ash hive is just south: fight down to the pod that holds Raschal, free him and keep him alive on the way out."] = "Cavalgue para sudeste até os gnolls Patábua; as mochilas do mensageiro estão no acampamento sul deles, e um pacote dentro delas inicia uma entrega para {area:489}. A colmeia Zukk'ash fica logo ao sul: lute até o casulo que prende Patiphe, o Mensageiro, liberte-o e mantenha-o vivo na saída.",
		["Ride west to the friendly mountain giant at the foot of the hills. Land Walkers and Cliff Giants around him are elite: give them room."] = "Cavalgue para oeste até o gigante da montanha amistoso ao pé das colinas. Os Terrâmbulos e Gigantes do Penhasco ao redor dele são elite: mantenha distância.",
		["Ring the bell whenever {npc:7774} stops to wander, and lead her south to {npc:7765}."] = "Toque o sino sempre que {npc:7774} parar para vagar e leve-a para o sul até {npc:7765}.",
		["Running {area:978} instead of grinding gets you there faster in a group. The troll city lies in northern {zone:1446}, the next zone on the route; come back to {npc:14637} on the {area:1108} afterwards."] = "Fazer {area:978} em vez de farmar leva você lá mais rápido em grupo. A cidade troll fica no norte de {zone:1446}, a próxima zona da rota; depois volte a {npc:14637} em {area:1108}.",
		["Shore Striders, Deep Striders and Wave Striders (elite giants) wade along the coast north of the dock: zap one with {item:18904} and kill the shrunken giant. Sea Elementals and Sea Sprays drift in the same surf."] = "Costívagos, Fundívagos e Ondarilhos (gigantes elite) andam pela costa ao norte da doca: atinja um com {item:18904} e mate o gigante encolhido. Elementais do Mar e Borrifos do Mar flutuam na mesma rebentação.",
		["Swim south from the island to the {area:1121}. Hatecrest Serpent Guards and Sorceresses hold it; {npc:8136} (level 47) waits in the cave at its south end. Pull his guards first."] = "Nade para o sul da ilha até {area:1121}. Serpentes Guardas Cristafúria e Feiticeiras Cristafúria a ocupam; {npc:8136} (nível 47) espera na caverna no extremo sul. Puxe os guardas dele primeiro.",
		["Take the boat to the {area:1108} and follow the shore south to the wrecked row boat on the beach."] = "Pegue o barco para {area:1108} e siga a costa para o sul até a Canoa Destruída na praia.",
		["The courier's boat"] = "O barco do mensageiro",
		["Walk south along the island to the naga ruins; the gazebo stands among them."] = "Caminhe para o sul pela ilha até as ruínas dos nagas; o mirante fica entre elas.",
		["You end at the {area:1108} dock: the {zone:1446} guide starts with the trip east from here."] = "Você termina na doca de {area:1108}: o guia de {zone:1446} começa com a viagem para leste a partir daqui.",
		["for Tyrande in {zone:1457}: the route takes you there at 47"] = "para Tyrande Murmuréolo em {zone:1457}: a rota leva você lá no 47",
		["grind on {npc:5292} at {area:1105}, {zone:1444}"] = "farme {npc:5292} em {area:1105}, {zone:1444}",
		["if you carry {quest:1100} from {zone:1441}"] = "se você trouxer {quest:1100} de {zone:1441}",
		["{area:978} instead of grinding"] = "{area:978} em vez de farmar",
		["{item:11463}, from the backpacks"] = "{item:11463}, das mochilas",
		["{npc:14637}'s refills are level 55: skip them."] = "As recargas de {npc:14637} são de nível 55: pule-as.",
		["{npc:3936} then asks you to carry news to {zone:1457}: skip it, {area:976} sends you there instead."] = "{npc:3936} então pede que você leve notícias a {zone:1457}: pule, {area:976} manda você lá em vez disso.",
		["{npc:3936}, beside him"] = "{npc:3936}, ao lado dele",
		["{npc:7764}: his answer waits in {area:702}, later"] = "{npc:7764}: a resposta dele espera em {area:702}, mais tarde",
		["{npc:7774} wanders the hills north of {npc:7765}, among the Northspring harpies; her bell is in the chest beside her."] = "{npc:7774} vaga pelas colinas ao norte de {npc:7765}, entre as harpias da Nascente Norte; o sino dela está no baú ao lado.",
		["{npc:7774}'s escort"] = "A escolta de {npc:7774}",
		["{npc:7877}, at the top of the stronghold"] = "{npc:7877}, no alto do bastião",
		["{npc:8136} waits for the end of the mainland loop."] = "{npc:8136} fica para o fim do circuito no continente.",
} end)()
t.guides["forever/alliance/40-50/04-tanaris"] = (function() return {
		["Fly from {area:976} to Theramore, take the boat to {area:150} and fly to {area:1537}. Train."] = "Voe de {area:976} para Theramore, pegue o barco para {area:150} e voe para {area:1537}. Treine.",
		["Fly to {area:348}. {zone:1425} guide starts here."] = "Voe para {area:348}. O guia de {zone:1425} começa aqui.",
		["Follow the coast south to the pirate cove. Southsea pirates crowd the beach and the boats: work along the edge and pull one at a time. {npc:7883} stands on the far side; {npc:7881}'s stolen cargo lies in the camp."] = "Siga a costa para o sul até a enseada dos piratas. Os Piratas dos Mares do Sul lotam a praia e os barcos: avance pela borda e puxe um de cada vez. {npc:7883} fica do outro lado; a carga roubada de {npc:7881} está no acampamento.",
		["From the {area:1108} dock, boat to Feathermoon and fly to {area:489}, then ride east through {zone:1441} to the {area:2240} on the {area:439}. {npc:4454} and {npc:4630} are in the camps beside the track; {npc:4709} stands by the goblin camp."] = "Do cais de {area:1108}, pegue o barco para Plumaluna e voe para {area:489}; depois cavalgue para o leste por {zone:1441} até a {area:2240} em {area:439}. {npc:4454} e {npc:4630} estão nos acampamentos ao lado da pista; {npc:4709} fica junto ao acampamento goblin.",
		["Gives the {item:8585}"] = "Dá o {item:8585}",
		["He runs off to keep Rizzle busy"] = "Ele sai correndo para distrair o Rebu",
		["Hearth to {area:976}."] = "Use a Pedra de Regresso para {area:976}.",
		["Pool by {area:979}"] = "Lagoa junto a {area:979}",
		["Ride back west to {area:976}."] = "Cavalgue de volta para o oeste até {area:976}.",
		["Ride back west toward {area:976}. The Wastewander bandits and thieves hold the dunes on the way; any of them can carry a water pouch."] = "Cavalgue de volta para o oeste rumo a {area:976}. Os Bandidos Errantes e os Ladrões Errantes dominam as dunas no caminho; qualquer um deles pode carregar um cantil de água.",
		["Ride east across the dunes to the goblin harbour on the north-east coast."] = "Cavalgue para o leste pelas dunas até o porto goblin na costa nordeste.",
		["Ride north-west to the Centipaar hive in the dunes. Any Centipaar can drop insect parts."] = "Cavalgue para o noroeste até a colmeia Centiparte nas dunas. Qualquer Centiparte pode deixar cair partes de inseto.",
		["Ride north-west to the Sandfury troll camp at {area:979}. Use the {item:8584} at the edge of its pool; the trolls stand close, so pull the nearest first."] = "Cavalgue para o noroeste até o acampamento dos trolls Zangareia em {area:979}. Use o {item:8584} na beira da lagoa; os trolls ficam perto, então puxe o mais próximo primeiro.",
		["Ride south into {quest:3362}. The Dew Collectors drop the glands; only some are full, so keep the Laden one. Gnarled Thistleshrubs and Rootshapers share the valley. The Thistleshrubs are 48-50, above you: pull one at a time."] = "Cavalgue para o sul até {quest:3362}. Os Coletores de Orvalho Moitagulhas deixam cair as glândulas; só algumas estão cheias, então guarde a Glândula de Orvalho Cheia. Moitagulhas Rotos e Fazraízes Moitaguhas dividem o vale. Os Moitagulhas Rotos são nível 48-50, acima de você: puxe um de cada vez.",
		["Ride south past the {area:1938} to the {area:981}, the Hazzali tunnels; Scrimshank's gear lies deep inside."] = "Cavalgue para o sul, passando por {area:1938}, até a {area:981}, os túneis Hazzali; o Aparelho de Inspeção do Anilhacido está bem no fundo.",
		["Ride south to the dig camp at the {area:1938}. {npc:7771} hands you a detector helm: wear it to see the {quest:3161} mounds, which lie thick in the sand around the camp and south-west toward the ogres."] = "Cavalgue para o sul até o acampamento de escavação em {area:1938}. {npc:7771} lhe entrega um elmo detector: use-o para ver os montes de {quest:3161}, espalhados pela areia ao redor do acampamento e a sudoeste, rumo aos ogros.",
		["Ride south-east off the {area:439} into {zone:1446}. {area:976} is just inside the border."] = "Saia de {area:439} para o sudeste, rumo a {zone:1446}. {area:976} fica logo depois da fronteira.",
		["Ride south-east to {area:985}. {npc:7847} stands in the middle of the southern Wastewander camp: clear around him first."] = "Cavalgue para o sudeste até {area:985}. O {npc:7847} fica no meio do acampamento Errante do sul: limpe ao redor dele primeiro.",
		["Ride south-west to the ogre compound. Brutes and Enforcers (46-48) fill it; {npc:12046} (49) stands in the middle with guards around him: clear them first."] = "Cavalgue para o sudoeste até o complexo dos ogros. Brutamontes Dunamalho e Impositores Dunamalho (46-48) o enchem; {npc:12046} (49) fica no meio, cercado de guardas: elimine-os primeiro.",
		["Rizzle's plans"] = "Projetos do Rebu",
		["The Wanted poster beside him"] = "O cartaz de Procurado ao lado dele",
		["The little turtle {npc:5955} hides at the north end of the valley. Lead him home to his wife {npc:6015}, by the water just east of {area:977}: he walks slowly and the desert's beasts go for him, so keep him alive."] = "A tartaruguinha {npc:5955} se esconde no extremo norte do vale. Leve-o para casa, até a esposa {npc:6015}, junto à água logo a leste de {area:977}: ele anda devagar e as feras do deserto vão atrás dele, então mantenha-o vivo.",
		["The pool by {area:979}"] = "A lagoa junto a {area:979}",
		["The same poster: {npc:7847} comes much later, after {area:976}"] = "O mesmo cartaz: {npc:7847} vem bem mais tarde, depois de {area:976}",
		["The tougher Wastewander rogues, shadow mages and assassins camp south-east of {area:976}, south of the bandits. Leave {npc:7847} in the middle of the southern camp for later."] = "Os Ladinos Errantes, Magos das Sombras Errantes e Assassinos Errantes, mais fortes, acampam a sudeste de {area:976}, ao sul dos bandidos. Deixe {npc:7847}, no meio do acampamento do sul, para depois.",
		["The {area:1938}"] = "{area:1938}",
		["Wastewander bandits"] = "Bandidos Errantes",
		["While {npc:4709} keeps Rizzle talking, his plans lie unguarded in the gnome camp across the track."] = "Enquanto {npc:4709} distrai o Rebu, os projetos dele ficam desprotegidos no acampamento gnomo do outro lado da pista.",
		["for {zone:1457}: the route takes you there at 47"] = "para {zone:1457}: a rota leva você lá no nível 47",
		["{npc:11758}, on the east side of town"] = "{npc:11758}, no lado leste da cidade",
		["{npc:5955}'s escort"] = "Escolta de {npc:5955}",
		["{npc:7407}, by the water tower"] = "{npc:7407}, junto à torre d'água",
		["{npc:7408}, next to him"] = "{npc:7408}, ao lado dele",
		["{npc:7583}'s next ingredient grows in the {zone:1425}, and the route never brings it back: skip it."] = "O próximo ingrediente de {npc:7583} cresce em {zone:1425}, e a rota nunca o traz de volta: pule.",
		["{npc:7763}: his crate goes to {area:702}, later"] = "{npc:7763}: o caixote dele vai para {area:702}, depois",
		["{npc:7881}'s next delivery goes back to {area:35}: skip it."] = "A próxima entrega de {npc:7881} volta para {area:35}: pule.",
		["{npc:7881}, in the port's tavern"] = "{npc:7881}, na taverna do porto",
		["{quest:2864}, north side of town"] = "{quest:2864}, no lado norte da cidade",
} end)()
t.guides["forever/alliance/40-50/05-the-hinterlands"] = (function() return {
		["Ashmane Boars and Redstone Basilisks share the slopes south-west of the keep. Keep clear of the Helboars further south: they are level 52."] = "Javalis Jubacinza e Basiliscos Itarrubra dividem as encostas a sudoeste da fortaleza. Fique longe dos Javiltuscos mais ao sul: são nível 52.",
		["Back to {area:144}"] = "De volta a {area:144}",
		["Boars and basilisks"] = "Javalis e basiliscos",
		["Fly from {area:144} to {area:150}, take the boat to {area:442} and fly to {area:702}."] = "Voe de {area:144} para {area:150}, pegue o barco para {area:442} e voe para {area:702}.",
		["Fly from {area:348} to {area:42}."] = "Voe de {area:348} para {area:42}.",
		["Hearth to {area:144}. The {zone:1427} guide starts at {area:1446}: from here, ride south into the {zone:1418}, west past the Horde town of {area:340} and up the trail into the gorge."] = "Use a Pedra de Regresso para {area:144}. O guia de {zone:1427} começa em {area:1446}: daqui, cavalgue para o sul até {zone:1418}, para o oeste passando pela cidade da Horda, {area:340}, e suba a trilha até a garganta.",
		["Hearth to {area:348}."] = "Use a Pedra de Regresso para {area:348}.",
		["Hearthstone on cooldown? Ride back north-west."] = "Pedra de Regresso em recarga? Cavalgue de volta para o noroeste.",
		["Ride back east to {area:1438} and fly to {area:144}."] = "Cavalgue de volta para o leste até {area:1438} e voe para {area:144}.",
		["Ride back north to Ironband's camp."] = "Cavalgue de volta para o norte até o acampamento de Bandaferro.",
		["Ride east along the south shore of the loch to Ironband's camp."] = "Cavalgue para o leste pela margem sul do lago até o acampamento de Bandaferro.",
		["Ride east through {zone:1430} into the {zone:1435} and south down the road into the {zone:1419}. The bloodmages' camp is the first stop beside the road."] = "Cavalgue para o leste por {zone:1430} até {zone:1435} e desça a estrada para o sul até {zone:1419}. O acampamento dos Magos Sangrentos é a primeira parada à beira da estrada.",
		["Ride north to {area:351} in the middle of the {zone:1425}. Green Sludges and Jade Oozes crawl all around it."] = "Cavalgue para o norte até {area:351}, no meio das {zone:1425}. Lodos Verdes e Gosmas Jade rastejam por toda a volta.",
		["Ride on east along the road to the keep first: the {item:6091} expires an hour after {area:42}, and the bloodmages' beasts take longer than that."] = "Siga primeiro pela estrada para o leste até a fortaleza: o {item:6091} expira uma hora depois de {area:42}, e as feras dos Magos Sangrentos levam mais tempo que isso.",
		["Ride south through the pass into the {zone:1418}' northern edge: the Stonevault troggs dig outside {area:1517} there. The carved urns and the magenta mushroom clusters sit in their caves and tunnels, outside the dungeon itself."] = "Cavalgue para o sul pelo desfiladeiro até a borda norte de {zone:1418}: os Troggs da Abóbada de Pedra escavam ali, fora de {area:1517}. As urnas entalhadas e os aglomerados de cogumelos magenta ficam nas cavernas e túneis deles, fora da masmorra.",
		["Ride south-east to the {area:355}, the stepped Vilebranch temple in the south of the {zone:1425}, and climb to the top. Qiaga and {npc:8636} (elite, 50) stand up there: touch the top and come straight back down."] = "Cavalgue para o sudeste até {area:355}, o templo escalonado Ramatorpe no sul das {zone:1425}, e suba até o topo. Qiaga e {npc:8636} (elite, 50) ficam lá em cima: toque o topo e desça logo.",
		["Ride west: Starving Snickerfangs roam the dry hills just south of the bloodmages' camp; Scorpok Stingers (level 50) scuttle across the middle of the north. {npc:5982} vultures circle over all of it. Pull one at a time."] = "Cavalgue para o oeste: Rasgarrindos Famintas vagam pelas colinas secas logo ao sul do acampamento dos Magos Sangrentos; Aguilhantes Escorpódes (nível 50) correm pelo meio do norte. Abutres {npc:5982} circulam sobre tudo. Puxe um de cada vez.",
		["Scorpoks and snickerfangs"] = "Escorpódes e rasgarrindos",
		["Step through the portal into {zone:1457}. The Temple of the Moon is in the south of the city."] = "Atravesse o portal para {zone:1457}. O Templo da Lua fica no sul da cidade.",
		["Temple of the Moon"] = "Templo da Lua",
		["The bloodmages"] = "Os Magos Sangrentos",
		["The bloodmages' second tier pays for the same parts with a buff item and no experience: skip it."] = "A segunda etapa dos Magos Sangrentos paga pelas mesmas partes com um item de bônus e sem experiência: pule.",
		["The druid trainers stand in the Enclave; {zone:1455} has none"] = "Os instrutores de druida ficam no Enclave; {zone:1455} não tem nenhum",
		["The {area:1517} dig"] = "A escavação de {area:1517}",
		["for {quest:2990} at {area:1438}, later"] = "para {quest:2990} em {area:1438}, depois",
		["the book on her table"] = "o livro na mesa dela",
		["the soil comes from {zone:1449}, later"] = "o solo vem de {zone:1449}, depois",
		["{npc:3516}, at the top of the tree"] = "{npc:3516}, no alto da árvore",
		["{npc:7740}, beside her"] = "{npc:7740}, ao lado dela",
		["{npc:7744}: the last guide binds here, so this usually ticks at once"] = "{npc:7744}: o guia anterior vincula você aqui, então isto costuma ser marcado na hora",
		["{npc:7907}'s next errand goes to {zone:1446}: skip it."] = "A próxima tarefa de {npc:7907} vai para {zone:1446}: pule.",
		["{npc:7916}: keep it, the feathers come at the end of the {zone:1428} guide"] = "{npc:7916}: guarde-a; as penas vêm no fim do guia de {zone:1428}",
		["{npc:8022}' next task, {item:9471}, is a {area:978} quest: skip it."] = "A próxima tarefa de {npc:8022}, {item:9471}, é uma missão de {area:978}: pule.",
		["{quest:2990}, at the top of the keep"] = "{quest:2990}, no alto da fortaleza",
} end)()
t.guides["forever/alliance/40-50/06-searing-gorge"] = (function() return {
		["For {npc:8256} in {zone:1455}, later"] = "Para {npc:8256} em {zone:1455}, depois",
		["From {area:144} ride south into the {zone:1418}, then west past the Horde town of {area:340} (give it room) and up the trail into {zone:1427}. {area:1446} is the scaffolded camp on the north-west rim."] = "De {area:144}, cavalgue para o sul até {zone:1418}, depois para o oeste passando pela cidade da Horda, {area:340} (mantenha distância), e suba a trilha até {zone:1427}. {area:1446} é o acampamento com andaimes na borda noroeste.",
		["Golems and elementals"] = "Golems e elementais",
		["Greater Lava Spiders"] = "Aranhas de Lava Abrasadoras",
		["Heavy War Golems patrol the floor of the Cauldron below Kalaran; Magma Elementals drift among them. Golems and elementals drop the oil, elementals the hearts."] = "Golems de Guerra Pesados patrulham o fundo de O Caldeirão, abaixo de Kalaran; Elementais de Magma vagam entre eles. Golems e elementais deixam cair o óleo; os elementais, os corações.",
		["Kalaran stands on the rim of the Cauldron, south of {area:1446}. Listen to his story."] = "Kalaran fica na borda de O Caldeirão, ao sul de {area:1446}. Ouça a história dele.",
		["Ride east across the Cauldron to the {area:247} in the south-east. The prisoner in the wooden outhouse wants 15 {item:4306} and eight dead Dark Iron Geologists from the dig site around it. The outhouse also opens with the key, if you found one."] = "Cavalgue para o leste pelo Caldeirão até {area:247}, no sudeste. O prisioneiro na casinha de madeira quer 15 {item:4306} e oito Geólogos Ferro Negro mortos da escavação ao redor. A casinha também abre com a chave, se você encontrou uma.",
		["Taskmasters and Slavers drive the slaves all over the Cauldron, and any of them can carry a {item:10551}. The Steamsmiths work at the furnaces in the middle (the {item:18959}), the Lookouts stand on the southern ridges (the Spyglass). Any {object:147516} may drop the {item:11818}: keep it."] = "Capatazes Ferro Negro e Feitores Ferro Negro tocam os escravos por todo O Caldeirão, e qualquer um deles pode carregar uma {item:10551}. Os Vaporistas Ferro Negro trabalham nas fornalhas no meio (a {item:18959}); os Atalaias Ferro Negro ficam nas cristas do sul (a Luneta do Espia). Qualquer {object:147516} pode deixar cair a {item:11818}: guarde-a.",
		["The Grimesilt outhouse"] = "A casinha de Pedrassuja",
		["The dwarf stands by the road at the dig site. Follow him north along the road and fight off the {object:147516} ambushes. When it is over, read the {object:175704} he leaves on the road in {area:1959}."] = "O anão fica à beira da estrada, na escavação. Siga-o para o norte pela estrada e repila as emboscadas {object:147516}. No fim, leia a {object:175704} que ele deixa na estrada em {area:1959}.",
		["The night elf stands alone west of {area:1446}. Hear his story."] = "O elfo noturno está sozinho a oeste de {area:1446}. Ouça a história dele.",
		["The prisoner's next task, Ledger from {zone:1446}, sends you to the {zone:1435} and {zone:1445}: skip it."] = "A próxima tarefa do prisioneiro, Livro-Caixa de {zone:1446}, manda você para {zone:1435} e {zone:1445}: pule.",
		["The spiders roam the plateaus and lava pools in the south-west of the gorge."] = "As aranhas vagam pelos platôs e poças de lava no sudoeste da garganta.",
		["The {object:179827} board"] = "O quadro {object:179827}",
		["{area:1443} opens in the north of the Cauldron. The Secret Plans lie on its upper ledge; Incendosaurs swim in the lava pools further in, so pull them to the edge. Stay clear of {npc:14621} and his elite guards deep inside."] = "{area:1443} se abre no norte de O Caldeirão. As Instruções Secretas: Fluxo Ígneo ficam na saliência superior; Incendossauros nadam nas poças de lava mais adentro, então puxe-os até a borda. Fique longe de {npc:14621} e de seus guardas de elite lá no fundo.",
		["{npc:6734}: the last guide hearths you here, so this usually ticks at once"] = "{npc:6734}: o guia anterior leva você até aqui com a pedra de regresso, então isto costuma ser marcado na hora",
		["{object:147516} dwarves"] = "Anões {object:147516}",
} end)()
t.guides["forever/alliance/40-50/07-un-goro-crater"] = (function() return {
		["Archesonus stands beside King Magni in the {object:171709}."] = "Arquefilis fica ao lado do Rei Magni, em {object:171709}.",
		["Bind and train"] = "Vincule e treine",
		["Bones and equipment"] = "Ossos e equipamentos",
		["Cross the south of the crater to {npc:9619} by the ramp."] = "Atravesse o sul da cratera até {npc:9619}, junto à rampa.",
		["Dinosaur Bones lie on the ground in the south-west, among the stegodons: those are elite, pick the bones up around them and take the rest from Diemetradons. The expedition's {item:11112} lies in the south-west jungle."] = "Ossos de Dinossauro ficam no chão no sudoeste, entre os estegodons: eles são elite, pegue os ossos ao redor deles e consiga o resto com os Dimetrodontes. O {item:11112} da expedição fica na selva sudoeste.",
		["Eastern Pylon"] = "Torre de Cristal Leste",
		["Ends with {npc:9298} in {zone:1452}: keep it"] = "Termina com {npc:9298}, em {zone:1452}: guarde",
		["Escort {npc:9999}"] = "Escolte {npc:9999}",
		["Fly from {area:144} to {area:1537}."] = "Voe de {area:144} para {area:1537}.",
		["For {npc:7775} in {zone:1444}: keep it"] = "Para {npc:7775}, em {zone:1444}: guarde",
		["Four rune rubbings in {zone:1447}: keep it"] = "Quatro decalques de runas em {zone:1447}: guarde",
		["From {area:144} fly to {area:150}, take the boat to Theramore and fly on to {area:976}. {npc:9619}'s first quest in the crater needs level 48: finish the level here if you are short."] = "De {area:144}, voe para {area:150}, pegue o barco para Theramore e voe até {area:976}. A primeira missão de {npc:9619} na cratera exige nível 48: complete o nível aqui se faltar.",
		["Grind to 50"] = "Suba até o nível 50",
		["Grind to 51"] = "Suba até o nível 51",
		["Gryfe"] = "Gryfe",
		["Lar'korwi Mates and the raft"] = "Lar'korwi Fêmeas e a jangada",
		["Lead {npc:9999} north to {area:541}. When he faints, use {item:11804} on him to wake him."] = "Leve {npc:9999} para o norte até {area:541}. Quando ele desmaiar, use {item:11804} nele para acordá-lo.",
		["Northern Pylon"] = "Torre de Cristal Norte",
		["Ride down the ramp into the crater: {npc:9619} camps at its foot."] = "Desça a rampa para a cratera: {npc:9619} acampa ao pé dela.",
		["Ride east to {area:537}, climb it and use {npc:10541} at the lava vents near the top."] = "Siga para o leste até {area:537}, suba e use {npc:10541} nas aberturas de lava perto do topo.",
		["Ride north along the east side of the crater to {area:541}, the camp in the caves of the northern cliff. Give the elite devilsaurs and stegodons a wide berth. Pick up every Power Crystal and {object:157936} you pass from here on."] = "Siga para o norte pelo lado leste da cratera até {area:541}, o acampamento nas cavernas do penhasco norte. Fique longe dos demossauros e estegodons elite. Daqui em diante, pegue todo Cristal de Poder e {object:157936} que encontrar.",
		["Ride north along the east side to the gorilla plateau. {npc:9622}, a level 55 gorilla, sits in its deepest cave: clear the gorillas at the cave mouth first."] = "Siga para o norte pelo lado leste até o planalto dos gorilas. {npc:9622}, um gorila de nível 55, fica na caverna mais funda: limpe os gorilas da entrada antes.",
		["Ride north along the western jungle back to the refuge."] = "Siga para o norte pela selva oeste de volta ao refúgio.",
		["Ride north to {area:1943}, where the robot stands among the gorillas. Stay out of the deep cave there."] = "Siga para o norte até {area:1943}, onde o robô fica entre os gorilas. Não entre na caverna funda dali.",
		["Ride south along the eastern cliffs to {npc:9619} at the foot of the ramp."] = "Siga para o sul pelos penhascos leste até {npc:9619}, ao pé da rampa.",
		["Ride south down the east side. Young Diemetradons graze the eastern jungle and {npc:9165} fly near the eastern cliffs; both drop {npc:9998}'s scales."] = "Desça para o sul pelo lado leste. Dimetrodontes Jovens pastam na selva leste e {npc:9165} voam perto dos penhascos leste; os dois deixam cair as escamas de {npc:9998}.",
		["Ride south to {area:537} in the middle of the crater, then east into the eastern jungle. Crystal clusters stand all over the crater, many of them around {area:537}: take a few extra of each colour. Bloodpetal Lashers and Threshers drop the petals; the expedition's {item:11113} sits at an abandoned camp in the eastern jungle."] = "Siga para o sul até {area:537}, no meio da cratera, e depois para o leste, até a selva leste. Há agrupamentos de cristais por toda a cratera, muitos ao redor de {area:537}: pegue alguns a mais de cada cor. Açoitadeiras Pétala Sangrenta e Látegas Pétala Sangrenta deixam cair as pétalas; o {item:11113} da expedição está num acampamento abandonado na selva leste.",
		["Ride west back to the refuge."] = "Volte para o oeste até o refúgio.",
		["Ride west from {npc:9619}: the silithid hive fills the south of the crater. Use the Scraping Vial on a hatchery, a chamber with hanging larvae. Gorishi wasps and workers drop {quest:3764}; {npc:9166} nest on the southern cliffs if you still need kills."] = "Siga para o oeste a partir de {npc:9619}: a colmeia silitídea ocupa o sul da cratera. Use o Frasco para Amostra numa câmara de incubação, uma câmara com larvas penduradas. Vespas e Trabalhadoras Gorishi deixam cair {quest:3764}; {npc:9166} fazem ninho nos penhascos sul, se ainda precisar de abates.",
		["Ride west out of {area:976} to the long ramp down into {zone:1449}. {npc:9619} camps at the foot of the ramp, in the south-east corner of the crater."] = "Siga para o oeste, saindo de {area:976}, até a longa rampa que desce para {zone:1449}. {npc:9619} acampa ao pé da rampa, no canto sudeste da cratera.",
		["Ride west past {area:541} and south down the western side to {area:543}: {npc:10302} the goblin sits by the water."] = "Siga para o oeste, passando {area:541}, e desça para o sul pelo lado oeste até {area:543}: {npc:10302}, o goblin, fica junto à água.",
		["Running the {area:1417} instead of grinding gets you there faster in a group. Skip this step to grind solo."] = "Fazer {area:1417} em vez de matar monstros leva você lá mais rápido, em grupo. Pule esta etapa para subir sozinho.",
		["Running {area:978} instead of grinding gets you there faster in a group. The troll city lies in the north-west of {zone:1446}, just north of {area:976}."] = "Fazer {area:978} em vez de matar monstros leva você lá mais rápido, em grupo. A cidade troll fica no noroeste de {zone:1446}, logo ao norte de {area:976}.",
		["The Centipaar silithid crawl around the {area:982} in western {zone:1446}, just east of the crater ramp. The Workers are the easiest pulls."] = "Os silitídeos Centiparte rastejam ao redor de {area:982}, no oeste de {zone:1446}, logo a leste da rampa da cratera. Os Trabalhadores são os mais fáceis de puxar.",
		["The Gorishi hive"] = "A colmeia Gorishi",
		["The Lar'korwi Mates prowl the jungle west of {npc:9619}. The wrecked raft lies on the shore of the lake there; the small pack sits in the water beside it. Keep the compass, map and key for {npc:8737}. Any beast in the crater may drop {item:11116}: right-click it."] = "As Lar'korwi Fêmeas rondam a selva a oeste de {npc:9619}. A jangada destruída fica na margem do lago ali; a mochila pequena está na água ao lado. Guarde a bússola, o mapa e a chave para {npc:8737}. Qualquer fera da cratera pode deixar cair {item:11116}: clique com o botão direito nele.",
		["The dead Threshadon lies by the water north of {npc:9619}."] = "O Manguadonte morto fica junto à água, ao norte de {npc:9619}.",
		["The east side"] = "O lado leste",
		["The gorillas live on {area:1943}, east of {area:541}. Keep their pelts for {npc:9619}. Stay out of the deepest cave: {npc:9622} is level 55."] = "Os gorilas vivem em {area:1943}, a leste de {area:541}. Guarde as peles para {npc:9619}. Fique fora da caverna mais funda: {npc:9622} é nível 55.",
		["The gorillas of {area:1943} come in small groups and drop nothing for you yet; {npc:9619}'s pelt quest comes later. Stay out of the deepest cave: {npc:9622} is level 55."] = "Os gorilas de {area:1943} vêm em pequenos grupos e ainda não deixam cair nada para você; a missão das peles de {npc:9619} vem depois. Fique fora da caverna mais funda: {npc:9622} é nível 55.",
		["The pelts come after loop 2, on the gorilla plateau"] = "As peles vêm depois do circuito 2, no planalto dos gorilas",
		["The pylon stands on the eastern cliffs."] = "A torre fica nos penhascos leste.",
		["The pylon stands on the slope east of the refuge. {npc:9166} circle the slopes around it: they count for {npc:9997} and drop {npc:9998}'s scales."] = "A torre fica na encosta a leste do refúgio. {npc:9166} sobrevoam as encostas ao redor: contam para {npc:9997} e deixam cair as escamas de {npc:9998}.",
		["The pylon stands on the western cliffs. {npc:9167} fly over the whole west side."] = "A torre fica nos penhascos oeste. {npc:9167} voam por todo o lado oeste.",
		["The relics are in the {zone:1428}: keep it"] = "As relíquias estão em {zone:1428}: guarde",
		["The wooden sign beside {npc:9997}"] = "A placa de madeira ao lado de {npc:9997}",
		["Western Pylon"] = "Torre de Cristal Oeste",
		["Xiggs waits in the {object:32359}."] = "Xisto espera em {object:32359}.",
		["grind on the Wastewanderers or Dunemaul ogres around {area:976}"] = "mate Errantes ou ogros Dunamalho ao redor de {area:976}",
		["grind on {npc:5458} at {area:982}, {zone:1446}"] = "mate {npc:5458} em {area:982}, {zone:1446}",
		["grind on {npc:6514} at {area:1943}, {zone:1449}"] = "mate {npc:6514} em {area:1943}, {zone:1449}",
		["{area:537} and the eastern jungle"] = "{area:537} e a selva leste",
		["{area:978} (optional)"] = "{area:978} (opcional)",
		["{npc:11406}: for Ogtinc in {zone:1447}, keep it"] = "{npc:11406}: para Ogtinc, em {zone:1447}, guarde",
		["{npc:6734}: the last guide hearths you here, so this usually ticks at once"] = "{npc:6734}: o guia anterior leva você até aqui com a pedra de regresso, então isto costuma ser marcado na hora",
		["{npc:9117}, at the back of the cave"] = "{npc:9117}, no fundo da caverna",
		["{npc:9616}: the oozes are in {zone:1448}, keep it"] = "{npc:9616}: os limos estão em {zone:1448}, guarde",
		["{npc:9618} stands just outside the refuge."] = "{npc:9618} fica logo fora do refúgio.",
		["{npc:9684}'s lair lies in the jungle north of {npc:9619}, below the eastern cliffs: use {item:11568} there. {npc:9684} is level 56: start at full health."] = "O covil de {npc:9684} fica na selva ao norte de {npc:9619}, abaixo dos penhascos leste: use {item:11568} ali. {npc:9684} é nível 56: comece com a vida cheia.",
		["{npc:9997}'s friend {npc:9999} has gone missing."] = "{npc:9999}, amigo de {npc:9997}, desapareceu.",
		["{npc:9998}, at the refuge entrance"] = "{npc:9998}, na entrada do refúgio",
		["{npc:9998}, at the refuge's entrance"] = "{npc:9998}, na entrada do refúgio",
		["{npc:9999} sits on the south-east slope of {area:537}, in the middle of the crater."] = "{npc:9999} está sentado na encosta sudeste de {area:537}, no meio da cratera.",
} end)()
t.guides["forever/alliance/50-60/01-burning-steppes"] = (function() return {
		["Climb back to {npc:8405} at the {area:1224}, above the ruins."] = "Suba de volta até {npc:8405} em {area:1224}, acima das ruínas.",
		["Climb to the top of {area:249} and plant the head in the soft dirt mound."] = "Suba até o topo de {area:249} e finque a cabeça no monte de terra fofa.",
		["Druid training"] = "Treinamento de druida",
		["Ends with {quest:4808} in {area:2255}, {zone:1452}: keep it"] = "Termina com {quest:4808} em {area:2255}, {zone:1452}: guarde-a",
		["Fly from {zone:1455} to {area:150} and take the boat to {area:442}."] = "Voe de {zone:1455} para {area:150} e pegue o barco para {area:442}.",
		["Fly from {zone:1455} to {area:69}."] = "Voe de {zone:1455} para {area:69}.",
		["Fly to {area:1438}."] = "Voe para {area:1438}.",
		["Fly to {area:150} and take the boat to {area:442}, then the boat on to {area:702}."] = "Voe para {area:150} e pegue o barco para {area:442} e depois o barco até {area:702}.",
		["Follow the road west, then climb north to the goblin camp on {area:251}."] = "Siga a estrada para o oeste e depois suba para o norte até o acampamento goblin em {area:251}.",
		["From the {area:442} dock, fly to {area:415}."] = "Do cais de {area:442}, voe para {area:415}.",
		["Mosshoof Coursers"] = "Ginetes Cascomusgo",
		["Optional: {npc:8395} wants two Undamaged Hippogryph Feathers from the hippogryphs around his camp. The data lists no experience for it."] = "Opcional: {npc:8395} quer duas Penas Intactas de Hipogrifo dos hipogrifos ao redor do acampamento dele. Os dados não indicam experiência para ela.",
		["Optional: {npc:8888}'s ghost stands on his tomb on the great chain inside {area:254}, and only the dead can see him. If you die near the mountain anyway, run your spirit to him before resurrecting."] = "Opcional: o fantasma de {npc:8888} fica sobre o túmulo dele, na grande corrente dentro de {area:254}, e só os mortos podem vê-lo. Se você morrer perto da montanha de qualquer forma, corra com seu espírito até ele antes de ressuscitar.",
		["Read the tablet in the {object:147516} camp among the ruins, south-west of {area:251}, to copy the transcript."] = "Leia a tábua no acampamento {object:147516} entre as ruínas, a sudoeste de {area:251}, para copiar a transcrição.",
		["Ride back east along the road to the Vigil."] = "Volte para o leste pela estrada até a Vigia de Morgan.",
		["Ride back to {area:1438} and fly to {area:348}. The Wildkin Feathers lie on the ground across the {zone:1425}, south and east of {area:348}, where the owlbeasts roam; the mobs here are well below you now."] = "Volte para {area:1438} e voe para {area:348}. As Penas de Coruscante ficam no chão por {zone:1425}, ao sul e a leste de {area:348}, onde as ferujas vagueiam; os monstros daqui agora são de nível bem abaixo do seu.",
		["Ride east along the road out of {zone:1440} into {zone:1447} to the Sentinels' camp at {area:3137}."] = "Siga para o leste pela estrada, saindo de {zone:1440} e entrando em {zone:1447}, até o acampamento das Sentinelas em {area:3137}.",
		["Ride north out of {area:69} through the pass into the {zone:1428}; {area:2418} sits at the top, in the south-east of the Steppes."] = "Siga para o norte saindo de {area:69}, pelo desfiladeiro, até {zone:1428}; {area:2418} fica no alto, no sudeste da região.",
		["Ride north-east from the shrine: {npc:8405} camps at the {area:1224}, in the hills above the road."] = "Siga para o nordeste a partir do santuário: {npc:8405} acampa em {area:1224}, nas colinas acima da estrada.",
		["Swim to the small island off the southern tip of {zone:1447}: {npc:8392} waits by the monument."] = "Nade até a pequena ilha na ponta sul de {zone:1447}: {npc:8392} espera junto ao monumento.",
		["Thaurissan Relics"] = "Relíquias Thaurissanas",
		["The Firegut ogres hold the great rock north of the Vigil, with the Brutes on its east side."] = "Os ogros Pirobucho ocupam a grande rocha ao norte da Vigia de Morgan, com os Brutamontes no lado leste.",
		["The Highborne ghosts haunt the ruins around the shrine; the Haldarr satyrs hold the camp just north of it."] = "Os fantasmas Altaneiros assombram as ruínas ao redor do santuário; os sátiros Haldarr ocupam o acampamento logo ao norte dele.",
		["The Spitelash naga of the {area:1221} carry {item:13815}. {npc:8507}'s four runes stand among the ruins: use his {item:10445} on each."] = "Os nagas Iralisca de {area:1221} carregam {item:13815}. As quatro runas de {npc:8507} ficam entre as ruínas: use o {item:10445} dele em cada uma.",
		["The nearest Mosshoof Coursers graze the hills north-east of the {area:1224}, toward the {area:1219}; a larger herd roams the open ground to the south."] = "Os Ginetes Cascomusgo mais próximos pastam nas colinas a nordeste de {area:1224}, em direção a {area:1219}; um rebanho maior vagueia pelo campo aberto ao sul.",
		["The relics are the carved stones scattered through the {area:250} around {area:251}: click them until the information is recovered."] = "As relíquias são as pedras entalhadas espalhadas por {area:250} ao redor de {area:251}: clique nelas até recuperar as informações.",
		["The shrine lies in the south-west corner of {zone:1447}, south of {area:3137}."] = "O santuário fica no canto sudoeste de {zone:1447}, ao sul de {area:3137}.",
		["The wildkin are in {zone:1452}: keep it"] = "Os coruscantes estão em {zone:1452}: guarde-a",
		["The {area:1221}"] = "{area:1221}",
		["The {quest:4296}"] = "{quest:4296}",
		["Use the {item:12284} on a {npc:7047} on the slopes east of {area:251} just before it dies, then loot the essence it leaves."] = "Use o {item:12284} em um {npc:7047} nas encostas a leste de {area:251} pouco antes de ele morrer e depois saqueie a essência que ele deixa.",
		["Wildkin feathers"] = "Penas de Coruscante",
		["{item:7972}: the {npc:7864}, about 10%"] = "{item:7972}: {npc:7864}, cerca de 10%",
		["{npc:5111}: the last guide binds here, so this usually ticks at once"] = "{npc:5111}: o guia anterior vincula você aqui, então isto costuma ser marcado na hora",
		["{npc:7363} waits at the {area:2517}, the hill south-west of the keep. The {zone:1419} mobs on the way drop the Imperfect Draenethyst Fragments; bring her what you have."] = "{npc:7363}, espera em {area:2517}, a colina a sudoeste da fortaleza. Os monstros de {zone:1419} no caminho deixam cair os Fragmentos Imperfeitos de Draenetista; leve a ele o que você tiver.",
		["{npc:8420} camps at the {area:1219} in the north; his equipment lies all over the {area:1220} just south-east of him."] = "{npc:8420} acampa em {area:1219}, no norte; o equipamento dele está espalhado por {area:1220}, logo a sudeste dele.",
		["{npc:9176} and the Blackrock orcs hold the camps and the stronghold at the foot of {area:254}, west of {area:251}. Pull them one at a time; every orc and worg may drop a medallion, so kill them until you have fifty."] = "{npc:9176} e os orcs Rocha Negra ocupam os acampamentos e a fortaleza ao pé de {area:254}, a oeste de {area:251}. Puxe-os um de cada vez; todo orc e worg pode deixar cair um medalhão, então mate-os até ter cinquenta.",
		["{npc:9177}: the Blackrock orcs drop the medallions, keep it open all through the Steppes"] = "{npc:9177}: os orcs Rocha Negra deixam cair os medalhões, mantenha-a aberta por toda a região",
		["{zone:1455} has no druid trainer: take the portal up to {zone:1457} and train in the {area:1658}, then come back down to {area:702}."] = "{zone:1455} não tem instrutor de druida: pegue o portal para subir até {zone:1457} e treine em {area:1658}, depois desça de volta até {area:702}.",
} end)()
t.guides["forever/alliance/50-60/02-felwood"] = (function() return {
		["Ends in the {zone:1413}: keep it"] = "Termina em {zone:1413}: guarde-a",
		["First crater"] = "Primeira cratera",
		["Five feathers buy a little Timbermaw reputation"] = "Cinco penas rendem um pouco de reputação com os Presamatos",
		["Fly from {area:1998} to the Sanctuary's end of the road, or ride south along it."] = "Voe de {area:1998} até o Santuário, no fim da estrada, ou siga por ela para o sul.",
		["Follow the road north to the cave mouth of {area:1769}; {npc:15395} guards it."] = "Siga a estrada para o norte até a entrada da caverna de {area:1769}; {npc:15395} a guarda.",
		["Follow the road north to the cratered vale and walk to each crater, killing the Entropic Beasts and Horrors between them."] = "Siga a estrada para o norte até o vale de crateras e vá até cada cratera, matando as Feras Entrópicas e os Horrores entre elas.",
		["Keep her alive until she is out of the cave"] = "Mantenha-a viva até ela sair da caverna",
		["Oozes"] = "Gosmas",
		["Ride east to the night elf camp at {area:1998}."] = "Siga para o leste até o acampamento dos elfos noturnos em {area:1998}.",
		["Ride north out of {area:415} into {zone:1448}. {npc:11554} the furbolg stands by the road just south of the {area:2479}."] = "Siga para o norte saindo de {area:415} até {zone:1448}. O furbolg {npc:11554} fica junto à estrada, logo ao sul de {area:2479}.",
		["Ride north to {area:1769} (or fly back to {area:1998} first) and through the tunnel into {zone:1452}; follow the road east to the goblin town of {area:2255}."] = "Siga para o norte até {area:1769} (ou antes volte voando para {area:1998}) e atravesse o túnel até {zone:1452}; siga a estrada para o leste até a cidade goblin de {area:2255}.",
		["Salfa stands at the {zone:1452} end of the tunnel: keep it"] = "Salfa fica na saída do túnel para {zone:1452}: guarde-a",
		["Second crater"] = "Segunda cratera",
		["Step into the cave: {npc:11558} and {npc:11557} stand just inside."] = "Entre na caverna: {npc:11558} e {npc:11557} ficam logo na entrada.",
		["Take the boat from {area:702} to {area:442} and fly to {area:415}."] = "Pegue o barco de {area:702} para {area:442} e voe para {area:415}.",
		["The Cursed and Tainted Oozes slide about the streams and fel pools around {area:1763} and {area:1765}: kill them and use Laris's Empty Ooze Jars on their remains."] = "As Gosmas Amaldiçoadas e as Gosmas Maculadas deslizam pelos córregos e poças vis ao redor de {area:1763} e {area:1765}: mate-as e use as Jarras de Gosma vazias de Laris Vagarroda nos restos delas.",
		["The Deadwood furbolgs live in the village just south-west of {npc:11554}; keep the Deadwood Headdress Feathers they drop."] = "Os furbolgs de Lenha Morta vivem na aldeia logo a sudoeste de {npc:11554}; guarde as Penas do Cocar de Lenha Morta que eles deixam cair.",
		["The Deadwood furbolgs of {area:1762} fill the hills west of the cave. The Avengers can drop a {quest:8470}."] = "Os furbolgs de Lenha Morta de {area:1762} enchem as colinas a oeste da caverna. Os Vingadores de Lenha Morta podem deixar cair um {quest:8470}.",
		["The Jadefire satyrs hold the glen west of the road, with {npc:9454} at its back."] = "Os sátiros Flamejade ocupam o vale a oeste da estrada, com {npc:9454} no fundo.",
		["The Warpwood treants of {area:1767}, east of {area:2618}, carry the {item:11503}."] = "Os arvorosos Lenhatorta de {area:1767}, a leste de {area:2618}, carregam {item:11503}.",
		["The vial is filled in {zone:1457}: keep it"] = "A ampola é enchida em {zone:1457}: guarde-a",
		["The {area:2479}"] = "{area:2479}",
		["Third crater"] = "Terceira cratera",
		["Use the {item:12922} at the corrupted moonwell in the middle of {area:1763}. If you freed {npc:11018}, go back into {area:1770} for the succubus {npc:9518}; Trey Lightforge's remains lie beside her."] = "Use o {item:12922} no poço lunar corrompido no meio de {area:1763}. Se você libertou {npc:11018}, volte a {area:1770} atrás da súcubo {npc:9518}; os Restos Mortais de Trey Forjaleve estão ao lado dela.",
		["{area:1763} again"] = "{area:1763} de novo",
		["{area:1763} is the ruined temple north of the glen. Some of its cultists drop a {item:13140}, about one kill in thirty: it opens {npc:11018}'s cell in {area:1770}, the cave at the back. If it drops, clear the way out before you free her; if not, skip her quests."] = "{area:1763} é o templo em ruínas ao norte do vale. Alguns dos seus sectários deixam cair uma {item:13140}, cerca de uma vez a cada trinta mortes: ela abre a cela de {npc:11018} em {area:1770}, a caverna no fundo. Se ela cair, limpe o caminho de saída antes de libertá-la; se não, pule as missões dela.",
		["{area:2618} is the satyr valley in the north-west, with {npc:10648} at its far end. He drops the {quest:939}; every Jadefire satyr can drop {item:11674}."] = "{area:2618} é o vale dos sátiros no noroeste, com {npc:10648} no fundo. Ele deixa cair {quest:939}; todo sátiro Flamejade pode deixar cair {item:11674}.",
		["{item:13140}, a rare drop"] = "{item:13140}, um saque raro",
		["{npc:11016}, in {area:1770}"] = "{npc:11016}, em {area:1770}",
		["{npc:11557}: thirty {quest:6031}, handed in when you pass through again at 57"] = "{npc:11557}: trinta {quest:6031}, entregues quando você passar por aqui de novo no nível 57",
		["{npc:11558}: the Timbermaw speak to you only from Neutral"] = "{npc:11558}: os Presamatos só falam com você a partir de Neutro",
		["{npc:15395} waits at the north end of {zone:1448}"] = "{npc:15395} espera no extremo norte de {zone:1448}",
		["{npc:9528}, in the ruins just east of {npc:11554}"] = "{npc:9528}, nas ruínas logo a leste de {npc:11554}",
		["{quest:8470}, a rare drop"] = "{quest:8470}, um saque raro",
} end)()
t.guides["forever/alliance/50-60/03-winterspring"] = (function() return {
		["Back to the hills: only the Ice Thistle Matriarchs and Patriarchs carry the horns. Keep killing yetis until level 54: Harlo's wildkin quests are red before that."] = "De volta às colinas: só as Matriarcas e os Patriarcas Cardo de Gelo levam os chifres. Continue matando yetis até o nível 54: as missões de plumacuns de Harlo ficam vermelhas antes disso.",
		["Follow the road east across the zone to the chapel."] = "Siga a estrada para leste atravessando a zona até a capela.",
		["Follow the road west to {npc:9298}'s camp beside the hot springs."] = "Siga a estrada para oeste até o acampamento de {npc:9298}, ao lado das fontes termais.",
		["Follow the southern road east into the {zone:1423}; the ruins of {area:2262} lie south of it. {npc:10926}'s ghost plays by the ruined house at the south end."] = "Siga a estrada do sul para leste até as {zone:1423}; as ruínas de {area:2262} ficam ao sul dela. O fantasma de {npc:10926} brinca junto à casa em ruínas no extremo sul.",
		["Follow {npc:9298}'s directions to the mouth of {area:2256}, past the Frostmaul giants: pass them one at a time."] = "Siga as instruções de {npc:9298} até a entrada do {area:2256}, passando pelos gigantes Friomalho: passe por eles um de cada vez.",
		["For Kernda in {area:1769}: keep it"] = "Para Kernda em {area:1769}: guarde-o",
		["Free Darrowshire Spirits: talk to them"] = "Liberte os Espíritos da Vila das Flechas: fale com eles",
		["Ice Thistle yetis live in the hills south of {area:2244}, Chillwind Chimaeras in the valley toward {area:2255}."] = "Yetis Cardo de Gelo vivem nas colinas ao sul da {area:2244}, Quimeras Ventogelantes no vale rumo a {area:2255}.",
		["Keep it: Gregan in {zone:1444} brews the elixir later"] = "Guarde-o: Gregan em {zone:1444} prepara o elixir mais tarde",
		["On {npc:10978}, by the inn"] = "Em {npc:10978}, perto da estalagem",
		["Optional: {area:1417}"] = "Opcional: {area:1417}",
		["Pick up the supplies around the wagon and take {npc:10301}'s amulet back from the owlbeasts nearby."] = "Pegue os suprimentos em volta da carroça e tome de volta o amuleto de {npc:10301} dos corujursos próximos.",
		["Pristine Yeti Horns"] = "Chifres Impolutos de Yeti",
		["Ride north to {area:2627}. {npc:12384} lives in the ruined hut, and his receipt book lies in the ruined inn nearby."] = "Cavalgue para o norte até {area:2627}. {npc:12384} mora na cabana em ruínas, e o livro de recibos dele está na estalagem em ruínas ali perto.",
		["Ride north-west back to the village."] = "Cavalgue para noroeste de volta à aldeia.",
		["Ride south-east down the valley to {npc:10301}'s damaged crate in the snow at {area:2245}, with his wrecked wagon just east of it."] = "Cavalgue para sudeste descendo o vale até o caixote danificado de {npc:10301} na neve em {area:2245}, com a carroça destruída dele logo a leste.",
		["Ride west along the road to the night elf village."] = "Cavalgue para oeste pela estrada até a aldeia dos elfos noturnos.",
		["Ride west along the road to {npc:10301}."] = "Cavalgue para oeste pela estrada até {npc:10301}.",
		["Short of level 54 after the yetis? Running the {area:1417} (50-54) instead of grinding gets you there faster in a group. Come back to {area:2255} afterwards."] = "Abaixo do nível 54 depois dos yetis? Fazer o {area:1417} (50-54) em grupo em vez de farmar leva você lá mais rápido. Volte a {area:2255} depois.",
		["The Deadwood cauldron in {zone:1448}: keep it"] = "O caldeirão Lenha Morta em {zone:1448}: guarde-o",
		["The Scourge around {area:2264}, west of the chapel, drop both kinds of Scourgestone; Darrowshire Spirits rise from them: talk to each one to free it."] = "O Flagelo em volta de {area:2264}, a oeste da capela, deixa cair os dois tipos de Pedra do Flagelo; Espíritos da Vila das Flechas surgem deles: fale com cada um para libertá-lo.",
		["The Winterfall camp"] = "O acampamento dos Invernosos",
		["The Winterfall furbolg village lies east of {area:2255}: Shaman (56-57), Den Watchers (55-56) and Ursa (57-58), all above you. Kill the Shaman first, they heal, and pull from the edge. {npc:10738} in the cave at the back is elite: stay out."] = "A aldeia dos furbolgs Invernosos fica a leste de {area:2255}: Xamãs (56-57), Vigias do Covil (55-56) e Ursinos (57-58), todos acima de você. Mate os Xamãs primeiro, eles curam, e atraia pelas bordas. {npc:10738}, na caverna dos fundos, é elite: fique longe.",
		["The next guide starts here and flies to {area:3197}."] = "O próximo guia começa aqui e voa para o {area:3197}.",
		["The ruins lie around the frozen lake south of {area:2253}. Pick up the four relic fragments lying in the ruins and the Moontouched Feathers on the ground where the wildkin roam."] = "As ruínas ficam em volta do lago congelado ao sul de {area:2253}. Pegue os quatro fragmentos de relíquia caídos nas ruínas e as Penas Lunamarca no chão onde os plumacuns vagam.",
		["The three pieces of the doll lie in the ruined houses of {area:2262}; picking one up can call out ghosts. Combine them into the doll."] = "As três partes da boneca estão nas casas em ruínas de {area:2262}; pegar uma pode chamar fantasmas. Junte-as na boneca.",
		["The western Winterfall camp sits in the hills between {npc:11556} and {npc:9298}. Any furbolg here can drop an {item:12771} (about one in ten) and, rarely, a {quest:8471}: right-click whichever drops. Keep the {quest:6031} the furbolgs drop for Meilosh."] = "O acampamento oeste dos Invernosos fica nas colinas entre {npc:11556} e {npc:9298}. Qualquer furbolg daqui pode deixar cair um {item:12771} (cerca de um em dez) e, raramente, um {quest:8471}: clique com o botão direito no que cair. Guarde o {quest:6031} que os furbolgs deixam cair para Meilosh.",
		["The western Winterfall furbolgs drop the beads."] = "Os furbolgs Invernosos do oeste deixam cair as contas.",
		["The {area:2247}"] = "As {area:2247}",
		["Walk through {area:1769} to {zone:1448} and fly on to the Eastern Kingdoms ({area:442}, the boat to {area:150}). Fly to {area:271} and ride north up the road through Alterac to {area:3197}."] = "Atravesse {area:1769} até {zone:1448} e voe para os Reinos do Leste ({area:442}, o navio para {area:150}). Voe até {area:271} e cavalgue para o norte pela estrada através de Alterac até o {area:3197}.",
		["grind on {npc:7460} at the {area:2247}, {zone:1452}"] = "farme {npc:7460} nas {area:2247}, {zone:1452}",
		["{item:12771}, a rare drop"] = "{item:12771}, item raro",
		["{npc:10301}'s camp"] = "Acampamento de {npc:10301}",
		["{npc:10301}'s supplies"] = "Suprimentos de {npc:10301}",
		["{npc:10431}: keep both for the Plaguelands"] = "{npc:10431}: guarde os dois para as Terras Pestilentas",
		["{npc:10926}'s doll"] = "A boneca de {npc:10926}",
		["{npc:10978}: {npc:7583} and {npc:10977} come later"] = "{npc:10978}: {npc:7583} e {npc:10977} vêm depois",
		["{npc:11038}: {npc:12250} is a level 54 elite"] = "{npc:11038}: {npc:12250} é elite de nível 54",
		["{npc:11118}: the last guide binds here, so this usually ticks at once"] = "{npc:11118}: o guia anterior vincula você aqui, então isto costuma ser marcado na hora",
		["{npc:11556} guards the mouth of {area:1769}, north-west of {npc:9298}."] = "{npc:11556} guarda a entrada de {area:1769}, a noroeste de {npc:9298}.",
		["{npc:11629}: keep it for {area:2262}"] = "{npc:11629}: guarde-o para {area:2262}",
		["{npc:12250} is elite: grouping up is advised. He waits at the bottom of the {area:2261}, the crypt in the south-west of the zone."] = "{npc:12250} é elite: é recomendado formar grupo. Ele espera no fundo da {area:2261}, a cripta no sudoeste da zona.",
		["{quest:5152}, in the {zone:1422}: keep it"] = "{quest:5152}, nas {zone:1422}: guarde-a",
		["{quest:6031}, for Meilosh later"] = "{quest:6031}, para Meilosh mais tarde",
		["{quest:8471}, a rare drop"] = "{quest:8471}, item raro",
} end)()
t.guides["forever/alliance/50-60/04-western-plaguelands"] = (function() return {
		["Andorhal"] = "Andorhal",
		["Andorhal Watches"] = "Relógios de Andorhal",
		["Back north to the {area:202}: the cauldron offers its own task now. The ghouls nearby drop Somatic Intensifiers."] = "Volte para o norte até {area:202}: o caldeirão agora oferece a própria tarefa. Os carniçais por perto deixam cair Intensificadores Somáticos.",
		["Buy one {item:13320} from {npc:11056} for Felstone's cauldron, right before you go: the quickeners vanish after 30 minutes."] = "Compre um {item:13320} de {npc:11056} para o caldeirão do Campo Pedravil, logo antes de ir: os aceleradores somem após 30 minutos.",
		["Buy two more Arcane Quickeners for the {area:202}'s and Dalson's cauldrons, and ride straight there: they vanish after 30 minutes."] = "Compre mais dois Aceleradores Arcanos para os caldeirões de {area:202} e das Lágrimas de Dalson, e vá direto para lá: eles somem após 30 minutos.",
		["Climb the hill west of {area:190} to look down on the town."] = "Suba a colina a oeste de {area:190} para observar a cidade lá de cima.",
		["Cross the river east to the {area:2261}, the crypt in the south-west of the zone. The {object:177667} lies inside: its key is on {npc:12248} in the far north-east, done in the next guide."] = "Atravesse o rio para o leste até a {area:2261}, a cripta no sudoeste da zona. O {object:177667} está lá dentro: a chave está com {npc:12248}, no extremo nordeste, no próximo guia.",
		["Cross the river west to {npc:1855}'s hut."] = "Atravesse o rio para o oeste até a cabana de {npc:1855}.",
		["Diseased Grizzlies"] = "Ursos-cinzentos Doentes",
		["Diseased Wolves"] = "Lobos Doentes",
		["Fly to {area:392}."] = "Voe para {area:392}.",
		["For the druids of {zone:1457}: keep it"] = "Para os druidas de {zone:1457}: guarde",
		["For {zone:1448}: keep it"] = "Para {zone:1448}: guarde",
		["For {zone:1451}: keep it"] = "Para {zone:1451}: guarde",
		["For {zone:1453}: keep it"] = "Para {zone:1453}: guarde",
		["From {area:392}, fly to {area:2255} and ride south to {area:2250}."] = "De {area:392}, voe para {area:2255} e cavalgue para o sul até {area:2250}.",
		["From {area:702}, fly to {area:1116}."] = "De {area:702}, voe para {area:1116}.",
		["Gaeriyan in {area:976}: keep it"] = "Gaeriyan em {area:976}: guarde",
		["Horgus' skull lies at {area:2624} and Marduk's sword in the {area:2623}, each where ghosts fight; grown Plaguehounds hunt the plains between."] = "O Crânio de Horgus está em {area:2624} e a espada de Marduque em {area:2623}, ambos onde fantasmas lutam; Cães Pestilentos adultos caçam nas planícies entre eles.",
		["Listen to his story"] = "Ouça a história dele",
		["Mark {npc:10902} with the {item:12815}"] = "Marque a {npc:10902} com a {item:12815}",
		["Mark {npc:10903} with the {item:12815}"] = "Marque a {npc:10903} com a {item:12815}",
		["Mark {npc:10904} with the {item:12815}"] = "Marque a {npc:10904} com a {item:12815}",
		["Mark {npc:10905} with the {item:12815}"] = "Marque a {npc:10905} com a {item:12815}",
		["More watches"] = "Mais relógios",
		["Radley and Durgen"] = "Eiras e Durgen",
		["Ride back south to the camp."] = "Cavalgue de volta para o sul até o acampamento.",
		["Ride back to {area:3197} and fly to {area:150}, take the boat to {area:442} and fly to {area:702}; the portal leads up to {zone:1457}."] = "Volte para {area:3197} e voe para {area:150}, pegue o barco para {area:442} e voe para {area:702}; o portal leva até {zone:1457}.",
		["Ride east to the border river: {npc:1855} lives in a small hut on the bank."] = "Cavalgue para o leste até o rio da fronteira: {npc:1855} mora numa pequena cabana na margem.",
		["Ride north up the road to the Northridge lumber mill; {npc:11610} hides at the camp's edge."] = "Cavalgue para o norte pela estrada até a Madeireira Beiranorte; {npc:11610} se esconde na borda do acampamento.",
		["Ride north-west to the Dalson farm. The diary lies in the barn; a wandering skeleton carries the outhouse key, and {npc:10836} waits in the outhouse with the cabinet key."] = "Cavalgue para o noroeste até a fazenda dos Dalson. O diário está no celeiro; um esqueleto errante carrega a chave da casinha, e {npc:10836} espera na casinha com a chave do armário.",
		["Ride north-west to {area:2276}, at the edge of the {area:2277}."] = "Cavalgue para o noroeste até {area:2276}, na borda de {area:2277}.",
		["Ride south to {area:201}, where {npc:11078} guards the cauldron."] = "Cavalgue para o sul até {area:201}, onde {npc:11078} guarda o caldeirão.",
		["Ride south-west to the camp."] = "Cavalgue para o sudoeste até o acampamento.",
		["Ride west along the road to the hot springs."] = "Cavalgue para o oeste pela estrada até as fontes termais.",
		["Ride west to {area:2627}. Plaguehound Runts, Plaguebats and Carrion Grubs roam its woods; fill the {item:15042} at the big termite mounds and kill the Frenzied Plaguehounds further north."] = "Cavalgue para o oeste até {area:2627}. Cães Pestilentos Miúdos, Quirópragos e Vermes Carniceiros vagam pelos bosques; encha a {item:15042} nos grandes cupinzeiros e mate os Cães Pestilentos Frenéticos mais ao norte.",
		["Skeletal Flayers and Slavering Ghouls roam the fields north of the camp; all the Scourge here drop Scourgestones."] = "Esfoladores Descarnados e Carniçais Salivantes vagam pelos campos ao norte do acampamento; todo o Flagelo daqui deixa cair Pedras do Flagelo.",
		["Small lockboxes lie in the rubble all over Andorhal; each holds a watch."] = "Pequenos cofres estão nos escombros por toda Andorhal; cada um guarda um relógio.",
		["Take the boat to the mainland and ride north-east to {npc:14637}'s camp by the {area:1119}."] = "Pegue o barco para o continente e cavalgue para o nordeste até o acampamento de {npc:14637}, junto a {area:1119}.",
		["Temple of the Moon"] = "Templo da Lua",
		["Ten {item:11040} from the {item:11020}"] = "Dez {item:11040} da {item:11020}",
		["The Andorhal watchtowers"] = "As torres de vigia de Andorhal",
		["The Scarlet Crusade"] = "A Cruzada Escarlate",
		["The Scarlet Medics, Hunters, Knights and Mages patrol the lumber camp and the road toward {area:190}."] = "Socorristas Escarlates, Caçadores Escarlates, Cavaleiros Escarlates e Magos Escarlates patrulham a madeireira e a estrada rumo a {area:190}.",
		["The cauldron now offers its own task; the skeletons around it drop Osseous Agitators."] = "O caldeirão agora oferece a própria tarefa; os esqueletos ao redor deixam cair Agitadores Ósseos.",
		["The cauldron sits at the {area:202}, by {npc:10739}' farm."] = "O caldeirão fica em {area:202}, junto à fazenda de {npc:10739}.",
		["The cauldron sits at {area:200}, north-east of Felstone; its Cauldron Lord stands beside it."] = "O caldeirão fica em {area:200}, a nordeste do Campo Pedravil; o Mestre da Caldeira dele fica ao lado.",
		["The fields"] = "Os campos",
		["The next guide starts here in {area:392} and flies on to {area:976}."] = "O próximo guia começa aqui em {area:392} e voa para {area:976}.",
		["The shrunken giants roam the {area:1119}; the sea elementals wade along the coast to the west."] = "Os gigantes encolhidos vagam por {area:1119}; os Elementais do Mar andam pela costa a oeste.",
		["Use the {item:12627} by the grain silos to draw out Temporal Parasites. {quest:5154} is one of the musty tomes in the town hall. Every skeleton in town drops {quest:5537}."] = "Use o {item:12627} junto aos silos de grãos para atrair Parasitas Temporais. {quest:5154} é um dos Tomos Mofados na prefeitura. Todo esqueleto da cidade deixa cair {quest:5537}.",
		["Use the {item:12815} at the foot of each of the four watchtowers around the edge of Andorhal, north of the camp."] = "Use a {item:12815} ao pé de cada uma das quatro torres de vigia na periferia de Andorhal, ao norte do acampamento.",
		["Walk into {area:1769} and take the {zone:1450} branch of the tunnel to {area:2361}."] = "Entre em {area:1769} e pegue o ramo do túnel para {zone:1450} até {area:2361}.",
		["Zapped giants and sea elementals"] = "Gigantes irradiados e Elementais do Mar",
		["grind on {npc:1796} at the {area:202}, {zone:1422}"] = "mate {npc:1796} em {area:202}, {zone:1422}",
		["{area:190} overlook"] = "Mirante de {area:190}",
		["{area:199} cauldron"] = "Caldeirão de {area:199}",
		["{area:200} cauldron"] = "Caldeirão de {area:200}",
		["{area:201} cauldron"] = "Caldeirão de {area:201}",
		["{area:202} cauldron"] = "Caldeirão de {area:202}",
		["{item:12894}, at the monument"] = "{item:12894}, no monumento",
		["{item:12954} lies in the town hall of {area:190}, west of {npc:1855}: the Scarlet guards stand close together."] = "{item:12954} está na prefeitura de {area:190}, a oeste de {npc:1855}: os guardas escarlates ficam bem juntos.",
		["{item:12955} lies east of the barn at {area:201}."] = "{item:12955} está a leste do celeiro em {area:201}.",
		["{item:13320}, from {npc:11056}"] = "{item:13320}, de {npc:11056}",
		["{npc:10300} in {zone:1452}: keep it"] = "{npc:10300} em {zone:1452}: guarde",
		["{npc:10300}: her escort comes later on the route"] = "{npc:10300}: a escolta dela vem mais tarde na rota",
		["{npc:10667} waits in the ruined inn on the west side of Andorhal."] = "{npc:10667} espera na estalagem em ruínas no lado oeste de Andorhal.",
		["{npc:10739} stands by the farm at the {area:202}, north-east of the fields."] = "{npc:10739} fica junto à fazenda em {area:202}, a nordeste dos campos.",
		["{npc:10778}'s ghost wanders by the farmhouse of {area:199}, west of {area:200}; her parcel lies inside."] = "O fantasma de {npc:10778} vaga junto à casa da fazenda de {area:199}, a oeste de {area:200}; o embrulho dela está lá dentro.",
		["{npc:10878} and {npc:7740} stand by the Temple of the Moon; fill {item:11682} at the moonwell inside."] = "{npc:10878} e {npc:7740} ficam junto ao Templo da Lua; encha o {item:11682} no poço lunar lá dentro.",
		["{npc:10927}'s farmhouse stands on the hill east of the camp; {npc:10936}'s monument is just north of it."] = "A casa de fazenda de {npc:10927} fica na colina a leste do acampamento; o monumento de {npc:10936} fica logo ao norte dela.",
		["{npc:11038}, by the graves south of the chapel"] = "{npc:11038}, junto aos túmulos ao sul da capela",
		["{npc:11075} guards the cauldron in {area:199}, west of Andorhal."] = "{npc:11075} guarda o caldeirão em {area:199}, a oeste de Andorhal.",
		["{npc:11140} stands by Augustus' hut in {area:2627}."] = "{npc:11140} fica junto à cabana de Augustus em {area:2627}.",
		["{npc:11613} walks the Northridge camp east of {npc:11610}; {npc:11611} guards the tower at {area:190}'s southern approach."] = "{npc:11613} anda pela Madeireira Beiranorte a leste de {npc:11610}; {npc:11611} guarda a torre na entrada sul de {area:190}.",
		["{npc:11616}: the termites come later, in {area:2627}"] = "{npc:11616}: os cupins vêm depois, em {area:2627}",
		["{npc:11886} is elite: grouping up is advised"] = "{npc:11886} é elite: recomenda-se ir em grupo",
		["{npc:16256}: the last guide binds here, so this usually ticks at once"] = "{npc:16256}: o guia anterior vincula você aqui, então isto costuma ser marcado na hora",
		["{npc:1852} is a level 61 elite"] = "{npc:1852} é elite de nível 61",
		["{npc:1852} is elite: grouping up is advised. He guards his phylactery in the middle of Andorhal."] = "{npc:1852} é elite: recomenda-se ir em grupo. Ele guarda o filactério no meio de Andorhal.",
		["{npc:5411} in {area:976}: keep it"] = "{npc:5411} em {area:976}: guarde",
		["{npc:5901}, on the coast north of town"] = "{npc:5901}, na costa ao norte da cidade",
		["{npc:7740}: keep it for {area:976}"] = "{npc:7740}: guarde para {area:976}",
		["{npc:7775}'s camp lies north of the {area:1119}. He sells the {item:11243} once he has his bait."] = "O acampamento de {npc:7775} fica ao norte de {area:1119}. Ele vende o {item:11243} quando recebe a isca.",
		["{npc:7900}: keep it for {zone:1446}"] = "{npc:7900}: guarde para {zone:1446}",
		["{npc:8496}: keep it for Un'Goro"] = "{npc:8496}: guarde para a Cratera Un'Goro",
		["{npc:9047}, in the {area:1658}"] = "{npc:9047}, em {area:1658}",
		["{object:175924}, in the farmhouse"] = "{object:175924}, na casa da fazenda",
		["{quest:5210}, at {area:2268}: keep it"] = "{quest:5210}, em {area:2268}: guarde",
		["{quest:6762} in {zone:1450}: keep it"] = "{quest:6762} em {zone:1450}: guarde",
		["{zone:1455}, where the next guide trains, has no druid trainer"] = "{zone:1455}, onde o próximo guia treina, não tem instrutor de druida",
} end)()
t.guides["forever/alliance/50-60/05-silithus"] = (function() return {
		["Chromie in Andorhal: keep it"] = "Crona nas Ruínas de Andorhal: guarde-a",
		["Dredge Crushers dig further west; Stonelash Pincers, Flayers and Rock Stalkers hunt the same sands."] = "Os Dragasmagas cavam mais a oeste; Tenazes Petraçoite, Esfoladores Petraçoite e Espreitadoras de Rocha caçam nas mesmas areias.",
		["Dredge Strikers dig in the dunes north-west of the hold; Stonelash Scorpids and Sand Skitterers roam all around."] = "Os Dragatacas cavam nas dunas a noroeste do forte; Escorpídeos Petraçoite e Rastejantes da Areia vagueiam por toda parte.",
		["Dredge and scorpids"] = "Dragas e escorpídeos",
		["Fly from {area:976} to {area:541}. {npc:8737}'s hut stands at the {area:538}, west of the refuge; {npc:9117} is up the hill behind it."] = "Voe de {area:976} para {area:541}. A cabana de {npc:8737} fica em {area:538}, a oeste do refúgio; {npc:9117} está no alto da colina atrás dela.",
		["Fly to {area:271} and ride north up the road toward Alterac: Haggerdin camps at {area:1056} beside it."] = "Voe para {area:271} e siga a estrada para o norte em direção às Montanhas de Alterac: o Tenente Haggerdin acampa em {area:1056}, ao lado dela.",
		["For {area:3197}: keep it"] = "Para {area:3197}: guarde-a",
		["For {npc:10778}: keep it"] = "Para {npc:10778}: guarde-a",
		["For {zone:1448}: keep it"] = "Para {zone:1448}: guarde-a",
		["From {area:392}, fly to {area:976}."] = "De {area:392}, voe para {area:976}.",
		["Its jars are filled on the next Un'Goro visit"] = "As jarras dela são enchidas na próxima visita à Cratera Un'Goro",
		["On {npc:7583}"] = "Em {npc:7583}",
		["Ride back to {area:3425} and fly to {area:392}."] = "Volte para {area:3425} e voe para {area:392}.",
		["Ride east to the {area:2742} tower in {area:2738}; climb it and kill the ambushers that rise for the encrusted object."] = "Siga para o leste até a torre de {area:2742} em {area:2738}; suba nela e mate os emboscadores que surgem pelo objeto incrustado.",
		["Ride east to {npc:13220}."] = "Siga para o leste até {npc:13220}.",
		["Ride north to the {area:2277}'s north-eastern edge."] = "Siga para o norte até a borda nordeste de {area:2277}.",
		["Ride on north to {area:3197} and fly to {area:2268}."] = "Continue para o norte até {area:3197} e voe para {area:2268}.",
		["Ride out of the crater's north-western pass into {zone:1451} and on to {area:3425}."] = "Saia da cratera pelo desfiladeiro noroeste até {zone:1451} e siga até {area:3425}.",
		["Ride south-west to the {area:2261}. The mound of dirt lies inside. {npc:11886} is elite: grouping up is advised."] = "Siga para o sudoeste até a {area:2261}. O monte de terra fica lá dentro. {npc:11886} é elite: recomenda-se formar um grupo.",
		["Ride south-west to {npc:7771}'s camp at the {area:1938}."] = "Siga para o sudoeste até o acampamento de {npc:7771} em {area:1938}.",
		["Scourge Champions"] = "Campeões do Flagelo",
		["Scourge Champions (59) roam the {area:2270}, north of {area:2268}. Pass {npc:11063}'s {item:13156} over each one you kill: the skulls that resonate are the ones he wants. Pull them one at a time."] = "Os Campeões do Flagelo (59) vagueiam por {area:2270}, ao norte de {area:2268}. Passe o {item:13156} de {npc:11063} sobre cada um que você matar: os crânios que ressoam são os que ele quer. Puxe-os um de cada vez.",
		["Sixty {item:2592}, if you carry them"] = "Sessenta {item:2592}, se você tiver",
		["Take the boat from {area:392} to {area:35} and fly to {zone:1453}."] = "Pegue o barco de {area:392} para {area:35} e voe para {zone:1453}.",
		["Take the {area:2257} to {zone:1455}."] = "Pegue o {area:2257} para {zone:1455}.",
		["Tar Beasts wallow in the {area:538}; the fire elementals of {area:537} in the middle carry the ash; the Gorishi wasps of the {area:540} in the south carry the gland. Every creature in the crater can drop {item:11018}."] = "Os Monstros de Piche chafurdam em {area:538}; os elementais de fogo de {area:537}, no meio, carregam a cinza; as vespas Gorishi de {area:540}, no sul, carregam a glândula. Toda criatura da cratera pode deixar cair {item:11018}.",
		["The crater"] = "A cratera",
		["The next guide starts here in {area:392}."] = "O próximo guia começa aqui, em {area:392}.",
		["The tortured druids and sentinels haunt the ruined village south-west of {npc:13220}."] = "Os Druidas Torturados e as Sentinelas Torturadas assombram a aldeia em ruínas a sudoeste de {npc:13220}.",
		["The western dunes"] = "As dunas do oeste",
		["The {area:2742} tower"] = "A torre de {area:2742}",
		["Umber in {zone:1450}: keep it"] = "Umbero em {zone:1450}: guarde-a",
		["grind on {npc:8532} at the {area:2258}, {zone:1423}"] = "farme {npc:8532} no {area:2258}, {zone:1423}",
		["{item:13155}, from the Scourge Champions"] = "{item:13155}, dos Campeões do Flagelo",
		["{item:14613}, from {npc:11886}"] = "{item:14613}, de {npc:11886}",
		["{npc:14724}, by the tram"] = "{npc:14724}, perto do metrô",
		["{npc:332}, in SI:7"] = "{npc:332}, na AVIN",
		["{npc:3520}, who walks the canals"] = "{npc:3520}, que anda pelos canais",
		["{npc:9299} waits at the graveyard just east of town; the gravestone stands nearby."] = "{npc:9299} espera no cemitério logo a leste da cidade; a lápide fica perto.",
		["{quest:3444} is in {area:392}"] = "{quest:3444} fica em {area:392}",
		["{quest:6184} at {area:3197}: keep it"] = "{quest:6184} em {area:3197}: guarde-a",
} end)()
t.guides["forever/alliance/50-60/06-silithus"] = (function() return {
		["Andorhal"] = "Ruínas de Andorhal",
		["Angerclaw bears and Felpaw wolves"] = "Ursos Garraivosos e Lobos Patavil",
		["Araj is elite: grouping up is advised."] = "Araj, o Evocador, é elite: recomenda-se formar um grupo.",
		["Back into {area:1770}: {npc:9861} and {npc:9860} guard {npc:9517} in its deepest chamber."] = "De volta a {area:1770}: {npc:9861} e {npc:9860} protegem {npc:9517} na câmara mais profunda.",
		["Bronzebeard's Encampment"] = "Acampamento Barbabronze",
		["Climb {area:537} in the middle of the crater and use the {item:14644} by the lava lake at the top, with two Thorium Bars in your bags. Fill {npc:9616}'s Empty Pure Sample Jars on the Primal Oozes in the pools around the ridge."] = "Suba {area:537}, no meio da cratera, e use o {item:14644} junto ao lago de lava no topo, com duas Barras de Tório nas bolsas. Encha as Jarras de Amostra Pura Vazias de {npc:9616} nas Gosmas Primevas das poças ao redor da serra.",
		["Cross the river east of {npc:1855} into {area:2627}. The Terrordale Spirits haunt the woods there."] = "Atravesse o rio a leste de {npc:1855} até {area:2627}. Os Espíritos da Várzea do Medo assombram o bosque ali.",
		["Dredge Crushers roam the dunes between {area:2743} and {area:3425}, on your way back. {npc:15181} only offers {quest:8304} from level 58."] = "Os Dragasmagas vagueiam pelas dunas entre {area:2743} e {area:3425}, no caminho de volta. {npc:15181} só oferece {quest:8304} a partir do nível 58.",
		["Fly to {area:3137} in {zone:1447} and ride west along the road to {area:2358}, just over the {zone:1440} border."] = "Voe para {area:3137} em {zone:1447} e siga para o oeste pela estrada até {area:2358}, logo depois da fronteira de {zone:1440}.",
		["Fly to {area:976}."] = "Voe para {area:976}.",
		["Follow the road north to {area:1767}. The Irontree Stompers carry the heart; finish the claws on the Angerclaw Grizzlies and Felpaw Ravagers of the north."] = "Siga a estrada para o norte até {area:1767}. Os Pisoteadores de Ferrárbol carregam o coração; termine as garras nos Ursos-cinzentos Garraivosos e nos Assoladores Patavil do norte.",
		["Follow the road south-west out of the pass to {area:3425}."] = "Siga a estrada para o sudoeste, saindo do desfiladeiro, até {area:3425}.",
		["Go back down to {area:702}, take the boat to {area:442} and the boat on to {area:17203}. Bring sixty Silk, sixty Mageweave and sixty {item:14047} for {npc:14722}: buy what you lack at the Auction House."] = "Desça de volta até {area:702}, pegue o barco para {area:442} e depois o barco até {area:17203}. Leve sessenta Sedas, sessenta Magitramas e sessenta {item:14047} para {npc:14722}: compre o que faltar na Casa de Leilões.",
		["Grind to 58"] = "Upe até o 58",
		["Grind to 59"] = "Upe até o 59",
		["Grind to 60"] = "Upe até o 60",
		["Hand him the ten texts you kept"] = "Entregue a ele os dez textos que você guardou",
		["Havunth's camp sits just west of {area:3425}."] = "O acampamento do Guardião do Crepúsculo Havunth fica logo a oeste de {area:3425}.",
		["Hearth to {area:1519} and train your level 60 spells. This is the end of the leveling route: look at the reputation and dungeon guides next."] = "Regresse para {area:1519} e treine seus feitiços de nível 60. Este é o fim da rota de evolução: veja depois os guias de reputação e de masmorras.",
		["Hearth to {area:392} and fly to {area:976}. Buy two Thorium Bars at the Auction House here for {quest:5801}."] = "Regresse para {area:392} e voe para {area:976}. Compre duas Barras de Tório na Casa de Leilões daqui para {quest:5801}.",
		["Into {zone:1451}"] = "Rumo a {zone:1451}",
		["Irontree Stompers"] = "Pisoteadores de Ferrárbol",
		["Keep the {item:11169}, the claws and the heart he hands back"] = "Guarde o {item:11169}, as garras e o coração que ele devolve",
		["Keep west on the road to {npc:9298}'s camp beside the hot springs."] = "Continue para o oeste pela estrada até o acampamento de {npc:9298}, ao lado das fontes termais.",
		["Level 60"] = "Nível 60",
		["Ride back north to {area:2255} and west along the road to the night elf village."] = "Volte para o norte até {area:2255} e siga para o oeste pela estrada até a aldeia dos elfos noturnos.",
		["Ride back south along the road to the Sanctuary."] = "Volte para o sul pela estrada até o Santuário.",
		["Ride back south-east to the hermit."] = "Volte para o sudeste até o eremita.",
		["Ride back south-west to {area:3197}."] = "Volte para o sudoeste até {area:3197}.",
		["Ride back to {area:3137} and fly to {area:2255}."] = "Volte para {area:3137} e voe para {area:2255}.",
		["Ride east into the hills. Use the {item:11169} to summon {quest:4005}, then defeat him for the totem."] = "Siga para o leste até as colinas. Use o {item:11169} para invocar {quest:4005} e derrote-o para obter o totem.",
		["Ride east to the ruins of {area:2738}. The {object:179565} lies among the ruined buildings, watched by Tortured Sentinels."] = "Siga para o leste até as ruínas de {area:2738}. {object:179565} está entre os edifícios em ruínas, vigiado por Sentinelas Torturadas.",
		["Ride north along the west side to Mayna's small camp."] = "Siga para o norte pelo lado oeste até o pequeno acampamento da Tutora do Crepúsculo Mayna.",
		["Ride north out of {area:415} into {zone:1448} to the druids' camp on the road just past the border."] = "Siga para o norte saindo de {area:415} até {zone:1448}, até o acampamento dos druidas na estrada, logo depois da fronteira.",
		["Ride north to the Deadwood furbolgs' village by the {area:1769} cave mouth."] = "Siga para o norte até a aldeia dos furbolgs de Lenha Morta, perto da entrada da caverna de {area:1769}.",
		["Ride north to {area:541}. Use {npc:10980} beside {npc:10977}."] = "Siga para o norte até {area:541}. Use {npc:10980} ao lado de {npc:10977}.",
		["Ride north up the road to the lumber mill and set the termite barrel down in the middle of it."] = "Siga a estrada para o norte até a serraria e coloque o barril de cupins no meio dela.",
		["Ride south to {area:2250}. Protect {npc:10300} while she lights the torches on the way to the {object:177404}."] = "Siga para o sul até {area:2250}. Proteja {npc:10300} enquanto ela acende as tochas a caminho de {object:177404}.",
		["Ride south-west to the dwarves' camp near the southern mountains and question {npc:15171} and {npc:15170}. {npc:15190}'s satchel lies in the sand just south-east of the camp."] = "Siga para o sudoeste até o acampamento dos anões perto das montanhas do sul e interrogue {npc:15171} e {npc:15170}. A Algibeira do {npc:15190} está na areia, logo a sudeste do acampamento.",
		["Ride south-west to {npc:7771}'s camp at the {area:1938}."] = "Siga para o sudoeste até o acampamento de {npc:7771} em {area:1938}.",
		["Ride west along the crater's northern wall to the pass in the north-west corner that climbs into {zone:1451}."] = "Siga para o oeste ao longo da parede norte da cratera até o desfiladeiro no canto noroeste, que sobe para {zone:1451}.",
		["Running {area:2057} ({area:2298}, south-east {zone:1422}) or {area:2279} instead of grinding gets you there faster in a group. Skip this step to grind solo."] = "Fazer {area:2057} ({area:2298}, sudeste de {zone:1422}) ou {area:2279} em vez de farmar leva você lá mais rápido em grupo. Pule esta etapa para farmar sozinho.",
		["Running {area:2577} in {zone:1444} instead of grinding gets you there faster in a group. Skip this step to grind solo."] = "Fazer {area:2577} em {zone:1444} em vez de farmar leva você lá mais rápido em grupo. Pule esta etapa para farmar sozinho.",
		["Shaman training"] = "Treinamento de xamã",
		["Take the boat from {area:442} to {area:702}."] = "Pegue o barco de {area:442} para {area:702}.",
		["Take the flight path in {area:2361} and fly to {area:442}."] = "Pegue a rota de voo em {area:2361} e voe para {area:442}.",
		["Take the portal up to {zone:1457}."] = "Pegue o portal para subir até {zone:1457}.",
		["Take the road west down into the crater and ride to the {area:540}, the silithid cave in the south. The {npc:10041} waits in its deepest chamber."] = "Pegue a estrada para o oeste, desça até a cratera e siga até a {area:540}, a caverna dos silitídeos no sul. {npc:10041} espera na câmara mais profunda.",
		["Take the {area:1769} tunnel from its {zone:1452} mouth, west of {npc:9298}, and follow the {area:493} branch to {area:2361}. {npc:11939} studies by the lake shore."] = "Pegue o túnel de {area:1769} pela entrada de {zone:1452}, a oeste de {npc:9298}, e siga o ramal de {area:493} até {area:2361}. {npc:11939} estuda à beira do lago.",
		["Take the {area:2257} to {zone:1455}. {npc:14724} and {npc:14723} each want sixty Wool, sixty Silk and sixty Mageweave, then sixty {item:14047}: 120 of each in all, from your bags or the Auction House."] = "Pegue o {area:2257} para {zone:1455}. {npc:14724} e {npc:14723} querem, cada um, sessenta Lãs, sessenta Sedas e sessenta Magitramas, e depois sessenta {item:14047}: 120 de cada no total, das suas bolsas ou da Casa de Leilões.",
		["Ten more for {quest:8323}"] = "Mais dez para {quest:8323}",
		["The Twilight's Hammer dig fills the north-west corner: tablet fragments lie on the ground and the Dust Stormers and Desert Rumblers carry them too. Every cultist can drop an {item:20404}: keep twenty, ten for {npc:15306} and ten for {npc:15194} later."] = "A escavação do Martelo do Crepúsculo ocupa o canto noroeste: há fragmentos de tábua no chão, e as Tempestades de Poeira e os Estrondores do Deserto também os carregam. Todo sectário pode deixar cair um {item:20404}: guarde vinte, dez para {npc:15306} e dez para {npc:15194} depois.",
		["The hermit hides among the rocks south-east of {area:2738}."] = "O eremita se esconde entre as rochas a sudeste de {area:2738}.",
		["The {area:2479}"] = "{area:2479}",
		["The {area:2739}"] = "{area:2739}",
		["The {area:3098}"] = "{area:3098}",
		["The {npc:7446} bears roam the snowy valley south of {area:2250}."] = "Os ursos {npc:7446} vagueiam pelo vale nevado ao sul de {area:2250}.",
		["Toward the north-west pass"] = "Rumo ao desfiladeiro noroeste",
		["Twilight Tablet Fragments"] = "Fragmentos de Tabuleta do Crepúsculo",
		["Twilight's Hammer cultists"] = "Sectários do Martelo do Crepúsculo",
		["Use the jars on slain oozes"] = "Use as jarras nas gosmas mortas",
		["Wait a moment for {npc:9116}"] = "Espere um pouco por {npc:9116}",
		["You start in {area:392}, where the previous guide hearthed you. Fly to {area:415}."] = "Você começa em {area:392}, para onde o guia anterior mandou você regressar. Voe para {area:415}.",
		["grind on {npc:11741} at the dunes east of {area:2743}, {zone:1451}"] = "farme {npc:11741} nas dunas a leste de {area:2743}, {zone:1451}",
		["grind on {npc:14564} at {area:2627}, {zone:1423}"] = "farme {npc:14564} em {area:2627}, {zone:1423}",
		["grind on {npc:7446} at the valley south of {area:2250}, {zone:1452}"] = "farme {npc:7446} no vale ao sul de {area:2250}, {zone:1452}",
		["{area:1770} braziers"] = "Braseiros de {area:1770}",
		["{area:1770} is the cave at the back of {area:1763}, west of the road. Use the {item:12906} on the four braziers inside. Kill the Angerclaw bears and Felpaw wolves you pass for the {item:11172}."] = "{area:1770} é a caverna no fundo de {area:1763}, a oeste da estrada. Use o {item:12906} nos quatro braseiros lá dentro. Mate os Ursos Garraivosos e os Lobos Patavil pelo caminho para obter {item:11172}.",
		["{area:2057} (optional)"] = "{area:2057} (opcional)",
		["{area:2057} fits levels 58 to 60; {quest:5505} is handed in at {area:3197} below."] = "{area:2057} é para os níveis 58 a 60; {quest:5505} é entregue em {area:3197}, abaixo.",
		["{area:2577} (optional)"] = "{area:2577} (opcional)",
		["{area:2577} fits levels 55 to 60; the {npc:7446} grind below gets you to 59 alone."] = "{area:2577} é para os níveis 55 a 60; farmar {npc:7446}, abaixo, leva você ao 59 sozinho.",
		["{npc:10667} waits in the ruined inn on the west side of Andorhal, the ruined city north of the camp. {npc:1852} guards his phylactery in the middle of the town."] = "{npc:10667} espera na estalagem em ruínas no lado oeste das Ruínas de Andorhal, a cidade em ruínas ao norte do acampamento. {npc:1852} protege o filactério dele no meio da cidade.",
		["{npc:10778}'s ghost wanders by the farmhouse of {area:199}, west of Andorhal. The Jabbering Ghouls in the field carry the other half of the charm: combine the two halves."] = "O fantasma de {npc:10778} vagueia perto da casa da fazenda de {area:199}, a oeste das Ruínas de Andorhal. Os Carniçais Grasnantes do campo carregam a outra metade do amuleto: junte as duas metades.",
		["{npc:10924}: ends in {zone:1452}, keep it"] = "{npc:10924}: termina em {zone:1452}, guarde-a",
		["{npc:11557}, if you have thirty {quest:6031}"] = "{npc:11557}, se você tiver trinta {quest:6031}",
		["{npc:11558}, just inside the cave: only from Neutral with the Timbermaw"] = "{npc:11558}, logo na entrada da caverna: só a partir de Neutro com os Presamatos",
		["{npc:11801}'s house stands in {area:2361}, east of {npc:11939}."] = "A casa de {npc:11801} fica em {area:2361}, a leste de {npc:11939}.",
		["{npc:11803} holds the cultists' camp in the far south-west."] = "{npc:11803} comanda o acampamento dos sectários no extremo sudoeste.",
		["{npc:14722}, in the {object:2096}"] = "{npc:14722}, em {object:2096}",
		["{npc:15174}, the innkeeper"] = "{npc:15174}, o estalajadeiro",
		["{npc:17080} camps outside {area:2743}, the western hive. Pick up a Silithyst at one of the red geysers nearby and carry it to the Alliance extractor at his camp."] = "{npc:17080} acampa fora de {area:2743}, a colmeia do oeste. Pegue um Silitista em um dos gêiseres vermelhos próximos e leve-o ao extrator da Aliança no acampamento dele.",
		["{npc:17082}, at the Alliance tents"] = "{npc:17082}, nas tendas da Aliança",
		["{npc:1852} is a level 61 elite"] = "{npc:1852} é um elite de nível 61",
		["{npc:1855} (optional)"] = "{npc:1855} (opcional)",
		["{npc:1855} lives in a small hut on the border river, north-east of the lumber camp. Hand in {quest:5781} if you finished it."] = "{npc:1855} Fordring vive numa pequena cabana à beira do rio da fronteira, a nordeste da madeireira. Entregue {quest:5781} se você a concluiu.",
		["{npc:3516}, atop the {area:1658}"] = "{npc:3516}, no alto de {area:1658}",
		["{npc:4155}, in the bank"] = "{npc:4155}, no banco",
		["{npc:6791}: the last guide hearths you here, so this usually ticks at once"] = "{npc:6791}: o guia anterior leva você até aqui com a pedra de regresso, então isto costuma ser marcado na hora",
		["{npc:7740} in {zone:1457}: keep it"] = "{npc:7740} em {zone:1457}: guarde-a",
		["{npc:7740}, in the Temple of the Moon"] = "{npc:7740}, no Templo da Lua",
		["{npc:8737}, at the back of the refuge"] = "{npc:8737}, no fundo do refúgio",
		["{npc:9598} waits in {area:1767}. Escort her out of the woods and keep her alive."] = "{npc:9598} espera em {area:1767}. Escolte-a para fora do bosque e mantenha-a viva.",
		["{object:176091}, if you found the Firewater flask in {zone:1452}"] = "{object:176091}, se você encontrou o Frasco Vazio de Aguardente em {zone:1452}",
		["{quest:5085}: {npc:9298} in {zone:1452}, keep it"] = "{quest:5085}: {npc:9298} em {zone:1452}, guarde-a",
		["{zone:1451}, {zone:1448}, {zone:1452} & the Plaguelands"] = "{zone:1451}, {zone:1448}, {zone:1452} e as Terras Pestilentas",
		["{zone:1453} has no shaman trainer"] = "{zone:1453} não tem instrutor de xamã",
		["{zone:1453} has no shaman trainer: take the {area:2257} from the {object:28027} to {zone:1455} and train your level 60 spells with {npc:258098}."] = "{zone:1453} não tem instrutor de xamã: pegue o {area:2257} de {object:28027} para {zone:1455} e treine seus feitiços de nível 60 com {npc:258098}.",
} end)()
t.guides["forever/alliance/dwarf-gnome/01-dun-morogh"] = (function() return {
		["A few Frostmane Troll Whelps if you are short"] = "Alguns Jovens Trolls Jubafria se faltar algum",
		["A few more troggs outside if you are short"] = "Mais alguns troggs lá fora se faltar algum",
		["Back through the tunnel to {npc:257597}' cave above the farm."] = "Volte pelo túnel até a caverna de {npc:257597} acima da fazenda.",
		["Back to {area:77}"] = "De volta a {area:77}",
		["Back to {npc:257446} in {area:77}. He gives you the {item:6635}: take the rubble-marked path that climbs west from the south of the valley to the Spirit Stone on the ridge, drink the Sapta beside it and speak to the {npc:5891}, then bring its {item:6656} back to Teo."] = "De volta a {npc:257446} em {area:77}. Ele lhe dá a {item:6635}: pegue a trilha marcada por escombros que sobe para oeste a partir do sul do vale até a Pedra Espiritual na crista, beba a Sapta ao lado dela e fale com a {npc:5891}, depois leve o {item:6656} dela de volta a Teo.",
		["Back to {npc:257597}"] = "De volta a {npc:257597}",
		["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls. {zone:1436} is next, west of {area:87}."] = "De volta a {npc:6122}. Use o {item:6928} no círculo de evocação do porão do {object:2164} e derrote o emissário do caos que ele chama. {zone:1436} é a próxima, a oeste de {area:87}.",
		["Boars and bears"] = "Javalis e ursos",
		["Cornelius is missing in the {area:136}: find him inside, then go back to Gretchen."] = "Cornelius está desaparecido no {area:136}: encontre-o lá dentro e depois volte até Gretchen.",
		["Crag Boars and Young Black Bears roam the fields around {area:131} and the depot."] = "Rochetuscos e Ursos Pretos Jovens vagam pelos campos em volta de {area:131} e da garagem.",
		["Each of Grif Wildheart's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him at the {area:131} smithy. Large Crag Boars, Snow Leopards and Ice Claw Bears all roam the fields just south and east of {area:131}."] = "Cada missão de Grif Selvacuore lhe dá um {item:15908}: use-o na fera que ele indicar e depois leve o bastão de volta a ele na ferraria de {area:131}. Rochetuscos Grandes, Leopardos da Neve e Ursos Garra de Gelo vagam pelos campos logo ao sul e a leste de {area:131}.",
		["Farsen camps on the ridge overlooking the {area:134} from the west. Talk to him for his farsight."] = "Farsen acampa na crista que dá vista para a {area:134}, a oeste. Fale com ele para usar a vidência dele.",
		["Feather Charms, from the Frostmane Novices"] = "Patuás de Penas, dos Noviços Jubafria",
		["Firewood"] = "Lenha",
		["Follow the road all the way east to the {area:806} at the {zone:1432} tunnel."] = "Siga a estrada até o extremo leste, até o {area:806} no túnel de {zone:1432}.",
		["Follow the road east past the depot to {area:138}."] = "Siga a estrada para leste passando a garagem até o {area:138}.",
		["Follow the road north-east from {area:131} to the depot below the {zone:1455} road."] = "Siga a estrada para nordeste a partir de {area:131} até a garagem abaixo da estrada de {zone:1455}.",
		["Follow the road through the tunnel and north-east to {area:131}. Kill the Crag Boars on the way: their ribs drop before you have {npc:1267}'s quest and count toward it. {npc:1252}, Eric and his campfire are outside the {area:2102}. {npc:6806}, {npc:1226} and {npc:1267} are inside. {npc:1872} works the forge."] = "Siga a estrada pelo túnel e para nordeste até {area:131}. Mate os Rochetuscos no caminho: as costelas caem antes de você ter a missão de {npc:1267} e contam para ela. {npc:1252}, Eric e a fogueira dele ficam do lado de fora da {area:2102}. {npc:6806}, {npc:1226} e {npc:1267} estão lá dentro. {npc:1872} trabalha na forja.",
		["Follow the road up to {zone:1455} and take the {object:32362}: {npc:5149}, {npc:6179} and {npc:6178} are in the {object:32386}. {npc:6175}, a beggar, wanders the city. He asks for ten {item:2589}: the troggs and trolls of {zone:1426} drop it, and the Auction House sells it."] = "Siga a estrada até {zone:1455} e pegue a {object:32362}: {npc:5149}, {npc:6179} e {npc:6178} estão no {object:32386}. {npc:6175}, um mendigo, anda pela cidade. Ele pede dez {item:2589}: os troggs e trolls de {zone:1426} deixam cair, e a Casa de Leilões vende.",
		["Follow the road up to {zone:1455} and train with your class trainer. The {area:2257} leaves from {object:171524}, in the east of the city. Ride it to {zone:1453}."] = "Siga a estrada até {zone:1455} e treine com seu instrutor de classe. O {area:2257} sai da {object:171524}, no leste da cidade. Vá nele até {zone:1453}.",
		["From the {quest:2997} she gives you"] = "Do {quest:2997} que ela lhe dá",
		["Frostmane Troll Whelps fill the slopes south and east of {npc:786}'s camp."] = "Jovens Trolls Jubafria enchem as encostas ao sul e a leste do acampamento de {npc:786}.",
		["Gnomes, bears and leopards"] = "Gnomos, ursos e leopardos",
		["Go through the tunnel into {zone:1432}. Just past it, a path marked by stones climbs the hills on the right of the road north to {npc:257808}'s camp."] = "Atravesse o túnel até {zone:1432}. Logo depois, uma trilha marcada por pedras sobe as colinas à direita da estrada rumo ao norte, até o acampamento de {npc:257808}.",
		["Hearth to {area:131}"] = "Regressar para {area:131}",
		["Iceclaw Bear Pendants, from the Frostmane Troll Whelps on the slopes above the camp"] = "Pingentes de Urso Garrálgido, dos Jovens Trolls Jubafria nas encostas acima do acampamento",
		["Inside {area:77}"] = "Dentro de {area:77}",
		["Leave {zone:1453} by the main gate, go south to {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "Saia de {zone:1453} pelo portão principal, vá para o sul até {area:87} e para leste pela estrada até a {area:62}. {npc:881} (nível 9) fica junto à casa da fazenda.",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "Saia de {zone:1453} pelo portão principal. A cachoeira do {quest:1861} fica a sudoeste dos portões, no caminho para oeste até {zone:1436}: encha o {item:7207} na base dela.",
		["Leopards and boars"] = "Leopardos e javalis",
		["Leper Gnomes around Brewnall and the {area:133} road carry the cogs and gears. Ice Claw Bears, Elder Crag Boars and Snow Leopards roam the hills around the lake."] = "Gnomos Leprosos em volta da Aldeia da Cevada e da estrada de {area:133} levam as rodas dentadas e engrenagens. Ursos Garra de Gelo, Rochetuscos Anciões e Leopardos da Neve vagam pelas colinas em volta do lago.",
		["Level 4 spells, before Gozwin's camp"] = "Feitiços de nível 4, antes do acampamento de Gozwin",
		["Minor Ice Elementals drift around the frozen lake by the refuge. The three rifles are in the snow around it."] = "Elementais de Gelo Menores flutuam em volta do lago congelado junto ao refúgio. Os três rifles estão na neve em volta dele.",
		["Ragged Young Wolves roam the snow just south of {area:77}."] = "Lobos Jovens Rotos vagam pela neve logo ao sul de {area:77}.",
		["Ride back out of {zone:1455} and east along the road to {area:212}. {npc:6177} lies dead by its shore: use the {item:6866} on him. The Dark Iron Spies sneaking around the lake carry the script."] = "Saia de {zone:1455} e cavalgue para leste pela estrada até {area:212}. {npc:6177} jaz morto na margem: use o {item:6866} nele. Os Espiões Ferro Negro que rondam o lago levam o manuscrito.",
		["Rockjaw Ambushers by {area:212}, north of the quarry, and Rockjaw Backbreakers further east drop the {quest:95214}."] = "Emboscadores Pedraqueixo junto ao {area:212}, ao norte da pedreira, e Quebradorsos Pedraqueixo mais a leste deixam cair a {quest:95214}.",
		["Rockjaw Bonesnappers prowl the quarry and {area:212}; Dark Iron Spies sneak around the lake shore. One spy drops the {item:274268}."] = "Quebraossos Pedraqueixo rondam a pedreira e {area:212}; Espiões Ferro Negro rondam às escondidas a margem do lago. Um espião deixa cair o {item:274268}.",
		["Rockjaw Skullthumpers fill the quarry; Rockjaw Ambushers by {area:212} drop the {item:268548}."] = "Batecrânios Pedraqueixo enchem a pedreira; Emboscadores Pedraqueixo junto ao {area:212} deixam cair o {item:268548}.",
		["Rockjaw Troggs and Burly Rockjaw Troggs dig all over the valley floor south of {area:77}."] = "Troggs Pedraqueixo e Troggs Pedraqueixo Parrudos cavam por todo o fundo do vale ao sul de {area:77}.",
		["Sit by Eric's campfire (type /sit) and wait for the buff, then {npc:1699} in the distillery teaches you cooking."] = "Sente-se junto à fogueira de Eric (digite /sentar) e espere o bônus; depois {npc:1699}, na destilaria, ensina culinária a você.",
		["Small Crag Boars graze around {npc:714}'s camp and along the west side of the valley."] = "Rochetuscos Pequenos pastam em volta do acampamento de {npc:714} e pelo lado oeste do vale.",
		["Snow Leopards and boars roam the snow between the ranch and the quarry. Blacksmiths: Copper Bars come from smelting {item:2770} or the trade vendors."] = "Leopardos da Neve e javalis vagam pela neve entre o rancho e a pedreira. Ferreiros: Barras de Cobre vêm da fundição de {item:2770} ou dos mercadores de profissão.",
		["Speak with {npc:1699}"] = "Fale com {npc:1699}",
		["Spies and Bonesnappers"] = "Espiões e Quebraossos",
		["Stonesplinter Seers (level 13) stand among the troggs in the south of {area:923}, south of {npc:257808}; Tunnel Rat Geomancers (level 12) work the {area:149} at the north end of the loch. The troggs come in packs and some throw from range: pull one at a time."] = "Videntes Lascapedra (nível 13) ficam entre os troggs no sul do {area:923}, ao sul de {npc:257808}; Geomantes Ratatúnel (nível 12) trabalham na {area:149}, no extremo norte do lago. Os troggs vêm em bandos e alguns atacam à distância: atraia um de cada vez.",
		["Subdue the voidwalker"] = "Subjugue o emissário do caos",
		["The Fire Spirit Stone"] = "A Pedra do Espírito de Fogo",
		["The Scalding Mornbrew lasts five minutes: go straight north to {npc:836} inside {area:77}."] = "O Rabo-de-galo Escaldante dura cinco minutos: vá direto para o norte até {npc:836} dentro de {area:77}.",
		["The boars"] = "Os javalis",
		["The cold"] = "O frio",
		["The firewood lies in the snow around the frozen lake by the refuge."] = "A lenha está na neve em volta do lago congelado junto ao refúgio.",
		["The quarry lies south-east of the ranch."] = "A pedreira fica a sudeste do rancho.",
		["The quarry troggs"] = "Os troggs da pedreira",
		["The tram arrives in the {object:28027}. {npc:5480} trains warriors in {object:2100}; {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug."] = "O metrô chega no {object:28027}. {npc:5480} treina guerreiros em {object:2100}; {npc:6089} e {npc:6090} ficam juntos perto da {object:2152} de lá. {npc:6090} luta com você pela caneca dele.",
		["The troggs"] = "Os troggs",
		["The troll cave"] = "A caverna dos trolls",
		["The tunnel"] = "O túnel",
		["The {area:2257}"] = "O {area:2257}",
		["The {object:176785} sits next to {npc:271546}, south of the {area:136}; {npc:1243} camps south-west of it, by the road to Coldridge."] = "{object:176785} fica ao lado de {npc:271546}, ao sul de {area:136}; {npc:1243} acampa a sudoeste dele, junto à estrada para o Vale Cristálgida.",
		["The {object:269} in the basement"] = "O {object:269} no porão",
		["The {object:270} in the distillery"] = "O {object:270} na destilaria",
		["Use the {item:6866} on {npc:6177}"] = "Use o {item:6866} em {npc:6177}",
		["You start in front of {area:77}, the stone hall at the north end of the valley. {npc:658} waits outside the door."] = "Você começa diante de {area:77}, o salão de pedra no extremo norte do vale. {npc:658} espera do lado de fora da porta.",
		["Young wolves"] = "Lobos jovens",
		["{area:131} and the depot"] = "{area:131} e a garagem",
		["{area:135} is the troll cave in the hills west of {area:137}. Kill Headhunters at its mouth and walk through to its far end."] = "{area:135} é a caverna dos trolls nas colinas a oeste de {area:137}. Mate os Caçadores de Cabeças na entrada e atravesse até o fundo.",
		["{area:137} sits on the lake north-west of {area:135}."] = "{area:137} fica no lago a noroeste de {area:135}.",
		["{item:13850}: the {object:176785}"] = "{item:13850}: {object:176785}",
		["{item:2667}: the meat locker"] = "{item:2667}: o armário de carne",
		["{item:2676} bushes grow on the hills around {area:137}."] = "Arbustos de {item:2676} crescem nas colinas em volta de {area:137}.",
		["{item:2686}, from {npc:1247} in the distillery"] = "{item:2686}, de {npc:1247} na destilaria",
		["{item:277976}, in the camp"] = "{item:277976}, no acampamento",
		["{item:286325} is by the frozen lake, among the ice elementals."] = "O {item:286325} fica junto ao lago congelado, entre os elementais de gelo.",
		["{item:2894}, from {npc:1247}"] = "{item:2894}, de {npc:1247}",
		["{item:3083}: Leper Gnomes"] = "{item:3083}: Gnomos Leprosos",
		["{item:3084}: Leper Gnomes"] = "{item:3084}: Gnomos Leprosos",
		["{item:5026} and the {item:6652}"] = "{item:5026} e a {item:6652}",
		["{item:5026}: Tunnel Rat Geomancers"] = "{item:5026}: Geomantes Ratatúnel",
		["{item:6635}, beside the Spirit Stone"] = "{item:6635}, ao lado da Pedra Espiritual",
		["{item:6636}, beside the Spirit Stone"] = "{item:6636}, ao lado da Pedra Espiritual",
		["{item:6652}: Stonesplinter Seers"] = "{item:6652}: Videntes Lascapedra",
		["{item:6847}: Dark Iron Spies"] = "{item:6847}: Espiões Ferro Negro",
		["{npc:10090} in {zone:1455} takes it"] = "{npc:10090} em {zone:1455} a recebe",
		["{npc:10090} is in the {object:32390}, {npc:258785} in the {object:32386}, {npc:6120} in the {object:32383}."] = "{npc:10090} está no {object:32390}, {npc:258785} no {object:32386}, {npc:6120} na {object:32383}.",
		["{npc:1126}: tame it with the {item:15908}"] = "{npc:1126}: dome-o com o {item:15908}",
		["{npc:1196}: tame it with the {item:15908}"] = "{npc:1196}: dome-o com o {item:15908}",
		["{npc:1201}: tame it with the {item:15908}"] = "{npc:1201}: dome-o com o {item:15908}",
		["{npc:1226}, next to {npc:6806}"] = "{npc:1226}, ao lado de {npc:6806}",
		["{npc:1226}: {npc:258785} in {zone:1455} takes it"] = "{npc:1226}: {npc:258785} em {zone:1455} a recebe",
		["{npc:1226}: {npc:376} in {zone:1453} takes it"] = "{npc:1226}: {npc:376} em {zone:1453} a recebe",
		["{npc:1231}, at the smithy"] = "{npc:1231}, na ferraria",
		["{npc:1254} and {npc:1256}"] = "{npc:1254} e {npc:1256}",
		["{npc:1266} camps in {area:801}, south of Brewnall. His meats are in the locker in {npc:1271}'s cave to the north-east of his camp: grab them and leave quickly."] = "{npc:1266} acampa no {area:801}, ao sul da Aldeia da Cevada. As carnes dele estão no armário da caverna do {npc:1271}, a nordeste do acampamento: pegue-as e saia rápido.",
		["{npc:1269}, by the depot"] = "{npc:1269}, perto da garagem",
		["{npc:12738}, next to him"] = "{npc:12738}, ao lado dele",
		["{npc:12738}: timed, five minutes to reach {npc:836} in {area:77}"] = "{npc:12738}: com tempo, cinco minutos para chegar a {npc:836} em {area:77}",
		["{npc:1373} guards the {item:2686} barrels in the distillery basement. Buy a {item:2686} from {npc:1247}, click the guarded barrel, then hand the ale to {npc:1373} from his quest window (there is no quest to accept); after that, the unguarded barrel takes the {spell:8553}."] = "{npc:1373} guarda os barris de {item:2686} no porão da destilaria. Compre uma {item:2686} de {npc:1247}, clique no barril vigiado e depois entregue a cerveja a {npc:1373} pela janela de missão dele (não há missão para aceitar); depois disso, o barril sem vigia recebe o {spell:8553}.",
		["{npc:1373}, beside the barrel"] = "{npc:1373}, ao lado do barril",
		["{npc:1377}, at the depot"] = "{npc:1377}, na garagem",
		["{npc:1698}: blacksmiths only"] = "{npc:1698}: só ferreiros",
		["{npc:1960} waits at the {area:808}; the dwarven corpse lies up the pass to the west of him."] = "{npc:1960} espera no {area:808}; o cadáver do anão está subindo o desfiladeiro a oeste dele.",
		["{npc:1965} guards the tunnel out of the valley, east of {area:77}; {npc:6782} stands beside him at its mouth."] = "{npc:1965} guarda o túnel que sai do vale, a leste de {area:77}; {npc:6782} fica ao lado dele na entrada.",
		["{npc:1977}, in the quarry"] = "{npc:1977}, na pedreira",
		["{npc:257446}, inside {area:77}"] = "{npc:257446}, dentro de {area:77}",
		["{npc:257446}: {npc:5873} and your {item:5175}"] = "{npc:257446}: {npc:5873} e seu {item:5175}",
		["{npc:257597} waits in a cave above the farm north-west of the {area:806}; the path up starts behind the farm."] = "{npc:257597} espera numa caverna acima da fazenda a noroeste do {area:806}; a trilha começa atrás da fazenda.",
		["{npc:257597}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:257597}: {npc:2523}, seu {item:5176} e o {item:263412}",
		["{npc:257808} gives you the {item:6636}. Climb to the peak above his camp, drink the Sapta beside the Spirit Stone and defeat the {npc:5893}, then place its {item:6655} in the {object:61934}, atop the Shrine of Eternal Flame."] = "{npc:257808} lhe dá a {item:6636}. Suba ao pico acima do acampamento dele, beba a Sapta ao lado da Pedra Espiritual e derrote a {npc:5893}, depois coloque a {item:6655} dela no {object:61934}, no alto do Santuário da Chama Eterna.",
		["{npc:258098}, the shaman trainer, north of the {object:32372}"] = "{npc:258098}, o instrutor de xamã, ao norte da {object:32372}",
		["{npc:258113}: {npc:257597} by the South Gate takes it"] = "{npc:258113}: {npc:257597}, perto do Portão Sul, a recebe",
		["{npc:2756} stands by {npc:8416} at the door of {area:77}. Gozwin's camp is in the hills just north-west; the {npc:269075} prowls around it."] = "{npc:2756} fica com {npc:8416} junto à porta de {area:77}. O acampamento de Gozwin fica nas colinas logo a noroeste; o {npc:269075} ronda por ali.",
		["{npc:376} is in the Cathedral of Light."] = "{npc:376} está na Catedral da Luz.",
		["{npc:460}, inside {area:77}"] = "{npc:460}, dentro de {area:77}",
		["{npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "{npc:5497} fica na torre do {object:2101}; ela lhe dá um frasco para a cachoeira do {quest:1861}.",
		["{npc:6120}: {npc:6122} in {zone:1453} takes it"] = "{npc:6120}: {npc:6122} em {zone:1453} a recebe",
		["{npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "{npc:6122} espera no porão do {object:2164}, no {object:2101}.",
		["{npc:6179}: Redemption"] = "{npc:6179}: Redenção",
		["{npc:658}: a rune for {npc:895}"] = "{npc:658}: uma runa para {npc:895}",
		["{npc:658}: read the {quest:98581}"] = "{npc:658}: leia a {quest:98581}",
		["{npc:6806}, in the distillery"] = "{npc:6806}, na destilaria",
		["{npc:713}, next to {npc:658}"] = "{npc:713}, ao lado de {npc:658}",
		["{npc:714}'s camp is at the west end of the valley. {item:10438} lies in the snow south of it, his Chest by the troll cave and his Bucket of Bolts east of the cave: grab them as you pass."] = "O acampamento de {npc:714} fica no extremo oeste do vale. A {item:10438} está na neve ao sul dele, o Baú de Felix perto da caverna dos trolls e o Balde de Parafusos a leste da caverna: pegue-os ao passar.",
		["{npc:786} and {npc:12738} camp at the south-west edge of the valley, below the troll cave."] = "{npc:786} e {npc:12738} acampam na borda sudoeste do vale, abaixo da caverna dos trolls.",
		["{npc:808} is inside the troll cave east of {npc:786}'s camp, not on the hill above it: go in at the mouth and follow the tunnel to the back."] = "{npc:808} está dentro da caverna dos trolls a leste do acampamento de {npc:786}, não na colina acima: entre pela boca e siga o túnel até o fundo.",
		["{npc:836}, inside {area:77}"] = "{npc:836}, dentro de {area:77}",
		["{npc:837}, the priest trainer"] = "{npc:837}, o instrutor de sacerdote",
		["{npc:8416}, by the door of {area:77}"] = "{npc:8416}, junto à porta de {area:77}",
		["{npc:895}, the hunter trainer"] = "{npc:895}, o instrutor de caçador",
		["{npc:912}, the warrior trainer"] = "{npc:912}, o instrutor de guerreiro",
		["{npc:916}, the rogue trainer"] = "{npc:916}, o instrutor de ladino",
		["{npc:926}, the paladin trainer"] = "{npc:926}, o instrutor de paladino",
		["{npc:944}, the mage trainer, inside {area:77}"] = "{npc:944}, o instrutor de mago, dentro de {area:77}",
		["{object:660964}, by the mailbox in {object:171524}"] = "{object:660964}, perto da caixa de correio na {object:171524}",
		["{quest:313} is the wendigo cave south-west of {area:131}. Flintfire's shipments lie on the cave floor."] = "{quest:313} é a caverna de wendigos a sudoeste de {area:131}. Os carregamentos de Pederfogo estão no chão da caverna.",
		["{zone:1455} class quests"] = "Missões de classe em {zone:1455}",
} end)()
t.guides["forever/alliance/human/01-elwynn-forest"] = (function() return {
		["\"Auntie\" Bernice Stonefield"] = "\"Titia\" Berenice Campedra",
		["Back south to the {area:120}, by the road to {zone:1436}. {npc:963} stands outside the barracks, {npc:955} beside him."] = "Volte para o sul até {area:120}, junto à estrada para {zone:1436}. {npc:963} fica do lado de fora do quartel; {npc:955}, ao lado dele.",
		["Back to the Cathedral of Light."] = "De volta à Catedral da Luz.",
		["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls."] = "De volta a {npc:6122}. Use o {item:6928} no círculo de evocação no porão de {object:2164} e derrote o emissário do caos que ele invocar.",
		["Bait ingredients"] = "Ingredientes da isca",
		["Billy plays in the {area:64}, east of the mine."] = "Guinho brinca em {area:64}, a leste da mina.",
		["Boar meat"] = "Carne de javali",
		["Chunks of Boar Meat"] = "Nacos de Carne de Javali",
		["Crystal Kelp Fronds"] = "Folhas de Cristalga",
		["Defias Rogue Wizards camp on the shores of {area:86}; they drop the Red Linen Bandanas too. {object:56} lies in the murloc village on the north-east shore."] = "Teurgos Proscritos Défias acampam nas margens de {area:86}; eles também soltam as Bandanas de Linho Vermelhas. {object:56} está na aldeia murloc da margem nordeste.",
		["Defias Thugs camp in the clearing east of the Abbey and along the valley's east side."] = "Capangas Défias acampam na clareira a leste da Abadia e ao longo do lado leste do vale.",
		["Follow the hills south to the tower, on the road west."] = "Siga pelas colinas para o sul até a torre, na estrada para o oeste.",
		["Follow the hills south to the tower."] = "Siga pelas colinas para o sul até a torre.",
		["Follow the path north to the mine. Kobold Workers swarm outside it; every kobold in the valley can drop the {object:83763}."] = "Siga a trilha para o norte até a mina. Trabalhadores Kobold enxameiam do lado de fora; qualquer kobold do vale pode soltar {object:83763}.",
		["Follow the road east past the {area:91} to the bridge."] = "Siga a estrada para o leste, passando por {area:91}, até a ponte.",
		["Follow the road north from {area:87} into {zone:1453}. {npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "Siga a estrada para o norte, de {area:87} até {zone:1453}. {npc:5497} fica no Sacrário dos Teurgos, a torre de {object:2101}; ela lhe dá um frasco para a cachoeira de {quest:1861}.",
		["Follow the road north from {area:87} into {zone:1453}. {npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "Siga a estrada para o norte, de {area:87} até {zone:1453}. {npc:6122} espera no porão de {object:2164}, em {object:2101}.",
		["Follow the road north from {area:87} into {zone:1453}. {npc:6171} and {npc:6173} are in the Cathedral of Light; {npc:6174} stands in {object:2100} and asks for ten {item:2589} (humanoids drop it; the Auction House sells it)."] = "Siga a estrada para o norte, de {area:87} até {zone:1453}. {npc:6171} e {npc:6173} estão na Catedral da Luz; {npc:6174} fica em {object:2100} e pede dez {item:2589} (humanoides soltam; a Casa de Leilões vende).",
		["Follow the road south out of the valley to {area:87}. {npc:295} is in the Lion's Pride Inn; {npc:240} stands outside the smithy across the road, {npc:253} at the inn's front and {npc:241} by the road south of it."] = "Siga a estrada para o sul, saindo do vale, até {area:87}. {npc:295} está na Estalagem do Leão Orgulhoso; {npc:240} fica do lado de fora da ferraria, do outro lado da estrada; {npc:253}, na frente da estalagem; e {npc:241}, junto à estrada ao sul dela.",
		["Follow the road south out of {area:87} to the {area:64}. {npc:251} waits by the house."] = "Siga a estrada para o sul, saindo de {area:87}, até {area:64}. {npc:251} espera junto à casa.",
		["Follow the road west back to {area:87}."] = "Siga a estrada para o oeste de volta a {area:87}.",
		["Follow the road west back to {area:87}; {npc:6306} and Jason stand on the lake shore before town."] = "Siga a estrada para o oeste de volta a {area:87}; {npc:6306} e Jasão ficam na margem do lago antes da cidade.",
		["Follow the road west past Westbrook into {zone:1436}, then south along it to {area:108}. Thor, the gryphon master, stands on the hill."] = "Siga a estrada para o oeste, passando pela Ribeira d'Oeste, até {zone:1436}; depois, para o sul por ela até {area:108}. Thor, o mestre de grifos, fica no morro.",
		["From the {quest:2998} he gives you"] = "Do {quest:2998} que ele lhe dá",
		["Fun with Elementals: {npc:248464}"] = "Diversão com Elementais: {npc:248464}",
		["He stands by the river west of the farm."] = "Ele fica junto ao rio, a oeste da fazenda.",
		["Head north-west across the fields to the {quest:91736}, north of the {area:120}. Hand it four Shiny Red Apples for a {item:247824}."] = "Siga para o noroeste pelos campos até {quest:91736}, ao norte de {area:120}. Coloque nele quatro Maçãs Vermelhas Brilhantes para obter um {item:247824}.",
		["Inside {area:34}"] = "Dentro de {area:34}",
		["It lies by the river north-west of the logging camp."] = "Fica junto ao rio, a noroeste do acampamento madeireiro.",
		["Kobold Laborers work the tunnels inside the mine. {npc:248362} waits down the second turn on the right."] = "Operários Kobold trabalham nos túneis dentro da mina. {npc:248362} espera depois da segunda curva à direita.",
		["Large Candles"] = "Velas Grandes",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "Saia de {zone:1453} pelo portão principal. A cachoeira de {quest:1861} fica a sudoeste dos portões, no caminho para o oeste rumo a {zone:1436}: encha {item:7207} na base dela.",
		["Lost Books: Kobold Miners and Tunnelers"] = "Livros Perdidos: Mineradores e Tuneleiros Kobold",
		["Murloc Foragers and Lurkers line the river south of the bridge. {npc:473}, a Defias, walks the {area:62} west of it. Finish the Prowlers and Young Forest Bears on the way. {npc:248278} roams the murloc shore too: right-click the head it drops. {npc:248278} is elite: grouping up is advised."] = "Murlocs Colhedores e Murlocs Tocaieiros ocupam o rio ao sul da ponte. {npc:473}, um Défias, anda por {area:62}, a oeste dele. Termine os Predadores e Jovens Ursos da Floresta no caminho. {npc:248278} também ronda a margem dos murlocs: clique com o botão direito na cabeça que ele deixa cair. {npc:248278} é elite: é bom ir em grupo.",
		["Murlocs and Murloc Streamrunners hold the east shore; the Junk Piles lie in their camp."] = "Murlocs e Murlocs Corredores ocupam a margem leste; as Pilhas de Sucata ficam no acampamento deles.",
		["Murlocs and the Collector"] = "Murlocs e o Coletor",
		["North-east of the logging camp. Defias Rogue Wizards camp on the shores of the lake."] = "A nordeste do acampamento madeireiro. Teurgos Proscritos Défias acampam nas margens do lago.",
		["Painted Gnoll Armbands"] = "Braçadeiras Pintadas dos Gnolls",
		["Red Burlap Bandanas"] = "Bandanas de Lona Vermelhas",
		["Red Linen Bandanas"] = "Bandanas de Linho Vermelhas",
		["Ride back out through {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "Saia de novo passando por {area:87} e siga a estrada para o leste até {area:62}. {npc:881} (nível 9) fica junto à casa da fazenda.",
		["Ride back out through {area:87} and east to {area:86}. {npc:6172} lies south of the lake: use the {item:6866} on him. The Defias Rogue Wizards around him carry the {item:6846}."] = "Saia de novo passando por {area:87} e siga para o leste até {area:86}. {npc:6172} está caído ao sul do lago: use o {item:6866} nele. Os Teurgos Proscritos Défias ao redor dele carregam o {item:6846}.",
		["Riverpaw Runts and Outrunners hold the hills south of the garrison, along the {zone:1436} border. {npc:100}, a level 12 gnoll, walks among them and carries the {item:1307}: right-click it."] = "Pata Molhada Miúdos e Vanguardeiros Pata Molhada ocupam as colinas ao sul da guarnição, ao longo da divisa com {zone:1436}. {npc:100}, um gnoll de nível 12, anda entre eles e carrega a {item:1307}: clique nela com o botão direito.",
		["Riverpaw gnolls camp in the hills west of {area:86}; the {quest:91725} lie in their camps."] = "Gnolls Pata Molhada acampam nas colinas a oeste de {area:86}; {quest:91725} estão nos acampamentos deles.",
		["She sits inside the farmhouse."] = "Ela fica sentada dentro da casa da fazenda.",
		["She stands by her cart at the vineyard east of the Abbey."] = "Ela fica junto à carroça, no vinhedo a leste da Abadia.",
		["She stands outside the mine entrance. {npc:248362}, inside, is elite: grouping up is advised."] = "Ela fica do lado de fora da entrada da mina. {npc:248362}, lá dentro, é elite: recomenda-se formar um grupo.",
		["Shiny Red Apples, from {npc:894}, for the {quest:91736}"] = "Maçãs Vermelhas Brilhantes, de {npc:894}, para {quest:91736}",
		["Sit (/sit) by his campfire until you have {spell:1229451}"] = "Sente-se (/sit) junto à fogueira dele até ganhar {spell:1229451}",
		["South down the road to the {area:64}."] = "Para o sul pela estrada até {area:64}.",
		["Speak with {npc:1430}"] = "Fale com {npc:1430}",
		["Stonetusk Boars graze between the vineyards and the farm."] = "Javalis Pedratusco pastam entre os vinhedos e a fazenda.",
		["Subdue the voidwalker"] = "Subjugue o emissário do caos",
		["The Defias camp"] = "O acampamento Défias",
		["The Fishing Traps sit along the west shore of the lake."] = "As armadilhas ({object:694772}) ficam ao longo da margem oeste do lago.",
		["The Stonefield farm is west of the mine. Ma and \"Auntie\" Bernice stand by the house."] = "A fazenda dos Campedra fica a oeste da mina. Mama e \"Titia\" Berenice ficam junto à casa.",
		["The bridge"] = "A ponte",
		["The camp is north-east of the bridge. Bundles of Wood lie around the camp and in the woods north of it."] = "O acampamento fica a nordeste da ponte. Feixes de Lenha estão espalhados pelo acampamento e pelo bosque ao norte dele.",
		["The crates of grapes lie in the vineyards behind the Defias. {npc:103} waits by the cabin at the east end of the valley."] = "Os caixotes de uvas estão nos vinhedos, atrás dos Défias. {npc:103} espera junto à cabana no extremo leste do vale.",
		["The gnoll camps"] = "Os acampamentos gnolls",
		["The kobold camp"] = "O acampamento kobold",
		["The lake shore"] = "A margem do lago",
		["The mine is south-west of the gnoll camps. {item:247816} lie near the entrance; Kobold Geomancers hold the tunnels."] = "A mina fica a sudoeste dos acampamentos gnolls. {item:247816} estão perto da entrada; Geomantes Kobold ocupam os túneis.",
		["The mine is west of the vineyards. Kobold Miners and Tunnelers fill both levels; {npc:248464}, a named kobold, holds the picture book in the lower tunnels. {npc:248464} is elite: grouping up is advised."] = "A mina fica a oeste dos vinhedos. Mineradores e Tuneleiros Kobold enchem os dois níveis; {npc:248464}, um kobold nomeado, guarda o livro ilustrado nos túneis inferiores. {npc:248464} é elite: recomenda-se formar um grupo.",
		["The murloc camp"] = "O acampamento murloc",
		["The murlocs on the east shore drop the kelp. Skinners: Gray Forest Wolves roam the woods between the lake and the {area:91}; Prowlers further east give pelts too."] = "Os murlocs da margem leste soltam a alga. Esfoladores: Lobos Cinza da Floresta vagam pelo bosque entre o lago e {area:91}; Predadores mais a leste também dão peles.",
		["The vineyards and {npc:103}"] = "Os vinhedos e {npc:103}",
		["The {area:88}"] = "{area:88}",
		["The {area:91}"] = "{area:91}",
		["The {item:247813}, Axe and Toolbox lie in the river south of the bridge. {npc:330}, a big boar, roots in the {area:62} west of the river with her {npc:390}: pull the piglets away first. Kill Prowlers and Young Forest Bears on the way."] = "{item:247813}, o Machado Encharcado e a Caixa de Ferramentas Encharcada estão no rio ao sul da ponte. {npc:330}, uma javalina grande, fuça em {area:62}, a oeste do rio, com seu {npc:390}: afaste os leitões primeiro. Mate Predadores e Jovens Ursos da Floresta no caminho.",
		["The {quest:91736}"] = "{quest:91736}",
		["Torn Murloc Fins"] = "Barbatanas Rasgadas de Murloc",
		["Use the {item:6866} on {npc:6172}"] = "Use o {item:6866} em {npc:6172}",
		["Walk into the mine"] = "Entre na mina",
		["Walk through the mine"] = "Atravesse a mina",
		["Wolves"] = "Lobos",
		["You start in front of the Abbey. {npc:823} stands at the foot of the steps, {npc:197} inside the hall, {npc:951} and {npc:247229} in the library to the right, {npc:196} outside the north-west corner."] = "Você começa em frente à Abadia. {npc:823} fica ao pé da escadaria; {npc:197}, dentro do salão; {npc:951} e {npc:247229}, na biblioteca à direita; {npc:196}, do lado de fora, no canto noroeste.",
		["Young Wolves and Timber Wolves roam the fields right around the Abbey."] = "Lobos Jovens e Lobos Silvestres vagam pelos campos bem ao redor da Abadia.",
		["his kobold tracker shows the kobolds to click on the road to {area:87}"] = "o rastreador de kobolds dele mostra os kobolds para clicar na estrada para {area:87}",
		["{area:18} and the wolves"] = "{area:18} e os lobos",
		["{item:247824}, from the still"] = "{item:247824}, do alambique",
		["{item:286215}: Stonetusk Boars"] = "{item:286215}: Javalis Pedratusco",
		["{item:6785}: the {object:83763} in the Defias camp"] = "{item:6785}: {object:83763} no acampamento Défias",
		["{item:6846}: Defias Rogue Wizards"] = "{item:6846}: Teurgos Proscritos Défias",
		["{npc:1430} cooks in the inn's kitchen."] = "{npc:1430} cozinha na cozinha da estalagem.",
		["{npc:1922}: tame it with the {item:15908}"] = "{npc:1922}: dome-o com o {item:15908}",
		["{npc:198}, the mage trainer, inside the Abbey"] = "{npc:198}, o instrutor de magos, dentro da Abadia",
		["{npc:247229}, in the library"] = "{npc:247229}, na biblioteca",
		["{npc:248242} and {npc:248248} stand at the foot of the tower."] = "{npc:248242} e {npc:248248} ficam ao pé da torre.",
		["{npc:248277} keeps watch at {area:798}, east of the murloc shore. Then head north-west back to the bridge."] = "{npc:248277} fica de guarda em {area:798}, a leste da margem dos murlocs. Depois volte para o noroeste até a ponte.",
		["{npc:248415} stands behind the Abbey, by the stables."] = "{npc:248415} fica atrás da Abadia, perto dos estábulos.",
		["{npc:248415}, by the Abbey"] = "{npc:248415}, perto da Abadia",
		["{npc:251507} stands with the {area:87} trainers. Each of her quests hands you a {item:15908}: use it on the beast she names, then bring the rod back to her. Rockhide Boars and Young Forest Bears roam the hills south of the {area:64}, Gray Forest Wolves the woods east of {area:18}."] = "{npc:251507} fica com os instrutores de {area:87}. Cada missão dela lhe dá um {item:15908}: use-o na fera que ela indicar e traga o bastão de volta. Javalis Couropedra e Jovens Ursos da Floresta vagam pelas colinas ao sul de {area:64}; Lobos Cinza da Floresta, pelo bosque a leste de {area:18}.",
		["{npc:258930}, beside her: {spell:5149}"] = "{npc:258930}, ao lado dela: {spell:5149}",
		["{npc:261} guards the bridge on the road east; {npc:248265} stands just across it."] = "{npc:261} guarda a ponte na estrada para o leste; {npc:248265} fica logo do outro lado.",
		["{npc:263399} camps north-east of the inn; {npc:6306}, {npc:383} and {npc:1651} stand on the shore of {area:18} east of town."] = "{npc:263399} acampa a nordeste da estalagem; {npc:6306}, {npc:383} e {npc:1651} ficam na margem de {area:18}, a leste da cidade.",
		["{npc:279} in {zone:1453} takes it (02-westfall)"] = "{npc:279} em {zone:1453} recebe (02-westfall)",
		["{npc:328}: {npc:5497} in {zone:1453} takes it"] = "{npc:328}: {npc:5497} em {zone:1453} recebe",
		["{npc:375}, the priest trainer"] = "{npc:375}, a instrutora de sacerdotes",
		["{npc:377}: {npc:376} in {zone:1453} takes both"] = "{npc:377}: {npc:376} em {zone:1453} recebe as duas",
		["{npc:459}, outside the Abbey"] = "{npc:459}, do lado de fora da Abadia",
		["{npc:524}: tame it with the {item:15908}"] = "{npc:524}: dome-o com o {item:15908}",
		["{npc:6121}: {npc:6122} in {zone:1453} takes it"] = "{npc:6121}: {npc:6122} em {zone:1453} recebe",
		["{npc:6171}: Redemption"] = "{npc:6171}: Redenção",
		["{npc:6306}: skinners only, the pelts are skinned"] = "{npc:6306}: só para esfoladores; as peles são esfoladas",
		["{npc:6774}, by the stables south of the Abbey"] = "{npc:6774}, perto dos estábulos ao sul da Abadia",
		["{npc:6} dig in the vineyards north-east of the Abbey. Now and then one drops a {quest:91741}: right-click it."] = "{npc:6} cavam nos vinhedos a nordeste da Abadia. De vez em quando um solta um {quest:91741}: clique nele com o botão direito.",
		["{npc:822}: tame it with the {item:15908}"] = "{npc:822}: dome-o com o {item:15908}",
		["{npc:823}, back at the Abbey steps"] = "{npc:823}, de volta à escadaria da Abadia",
		["{npc:911}, the warrior trainer"] = "{npc:911}, o instrutor de guerreiros",
		["{npc:915}, the rogue trainer"] = "{npc:915}, o instrutor de ladinos",
		["{npc:925}, the paladin trainer"] = "{npc:925}, o instrutor de paladinos",
		["{npc:927}: {npc:6171} in {zone:1453} takes it"] = "{npc:927}: {npc:6171} em {zone:1453} recebe",
		["{npc:952}, upstairs"] = "{npc:952}, no andar de cima",
		["{npc:955}: he wants your {item:247824}"] = "{npc:955}: ele quer seu {item:247824}",
		["{object:694855} grows in the fields around the vineyards and the Stonefield farm; Stonetusk Boars around them give the blood."] = "{object:694855} cresce nos campos ao redor dos vinhedos e da fazenda dos Campedra; os Javalis Pedratusco por ali dão o sangue.",
		["{quest:76}'s entrance"] = "Entrada de {quest:76}",
		["{quest:87} is inside the {area:57}, not on the hill above it: go in at the mouth and keep left to the back of the mine floor; don't take the stairs up. Defias Bandits around the vineyards drop a {item:1972} now and then: right-click it."] = "{quest:87} está dentro de {area:57}, não no morro acima dela: entre pela boca e mantenha-se à esquerda até o fundo do piso da mina; não suba as escadas. Bandidos Défias ao redor dos vinhedos soltam uma {item:1972} de vez em quando: clique nela com o botão direito.",
		["{quest:91733} and {npc:330}"] = "{quest:91733} e {npc:330}",
} end)()
t.guides["forever/alliance/nightelf/01-teldrassil"] = (function() return {
		["/sit by {npc:265811}'s campfire until you get {spell:1229451}"] = "Use /sentar junto à fogueira de {npc:265811} até receber {spell:1229451}",
		["Back at {area:256}"] = "De volta a {area:256}",
		["Back to the moonwell."] = "De volta ao poço lunar.",
		["Back to the top of {area:256}. The {object:654846} lies beside him."] = "De volta ao topo de {area:256}. {object:654846} está ao lado dele.",
		["Bloodfeather harpies"] = "Harpias Plumassangue",
		["Boat to {zone:1453}"] = "Barco para {zone:1453}",
		["Each of Dazalar's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him in {area:186}. Webwood Lurkers creep around the village, Nightsaber Stalkers and Strigid Screechers roam the woods south of it."] = "Cada missão de Dazalar lhe dá um {item:15908}: use-o na fera indicada e depois leve o bastão de volta para ele em {area:186}. Tocaieiras Lenhateia rastejam ao redor da aldeia; Espreitadores Sabre-da-noite e Guinchadoras Estrígidas vagueiam pelo bosque ao sul dela.",
		["East to {area:260}"] = "Ao leste, para {area:260}",
		["Escort {npc:275744} out of the barrow; {npc:2081} in {area:186} takes the report."] = "Escolte {npc:275744} para fora do túmulo; {npc:2081}, em {area:186}, recebe o relatório.",
		["Fandral in {zone:1457} takes it"] = "Fandral Guenelmo, em {zone:1457}, a recebe",
		["Fel Cones lie under the trees all around {area:186} and {npc:2150}. Nightsabers and Webwood Lurkers keep roaming the road east. {object:126158} is in the house on the hill at the east end of the village."] = "As Pinhas Vis ficam sob as árvores ao redor de {area:186} e de {npc:2150}. Sabres-da-noite e Tocaieiras Lenhateia continuam vagando pela estrada para o leste. {object:126158} está na casa da colina, no extremo leste da aldeia.",
		["Fly to {area:702} once more and take the portal up to {npc:4217}, then fly back to {area:442} for the boat."] = "Voe para {area:702} mais uma vez e pegue o portal para subir até {npc:4217}; depois volte voando para {area:442} para pegar o barco.",
		["Follow the road south-west out of {area:188}. {npc:2150} sits beside it just east of {area:186}."] = "Siga a estrada para o sudoeste, saindo de {area:188}. {npc:2150} fica junto a ela, logo a leste de {area:186}.",
		["Follow the road west into {zone:1457}. {npc:4241} stands on the {area:1659} just inside the city. {npc:3516} is in the {area:1658} at the north end of the city, {quest:922} just south of it; {npc:4092} and {npc:7999} are in the Temple of the Moon at the south end. {npc:7316} is in the west of the city, on the way to the pink portal down to Rut'theran."] = "Siga a estrada para o oeste até {zone:1457}. {npc:4241} fica em {area:1659}, logo na entrada da cidade. {npc:3516} está em {area:1658}, no extremo norte da cidade, e {quest:922} logo ao sul; {npc:4092} e {npc:7999} estão no Templo da Lua, no extremo sul. {npc:7316} está no oeste da cidade, a caminho do portal rosa que desce até a Vila de Rut'theran.",
		["From the harbour walk into {object:2100}. {npc:5480} trains warriors there; {npc:6089} and {npc:6090} stand together by the {object:2152}. {npc:6090} fights you for his mug."] = "Do porto, entre em {object:2100}. {npc:5480} treina guerreiros ali; {npc:6089} e {npc:6090} ficam juntos perto de {object:2152}. {npc:6090} luta com você pela caneca dele.",
		["From {area:17203}, ride through the city gates into {zone:1429} and follow the road west to {zone:1436}."] = "De {area:17203}, atravesse os portões da cidade até {zone:1429} e siga a estrada para o oeste até {zone:1436}.",
		["Gnarlpine Ambushers hide along the road west of {area:258}."] = "Emboscadores Masca-pinho se escondem ao longo da estrada a oeste de {area:258}.",
		["Gnarlpine Mystics and Ferocitas camp north-east of {area:260}. Ferocitas drops the {item:8049}: open it for the jewel."] = "Místicos Masca-pinho e Ferócitas, o Comedor de Sonhos, acampam a nordeste de {area:260}. Ferócitas deixa cair o {item:8049}: abra-o para obter a joia.",
		["Gnarlpine Shamans"] = "Xamãs Masca-pinho",
		["Go back down to {area:702} and fly to {area:442}. The {object:177525} stands in the hills just east of the village: use the {item:15208} there, defeat Lunaclaw and speak to the {npc:12144}."] = "Desça de volta até {area:702} e voe para {area:442}. {object:177525} fica nas colinas logo a leste da vila: use o {item:15208} ali, derrote Lunagarra e fale com {npc:12144}.",
		["Hearth to {area:186}"] = "Regresse para {area:186}",
		["Learn the {area:442} flight path on the hill south of the inn, then cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5929} sits in the woods to the north-west. Learn the {area:493} flight path in {area:2361} and fly to {area:702} (by way of {area:442})."] = "Aprenda a rota de voo de {area:442} na colina ao sul da estalagem e depois lance {spell:18960}. {npc:11802} está em {area:2361}; {quest:5929} fica no bosque a noroeste. Aprenda a rota de voo de {area:493} em {area:2361} e voe para {area:702} (passando por {area:442}).",
		["Leave {area:188} by the path south-east of {area:256}: {npc:6780} stands beside it, where it goes down towards the road to {area:186}."] = "Saia de {area:188} pela trilha a sudeste de {area:256}: {npc:6780} fica ao lado dela, onde ela desce em direção à estrada para {area:186}.",
		["Mangy Nightsabers and Thistle Boars roam north of {area:256}, on the way to the cave. {npc:8584} waits in the trees west of the cave mouth; {npc:1994} sits deep inside."] = "Sabres-da-noite Sarnentos e Javalis-espinho vagueiam ao norte de {area:256}, a caminho da caverna. {npc:8584} espera entre as árvores a oeste da entrada da caverna; {npc:1994} fica bem no fundo.",
		["Nightsabers"] = "Sabres-da-noite",
		["Nightsabers, Strigid Owls and Webwood Lurkers roam all around {area:186} and along the road east. The moonwell is at the west edge of {area:260}."] = "Sabres-da-noite, Corujas Estrígidas e Tocaieiras Lenhateia rondam por todo {area:186} e ao longo da estrada para o leste. O poço lunar fica na borda oeste de {area:260}.",
		["North to {area:257}"] = "Ao norte, para {area:257}",
		["North-east from Ursal's den, back to {area:186}."] = "Para o nordeste a partir do covil de Ursal, de volta a {area:186}.",
		["Sentinel Arynia again"] = "Sentinela Arynia de novo",
		["South of Zenn. {npc:2080} tends his saplings on the shore; Lasher Sproutlings and Timberlings wander around him, and the {quest:919} grow among them."] = "Ao sul de Zenn Cascovil. {npc:2080} cuida das mudas dele na margem; Brotos de Açoitadeira e Muscoides vagueiam ao redor dele, e {quest:919} crescem entre eles.",
		["South of the pools. The {object:6751} grows by the Hold."] = "Ao sul dos lagos. {object:6751} cresce junto ao Acampamento Masca-pinho.",
		["South-east of Dolanaar, to {npc:2080}. Lasher Sproutlings wander around him on the shore."] = "A sudeste de Dolanaar, até {npc:2080}. Brotos de Açoitadeira vagueiam ao redor dele na margem.",
		["South-west of the barrow. The moonwell sits by the pools."] = "A sudoeste do túmulo. O poço lunar fica junto aos lagos.",
		["Speak with the {quest:5929}"] = "Fale com {quest:5929}",
		["Speak with {npc:6286}, south of the inn"] = "Fale com {npc:6286}, ao sul da estalagem",
		["Take the portal down to {area:702}. {npc:10118} stands on the dock, {npc:3838} by the hippogryphs."] = "Pegue o portal para descer até {area:702}. {npc:10118} fica no cais, {npc:3838} junto aos hipogrifos.",
		["Take the portal up from {area:702} to {npc:4217} in the {area:1658}."] = "Pegue o portal para subir de {area:702} até {npc:4217} em {area:1658}.",
		["Take the road north-west from {area:186} again; she still lies beside it, on the way to {zone:1457}."] = "Pegue de novo a estrada para o noroeste a partir de {area:186}; ela continua à beira da estrada, a caminho de {zone:1457}.",
		["Take the road north-west from {area:186} towards the {area:264}; she lies hurt beside it."] = "Pegue a estrada para o noroeste a partir de {area:186}, em direção a {area:264}; ela está ferida à beira da estrada.",
		["The Bloodfeather harpies nest on the slopes west and north of the glade."] = "As Harpias Plumassangue fazem ninho nas encostas a oeste e ao norte da clareira.",
		["The barrow is south of the road. {npc:275744} is held inside, {npc:7317} sleeps in its depths, and the four relic chests sit in the lower rooms."] = "O túmulo fica ao sul da estrada. {npc:275744} está presa lá dentro, {npc:7317} dorme nas profundezas, e os quatro baús de relíquias ficam nas salas inferiores.",
		["The moonwell and {npc:8584}"] = "O poço lunar e {npc:8584}",
		["The moonwell is in the middle of the glade. The {object:6752} grows at its north end."] = "O poço lunar fica no meio da clareira. {object:6752} cresce no extremo norte dela.",
		["The moonwell sits north of {area:256}; {npc:8584} is a little further north-west. {quest:3522} lasts five minutes: fill the phial and go straight on to him."] = "O poço lunar fica ao norte de {area:256}; {npc:8584} está um pouco mais a noroeste. {quest:3522} dura cinco minutos: encha o frasco e vá direto até ele.",
		["The named harpies"] = "As harpias nomeadas",
		["The road to {zone:1457}"] = "A estrada para {zone:1457}",
		["The {area:478}"] = "{area:478}",
		["The {object:177525}"] = "{object:177525}",
		["The {object:4406} lie at the back of {area:257}: take the central path, then left where it splits, up to the high ledge. Hyacinth Mushrooms drop from Grells, Moonpetal Lilies grow by the ponds north of {area:256}."] = "{object:4406} ficam no fundo de {area:257}: pegue o caminho central e vire à esquerda na bifurcação, até a saliência alta. Os Capetas deixam cair Cogumelos Jacinto; os Lírios Lunapétala crescem junto aos lagos ao norte de {area:256}.",
		["Use the {item:5185} at the moonwell"] = "Use o {item:5185} no poço lunar",
		["Use the {item:5619} at the moonwell"] = "Use o {item:5619} no poço lunar",
		["Use the {item:5621} at the moonwell"] = "Use o {item:5621} no poço lunar",
		["Use the {item:5623} at the moonwell"] = "Use o {item:5623} no poço lunar",
		["Walk Lynessa out and keep her alive"] = "Leve Lynessa para fora e mantenha-a viva",
		["Walk south along the west side of the island. Ursal prowls the far south, below the {area:478}."] = "Ande para o sul pelo lado oeste da ilha. Ursal, o Espancador, ronda o extremo sul, abaixo de {area:478}.",
		["Webwood Lurkers"] = "Tocaieiras Lenhateia",
		["Webwood Spiders"] = "Aranhas Lenhateia",
		["You start at the foot of {area:256}, the great tree of {area:188}."] = "Você começa ao pé de {area:256}, a grande árvore de {area:188}.",
		["Young Nightsabers and Young Thistle Boars roam around {area:256}. Grells carry {item:3297} in the woods west of the tree, where the Gnarlpine Totems stand."] = "Sabres-da-noite Jovens e Javalis-espinho Jovens vagueiam ao redor de {area:256}. Os Capetas carregam {item:3297} no bosque a oeste da árvore, onde ficam os Totens de Masca-pinho.",
		["{area:186} again"] = "{area:186} de novo",
		["{area:186} quests"] = "Missões de {area:186}",
		["{area:258}'s mouth"] = "Entrada de {area:258}",
		["{area:736}, outside the barrow"] = "{area:736}, fora do túmulo",
		["{item:159} from {npc:6736}, for {npc:6094}"] = "{item:159} de {npc:6736}, para {npc:6094}",
		["{item:3371} from {npc:3614}, beside {npc:6094}"] = "{item:3371} de {npc:3614}, ao lado de {npc:6094}",
		["{npc:11401}, in the Temple of the Moon: Starshards"] = "{npc:11401}, no Templo da Lua: Fragmentos Estelares",
		["{npc:1992}, south of the tree"] = "{npc:1992}, ao sul da árvore",
		["{npc:1996}: tame it with the {item:15908}"] = "{npc:1996}: dome-a com o {item:15908}",
		["{npc:1998}: tame it with the {item:15908}"] = "{npc:1998}: dome-a com o {item:15908}",
		["{npc:2038} waits inside the cave, at the bottom or up on the ledge; keep to the right."] = "{npc:2038} espera dentro da caverna, no fundo ou em cima da saliência; mantenha-se à direita.",
		["{npc:2043}: tame it with the {item:15908}"] = "{npc:2043}: dome-o com o {item:15908}",
		["{npc:2077}, by the path"] = "{npc:2077}, junto à trilha",
		["{npc:2079}: a sigil for {npc:3596}"] = "{npc:2079}: um sigilo para {npc:3596}",
		["{npc:2080}: {quest:922} in {zone:1457} takes it"] = "{npc:2080}: {quest:922}, em {zone:1457}, a recebe",
		["{npc:2082}, on the tree's ramp"] = "{npc:2082}, na rampa da árvore",
		["{npc:2150}, on the way back"] = "{npc:2150}, no caminho de volta",
		["{npc:2151} patrols the road west of the village: if she isn't at the arrow, follow the road until you meet her."] = "{npc:2151} patrulha a estrada a oeste da aldeia: se ela não estiver na seta, siga a estrada até encontrá-la.",
		["{npc:2151}, on the road west of the village"] = "{npc:2151}, na estrada a oeste da aldeia",
		["{npc:265811}, by the campfire"] = "{npc:265811}, junto à fogueira",
		["{npc:272034} and {npc:272044} fly just west of the moonwell, {npc:272046} further north."] = "{npc:272034} e {npc:272044} voam logo a oeste do poço lunar, {npc:272046} mais ao norte.",
		["{npc:3514}, at the top of the tree"] = "{npc:3514}, no topo da árvore",
		["{npc:3515}, south of the inn"] = "{npc:3515}, ao sul da estalagem",
		["{npc:3516}, in the {area:1658}"] = "{npc:3516}, em {area:1658}",
		["{npc:3519}, by the moonwell"] = "{npc:3519}, junto ao poço lunar",
		["{npc:3567}, back in {area:186}"] = "{npc:3567}, de volta a {area:186}",
		["{npc:3593}, the warrior trainer"] = "{npc:3593}, o instrutor de guerreiro",
		["{npc:3594}, the rogue trainer"] = "{npc:3594}, o instrutor de ladino",
		["{npc:3596}, the hunter trainer"] = "{npc:3596}, a instrutora de caçador",
		["{npc:3597}, the druid trainer at {area:256}"] = "{npc:3597}, o instrutor de druida em {area:256}",
		["{npc:3600}: {npc:11401} in {zone:1457} takes it"] = "{npc:3600}: {npc:11401}, em {zone:1457}, a recebe",
		["{npc:3602}: {npc:4217} in {zone:1457} takes it"] = "{npc:3602}: {npc:4217}, em {zone:1457}, a recebe",
		["{npc:4092}, in the Temple of the Moon"] = "{npc:4092}, no Templo da Lua",
		["{npc:4146} in {zone:1457} takes it"] = "{npc:4146}, em {zone:1457}, a recebe",
		["{npc:4146}, in the {area:1658}: {spell:5149}"] = "{npc:4146}, em {area:1658}: {spell:5149}",
		["{npc:4200}'s fish stall is by the docks. Then take the boat to {zone:1453}."] = "A banca de peixe de {npc:4200} fica perto do cais. Depois pegue o barco para {zone:1453}.",
		["{npc:4217}, in the {area:1658}"] = "{npc:4217}, em {area:1658}",
		["{npc:7318}, in the den"] = "{npc:7318}, na toca",
		["{npc:7999}, above {npc:4092}"] = "{npc:7999}, acima de {npc:4092}",
		["{npc:8583}, east of the tree"] = "{npc:8583}, a leste da árvore",
		["{object:673378}, just west of the moonwell"] = "{object:673378}, logo a oeste do poço lunar",
		["{object:7510}, beside him"] = "{object:7510}, ao lado dele",
		["{quest:488} and the Starbreeze moonwell"] = "{quest:488} e o poço lunar do Vilarejo Brisastral",
		["{quest:917} and the antidote"] = "{quest:917} e o antídoto",
		["{quest:97979}: cast {spell:1259799} and Shadowmeld, then hand it back to {npc:3595}"] = "{quest:97979}: lance {spell:1259799} e Fusão Sombria e depois entregue a {npc:3595}",
} end)()
t.guides["forever/alliance/skyborne/01-zephras-isle"] = (function() return {
		["/sit by {npc:263664}'s campfire until you get {spell:1229451}"] = "Use /sentar junto à fogueira de {npc:263664} até receber {spell:1229451}",
		["Al'Aketh Stormchasers and Footsoldiers camp just north of {npc:257944} and drop the heirloom; the Shrieklings west of her drop the feathers and talons; the {item:265105} grows along the stream west of her."] = "Caça-tempestades e Soldados de Infantaria Al'Aketh acampam logo ao norte de {npc:257944} e deixam cair a herança; os Guinchotes a oeste dela deixam cair as penas e garras; o {item:265105} cresce ao longo do riacho a oeste dela.",
		["Back in {quest:92529}: Stormcallers and {npc:251662} fill the village, the Stormcallers carry the stolen supplies, and {npc:251966} stands at its south end."] = "De volta à {quest:92529}: Tempestários e {npc:251662} enchem a aldeia, os Tempestários carregam os suprimentos roubados e {npc:251966} fica no extremo sul.",
		["Back to Shen'dar"] = "De volta a Shen'dar",
		["Back to the Hermit"] = "De volta ao Eremita",
		["Back to {area:16622}"] = "De volta a {area:16622}",
		["Back to {npc:255853} by the falls north-east of {area:16638}, on the way north to the shrine."] = "Volte a {npc:255853}, junto às cachoeiras a nordeste de {area:16638}, no caminho para o santuário ao norte.",
		["Bandit Highwaymen"] = "Bandoleiros Bandidos",
		["Bolvar Fordragon stands in the throne room of {object:2117}, at the north end of the city. Then leave by the main gate for {zone:1436}."] = "Bolvar Fordragon fica na sala do trono de {object:2117}, no extremo norte da cidade. Depois saia pelo portão principal rumo a {zone:1436}.",
		["Cast {spell:1259705} at the {object:460002}"] = "Use sua habilidade racial {spell:1259705} na Linha Ley",
		["Desperate times"] = "Tempos desesperados",
		["Each of Quel'ana's quests hands you a {item:15908}: use it on the beast she names, then bring the rod back to her in {area:16638}. Windsong Crawlers line the shore west of town; Vuldren Alphas and Ornery Galestriders roam the {area:16626} around the Windfield farm. Her sister {npc:254411} stands beside her."] = "Cada missão de Quel'ana dá a você um {item:15908}: use-o na fera que ela indicar e depois devolva o bastão a ela em {area:16638}. Rastejantes Cantéolo ocupam a margem a oeste da cidade; Vuldrens Alfa e Vagaventos Turrões vagam por {area:16626}, em volta da fazenda Windfield. A irmã dela, {npc:254411}, fica ao lado.",
		["Fight north to the {area:16629}. Guardians, Spiritcallers and Blademasters hold the approach; {npc:253576} waits at the shrine's door, {npc:253590} inside the inner sanctum."] = "Abra caminho para o norte até o {area:16629}. Guardiões, Evoca-espíritos e Mestres de Espadas defendem o acesso; {npc:253576} espera na porta do santuário, e {npc:253590} no sacrário interno.",
		["Find Fillion and his bedroll"] = "Encontre Filião e o saco de dormir dele",
		["Follow the road south to {area:16624}. {npc:263664} camps by the fire west of the village; {npc:251523} and {npc:251903} stand in its middle."] = "Siga a estrada para o sul até {area:16624}. {npc:263664} acampa junto à fogueira a oeste da aldeia; {npc:251523} e {npc:251903} ficam no centro dela.",
		["For {npc:234} at {area:108}"] = "Para {npc:234} em {area:108}",
		["Havoc in Falaath"] = "Caos em Falaath",
		["Head north into {area:16631}. {npc:257944} camps in its east."] = "Siga para o norte, entrando em {area:16631}. {npc:257944} acampa na parte leste.",
		["Head north-west to the hippogryph nests on the western cliffs. {item:263493} lies around the nests; the Matriarch patrols among them."] = "Vá para noroeste até os ninhos de hipogrifo nos penhascos do oeste. {item:263493} fica espalhada pelos ninhos; a Matriarca Hipogrifo patrulha entre eles.",
		["Heal 7 druids in the Nightfang Den, then find {npc:258130}"] = "Cure 7 druidas no Covil Presanoite e depois encontre {npc:258130}",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "Saia de {zone:1453} pelo portão principal. A cachoeira do {quest:1861} fica a sudoeste dos portões, no caminho para {zone:1436}, a oeste: encha o {item:7207} na base dela.",
		["Level 4 spells"] = "Feitiços de nível 4",
		["Level 6 spells"] = "Feitiços de nível 6",
		["Listen to {npc:257554}"] = "Escute {npc:257554}",
		["Lorthuna waits on the eastern shore of the isle, east of the {area:16629}."] = "Lorthuna espera na costa leste da ilha, a leste do {area:16629}.",
		["Meet Valennia at the gate"] = "Encontre Valennia no portão",
		["North of the cones: the Wind Hollows drift around the refugees' camp, the {item:266433} lie between the tents, and {npc:259013} lies at its north end."] = "Ao norte das pinhas: os Abantesmas do Vento vagueiam pelo acampamento dos refugiados, os {item:266433} estão entre as tendas e {npc:259013} jaz no extremo norte.",
		["North-west of Valanaar along the road: {npc:273017} watches the {quest:98512}; the dead cultist lies just north of him."] = "A noroeste de Valanaar, pela estrada: {npc:273017} vigia os {quest:98512}; o sectário morto jaz logo ao norte dele.",
		["Prideclaws and Galestriders"] = "Garraltivas e Vagaventos",
		["Prideclaws and Galestriders roam the grasslands south of the village. Galestriders drop both the eggs and the meat."] = "Garraltivas e Vagaventos vagam pelos campos ao sul da aldeia. Os Vagaventos deixam cair tanto os ovos quanto a carne.",
		["Rally Valennia, {npc:251968} (west of town) and {npc:252475}"] = "Reúna Valennia, {npc:251968} (a oeste da cidade) e {npc:252475}",
		["Raw Windstones and the {npc:251404}"] = "Pedras Eólicas Brutas e a {npc:251404}",
		["Ripe Stormapples and Hungry Bandits are in the orchard by the farm, {quest:92683} in the fields north-east of it, Ornery Galestriders all around. The {npc:250929} stands in the field north-east of the farm."] = "Maçãs-dos-raios Maduras e Bandidos Famintos estão no pomar junto à fazenda, {quest:92683} nos campos a nordeste dela, e Vagaventos Turrões por toda parte. O {npc:250929} fica no campo a nordeste da fazenda.",
		["Search the dead cultist"] = "Reviste o sectário morto",
		["Search the wardrobe"] = "Revire o guarda-roupa",
		["Shen'dar turn-ins"] = "Entregas em Shen'dar",
		["Skycutter to {area:279}"] = "Nave celeste para {area:279}",
		["Skyhoppers"] = "Saltacéus",
		["Skyhoppers swarm the fields west of {area:16638}."] = "Saltacéus infestam os campos a oeste de {area:16638}.",
		["Speak with {npc:251903} and {npc:254089}, north-west of the village"] = "Fale com {npc:251903} e {npc:254089}, a noroeste da aldeia",
		["Stand with {npc:252800} against {npc:252863}"] = "Lute ao lado de {npc:252800} contra {npc:252863}",
		["Standing our ground"] = "Firmes na posição",
		["Take the road south-east. {npc:257006} and {npc:252448} stand by the road west of {area:16638}; Windsong Crawlers line the shore further west, around 51,70."] = "Pegue a estrada para sudeste. {npc:257006} e {npc:252448} ficam à beira da estrada a oeste de {area:16638}; Rastejantes Cantéolo ocupam a margem mais a oeste, por volta de 51,70.",
		["Tame it with the {item:15908}"] = "Dome-o com o {item:15908}",
		["The Bandit Highwaymen hold the hills north of the farm."] = "Os Bandoleiros Bandidos ocupam as colinas ao norte da fazenda.",
		["The Highlands Bandits camp north-east of the village. \"Badwind\" Bennic waits at the far north end of their camp."] = "Os Bandidos do Planalto acampam a nordeste da aldeia. Bennic \"Malevento\" espera no extremo norte do acampamento.",
		["The Highlands bandits"] = "Os bandidos do Planalto",
		["The Novice Seers practise in the clearing west of Shen'dar."] = "Os Videntes Noviços treinam na clareira a oeste de Shen'dar.",
		["The Raw Windstones glitter on the ground just south of the grove. {quest:92463} hovers over the meadow further east, on the way to {npc:249363}."] = "As Pedras Eólicas Brutas brilham no chão logo ao sul do bosque. {quest:92463} paira sobre a campina mais a leste, no caminho até {npc:249363}.",
		["The Windfield farm"] = "A fazenda Windfield",
		["The Windstone Formations"] = "As Formações de Pedra Eólica",
		["The Windstone Formations stand on the rise west of Fillion's camp."] = "As Formações de Pedra Eólica ficam na elevação a oeste do acampamento de Filião.",
		["The bounty board"] = "O quadro de recompensas",
		["The class trainers stand together in the grove"] = "Os instrutores de classe ficam juntos no bosque",
		["The dead cultist"] = "O sectário morto",
		["The eastern watchtower"] = "A torre de vigia leste",
		["The hippogryph roost"] = "O ninhal dos hipogrifos",
		["The missing scholar"] = "O erudito desaparecido",
		["The refugees' camp"] = "O acampamento dos refugiados",
		["The road to {area:16638}"] = "A estrada para {area:16638}",
		["The skycutter"] = "A nave celeste",
		["The skycutter docks at the tower south of {area:16638}. It lands by the Kirin Tor camp on the lake shore west of {area:279}."] = "A nave celeste atraca na torre ao sul de {area:16638}. Ela pousa junto ao acampamento do Kirin Tor, na margem do lago a oeste de {area:279}.",
		["The {area:16629}"] = "{area:16629}",
		["The {item:254871}"] = "O {item:254871}",
		["The {object:581822}"] = "A {object:581822}",
		["The {object:581822} lies by the path west of {area:16638}; Fillion's camp is north-west of it, and the Shriekling Matriarchs nest just west of the camp."] = "A {object:581822} está junto à trilha a oeste de {area:16638}; o acampamento de Filião fica a noroeste dela, e as Matriarcas Guinchote fazem ninho logo a oeste do acampamento.",
		["Use {spell:1259416}"] = "Use {spell:1259416}",
		["Village quests"] = "Missões da aldeia",
		["Vuldren and Cirrusflies"] = "Vuldrens e Cirromoscas",
		["Windshaper Novice Seers"] = "Videntes Noviços Moldavento",
		["You wake in {area:16622}. {npc:251362} stands beside you; {npc:251361} is a few steps west, {npc:251368} by the south edge of the grove."] = "Você acorda em {area:16622}. {npc:251362} está ao seu lado; {npc:251361} fica a alguns passos a oeste, e {npc:251368} na borda sul do bosque.",
		["{area:16622} turn-ins"] = "Entregas em {area:16622}",
		["{area:16624} again"] = "{area:16624} de novo",
		["{area:16638} turn-ins"] = "Entregas em {area:16638}",
		["{area:16638}, the fate of Zephras"] = "{area:16638}, o destino de Zefras",
		["{area:16638}, the turncoat"] = "{area:16638}, o desertor",
		["{item:262668}: by the wind shrine south of {quest:92529}"] = "{item:262668}: junto ao santuário do vento ao sul da {quest:92529}",
		["{item:263993}: {npc:257196}, west of the shrine's approach"] = "{item:263993}: {npc:257196}, a oeste do acesso ao santuário",
		["{npc:249363} keeps watch east of the grove. The {npc:251143} and Al'Aketh Converts gather just north of her; the {object:460002} rises further north: cast your {spell:1259705} racial ability at it."] = "{npc:249363} vigia a leste do bosque. Os {npc:251143} e os Convertidos Al'Aketh se reúnem logo ao norte dela; a Linha Ley se ergue mais ao norte: use nela sua habilidade racial {spell:1259705}.",
		["{npc:250873} and Pesky Cirrusflies roam the meadow just south-east of the grove."] = "{npc:250873} e Cirromoscas Irritantes vagam pela campina logo a sudeste do bosque.",
		["{npc:250926} and {npc:251115}"] = "{npc:250926} e {npc:251115}",
		["{npc:250926} prowl the woods just west of the grove; the Ursera Scavengers den further west, with {npc:251115}, the matriarch, at the back of the den."] = "{npc:250926} rondam a mata logo a oeste do bosque; os Catadores Ursera têm a toca mais a oeste, com {npc:251115}, a matriarca, no fundo da toca.",
		["{npc:251361}: a note from your trainer"] = "{npc:251361}: um bilhete do seu instrutor",
		["{npc:251361}: read the {item:9547}"] = "{npc:251361}: leia o {item:9547}",
		["{npc:251361}: the {item:4100}"] = "{npc:251361}: o {item:4100}",
		["{npc:251373}, the druid trainer, on the ground floor of the tree behind {npc:251361}"] = "{npc:251373}, o instrutor de druidas, no térreo da árvore atrás de {npc:251361}",
		["{npc:251379}, the mage trainer: read the {item:282416} first"] = "{npc:251379}, a instrutora de magos: leia o {item:282416} primeiro",
		["{npc:251389}, in the watchtower"] = "{npc:251389}, na torre de vigia",
		["{npc:251964}, in the watchtower"] = "{npc:251964}, na torre de vigia",
		["{npc:252095} camps south of the Ursera den. The Al'Aketh thugs hold the camp south-west of her; {npc:256935} stands in its middle."] = "{npc:252095} acampa ao sul da toca dos Ursera. Os Bandidos Al'Aketh ocupam o acampamento a sudoeste dela; {npc:256935} fica no meio dele.",
		["{npc:252155} holds the western watch, south-west of Falaath. {npc:256966} and the fallen guards lie just south of her."] = "{npc:252155} guarda a vigia oeste, a sudoeste de Falaath. {npc:256966} e os guardas caídos jazem logo ao sul dela.",
		["{npc:252373}, the mage trainer"] = "{npc:252373}, o instrutor de magos",
		["{npc:252377}: {npc:257196} waits at the {area:16629}"] = "{npc:252377}: {npc:257196} espera no {area:16629}",
		["{npc:252378} holds the watchtower north of {area:16638}. The Al'Aketh camp is just west of the tower, its healers around 65,68 and 65,65; {npc:252666} stands at its north end. The Al'Aketh there drop Windstone Charms."] = "{npc:252378} guarda a torre de vigia ao norte de {area:16638}. O acampamento Al'Aketh fica logo a oeste da torre, com os curandeiros por volta de 65,68 e 65,65; {npc:252666} fica no extremo norte. Os Al'Aketh de lá deixam cair Patuás da Pedra Eólica de Al'Aketh.",
		["{npc:252383} and {npc:252476} stand at the north end of {area:16638}, {npc:252475} and {npc:253204} at the south end."] = "{npc:252383} e {npc:252476} ficam no extremo norte de {area:16638}; {npc:252475} e {npc:253204}, no extremo sul.",
		["{npc:252475}: {npc:259084} waits by the Skyborne portal"] = "{npc:252475}: {npc:259084} espera junto ao portal Celonato",
		["{npc:252800} again"] = "{npc:252800} de novo",
		["{npc:252800} runs the farm in the south-west lowlands."] = "{npc:252800} cuida da fazenda nas terras baixas do sudoeste.",
		["{npc:253590}, in the sanctum"] = "{npc:253590}, no sacrário",
		["{npc:254151}, {npc:258130} and {npc:258134} are north-east of {npc:257944}; {npc:253622} stands east of them. Haalien also drops a {quest:94490}."] = "{npc:254151}, {npc:258130} e {npc:258134} ficam a nordeste de {npc:257944}; {npc:253622} fica a leste deles. Haalien também deixa cair uma {quest:94490}.",
		["{npc:254588}: tame it with the {item:15908}"] = "{npc:254588}: dome-o com o {item:15908}",
		["{npc:254589} lurks in the hills south-west of the village, on the way back. {npc:254589} is elite: grouping up is advised."] = "{npc:254589} espreita nas colinas a sudoeste da aldeia, no caminho de volta. {npc:254589} é Elite: recomenda-se formar um grupo.",
		["{npc:255853} waits by the falls north-east of {area:16638}. {npc:258443} prowls the {area:16623} west of {area:16638}, by the road you take next."] = "{npc:255853} espera junto às cachoeiras a nordeste de {area:16638}. {npc:258443} ronda {area:16623} a oeste de {area:16638}, perto da estrada que você pegará em seguida.",
		["{npc:257065} waits at the entrance to {quest:92529}, south of Shen'dar. The {spell:1254832} lets you walk in among the faithful."] = "{npc:257065} espera na entrada de {quest:92529}, ao sul de Shen'dar. {spell:1254832} permite que você ande entre os fiéis.",
		["{npc:257944} again"] = "{npc:257944} de novo",
		["{npc:257944}, the missive"] = "{npc:257944}, a missiva",
		["{npc:258443}, in the highlands south-west of the cultist"] = "{npc:258443}, no planalto a sudoeste do sectário",
		["{npc:259084} stands beside the Skyborne Portal where the zeppelin lands. The portal takes you to {zone:1453}."] = "{npc:259084} fica ao lado do Portal Celonato, onde o zepelim pousa. O portal leva você a {zone:1453}.",
		["{npc:270459}, beside {npc:259084}: for {npc:5504} in {zone:1453}"] = "{npc:270459}, ao lado de {npc:259084}: para {npc:5504} em {zone:1453}",
		["{npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "{npc:5497} fica no Santuário do Mago, a torre do {object:2101}; ela dá a você um frasco para a cachoeira do {quest:1861}.",
		["{npc:5504}, {zone:1453}'s druid trainer, teaches you {spell:18960}. {npc:11802}'s welcome waits for your {spell:499} trip at the end of {zone:1439}."] = "{npc:5504}, instrutor de druidas de {zone:1453}, ensina {spell:18960}. As boas-vindas de {npc:11802} aguardam sua viagem de {spell:499} no fim de {zone:1439}.",
		["{quest:93159} lives west of {npc:257944}. The Zephyrseed Cones lie in the woods between his hut and {npc:257944}."] = "{quest:93159} mora a oeste de {npc:257944}. As Pinhas de Semente-de-zéfiro ficam na mata entre a cabana dele e {npc:257944}.",
} end)()
t.guides["forever/class/druid/aquatic-form"] = (function() return {
		["At the {area:2362}"] = "No {area:2362}",
		["Cast {spell:18960}. Join the two halves into the {item:15885} near the {area:2362}, on the north-west shore of the lake, then see {npc:11802} in {area:2361}. Fly to {area:702} afterwards."] = "Lance {spell:18960}. Junte as duas metades no {item:15885} perto de {area:2362}, na margem noroeste do lago, e depois fale com {npc:11802} em {area:2361}. Depois voe até {area:702}.",
		["Cast {spell:18960}. Join the two halves into the {item:15885} near the {area:2362}, on the north-west shore of the lake, then see {npc:11802} in {area:2361}. {npc:11798} flies druids to {area:1638}."] = "Lance {spell:18960}. Junte as duas metades no {item:15885} perto de {area:2362}, na margem noroeste do lago, e depois fale com {npc:11802} em {area:2361}. {npc:11798} leva druidas voando até {area:1638}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}. Shrine Baubles lie in the containers on the floor of {area:656}, below {area:2361}: take one to the {area:2362} on the north-west shore, use it there and speak to {npc:11799}."] = "Lance {spell:18960}. {npc:11802} está em {area:2361}. Adornos de Altar ficam nos recipientes no fundo de {area:656}, abaixo de {area:2361}: leve um até {area:2362} na margem noroeste, use-o lá e fale com {npc:11799}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}. The Shrine Baubles lie on the bed of {area:656} and fade within minutes: swim one straight to the {area:2362} on the north-west shore, use it there and speak to {npc:11799}."] = "Lance {spell:18960}. {npc:11802} está em {area:2361}. Os Adornos de Altar ficam no fundo de {area:656} e somem em poucos minutos: nade com um direto até {area:2362} na margem noroeste, use-o lá e fale com {npc:11799}.",
		["Fly from {area:2361} to {area:442}. The {object:177792} lies under the water off the north coast, west of the {area:443}."] = "Voe de {area:2361} até {area:442}. O {object:177792} está debaixo d'água perto da costa norte, a oeste das {area:443}.",
		["Take the boat from {area:442} to {zone:1453} and fly to {area:108}. Ride north-west to the coast: the {object:177790} lies on the sea floor off the shore."] = "Pegue o navio de {area:442} até {zone:1453} e voe até {area:108}. Cavalgue para noroeste até a costa: o {object:177790} está no fundo do mar perto da praia.",
		["Take the portal up to {npc:4217} in the {area:1658}."] = "Pegue o portal até {npc:4217} no {area:1658}.",
		["Take {npc:11798}'s flight to {zone:1456}, fly to {zone:1454} and take the zeppelin to {zone:1420}; {zone:1421} is south of the {zone:1458}. The {object:177790} lies on the coast west of the {area:240}, north of the {area:228}."] = "Pegue o voo de {npc:11798} até {zone:1456}, voe até {zone:1454} e pegue o zepelim até {zone:1420}; {zone:1421} fica ao sul de {zone:1458}. O {object:177790} está na costa a oeste do {area:240}, ao norte do {area:228}.",
		["The {object:177792} lies at the north edge of the {area:382}, by the Venture Co. tower, north of the {area:380}."] = "O {object:177792} está na borda norte do {area:382}, perto da torre da Empreendimentos S.A., ao norte da {area:380}.",
		["Your water travel form: swim fast and breathe underwater, with a belt and an idol besides."] = "Sua forma de viagem aquática: nade rápido e respire debaixo d'água, com um cinto e um ídolo de quebra.",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}, de um {object:177785} no lago",
		["{item:15885}: join the halves at the shrine"] = "{item:15885}: junte as metades no santuário",
		["{npc:3033} stands on {area:1639}."] = "{npc:3033} fica no {area:1639}.",
		["{npc:4217} stands in the {area:1658}."] = "{npc:4217} fica no {area:1658}.",
} end)()
t.guides["forever/class/druid/bear-form"] = (function() return {
		["At 10 a druid's call reaches you: {npc:3064} in {area:222} or {npc:6746} in {zone:1456} ({npc:6929}'s letter in {zone:1454} works too). Any one of them sends you to {npc:3033} on {area:1639} in {zone:1456}."] = "No nível 10, o chamado dos druidas chega até você: {npc:3064} em {area:222} ou {npc:6746} em {zone:1456} (a carta de {npc:6929} em {zone:1454} também serve). Qualquer um deles envia você a {npc:3033} no {area:1639}, em {zone:1456}.",
		["At 10 a druid's call reaches you: {npc:3602} in {area:186}, Denatharion in {zone:1457} or Theridran in {zone:1453}. Any one of them sends you to {npc:4217} in the Cenarion Enclave of Darnassus."] = "No nível 10, o chamado dos druidas chega até você: {npc:3602} em {area:186}, Denatharion em {zone:1457} ou Theridran em {zone:1453}. Qualquer um deles envia você a {npc:4217} no Enclave Cenariano de Darnassus.",
		["Back to {npc:255853} by the falls."] = "Volte a {npc:255853}, junto às cachoeiras.",
		["Back to {npc:3033} on {area:1639}."] = "Volte a {npc:3033} no {area:1639}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}. Learn the {area:493} flight path while you are here."] = "Lance {spell:18960}. {npc:11802} está em {area:2361}. Aprenda a rota de voo de {area:493} enquanto estiver lá.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5929} sits in the woods to the north-west. Learn the {area:493} flight path, then fly to {area:702} (by way of {area:442}) and take the portal up to {zone:1457}."] = "Lance {spell:18960}. {npc:11802} está em {area:2361}; {quest:5929} fica na mata a noroeste. Aprenda a rota de voo de {area:493}, depois voe até {area:702} (passando por {area:442}) e pegue o portal até {zone:1457}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; the {quest:5930} sits in the woods to the north-west. {npc:11798} in {area:2361} flies druids to {area:1638}."] = "Lance {spell:18960}. {npc:11802} está em {area:2361}; {quest:5930} fica na mata a noroeste. {npc:11798}, em {area:2361}, leva druidas voando até {area:1638}.",
		["Fly back to {area:702} and take the portal up to {npc:4217}."] = "Volte voando para {area:702} e pegue o portal até {npc:4217}.",
		["Fly from {area:702} to {area:442}. The {object:177525} stands in the hills just east of the village: use the {item:15208} there, defeat Lunaclaw and speak to the {npc:12144}."] = "Voe de {area:702} até {area:442}. A {object:177525} fica nas colinas logo a leste da vila: use a {item:15208} lá, derrote Lunagarra e fale com o {npc:12144}.",
		["Skyboat from {area:279}"] = "Barco celeste de {area:279}",
		["Skyboat from {zone:1456}"] = "Barco celeste de {zone:1456}",
		["Skyboat to {zone:2521}"] = "Barco celeste para a {zone:2521}",
		["Speak with the {quest:5929}"] = "Fale com o {quest:5929}",
		["Speak with the {quest:5930}"] = "Fale com o {quest:5930}",
		["The Skyborne Portal takes you to {zone:1453}. {npc:5504} is the city's druid trainer."] = "O Portal Celonato leva você a {zone:1453}. {npc:5504} é o instrutor de druidas da cidade.",
		["The {object:177525}"] = "A {object:177525}",
		["The {object:177525} stands in the pass from {zone:1412} into the {zone:1413}. Use the {item:15710} there, defeat Lunaclaw and speak to the {npc:12144}."] = "A {object:177525} fica na passagem de {zone:1412} para {zone:1413}. Use a {item:15710} lá, derrote Lunagarra e fale com o {npc:12144}.",
		["Your tanking form: Forever no longer trains {spell:5487}, these quests give it. Opens {area:493} too."] = "Sua forma de tanque: o Forever não ensina mais {spell:5487} no instrutor; estas missões a concedem. Também liberam {area:493}.",
		["or whichever of the three letters you carry"] = "ou qualquer uma das três cartas que você tiver",
		["{npc:252359} stands in {area:16638}."] = "{npc:252359} fica em {area:16638}.",
		["{npc:255853} and {npc:258443}"] = "{npc:255853} e {npc:258443}",
		["{npc:255853} waits by the falls north-east of {area:16638}. {npc:258443} prowls the {area:16623}, west of {area:16638}."] = "{npc:255853} espera junto às cachoeiras a nordeste de {area:16638}. {npc:258443} ronda {area:16623}, a oeste de {area:16638}.",
		["{npc:259118} waits where the airship from {zone:2521} lands, in northern {zone:1412} beside {zone:1456}."] = "{npc:259118} espera onde a aeronave vinda da {zone:2521} pousa, no norte de {zone:1412}, junto a {zone:1456}.",
		["{npc:270459} stands beside {npc:259084} and the Skyborne Portal, west of {area:279}, where the skycutter from {zone:2521} lands. {npc:2543} offers the same quest."] = "{npc:270459} fica ao lado de {npc:259084} e do Portal Celonato, a oeste de {area:279}, onde pousa a nave celeste vinda da {zone:2521}. {npc:2543} oferece a mesma missão.",
		["{npc:3033} stands on {area:1639}."] = "{npc:3033} fica no {area:1639}.",
		["{npc:3033} trains druids on {area:1639}."] = "{npc:3033} treina druidas no {area:1639}.",
		["{npc:3064}, {area:222}; Pala's and Gryshka's letters lead to the same place"] = "{npc:3064}, {area:222}; as cartas de Pala e Gryshka levam ao mesmo lugar",
		["{npc:3602}, {area:186}; Denatharion's and Theridran's letters lead to the same place"] = "{npc:3602}, {area:186}; as cartas de Denatharion e Theridran levam ao mesmo lugar",
		["{npc:4217} stands in the {area:1658}."] = "{npc:4217} fica no {area:1658}.",
		["{spell:5487} and {area:493}"] = "{spell:5487} e {area:493}",
		["{spell:5487} is taught on {zone:2521}. Skip this if you are still on the isle; otherwise take the skyboat from the cliffs south of {area:17045}, north of {zone:1456}."] = "{spell:5487} é ensinada na {zone:2521}. Pule isto se ainda estiver na ilha; senão, pegue o barco celeste nos penhascos ao sul de {area:17045}, ao norte de {zone:1456}.",
		["{spell:5487} is taught on {zone:2521}. Skip this if you are still on the isle; otherwise take the skyboat from the north side of {area:279}."] = "{spell:5487} é ensinada na {zone:2521}. Pule isto se ainda estiver na ilha; senão, pegue o barco celeste no lado norte de {area:279}.",
} end)()
t.guides["forever/class/druid/bloodpetal-poison"] = (function() return {
		["Back to {npc:9619} in the south-east corner of {zone:1449}."] = "De volta a {npc:9619}, no canto sudeste da {zone:1449}.",
		["Cast {spell:18960}. {npc:12042} stands in {area:2361}; your class trainer offers the same quest."] = "Lance {spell:18960}. {npc:12042} fica em {area:2361}; seu instrutor de classe oferece a mesma missão.",
		["Experience in Un'Goro at 50 and two healing potions; Forever removed the Classic item choice."] = "Experiência em Un'Goro no nível 50 e duas poções de cura; o Forever removeu a escolha de item do Classic.",
		["Fly to {area:976}, ride west to the long ramp down into {zone:1449}: {npc:9619} camps at its foot, in the south-east corner of the crater."] = "Voe até {area:976}, cavalgue para oeste até a longa rampa que desce para a {zone:1449}: {npc:9619} acampa ao pé dela, no canto sudeste da cratera.",
		["Gorishi Stings and {item:22434}"] = "Ferrões de Gorishi e {item:22434}",
		["The Gorishi wasps, workers and reavers of the hive in the south of the crater drop the stings; the Bloodpetal Sprouts that give the {item:22434} grow all over the crater's western half."] = "As vespas, trabalhadoras e aniquiladoras Gorishi da colmeia no sul da cratera deixam cair os ferrões; os Brotos de Pétala Sangrenta que dão o {item:22434} crescem por toda a metade oeste da cratera.",
		["The {area:1417}"] = "O {area:1417}",
		["Use the {item:22432} on a {npc:6498}. Devilsaurs are elite (level 54-55) and roam the crater: grouping up is advised."] = "Use a {item:22432} num {npc:6498}. Demossauros são elite (nível 54-55) e vagam pela cratera: é recomendado formar grupo.",
		["{area:1477} lies in the {area:74} in the {zone:1435}. {npc:8580} guards the bottom of the temple: a dungeon boss, so bring a group."] = "{area:1477} fica no {area:74}, no {zone:1435}. {npc:8580} guarda o fundo do templo: é chefe de masmorra, então leve um grupo.",
		["{npc:6498}: stab it with the {item:22432}"] = "{npc:6498}: espete-o com a {item:22432}",
} end)()
t.guides["forever/class/druid/cat-form"] = (function() return {
		["Back to {npc:11802}"] = "De volta a {npc:11802}",
		["Back to {npc:11802} in {area:2361}, then fly to {area:702}."] = "De volta a {npc:11802} em {area:2361}, depois voe para {area:702}.",
		["Back to {npc:11802} in {area:2361}, then take {npc:11798}'s flight to {area:1638}."] = "De volta a {npc:11802} em {area:2361}, depois pegue o voo de {npc:11798} para {area:1638}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}."] = "Lance {spell:18960}. {npc:11802} está em {area:2361}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}; learn the flight path there if you do not have it."] = "Lance {spell:18960}. {npc:11802} está em {area:2361}; aprenda a rota de voo de lá se ainda não a tiver.",
		["Take the portal up to {npc:4217} in the {area:1658}."] = "Pegue o portal até {npc:4217} no {area:1658}.",
		["The relics of the Barrow Dens"] = "As relíquias dos Templos de Tempesfúria",
		["The {area:2363}"] = "Os {area:2363}",
		["Your stealth and melee form: in Forever this chain gives {spell:768} at 20, not the trainer."] = "Sua forma furtiva e corpo a corpo: no Forever esta série dá {spell:768} no nível 20, não o instrutor.",
		["{npc:3033} stands on {area:1639}."] = "{npc:3033} fica em {area:1639}.",
		["{npc:4217} stands in the {area:1658}. Skyborne without the Rut'theran flight path: take the boat from {area:442}."] = "{npc:4217} fica no {area:1658}. Celonato sem a rota de voo de Vila de Rut'theran: pegue o barco em {area:442}.",
		["{quest:98342} (Tauren) waits on the southern hill above the bridge, the {npc:272054} (Skyborne) south of the twin bridges. The relics lie in the {area:2363} east of the lake: leave your form, click the statue at the entrance for five minutes of stealth, keep clear of the spirits inside and take one of each relic; the {item:280680} lies at the foot of the white cat statue. A relic gives no loot while another player is looting it: wait a moment and try again."] = "{quest:98342} (Taurens) espera na colina sul acima da ponte, o {npc:272054} (Celonatos) ao sul das pontes gêmeas. As relíquias ficam nos {area:2363} a leste do lago: saia da forma, clique na estátua da entrada para ter cinco minutos de furtividade, fique longe dos espíritos lá dentro e pegue uma de cada relíquia; a {item:280680} fica ao pé da estátua do gato branco. Uma relíquia não dá saque enquanto outro jogador a estiver saqueando: espere um pouco e tente de novo.",
		["{quest:98394} (Night Elves) waits on the southern hill above the bridge, the {npc:272054} (Skyborne) south of the twin bridges. The relics lie in the {area:2363} east of the lake: leave your form, click the statue at the entrance for five minutes of stealth, keep clear of the spirits inside and take one of each relic; the {item:280680} lies at the foot of the white cat statue. A relic gives no loot while another player is looting it: wait a moment and try again."] = "{quest:98394} (Elfos Noturnos) espera na colina sul acima da ponte, o {npc:272054} (Celonatos) ao sul das pontes gêmeas. As relíquias ficam nos {area:2363} a leste do lago: saia da forma, clique na estátua da entrada para ter cinco minutos de furtividade, fique longe dos espíritos lá dentro e pegue uma de cada relíquia; a {item:280680} fica ao pé da estátua do gato branco. Uma relíquia não dá saque enquanto outro jogador a estiver saqueando: espere um pouco e tente de novo.",
} end)()
t.guides["forever/class/druid/cure-poison"] = (function() return {
		["Back in {area:442}."] = "De volta a {area:442}.",
		["Cast {spell:18960} and see {npc:11802}, then fly to {area:702} and take the portal up to {zone:1457}."] = "Lance {spell:18960} e fale com {npc:11802}, depois voe para {area:702} e pegue o portal até {zone:1457}.",
		["Cast {spell:18960} and see {npc:11802}, then take {npc:11798}'s flight to {area:1638}."] = "Lance {spell:18960} e fale com {npc:11802}, depois pegue o voo de {npc:11798} para {area:1638}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}. Then fly to {area:442}."] = "Lance {spell:18960}. {npc:11802} está em {area:2361}. Depois voe para {area:442}.",
		["Cast {spell:18960}. {npc:11802} is in {area:2361}. {npc:11798} flies druids to {area:1638}; fly on to the {area:380} from there."] = "Lance {spell:18960}. {npc:11802} está em {area:2361}. {npc:11798} leva druidas voando a {area:1638}; de lá, siga voando até {area:380}.",
		["From the {area:380} ride north to {area:384} and fill the {item:15842} at the {object:19464}."] = "De {area:380} cavalgue para o norte até {area:384} e encha o {item:15842} no {object:19464}.",
		["Lost Barrens Kodos roam the plains north and west of the {area:380} and around the {area:388}; each drops a horn. Herbalists find {item:2449} all over the northern {zone:1413}."] = "Kodos Perdidos dos Sertões vagam pelas planícies ao norte e a oeste de {area:380} e em volta de {area:388}; cada um deixa cair um chifre. Herbalistas encontram {item:2449} por todo o norte de {zone:1413}.",
		["Ride north-east from {area:442} to {area:445} and fill the {item:15844} at the mouth of the cave by the falls."] = "Cavalgue para nordeste de {area:442} até {area:445} e encha o {item:15844} na boca da caverna junto às cascatas.",
		["Sickly Gazelles"] = "Gazelas Doentes",
		["The Lunar Fungal Blooms grow in the moonkin caves in the hills just east of {area:442}; the moonkin there are irritable. {item:2449} needs {skill:182}: herbalists pick it all over {zone:1439}, anyone else buys it from {npc:1313} (Alchemy Supplies) in {zone:1453} or on the Auction House."] = "Os Brotos Fúngicos Lunares crescem nas cavernas dos luniscantes nas colinas logo a leste de {area:442}; os luniscantes de lá são irritadiços. {item:2449} exige {skill:182}: herbalistas a colhem por toda {zone:1439}, os demais a compram de {npc:1313} (Suprimentos de Alquimia) em {zone:1453} ou na Casa de Leilões.",
		["Use the {item:15826} on Sickly Gazelles: they graze north of the road that runs east and west through the {area:380}."] = "Use o {item:15826} nas Gazelas Doentes: elas pastam ao norte da estrada que corta {area:380} de leste a oeste.",
		["Use the {item:15826} on {npc:12298}. They roam {zone:1439} from the {area:456} in the north to the {zone:1440} border in the south."] = "Use o {item:15826} em {npc:12298}. Eles vagam por {zone:1439}, do {area:456} ao norte até a fronteira de {zone:1440} ao sul.",
		["{item:15851} and {item:2449}"] = "{item:15851} e {item:2449}",
		["{item:2449} and Kodo Horns"] = "{item:2449} e Chifres de Kodo",
		["{item:2449}; herbalists pick it on the plains"] = "{item:2449}; herbalistas a colhem nas planícies",
		["{npc:12296}: use the salve on them"] = "{npc:12296}: use o unguento nelas",
		["{npc:12298}: use the salve on them"] = "{npc:12298}: use o unguento neles",
		["{npc:3033} stands on {area:1639}."] = "{npc:3033} fica em {area:1639}.",
		["{npc:3448} stands in the {area:380}. No {skill:182}? {npc:3490}, a few steps away, sells {item:2449}, three at a time until he restocks."] = "{npc:3448} fica em {area:380}. Sem {skill:182}? {npc:3490}, a poucos passos, vende {item:2449}, três de cada vez até repor o estoque.",
		["{npc:4217} stands in the {area:1658}."] = "{npc:4217} fica no {area:1658}.",
		["{spell:8946} is no longer trained in Forever: this chain teaches it, with a medicine bag on the way."] = "{spell:8946} não é mais ensinado no Forever: esta série o ensina, com uma bolsa de remédios no caminho.",
} end)()
t.guides["forever/class/hunter/rhokdelar"] = (function() return {
		["Back to the Ancients"] = "De volta aos Ancientes",
		["Hastat's quiver needs the {item:18704}. {npc:6109}, a world boss for a raid, roams the south of {zone:1447} and drops it most of the time; the Cobalt dragonkin of {zone:1452} drop it very rarely. Skip the rest of this guide if you do not want the quiver."] = "A aljava de Hastat requer o {item:18704}. {npc:6109}, um chefe mundial para raide, vaga pelo sul de {zone:1447} e o deixa cair na maioria das vezes; os dragonídeos Cobalto de {zone:1452} o deixam cair muito raramente. Pule o resto deste guia se não quiser a aljava.",
		["Not confirmed in Forever. In Classic, using the {item:18707} with the {item:18724} in your bags made Rhok'delar, and Vartrus then gave {item:18715} ({spell:425121})."] = "Não confirmado no Forever. No Classic, usar o {item:18707} com o {item:18724} nas bolsas criava Rhok'delar, e Vartrus então dava {item:18715} ({spell:425121}).",
		["Onyxia"] = "Onyxia",
		["Onyxia drops the {item:18705}; she is the 40-player raid boss of {area:2159}, a cave in the {area:511} of southern {zone:1445}."] = "Onyxia deixa cair o {item:18705}; ela é a chefe da raide de 40 jogadores do {area:2159}, uma caverna no {area:511}, no sul do {zone:1445}.",
		["Rhok'delar and Lok'delar"] = "Rhok'delar e Lok'delar",
		["The hunter's epic bow chain: in Classic the stave and sinew became Rhok'delar and Lok'delar (unconfirmed in Forever)."] = "A série do arco épico do caçador: no Classic, o báculo e o tendão viravam Rhok'delar e Lok'delar (não confirmado no Forever).",
		["The {item:18703}"] = "A {item:18703}",
		["The {object:179703} appears in {area:2717} when {npc:12018} yields; it holds the {item:18703} about half the time. {area:2717} is a 40-player raid inside {area:254}. Right-click the leaf to start the quest."] = "O {object:179703} aparece no {area:2717} quando {npc:12018} se rende; ele tem a {item:18703} em cerca de metade das vezes. {area:2717} é uma raide de 40 jogadores dentro da {area:254}. Clique com o botão direito na folha para iniciar a missão.",
		["Vartrus, Stoma and {npc:14526} stand together in the north of {zone:1448}. Alliance: {area:1998} is the nearest flight point; Horde: {area:1997}."] = "Vartrus, Stoma e {npc:14526} ficam juntos no norte de {zone:1448}. Aliança: {area:1998} é o ponto de voo mais próximo; Horda: {area:1997}.",
		["from the {item:18703}"] = "da {item:18703}",
		["{item:18704}, from {npc:6109}"] = "{item:18704}, de {npc:6109}",
		["{item:18705}, from Onyxia"] = "{item:18705}, de Onyxia",
		["{item:18707}, by Vartrus"] = "{item:18707}, por Vartrus",
		["{npc:14524}: Lok'delar in Classic"] = "{npc:14524}: Lok'delar no Classic",
		["{npc:14526}: the quiver, last in this guide"] = "{npc:14526}: a aljava, por último neste guia",
		["{npc:14527}, a troll, stands in the west of {zone:1449}. Talk to her and she becomes {npc:14533}, with a pet of her own. Alone, without your pet."] = "{npc:14527}, uma troll, fica no oeste da {zone:1449}. Fale com ela e ela se torna {npc:14533}, com um ajudante próprio. Sozinho, sem seu ajudante.",
		["{npc:14529}, a human, stands in the west of the {zone:1428}. Talk to him and he becomes {npc:14534}. Alone, without your pet."] = "{npc:14529}, um humano, fica no oeste das {zone:1428}. Fale com ele e ele se torna {npc:14534}. Sozinho, sem seu ajudante.",
		["{npc:14531}, a tauren, waits in the north-east of {zone:1452}. Talk to him and he becomes {npc:14535}. Fight every demon alone and without your pet: help of any kind makes it vanish. Loot the head."] = "{npc:14531}, um tauren, espera no nordeste de {zone:1452}. Fale com ele e ele se torna {npc:14535}. Lute contra cada demônio sozinho e sem seu ajudante: qualquer tipo de ajuda o faz sumir. Saqueie a cabeça.",
		["{npc:14536}, a gnome, stands in the south-west of {zone:1451}. Talk to him and he becomes {npc:14530}. Alone, without your pet; keep away from the beetles he calls."] = "{npc:14536}, um gnomo, fica no sudoeste de {zone:1451}. Fale com ele e ele se torna {npc:14530}. Sozinho, sem seu ajudante; fique longe dos besouros que ele chama.",
} end)()
t.guides["forever/class/hunter/the-hunters-charm"] = (function() return {
		["At 50 any Alliance hunter trainer offers it: {npc:5516} in {zone:1453}'s {object:28027}, {npc:5116} in {zone:1455}'s {object:32390} or Dorion in {zone:1457}' Cenarion Enclave."] = "No nível 50, qualquer instrutor de caçador da Aliança a oferece: {npc:5516} no {object:28027} de {zone:1453}, {npc:5116} no {object:32390} de {zone:1455} ou Dorion no Enclave Cenariano de {zone:1457}.",
		["At 50 any Horde hunter trainer offers it: {npc:3352} in {zone:1454}'s {object:172958} or {npc:3039} on {area:1641} in {zone:1456}."] = "No nível 50, qualquer instrutor de caçador da Horda a oferece: {npc:3352} no {object:172958} de {zone:1454} ou {npc:3039} no {area:1641} em {zone:1456}.",
		["Experience"] = "Experiência",
		["Experience at 50 through {zone:1447} and the {area:1417}; Forever removed the Classic item choice."] = "Experiência no nível 50 por {zone:1447} e o {area:1417}; o Forever removeu a escolha de item do Classic.",
		["Morphaz in the {area:1417}"] = "Morphaz no {area:1417}",
		["Morphaz is an elite dragon boss inside the {area:1417}, a five-player dungeon: bring a group. The temple stands in the middle of the {area:74}; swim down into it to reach the entrance. Horde: fly to {area:75}; Alliance: fly to {area:42} or {area:1438} and ride on."] = "Morphaz é um chefe dragão de elite dentro do {area:1417}, uma masmorra de cinco jogadores: leve um grupo. O templo fica no meio do {area:74}; mergulhe nele para chegar à entrada. Horda: voe até {area:75}; Aliança: voe até {area:42} ou {area:1438} e siga cavalgando.",
		["Mosshoof Coursers graze all over {zone:1447}; one in a dozen or so drops a pair of Perfect Courser Antlers."] = "Ginetes Cascomusgo pastam por todo {zone:1447}; mais ou menos um em cada doze deixa cair um par de Galhadas Perfeitas de Ginete.",
		["Wavethrashers crawl along {zone:1447}'s coasts: Young Wavethrashers on the north-east shore and Wavethrashers on the east coast drop the scales about twice as often as the Great Wavethrashers of the south shore."] = "Fura-ondas rastejam pelas costas de {zone:1447}: Jovens Fura-ondas na margem nordeste e Fura-ondas na costa leste deixam cair as escamas cerca de duas vezes mais que os Grandes Fura-ondas da margem sul.",
		["{item:20019}, inside the {area:1417}"] = "{item:20019}, dentro do {area:1417}",
		["{npc:8405} lives atop the cliffs north-east of the {area:1221}. Alliance: fly to {area:3137}; Horde: fly to {area:1237}."] = "{npc:8405} vive no alto dos penhascos a nordeste das {area:1221}. Aliança: voe até o {area:3137}; Horda: voe até {area:1237}.",
		["{quest:8151} (Alliance)"] = "{quest:8151} (Aliança)",
		["{quest:8151} (Horde)"] = "{quest:8151} (Horda)",
} end)()
t.guides["forever/class/mage/arcane-refreshment"] = (function() return {
		["Back to Lydros"] = "De volta a Lydros",
		["Fly to Feathermoon (Alliance) or {area:1099} (Horde) and ride to {area:2577} in central {zone:1444}. {npc:14368} waits in the Athenaeum, the library, reached through the West wing (or the North wing with a {item:18249})."] = "Voe para o Domínio de Plumaluna (Aliança) ou {area:1099} (Horda) e cavalgue até {area:2577}, no centro de {zone:1444}. {npc:14368} espera no Ateneu, a biblioteca, alcançado pela ala Oeste (ou pela ala Norte com uma {item:18249}).",
		["Hydrospawn"] = "Rebentágua",
		["Hydrospawn, a water elemental, lives in the Warpwood Quarter (Dire Maul East): chase the imp Pusillin until he turns to fight, clear the satyr room, then take the spiral ramp down to the pool."] = "Rebentágua, um elemental da água, vive no Warpwood Quarter (Gládio Cruel Leste): persiga o diabrete Pusillin até ele se virar para lutar, limpe a sala dos sátiros e desça a rampa em espiral até o lago.",
		["Shen'dralar reputation"] = "Reputação com os Shen'dralar",
		["The level 60 {spell:10140}, from a {area:2577} library: drink for you and your group."] = "{spell:10140} de nível 60, de uma biblioteca de {area:2577}: bebida para você e seu grupo.",
		["{item:18299}: Hydrospawn"] = "{item:18299}: Rebentágua",
} end)()
t.guides["forever/class/mage/astral-knot-garment"] = (function() return {
		["A robe or a blouse for Human and Gnome mages in their late 20s."] = "Um manto ou uma blusa para magos humanos e gnomos perto do nível 30.",
		["Back to Andromath"] = "Volte a Andromath",
		["Carrion Recluses"] = "Reclusas Carniceiras",
		["Carrion Recluses lurk in the woods of western {zone:1431} and each one drops the silk. The Black Widow Hatchlings further east drop it now and then."] = "As Reclusas Carniceiras espreitam nos bosques do oeste de {zone:1431}, e todas soltam a seda. Os Filhotes de Viúva Negra mais a leste a soltam de vez em quando.",
		["Ride east through {zone:1429} into Redridge. The fallen mage's tower of Ilgalar stands in the east of the zone; the treatise is in his library."] = "Cavalgue para o leste por {zone:1429} até as Montanhas Cristarrubra. A torre de Ilgalar, o mago caído, fica no leste da zona; o tratado está na biblioteca dele.",
		["The {area:96}"] = "{area:96}",
		["{npc:1309} works at {object:23296} in the {object:2101}."] = "{npc:1309} trabalha em {object:23296}, no {object:2101}.",
		["{npc:5144} teaches mages in {zone:1455}'s {object:32362}. Take the {area:2257} from {object:171524} to {zone:1453} afterwards."] = "{npc:5144} treina magos na {object:32362} de {zone:1455}. Depois, pegue o {area:2257} em {object:171524} até {zone:1453}.",
		["{npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}."] = "{npc:5497} fica no Sacrário dos Teurgos, a torre do {object:2101}.",
		["{quest:1939} is in the Wizard's Sanctum too."] = "{quest:1939} também fica no Sacrário dos Teurgos.",
} end)()
t.guides["forever/class/mage/celestial-orb"] = (function() return {
		["An off-hand orb or a staff for the late 30s, your pick."] = "Um orbe de mão secundária ou um cajado para o fim dos 30, à sua escolha.",
		["Back to {npc:6546}. She opens a mana rift beside her cottage: kill twelve {quest:1957} within ten minutes."] = "De volta a {npc:6546}. Ela abre uma fenda de mana ao lado da cabana: mate doze {quest:1957} em dez minutos.",
		["The Burning Blade Summoners work the {area:602} in southern {zone:1443}; any of them carries an {item:7291}."] = "Os Evocadores da Lâmina Ardente trabalham no {area:602}, no sul de {zone:1443}; qualquer um deles leva um {item:7291}.",
		["{area:1517} is a dungeon in the northern {zone:1418}, by the {object:178824}: a group of five. Defeat the {npc:7023} inside for its power source."] = "{area:1517} é uma masmorra no norte de {zone:1418}, junto à {object:178824}: um grupo de cinco. Derrote o {npc:7023} lá dentro para pegar a fonte de energia dele.",
		["{item:7515} and Stave"] = "{item:7515} e Báculo",
		["{npc:5497} in the Wizard's Sanctum, {zone:1453}'s {object:2101}, sends you back to {npc:6546}; Bink in {zone:1455} gives the same quest."] = "{npc:5497}, na torre do {object:2101} de {zone:1453}, manda você de volta a {npc:6546}; Bink em {zone:1455} dá a mesma missão.",
		["{npc:5885}, one of {zone:1454}'s mage trainers, sends you back to {npc:6546}; {npc:4568} in the {zone:1458} and {npc:3048} in {zone:1456} give the same quest."] = "{npc:5885}, um dos instrutores de mago de {zone:1454}, manda você de volta a {npc:6546}; {npc:4568} em {zone:1458} e {npc:3048} em {zone:1456} dão a mesma missão.",
		["{npc:6546} draws the demon out of the orb beside her cottage. The {npc:6549} is elite: grouping up is advised. You have three minutes before it slips back into the orb."] = "{npc:6546} tira o demônio do orbe ao lado da cabana dela. O {npc:6549} é elite: é recomendado formar grupo. Você tem três minutos antes que ele volte para o orbe.",
		["{npc:6546}'s cottage is deep in the marsh west of Theramore, just north of the {area:508}."] = "A cabana de {npc:6546} fica no fundo do pântano a oeste de Theramore, logo ao norte das {area:508}.",
} end)()
t.guides["forever/class/mage/destroy-morphaz"] = (function() return {
		["Back to {npc:8395} and up to the tower."] = "Volte a {npc:8395} e suba à torre.",
		["Back to {npc:8395}, who teleports you up to the tower."] = "Volte a {npc:8395}, que teleporta você até a torre.",
		["Back to {zone:1447}, {npc:8395} and the tower."] = "De volta a {zone:1447}, a {npc:8395} e à torre.",
		["Experience"] = "Experiência",
		["Experience at 50 through {zone:1447} and the {area:1417}; Forever removed the Classic item choice."] = "Experiência no nível 50 por {zone:1447} e pelo {area:1417}; o Forever removeu a escolha de item do Clássico.",
		["Fly to {area:3137} (Alliance) or {area:1237} (Horde). {npc:8395} camps below his master's tower: from the fork of {zone:1447}'s main road at the {area:1221}, head straight north to the cliffs. He teleports you up to {npc:8379}."] = "Voe até {area:3137} (Aliança) ou {area:1237} (Horda). {npc:8395} acampa ao pé da torre do seu mestre: da bifurcação da estrada principal de {zone:1447} nas {area:1221}, siga direto para o norte até os penhascos. Ele teleporta você até {npc:8379}.",
		["Morphaz"] = "Morphaz",
		["Morphaz, a green drake, waits deep in the {area:1477}, the {area:1417} in the {area:74}: a group of five, level 50-54. Kill him for the {item:20085}."] = "Morphaz, um draco verde, espera no fundo do {area:1477}, o {area:1417}, no {area:74}: grupo de cinco, nível 50-54. Mate-o para obter o {item:20085}.",
		["The Spitelash Sirens walk the ruins and beaches around the {area:1221} and the bay; they carry the coral."] = "As Sirenas Iralisca andam pelas ruínas e praias em volta das {area:1221} e da baía; elas carregam o coral.",
		["The blood elves camp along the cliffs of north-eastern {zone:1447}; Blood Elf Surveyors and Reclaimers drop the dust."] = "Os elfos sangrentos acampam ao longo dos penhascos do nordeste de {zone:1447}; Topógrafos e Recuperadores Sanguinélficos deixam cair o pó.",
		["The {item:20085}"] = "O {item:20085}",
		["{item:20085}: Morphaz"] = "{item:20085}: Morphaz",
		["{npc:331}, the Master Mage, stands in the Wizard's Sanctum in {zone:1453}'s {object:2101}; Dink in {zone:1455} gives the same quest."] = "{npc:331}, o Mestre Mago, fica no Santuário do Mago, no {object:2101} de {zone:1453}; Dink, em {zone:1455}, dá a mesma missão.",
		["{npc:7311}, one of {zone:1454}'s mage trainers, gives it; so do {npc:4567} in the {zone:1458} and {npc:3047} in {zone:1456}."] = "{npc:7311}, um dos instrutores de magos de {zone:1454}, dá a missão; {npc:4567}, em {zone:1458}, e {npc:3047}, em {zone:1456}, também.",
		["{npc:8379} again"] = "{npc:8379} de novo",
		["{npc:8379}, in the tower"] = "{npc:8379}, na torre",
} end)()
t.guides["forever/class/mage/ju-ju-heaps"] = (function() return {
		["A staff or an orb at 10 for Horde mages, worth a short trip back to the {area:368}."] = "Um cajado ou um orbe no nível 10 para magos da Horda; vale uma viagem curta de volta às {area:368}.",
		["Back to Un'thuwa"] = "Volte a Un'Thuwa",
		["The {quest:1884}"] = "{quest:1884}",
		["Un'thuwa"] = "Un'Thuwa",
		["Un'thuwa stands in {area:367}, on the {zone:1411} coast south of {area:362}."] = "Un'Thuwa fica em {area:367}, no litoral de {zone:1411}, ao sul de {area:362}.",
		["Wade across to the {area:368}, south-east of Sen'jin. Zalazane placed the heaps among his huts on the main isle: click a heap to destroy it."] = "Atravesse a vau até as {area:368}, a sudeste da Aldeia Sen'jin. Zalazane pôs os montes entre suas cabanas na ilha principal: clique num monte para destruí-lo.",
} end)()
t.guides["forever/class/mage/mages-wand"] = (function() return {
		["\"Plucky\" Johnson"] = "Johnson \"Depenado\"",
		["A wand of your school for the 30s: frost, arcane or fire."] = "Uma varinha da sua escola para os níveis 30: gelo, arcano ou fogo.",
		["Back to {npc:6546}"] = "De volta a {npc:6546}",
		["The Witherbark trolls hold south-eastern {zone:1417}; every one of them can drop a {item:7273}. Then take the ten sticks north-west to the binding circle where they become the {item:7272}. {npc:6546} also wants a {item:1529}: buy one at an Auction House on the way; miners sometimes find one in Tin Veins."] = "Os trolls Cascasseca dominam o sudeste de {zone:1417}; qualquer um deles pode deixar cair uma {item:7273}. Depois leve as dez varas para noroeste até o círculo de vinculação, onde elas viram o {item:7272}. {npc:6546} também quer um {item:1529}: compre um numa Casa de Leilões no caminho; mineradores às vezes acham um em Veios de Estanho.",
		["Tirth sold the book to the Scarlet Brotherhood. The {area:796} stands in north-eastern {zone:1420}; take the Library wing. The book juts out of the wall on the left as you enter the Athenaeum, before {npc:6487}."] = "Tirth vendeu o livro à Cruzada Escarlate. O {area:796} fica no nordeste de {zone:1420}; entre na ala da Biblioteca. O livro se projeta da parede à esquerda ao entrar no Ateneu, antes de {npc:6487}.",
		["Tirth's apprentice is \"Plucky\" Johnson, a small grey chicken by the race track. Target him and type /beckon: he turns human for a moment, long enough to talk to him."] = "O aprendiz de Tirth é Johnson \"Depenado\", uma galinha cinzenta junto à pista de corrida. Selecione-o e digite /chamar: ele vira humano por um instante, tempo suficiente para falar com ele.",
		["Witherbark trolls"] = "Trolls Cascasseca",
		["{npc:5497} in the Wizard's Sanctum, {zone:1453}'s {object:2101}, sends you to {npc:6546}; Bink in {zone:1455} gives the same quest."] = "{npc:5497}, no Santuário do Mago do {object:2101} de {zone:1453}, envia você a {npc:6546}; Bink, em {zone:1455}, dá a mesma missão.",
		["{npc:5885}, one of {zone:1454}'s mage trainers, sends you to {npc:6546}; {npc:4568} in the {zone:1458} and {npc:3048} in {zone:1456} give the same quest."] = "{npc:5885}, um dos instrutores de magos de {zone:1454}, envia você a {npc:6546}; {npc:4568}, em {zone:1458}, e {npc:3048}, em {zone:1456}, dão a mesma missão.",
		["{npc:6546}'s ritual"] = "O ritual de {npc:6546}",
		["{npc:6546}, a hermit, lives in a cottage deep in the marsh west of Theramore, just north of the {area:508}."] = "{npc:6546}, uma eremita, mora num chalé no fundo do pântano a oeste de Theramore, logo ao norte das {area:508}.",
		["{npc:6548} spends his days at the race track in the {area:439}, south-east {zone:1441}."] = "{npc:6548} passa os dias na pista de corrida em {area:439}, no sudeste de {zone:1441}.",
		["{quest:1951}: Scarlet Monastery Library"] = "{quest:1951}: Biblioteca do Monastério Escarlate",
} end)()
t.guides["forever/class/mage/manaweave-robe"] = (function() return {
		["A robe at 15 for Alliance mages, from {zone:1453} and {zone:1432}."] = "Um manto no nível 15 para magos da Aliança, em {zone:1453} e {zone:1432}.",
		["Back to {npc:5497}"] = "Volte a {npc:5497}",
		["Back to {zone:1453} by the tram. {npc:1309} works at {object:23296} in the {object:2101}."] = "Volte a {zone:1453} pelo metrô. {npc:1309} trabalha em {object:23296}, no {object:2101}.",
		["Humanoids drop {item:2589}; the Auction House in the {object:2096} sells it."] = "Humanoides soltam {item:2589}; a Casa de Leilões do {object:2096} também vende.",
		["Take the {area:2257} to {zone:1455}, then the road east through the South Gate tunnel into {zone:1432}. The dwarven miners' league left the crates in the {area:149} at the north end of the loch; Tunnel Rat troggs hold the mine."] = "Pegue o {area:2257} até {zone:1455} e siga a estrada para o leste pelo túnel do Portão Sul até {zone:1432}. A liga de mineiros anões deixou os caixotes na {area:149}, no norte do lago; troggs Rato-de-túnel ocupam a mina.",
		["The {area:149}"] = "{area:149}",
		["{npc:328} is the {area:87} mage trainer."] = "{npc:328} é o instrutor de magos de {area:87}.",
		["{npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}. The {item:7247} and the {item:7308} lie behind her."] = "{npc:5497} fica no Sacrário dos Teurgos, a torre do {object:2101}. O {item:7247} e a {item:7308} estão atrás dela.",
		["{npc:7312} teaches mages in {zone:1455}'s {object:32362}. Take the {area:2257} from {object:171524} to {zone:1453} afterwards."] = "{npc:7312} treina magos na {object:32362} de {zone:1455}. Depois, pegue o {area:2257} em {object:171524} até {zone:1453}.",
		["{object:2169} is the tavern in the {object:2101}. Use the {item:7308} inside to make the {npc:6492} visible, subdue one with your spells, then use the {item:7247} to throw down a coffer and capture it."] = "{object:2169} é a taverna do {object:2101}. Use a {item:7308} lá dentro para tornar visível a {npc:6492}, domine uma com seus feitiços e use o {item:7247} para lançar um cofre e capturá-la.",
} end)()
t.guides["forever/class/mage/nether-lace-garment"] = (function() return {
		["A robe or a tunic for Undead and Troll mages in their late 20s."] = "Uma veste ou túnica para magos Mortos-vivos e Trolls no fim dos níveis 20.",
		["Back to {npc:5885}"] = "De volta a {npc:5885}",
		["Satyrs hold the ruins of {area:429} in eastern {zone:1440}. {spell:9052} at the bottom of the highest waterfall."] = "Sátiros dominam as ruínas de {area:429}, no leste de {zone:1440}. {spell:9052} no pé da cachoeira mais alta.",
		["Take the zeppelin to {zone:1454}. {npc:5885} is one of {zone:1454}'s mage trainers."] = "Pegue o zepelim para {zone:1454}. {npc:5885} é um dos instrutores de magos de {zone:1454}.",
		["The {object:174797}"] = "A {object:174797}",
		["The {quest:1945}"] = "As {quest:1945}",
		["The {quest:1945}, dryads, gather near the {area:426} in central {zone:1440}."] = "As {quest:1945}, dríades, se reúnem perto do {area:426}, no centro de {zone:1440}.",
		["{npc:3484}, a troll tailor, works at the {area:380}."] = "{npc:3484}, uma alfaiate troll, trabalha na {area:380}.",
