} end)()
t.guides["forever/class/mage/polymorph-pig"] = (function() return {
		["A new look for {spell:118}: it turns the target into a pig rather than a sheep."] = "Um novo visual para {spell:118}: transforma o alvo em porco em vez de ovelha.",
		["Back to {npc:8395} and up to the tower."] = "Volte a {npc:8395} e suba à torre.",
		["Carry the {item:23250} back to the {area:1221}. Polymorph a Spitelash naga and wait a few seconds: it splits into small Polymorph Clones. Kill the clones quickly; the shell collects their essence."] = "Leve a {item:23250} de volta para {area:1221}. Use Polimorfia numa naga Iralisca e espere alguns segundos: ela se divide em pequenos Clones Polimorfados. Mate os clones rápido; a concha coleta a essência deles.",
		["Fly to {area:3137} (Alliance) or {area:1237} (Horde). {npc:8395} camps below {npc:8379}'s tower: from the fork of {zone:1447}'s main road at the {area:1221}, head straight north to the cliffs. He teleports you up to the Archmage."] = "Voe até {area:3137} (Aliança) ou {area:1237} (Horda). {npc:8395} acampa ao pé da torre de {npc:8379}: da bifurcação da estrada principal de {zone:1447} nas {area:1221}, siga direto para o norte até os penhascos. Ele teleporta você até o Arquimago.",
		["Krellian hides behind his Spitelash guards in the {area:1223}, the biggest building in the middle of the {area:1221}. He drops the {item:23250}."] = "Krellian se esconde atrás dos guardas Iralisca no {area:1223}, o maior edifício no meio das {area:1221}. Ele deixa cair a {item:23250}.",
		["Polymorph Clones"] = "Clones Polimorfados",
		["{npc:8379}: {spell:118} (pig)"] = "{npc:8379}: {spell:118} (porco)",
} end)()
t.guides["forever/class/mage/spellfire-robes"] = (function() return {
		["A robe at 15 for Horde mages, from the {zone:1458} and {zone:1421}."] = "Uma toga no nível 15 para magos da Horda, de {zone:1458} e {zone:1421}.",
		["Algernon's alchemist shop is in the Apothecarium. Use the {item:7308} there to make the {npc:6492} visible, subdue one with your spells, then use the {item:7247} to throw down a coffer and capture it."] = "A loja de alquimia de Algernon fica no Apothecarium. Use a {item:7308} lá para tornar o {npc:6492} visível, subjugue um com seus feitiços e depois use o {item:7247} para lançar um cofre e capturá-lo.",
		["Back to the {zone:1458}. {npc:4576}, {npc:11048} and {npc:11049} keep the tailor's shop."] = "De volta a {zone:1458}. {npc:4576}, {npc:11048} e {npc:11049} cuidam da loja do alfaiate.",
		["Back to {npc:4568}"] = "De volta a {npc:4568}",
		["Humanoids drop {item:2589}; the Undercity Auction House sells it."] = "Humanoides deixam cair {item:2589}; a Casa de Leilões da Cidade Baixa vende.",
		["Leave the {zone:1458} and follow the road south through {zone:1421}. The {area:279} mages hold {area:233}, south-east of the {area:228}; every {npc:1867}, Mage, Protector, Warder, Conjuror, Watcher and Wizard can drop a {item:7293}."] = "Saia de {zone:1458} e siga a estrada para o sul por {zone:1421}. Os magos de {area:279} ocupam {area:233}, a sudeste do {area:228}; todo {npc:1867}, Mago, Protetora, Guardião, Conjurador, Vigia e Teurgo pode deixar cair uma {item:7293}.",
		["The alchemist shop"] = "A loja do alquimista",
		["{npc:2128} is the {area:159} mage trainer."] = "{npc:2128} é o instrutor de mago de {area:159}.",
		["{npc:4568} stands in the {object:36082}. The {item:7247} and the {item:7308} lie behind her."] = "{npc:4568} fica no {object:36082}. O {item:7247} e a {item:7308} ficam atrás dela.",
		["{npc:7311} is one of {zone:1454}'s mage trainers. Then take the zeppelin to {zone:1420} from the tower outside {zone:1454}'s main gate."] = "{npc:7311} é um dos instrutores de mago de {zone:1454}. Depois pegue o zepelim para {zone:1420} na torre do lado de fora do portão principal de {zone:1454}.",
} end)()
t.guides["forever/class/paladin/cloak-of-the-divine-storm"] = (function() return {
		["A rare cloak at 30 from the old {spell:407778} story; for now only Alliance paladins can finish it."] = "Um manto raro no nível 30, da antiga história de {spell:407778}; por enquanto só paladinos da Aliança podem concluí-la.",
		["Back to {area:413}."] = "De volta a {area:413}.",
		["Back to {npc:5495}"] = "De volta a {npc:5495}",
		["Blackrock Summoners, Champions and Trackers camp in the north-west of Redridge; they drop the {item:209778}."] = "Evocadores, Campeões e Rastreadores Rocha Negra acampam no noroeste das Montanhas Cristarrubra; eles deixam cair o {item:209778}.",
		["Climb to the top of the {area:444} in northern {zone:1439}. Loot the Strange Orb up there: it gives you the Althalaxx Orb, which starts the quest."] = "Suba ao topo da {area:444}, no norte de {zone:1439}. Saqueie o Orbe Estranho lá em cima: ele dá o Orbe de Althalaxx, que inicia a missão.",
		["Katherine sends you to the warlocks in the {object:2101}; {npc:5495} speaks for them."] = "Katherine manda você aos bruxos no {object:2101}; {npc:5495} fala por eles.",
		["Motes of Mannoroth"] = "Partículas de Mannoroth",
		["Strange Orb atop the {area:444}: right-click the Althalaxx Orb it gives"] = "Orbe Estranho no topo da {area:444}: clique com o botão direito no Orbe de Althalaxx que ele dá",
		["The Strange Orb"] = "O Orbe Estranho",
		["The {object:409311}"] = "A {object:409311}",
		["The {object:409311} stands at the east end of {area:435}. Shatter the orb on it; the {object:409315} appears beside it."] = "A {object:409311} fica na ponta leste de {area:435}. Use Estilhaçar no orbe dela; o {object:409315} aparece ao lado.",
		["from the {object:409315}"] = "do {object:409315}",
		["{area:435} is in south-east {zone:1440}. The Mannoroc Lashers, Searing Infernals, Felguards and Legion Hounds in it drop the Motes of Mannoroth."] = "{area:435} fica no sudeste de {zone:1440}. As Açoitadeiras Mannoroc, Infernais Abrasadores, Guardas Vis e Farejadores Legionários de lá deixam cair as Partículas de Mannoroth.",
		["{npc:3663} stands at {area:413} in western {zone:1440}."] = "{npc:3663} fica em {area:413}, no oeste de {zone:1440}.",
