t.guides["forever/class/paladin/lumina-windsinger"] = (function() return {
		["Back to the {area:228}"] = "De volta ao {area:228}",
		["Free her with the key, then stay close while she fights her way out of the keep."] = "Liberte-a com a chave e fique perto enquanto ela abre caminho para fora da fortaleza.",
		["Free {npc:248755}"] = "Liberte {npc:248755}",
		["No item yet: a Forsaken paladin rescue story; its sequel, the {item:268484}, cannot be finished yet."] = "Ainda sem item: uma história de resgate de paladino Renegado; a continuação, a {item:268484}, ainda não pode ser concluída.",
		["Once she is clear of {area:235}, {npc:259620} waits for you in the {area:228}. Speak with her again to hear what really happened on the road."] = "Assim que sair de {area:235}, {npc:259620} espera você no {area:228}. Fale com ela de novo para saber o que realmente aconteceu na estrada.",
		["Rescuing {quest:91862}"] = "Resgatando {quest:91862}",
		["Ride south through {zone:1421} to the {area:228}. {npc:248840} stands in the town; {npc:259611} keeps watch near its entrance."] = "Siga para o sul por {zone:1421} até o {area:228}. {npc:248840} fica na cidade; {npc:259611} vigia perto da entrada.",
		["The pyre on {area:172}"] = "A pira em {area:172}",
		["from the {object:566037}"] = "dos {object:566037}",
		["{area:172} lies in the lake east of the {area:228}. The charred remains are on its shore."] = "{area:172} fica no lago a leste do {area:228}. Os restos carbonizados estão na margem.",
		["{item:267412}, from the Rot Hide gnolls"] = "{item:267412}, dos Gnolls Putricouro",
		["{npc:246378} leads the Paladins of Tyr's Watch from inside {area:16602}, on the bluffs north-west of the {area:156}."] = "{npc:246378} lidera os Paladinos da Vigília de Tyr de dentro de {area:16602}, nos penhascos a noroeste de {area:156}.",
		["{npc:259620}, the {area:228}"] = "{npc:259620}, {area:228}",
		["{quest:91862} is caged inside {area:235}, at the north end of the isle. The Rot Hide gnolls around her carry the key."] = "{quest:91862} está presa numa jaula dentro de {area:235}, no extremo norte da ilha. Os Gnolls Putricouro em volta dela carregam a chave.",
		["{zone:1458} and Earthen Ring reputation"] = "Reputação com {zone:1458} e Harmonia Telúrica",
} end)()
t.guides["forever/class/paladin/tyrs-watch"] = (function() return {
		["Back to the keep"] = "Volte à fortaleza",
		["Back to {area:16602}. {npc:246378} gives you the {item:6866}; {npc:257655} waits downstairs in the keep."] = "Volte a {area:16602}. {npc:246378} lhe dá o {item:6866}; {npc:257655} espera no andar de baixo da fortaleza.",
		["Back to {area:16602}: Billmuth takes the plans, {npc:246378} teaches you {spell:7328}."] = "Volte a {area:16602}: Billmuth fica com os planos, {npc:246378} lhe ensina {spell:7328}.",
		["Tarnished Drudges"] = "Labutadores Manchados",
		["Tarnished Zealots"] = "Zelotes Manchados",
		["The Scarlet Crusaders camped around {area:812} carry the attack plans."] = "Os Cruzados Escarlates acampados em volta de {area:812} carregam os planos de ataque.",
		["The Scarlet attack plans"] = "Os planos de ataque Escarlates",
		["The Vile Fin murlocs lurk on the bluffs along the road east of the keep and in the camps around the lake to the west."] = "Os murlocs Pinavil espreitam nos penhascos ao longo da estrada a leste da fortaleza e nos acampamentos em volta do lago a oeste.",
		["The {item:6866}"] = "{item:6866}",
		["Tyr's Watch and {spell:7328}"] = "Tyr's Watch e {spell:7328}",
		["Vile Fin Attackers"] = "Atacantes Pinavil",
		["Vile Fin Seers"] = "Videntes Pinavil",
		["Walk south from {area:159} to the {area:153} and down into the {zone:1458}. {npc:10181} holds court in the {object:36126}; {npc:257648} begs in the {object:36078}."] = "Ande para o sul de {area:159} até as {area:153} e desça até a {zone:1458}. {npc:10181} reina no {object:36126}; {npc:257648} mendiga no {object:36078}.",
		["{area:16602} stands on the bluffs north-west of the {area:156}. {npc:246349} waits at the gate."] = "{area:16602} fica nos penhascos a noroeste de {area:156}. {npc:246349} espera no portão.",
		["{area:812} is at the far east end of the glades. Use the {item:6866} on {npc:257663}, then speak to him. If you lose the symbol, {npc:246378} gives you another."] = "{area:812} fica no extremo leste das clareiras. Use o {item:6866} em {npc:257663} e fale com ele. Se perder o símbolo, {npc:246378} lhe dá outro.",
		["{npc:246152}, who trains Paladins in {area:159}, sends you to the order's keep on the west coast."] = "{npc:246152}, que treina paladinos em {area:159}, envia você à fortaleza da ordem no litoral oeste.",
		["{npc:246378} leads the order from inside the keep; {npc:246393} stands beside it."] = "{npc:246378} lidera a ordem de dentro da fortaleza; {npc:246393} fica ao lado dela.",
		["{npc:246378} offers the first Lesson in Divinity at level 12."] = "{npc:246378} oferece a primeira missão Uma lição de divindade no nível 12.",
		["{npc:257648} needs 10 {item:2589}. Scarlet Zealots and Scarlet Friars drop it about three times in ten; bring it along if you already carry some."] = "{npc:257648} precisa de 10 {item:2589}. Zelotes Escarlates e Frades Escarlates soltam cerca de três vezes em dez; traga se já tiver.",
		["{object:554626}, in the root cellar"] = "{object:554626}, no porão",
		["{quest:91317} hold the ruined village of {area:16881} in the {area:16616}, south-west of the keep. The {item:246213} is piled in the root cellar of one of its houses; Commander {npc:259431} walks among his Tarnished."] = "{quest:91317} ocupam a aldeia em ruínas de {area:16881}, em {area:16616}, a sudoeste da fortaleza. A {item:246213} está empilhada no porão de uma das casas; o comandante {npc:259431} anda entre seus Manchados.",
		["{spell:7328} to raise fallen allies, plus a weapon and a shield for a new Forsaken paladin."] = "{spell:7328} para reerguer aliados caídos, além de uma arma e um escudo para um novo paladino Renegado.",
} end)()
t.guides["forever/class/paladin/verigans-fist"] = (function() return {
		["At 20 {npc:6179} in the {object:32362} gives you the {item:6776}; it sends you to {npc:6171} in {zone:1453}'s Cathedral of Light. Take the tram from {zone:1455} to {zone:1453}."] = "No nível 20, {npc:6179} na {object:32362} lhe dá o {item:6776}; ele manda você a {npc:6171} na Catedral da Luz de {zone:1453}. Pegue o metrô de {zone:1455} até {zone:1453}.",
		["Back to {npc:3649} in {area:442}: he purifies the gem."] = "De volta a {npc:3649} em {area:442}: ele purifica a gema.",
		["Back to {npc:6241}"] = "De volta a {npc:6241}",
		["Bring the four parts to {npc:6181} outside {zone:1455}."] = "Leve as quatro partes a {npc:6181}, do lado de fora de {zone:1455}.",
		["Goblin Woodcarvers, inside"] = "Goblins Entalhadores, lá dentro",
		["Protect {npc:6182}"] = "Proteja {npc:6182}",
		["The Alliance paladin's rare two-handed mace for the 20s, with a shield on the way."] = "A maça de duas mãos rara do paladino da Aliança para os 20, com um escudo no caminho.",
		["The Blackfathom naga by the entrance of {area:2797} on {zone:1440}'s north-west coast drop the {item:6995}. They are elite: grouping up is advised."] = "Os nagas das Profundezas Negras junto à entrada das {area:2797}, na costa noroeste de {zone:1440}, deixam cair a {item:6995}. Eles são elite: é recomendado formar grupo.",
		["The ore crate lies by the trees in the middle of the Mo'grosh ogre camp in north-east {zone:1432}. The Mo'grosh ogres are elite: grouping up is advised."] = "O caixote de minério fica junto às árvores no meio do acampamento dos ogros Mo'grosh, no nordeste de {zone:1432}. Os ogros Mo'grosh são elite: é recomendado formar grupo.",
		["The {item:6995}"] = "A {item:6995}",
		["The {item:7083}"] = "A {item:7083}",
		["from the {item:6776}"] = "do {item:6776}",
		["{area:1581} is a group of five under {area:20}; the instance portal is inside the {area:20} mine. The Goblin Woodcarvers in the Mast Room, with Sneed, drop the lumber."] = "{area:1581} é para um grupo de cinco, embaixo de {area:20}; o portal da instância fica dentro da mina de {area:20}. Os Goblins Entalhadores na sala do mastro, com Sneed, deixam cair a madeira.",
		["{area:1581}, in the {area:20} mine"] = "{area:1581}, na mina de {area:20}",
		["{area:236} is a level 20-30 dungeon in southern {zone:1421}. The hammer lies on a box inside the stables, at the far end of the courtyard before the ramp up."] = "{area:236} é uma masmorra de nível 20-30 no sul de {zone:1421}. O martelo está numa caixa dentro dos estábulos, no fundo do pátio, antes da rampa.",
		["{npc:3649} is in {area:442}."] = "{npc:3649} está em {area:442}.",
		["{npc:6171} stands in the Cathedral of Light. Right-click the {item:6776} to start its quest."] = "{npc:6171} fica na Catedral da Luz. Clique com o botão direito no {item:6776} para iniciar a missão dele.",
		["{npc:6181} stands outside the gates of {zone:1455}. He gives you {item:6996}, which list the four parts."] = "{npc:6181} fica do lado de fora dos portões de {zone:1455}. Ele lhe dá as {item:6996}, que listam as quatro partes.",
		["{npc:6182}'s farmhouse stands on the south-west coast of {zone:1436}. Waves of Defias attack it during her quest: keep her alive, and heal her if she needs it."] = "A casa da fazenda de {npc:6182} fica na costa sudoeste de {zone:1436}. Ondas de Défias a atacam durante a missão dela: mantenha-a viva e cure-a se precisar.",
		["{npc:6241} is in {area:144}."] = "{npc:6241} está em {area:144}.",
		["{npc:6241} turns the ore into {item:6993}."] = "{npc:6241} transforma o minério no {item:6993}.",
		["{object:91138}, inside"] = "{object:91138}, lá dentro",
		["{object:92420} crate"] = "Caixote de {object:92420}",
} end)()
t.guides["forever/class/priest/benediction"] = (function() return {
		["Equip {item:18646} to see {npc:14494}, a ghost on the mountainside in the north-west of the {zone:1423}. Come with full mana, Major Mana Potions and {item:8956}: if you fail, the event takes about two hours to return."] = "Equipe {item:18646} para ver {npc:14494}, um fantasma na encosta no noroeste de {zone:1423}. Venha com mana cheia, Poções Elevadas de Mana e {item:8956}: se falhar, o evento leva umas duas horas para voltar.",
		["Save 50 peasants before 15 die. Kill the skeletons that attack them, cure their diseases (the purple ones first) and heal the wounded with {spell:139}. Friends may buff you beforehand but must stay out of the fight, or a demon appears and kills everyone."] = "Salve 50 camponeses antes que 15 morram. Mate os esqueletos que os atacam, cure as doenças deles (os roxos primeiro) e cure os feridos com {spell:139}. Amigos podem dar bônus antes, mas devem ficar fora da luta, ou um demônio aparece e mata todos.",
		["With both Eyes in your bags: {item:18608}"] = "Com os dois Olhos nas bolsas: {item:18608}",
		["You need {item:18646} first: it comes from the {object:179703} after {npc:12018} in {area:2717}. {item:18665} drops from elite demons ({npc:12397}, a world boss, always; Doomguard Commanders and Manahounds rarely); it binds when equipped, so buying one works too."] = "Primeiro você precisa de {item:18646}: vem do {object:179703} depois de {npc:12018} em {area:2717}. {item:18665} cai de demônios de elite ({npc:12397}, chefe mundial, sempre; Comandantes Demonarcas e Cães de Mana, raramente); vincula ao equipar, então comprar um também serve.",
		["{item:18608} and Anathema"] = "{item:18608} e Anátema",
		["{npc:14494}'s splinter and the two Eyes make {item:18608}, the epic priest staff that turns into Anathema."] = "A lasca de {npc:14494} e os dois Olhos formam {item:18608}, o cajado épico de sacerdote que se transforma em Anátema.",
} end)()
t.guides["forever/class/priest/blood-of-morphaz"] = (function() return {
		["Any undead can drop it. The {npc:7864} in the {area:1221}, below {npc:8405}'s cliffs, are the nearest; Highborne Apparitions and Lichlings haunt the ruins near {area:3137}."] = "Qualquer morto-vivo pode deixá-lo cair. Os {npc:7864} nas {area:1221}, abaixo dos penhascos de {npc:8405}, são os mais próximos; Aparições Altaneiras e Sub-liches Altaneiros assombram as ruínas perto de {area:3137}.",
		["At 50 {npc:5489} in {zone:1453}'s Cathedral of Light or {npc:11406} in {zone:1455}'s {object:32386} offers it."] = "No nível 50, {npc:5489}, na Catedral da Luz de {zone:1453}, ou {npc:11406}, no {object:32386} de {zone:1455}, oferece a missão.",
		["At 50 {npc:6018} in {zone:1454}'s {object:172961} offers it."] = "No nível 50, {npc:6018}, no {object:172961} de {zone:1454}, oferece a missão.",
		["Experience and gold"] = "Experiência e ouro",
		["Experience and gold at 50 through {zone:1447} and the {area:1417}; Forever removed the Classic item choice."] = "Experiência e ouro no nível 50 por {zone:1447} e pelo {area:1417}; o Forever removeu a escolha de item do Clássico.",
		["Morphaz in the {area:1417}"] = "Morphaz no {area:1417}",
		["Morphaz is an elite dragon boss inside the {area:1417}, a level 50 dungeon: bring a group of five. The temple stands in the middle of the {area:74}; swim down into it to reach the entrance. Horde: fly to {area:75}; Alliance: fly to {area:42} or {area:1438} and ride on."] = "Morphaz é um chefe dragão de Elite dentro do {area:1417}, uma Masmorra de nível 50: leve um grupo de cinco. O templo fica no meio do {area:74}; mergulhe para chegar à entrada. Horda: voe até {area:75}; Aliança: voe até {area:42} ou {area:1438} e siga montado.",
		["Mosshoof Coursers graze all over {zone:1447}; about one in three drops a {item:20027}."] = "Ginetes Cascomusgo pastam por toda {zone:1447}; cerca de um em cada três deixa cair uma {item:20027}.",
		["{npc:10922} is at the {area:2479} in southern {zone:1448}."] = "{npc:10922} está no {area:2479}, no sul de {zone:1448}.",
		["{npc:8405} lives atop the cliffs north-east of the {area:1221}. Alliance: fly to {area:3137}; Horde: fly to {area:1237}."] = "{npc:8405} mora no alto dos penhascos a nordeste das {area:1221}. Aliança: voe até {area:3137}; Horda: voe até {area:1237}.",
		["{quest:8254} (Alliance)"] = "{quest:8254} (Aliança)",
		["{quest:8254} (Horde)"] = "{quest:8254} (Horda)",
		["{quest:8257}: the {area:1417} entrance"] = "{quest:8257}: entrada do {area:1417}",
} end)()
t.guides["forever/class/priest/confounding-flash-and-contingency-plan"] = (function() return {
