t.guides["forever/class/rogue/certificate-of-thievery"] = (function() return {
		["At 16 {npc:1234} in the {area:2102} in {area:131} sends you to {npc:5165}, in the north of {zone:1455}."] = "No nível 16, {npc:1234}, na {area:2102} em {area:131}, envia você a {npc:5165}, no norte de {zone:1455}.",
		["At 16 {npc:3599} in {area:186} sends you to {quest:2259} in {zone:1457}."] = "No nível 16, {npc:3599}, em {area:186}, envia você a {quest:2259} em {zone:1457}.",
		["At 16 {npc:917}, the rogue trainer in the Lion's Pride Inn in {area:87}, sends you to {npc:6946} in {zone:1453}."] = "No nível 16, {npc:917}, o instrutor de ladinos na Estalagem Orgulho do Leão, em {area:87}, envia você a {npc:6946} em {zone:1453}.",
		["Back to {npc:6966}"] = "De volta a {npc:6966}",
		["Ride east through {zone:1429} into Redridge, or fly to {area:69}. {npc:6966} waits on the west side of {area:69} and gives you {item:5060}."] = "Siga para o leste por {zone:1429} até as Montanhas Cristarrubra, ou voe até {area:69}. {npc:6966} espera no lado oeste de {area:69} e dá a você {item:5060}.",
		["Your first lockpicking job at 16: {npc:6966}'s lockbox at {quest:2282}, for {quest:2300}."] = "Seu primeiro serviço de arrombamento no nível 16: o cofre de {npc:6966} em {quest:2282}, para a {quest:2300}.",
		["{npc:6946} stands beside {npc:332} at {quest:2300} in {object:2100}. Dwarves and Gnomes take the {area:2257} from {zone:1455}; Night Elves take the boat from {area:442} to {area:17203}."] = "{npc:6946} fica ao lado de {npc:332} na {quest:2300}, em {object:2100}. Anões e Gnomos pegam o {area:2257} em {zone:1455}; Elfos Noturnos pegam o Barco de {area:442} para {area:17203}.",
		["{quest:2282} stands east of {area:69}, up off the road. Open {object:121264} there."] = "{quest:2282} fica a leste de {area:69}, acima da estrada. Abra o {object:121264} lá.",
} end)()
t.guides["forever/class/rogue/plundering-the-plunderers"] = (function() return {
		["At 16 {npc:3170}, the rogue trainer in {area:362}, sends you to {npc:3401} in {zone:1454}."] = "No nível 16, {npc:3170}, o instrutor de ladinos em {area:362}, manda você até {npc:3401} em {zone:1454}.",
		["At 16 {npc:6467} in the {object:36073} sends you to {npc:3401} in {zone:1454}. Take {quest:1998} from him too; it is done in {zone:1421} at the end of this guide."] = "No nível 16, {npc:6467} no {object:36073} manda você até {npc:3401} em {zone:1454}. Pegue também {quest:1998} com ele; ela é feita em {zone:1421} no fim deste guia.",
		["Back to {npc:6467}"] = "De volta a {npc:6467}",
		["Back to {npc:7161}"] = "De volta a {npc:7161}",
		["Fly or ride to {area:392} on the {zone:1413} coast. {npc:7161} stands in town with his Gizmotronic Apparatus: buy an {item:7970} and {item:5060} from the apparatus before you go."] = "Voe ou cavalgue até {area:392}, no litoral dos {zone:1413}. {npc:7161} fica na cidade com seu Aparato Mercadotrônico: compre um {item:7970} e {item:5060} no aparato antes de ir.",
		["South along the coast from {area:392}, at the Southsea pirates' camp. If an unusually hostile parrot attacks you, use the {item:7970} on it (the quest's own advice)."] = "Ao sul pelo litoral a partir de {area:392}, no acampamento dos piratas dos Mares do Sul. Se um papagaio estranhamente hostil atacar você, use o {item:7970} nele (o conselho da própria missão).",
		["Take the zeppelin from {zone:1454} to the {zone:1458} and ride south into Silverpine. {quest:1998} stands north-east of the {area:228}."] = "Pegue o zepelim de {zone:1454} para {zone:1458} e cavalgue para o sul até a Floresta de Pinhaprata. {quest:1998} fica a nordeste de {area:228}.",
		["Ten {item:7676}, the rogue energy drink, from the Horde lockpicking jobs at 16."] = "Dez {item:7676}, a bebida de energia dos ladinos, dos trabalhos de arrombamento da Horda no nível 16.",
		["The Kirin Tor keep their reports at {area:233}, in south-east Silverpine: pick the lock on the {object:103815}."] = "O Kirin Tor guarda seus relatórios em {area:233}, no sudeste da Floresta de Pinhaprata: arrombe a fechadura do {object:103815}.",
		["Undead take the zeppelin from the towers outside the {zone:1458} to {zone:1411}. {npc:3401} and {quest:2379} stand in the {object:172960}, the canyon under the {object:172982}."] = "Mortos-vivos pegam o zepelim nas torres do lado de fora de {zone:1458} para {zone:1411}. {npc:3401} e {quest:2379} ficam na {object:172960}, o cânion abaixo do {object:172982}.",
		["{npc:3401} and {quest:2379}"] = "{npc:3401} e {quest:2379}",
		["{npc:7161}: ten {item:7676}"] = "{npc:7161}: dez {item:7676}",
} end)()
t.guides["forever/class/rogue/poisons-alliance"] = (function() return {
		["/lay down"] = "/lay down",
		["At 20 {npc:332} at SI:7 in {object:2100} sends you to {npc:7024} in {zone:1436}."] = "No nível 20, {npc:332} na AVIN, em {object:2100}, manda você até {npc:7024} em {zone:1436}.",
		["Back to {npc:7207}"] = "De volta a {npc:7207}",
		["Everything is in {zone:1453}: the Gumps sell {item:3421}, the {item:8431} lies in the city, and the nearest vendors sell a {item:3372} and a {item:4371}."] = "Está tudo em {zone:1453}: os Gump vendem {item:3421}, a {item:8431} está na cidade, e os vendedores mais próximos vendem um {item:3372} e um {item:4371}.",
		["Forever teaches {spell:2842} through this chain, not the trainer; the {item:7676} recipe comes with it."] = "O Forever ensina {spell:2842} por esta série, não pelo instrutor; a receita de {item:7676} vem junto.",
		["Ride north through Elwynn to {zone:1453}; Mathias Shaw is at SI:7 in {object:2100}."] = "Cavalgue para o norte pela Floresta de Elwynn até {zone:1453}; Mestre Mathias Shaw está na AVIN, em {object:2100}.",
		["The cure's ingredients"] = "Os ingredientes da cura",
		["{item:7908}, in the {object:123214}"] = "{item:7908}, no {object:123214}",
		["{npc:7024} watches {npc:7053}'s tower from the hills in the far east of {zone:1436}, by the {zone:1431} border. The {npc:7051} (level 23) guarding the tower carries its key; Klaven's journal is in the chest at the top."] = "{npc:7024} vigia a torre de {npc:7053} das colinas no extremo leste de {zone:1436}, junto à fronteira de {zone:1431}. O {npc:7051} (nível 23) que guarda a torre leva a chave dela; o diário de Filipe está no baú lá no alto.",
		["{npc:7207} works in the cellar of SI:7, the Barracks. Type /lay down beside him to be examined."] = "{npc:7207} trabalha no porão da AVIN, o Quartel. Digite /lay down ao lado dele para ser examinado.",
		["{spell:2842} (Alliance)"] = "{spell:2842} (Aliança)",
} end)()
t.guides["forever/class/rogue/poisons-horde"] = (function() return {
		["/salute {npc:3401}"] = "/saudar {npc:3401}",
		["At 20 {npc:3401} stands in the {object:172960}, the canyon under the {object:172982}. Target him and type /salute."] = "No nível 20, {npc:3401} fica na {object:172960}, o cânion abaixo do {object:172982}. Selecione-o e digite /saudar.",
		["Back to {npc:3401}"] = "De volta a {npc:3401}",
		["Fly back to {zone:1454}."] = "Voe de volta a {zone:1454}.",
		["Fly to the {area:380} and ride north to the Venture Co. tower north of the {area:382}. In sight of the tower, fire the {item:8051} twice, then /salute {npc:7233} before he attacks you."] = "Voe até a {area:380} e cavalgue para o norte até a torre da Empreendimentos S.A. ao norte do {area:382}. À vista da torre, dispare a {item:8051} duas vezes e depois faça /saudar para {npc:7233} antes que ele ataque você.",
		["Forever teaches {spell:2842} through this chain, not the trainer; the {item:7676} recipe comes with it."] = "O Forever ensina {spell:2842} por esta série, não pelo instrutor; a receita de {item:7676} vem junto.",
		["Stay stealthed. {npc:7287} carries the tower key; Gallywix (elite) and his lockbox are at the top of the tower. Kill two each of the drones, patrollers and lookouts around it."] = "Fique furtivo. {npc:7287} leva a chave da torre; Gallywix (elite) e o cofre dele ficam no alto da torre. Mate dois de cada: peões, patrulheiros e vigias em volta dela.",
		["Take the zeppelin from {zone:1454} to the {zone:1458} and ride south through {zone:1421} to {area:272} in {area:287}. {npc:2391} stands in {area:272}; wait beside him while he brews the cure."] = "Pegue o zepelim de {zone:1454} até {zone:1458} e cavalgue para o sul por {zone:1421} até {area:272}, em {area:287}. {npc:2391} fica em {area:272}; espere ao lado dele enquanto ele prepara a cura.",
		["Wait for the cure"] = "Espere pela cura",
		["{item:8051}, twice, in sight of the tower"] = "{item:8051}, duas vezes, à vista da torre",
		["{item:8074}: {npc:7288} (elite)"] = "{item:8074}: {npc:7288} (elite)",
		["{quest:2458}: keep the {item:8051}"] = "{quest:2458}: guarde a {item:8051}",
		["{spell:2842} (Horde)"] = "{spell:2842} (Horda)",
} end)()
t.guides["forever/class/rogue/ravenholdt"] = (function() return {
		["At 24 an {item:17126} from {npc:13936} starts this; the data gives it to you through {npc:332} or {npc:918} in {zone:1453}, or Gest or Ormok in {zone:1454}. The quest hands you the {item:17125} for {npc:6707}."] = "No nível 24, uma {item:17126} de {npc:13936} inicia isto; os dados a entregam por {npc:332} ou {npc:918} em {zone:1453}, ou por Gest ou Ormok em {zone:1454}. A missão dá a você o {item:17125} para {npc:6707}.",
		["At 36, {npc:13085} sends you after Barton's scouting report. Barton leads a Syndicate party at {area:280}, in the east of the {zone:1416}: pick his pocket, do not kill him."] = "No nível 36, {npc:13085} manda você atrás do relatório de patrulha de Barton. Barton lidera um grupo da Camarilha em {area:280}, no leste das {zone:1416}: bata a carteira dele, não o mate.",
		["Back to {npc:13085}"] = "De volta a {npc:13085}",
		["Horde fly to {area:272}, Alliance to {area:271}. The manor hides in the hills east of {area:272}, up a path into the {zone:1416}; the Rite of Cunning is passing its way in."] = "A Horda voa para {area:272}, a Aliança para {area:271}. O solar se esconde nas colinas a leste de {area:272}, subindo uma trilha para as {zone:1416}; o Rito da Astúcia passa pelo caminho.",
		["Opens {area:3486}, the hidden rogue house in the Alterac hills, and its first jobs."] = "Abre {area:3486}, a casa secreta dos ladinos nas colinas de Alterac, e seus primeiros trabalhos.",
		["Rite of Cunning"] = "Rito da Astúcia",
		["The {item:17126}"] = "A {item:17126}",
		["{item:275482}: pickpocket Barton"] = "{item:275482}: bata a carteira de Barton",
		["{npc:13936} reputation"] = "Reputação com {npc:13936}",
		["{npc:266216} is inside {area:275}, the Syndicate fortress in eastern {area:287}, south of the manor. Quick and quiet, says {npc:13085}."] = "{npc:266216} está dentro de {area:275}, a fortaleza da Camarilha no leste de {area:287}, ao sul do solar. Rápido e silencioso, diz {npc:13085}.",
		["{npc:6766}: {quest:6701}, repeatable"] = "{npc:6766}: {quest:6701}, repetível",
} end)()
t.guides["forever/class/rogue/the-azure-key"] = (function() return {
		["Alliance fly to {area:3137}, Horde to {area:1237}. The Timbermaw Shamans in {zone:1447}'s northern hills drop the bag, about one in thirty."] = "A Aliança voa para {area:3137}, a Horda para {area:1237}. Os Xamãs Presamatos nas colinas do norte de {zone:1447} deixam cair a bolsa, cerca de um em trinta.",
		["At 50 {npc:3328} in the {object:172960} has it; so does {npc:4583} in the {zone:1458}'s {object:36073}."] = "No nível 50, {npc:3328} na {object:172960} a tem; assim como {npc:4583} no {object:36073} de {zone:1458}.",
		["At 50 {npc:918} in {zone:1453}'s {object:2100} has it; so do Syurna in {zone:1457} and {npc:5165} and Fenthwick in {zone:1455}."] = "No nível 50, {npc:918} em {object:2100} de {zone:1453} a tem; assim como Syurna em {zone:1457} e {npc:5165} e Degrauzinho em {zone:1455}.",
		["Back to Xylem"] = "De volta a Tauriel",
		["Lord Ravenholdt"] = "Lorde Ravenholdt",
		["Morphaz in the {area:1417}"] = "Morphaz no {area:1417}",
		["Morphaz, a green drake, is an elite boss deep in the {area:1417}, a level 50 dungeon: bring a group of five. The temple stands in the {area:74}; swim down to the entrance. Horde: fly to {area:75}; Alliance: fly to {area:1438} and ride on."] = "Morphaz, um draco verde, é um chefe de elite no fundo do {area:1417}, uma masmorra de nível 50: leve um grupo de cinco. O templo fica no {area:74}; nade até a entrada. Horda: voe para {area:75}; Aliança: voe para {area:1438} e siga cavalgando.",
		["Ravenholdt reputation"] = "Reputação com Ravenholdt",
		["Ravenholdt reputation and experience at 50; Forever removed the Classic item choice."] = "Reputação com Ravenholdt e experiência no nível 50; o Forever removeu a escolha de item do Classic.",
		["The Forest Oozes of southern {zone:1447} drop the fragments."] = "As Gosmas Florestais do sul de {zone:1447} deixam cair os fragmentos.",
		["{area:3486} hides in the hills east of {area:272}, up a path into the {zone:1416}. Horde fly to {area:272}, Alliance to {area:271}."] = "{area:3486} se esconde nas colinas a leste de {area:272}, subindo uma trilha para as {zone:1416}. A Horda voa para {area:272}, a Aliança para {area:271}.",
		["{item:20022}: Morphaz, inside the temple"] = "{item:20022}: Morphaz, dentro do templo",
		["{npc:6768}: no item choices in Forever"] = "{npc:6768}: sem escolha de itens no Forever",
		["{quest:8233} (Alliance)"] = "{quest:8233} (Aliança)",
		["{quest:8233} (Horde)"] = "{quest:8233} (Horda)",
} end)()
t.guides["forever/class/rogue/the-eye-of-bhossca"] = (function() return {
		["Back to the dead drop"] = "De volta ao ponto de entrega",
		["C's dead drop"] = "O ponto de entrega de C",
		["Find the Eye of Bhossca inside the {area:796}."] = "Encontre o Olho de Bhossca dentro do {area:796}.",
		["Place the eye in the {object:410369} near Pyrewood. C's payment is the second Eye of Bhossca quest at the same chest."] = "Coloque o olho no {object:410369} perto de Vilarejo Lenhardente. O pagamento de C é a segunda missão Olho de Bhossca, no mesmo baú.",
		["The monastery stands in the far north-east of {zone:1420}. Go in alone; C advises a disguise from the monastery's grounds before you enter."] = "O monastério fica no extremo nordeste de {zone:1420}. Entre sozinho; C recomenda pegar um disfarce nos arredores do monastério antes de entrar.",
		["The {area:796}"] = "{area:796}",
		["The {item:277246}, C's payment for a solo job inside the {area:796}."] = "A {item:277246}, o pagamento de C por um serviço solo dentro do {area:796}.",
		["The {object:410369} is a chest near {area:204} in southern Silverpine, just south of {area:236}. C's next note waits there once you are 25."] = "O {object:410369} é um baú perto de {area:204}, no sul da Floresta de Pinhaprata, logo ao sul de {area:236}. O próximo bilhete de C espera lá quando você tiver nível 25.",
} end)()
t.guides["forever/class/rogue/the-horn-of-xelthos"] = (function() return {
		["Back to the dead drop"] = "Volte ao esconderijo",
		["C's dead drop"] = "O esconderijo de C",
		["Go in alone. The {item:210186} gets you past the courtyard gate; the data does not say where in the keep the horn lies."] = "Entre sozinho. A {item:210186} passa pelo portão do pátio; os dados não dizem onde a trompa está no castelo.",
		["Place the horn in the {object:410369} near Pyrewood. C's payment is the second {item:210183} quest at the same chest."] = "Coloque a trompa na {object:410369} perto da vila. O pagamento de C é a segunda missão {item:210183} no mesmo baú.",
		["The {item:277210}, C's payment for a solo job inside {area:236}."] = "O {item:277210}, o pagamento de C por um serviço solo dentro do {area:236}.",
		["The {object:410369} is a chest near {area:204} in southern Silverpine, just south of {area:236}. Read C's note."] = "{object:410369} é um baú perto de {area:204}, no sul da Floresta de Pinhaprata, logo ao sul do {area:236}. Leia o bilhete de C.",
		["{item:210183}, inside {area:236}"] = "{item:210183}, dentro do {area:236}",
		["{npc:4086}, a goblin friendly to both factions, stands among the Venture Co. in the {area:461}, east Stonetalon. Horde fly to {area:460}; Alliance to {area:467}. He wants a {item:210187} before he hands over explosives: the Venture Co. Loggers around him carry them."] = "{npc:4086}, um goblin amigável às duas facções, fica entre a Empreendimentos S.A. no {area:461}, no leste da Cordilheira das Torres de Pedra. A Horda voa até o {area:460}; a Aliança, até o {area:467}. Ele quer uma {item:210187} antes de entregar explosivos: os Madeireiros da Empreendimentos S.A. em volta dele as carregam.",
} end)()
t.guides["forever/class/shaman/call-of-air-alliance"] = (function() return {
		["At 30 {npc:258098}, the shaman trainer in {zone:1455}, sends you to {npc:259023} in {zone:1417}."] = "No nível 30, {npc:258098}, o instrutor de xamãs em {zone:1455}, manda você até {npc:259023} nas {zone:1417}.",
		["The Lost Ones in the north of the {zone:1435} carry the Twisted Earth Totems."] = "Os Perdidos no norte do {zone:1435} carregam os Totens da Terra Deturpados.",
		["The Maraudine centaurs of western {zone:1443} carry the Twisted Air Totems."] = "Os centauros Maraudinos do oeste de {zone:1443} carregam os Totens do Ar Deturpados.",
		["The Mirefin murlocs of northern {zone:1445} carry the Twisted Water Totems."] = "Os murlocs Lamapina do norte de {zone:1445} carregam os Totens da Água Deturpados.",
		["The Stonevault troggs in the south of the {zone:1418} carry the Twisted Fire Totems."] = "Os troggs da Abóbada de Pedra no sul das {zone:1418} carregam os Totens do Fogo Deturpados.",
		["The steam pools"] = "As fontes de vapor",
		["The {item:5178} that lets you place air totems, then a weapon of your choice at 40."] = "O {item:5178} que permite pôr totens de ar, e depois uma arma à sua escolha no nível 40.",
		["Twisted Air Totems"] = "Totens do Ar Deturpados",
		["Twisted Earth Totems"] = "Totens da Terra Deturpados",
		["Twisted Fire Totems"] = "Totens do Fogo Deturpados",
		["Twisted Water Totems"] = "Totens da Água Deturpados",
		["{area:1717} is a dungeon at the southern edge of the {zone:1413} (the arrow points at its entrance); {npc:4421} is its last boss. Bring a group."] = "{area:1717} é uma masmorra na borda sul dos {zone:1413} (a seta aponta para a entrada); {npc:4421} é o último chefe. Leve um grupo.",
		["{item:212792}, from the {npc:216474}"] = "{item:212792}, de {npc:216474}",
		["{item:274463}, from {npc:4421}"] = "{item:274463}, de {npc:4421}",
		["{npc:259023} camps in the northern hills of {zone:1417}."] = "{npc:259023} Thunderhame acampa nas colinas do norte das {zone:1417}.",
		["{npc:259023} hands you the {item:268582}: place them at the steam pools of {zone:1441} and defeat the {npc:216474} they call. {quest:96135} is an elite quest: grouping up is advised."] = "{npc:259023} Thunderhame entrega a você os {item:268582}: ponha-os nas fontes de vapor de {zone:1441} e derrote {npc:216474} que eles invocam. {quest:96135} é uma missão de elite: é recomendado formar um grupo.",
		["{npc:259023}: your {item:5178}"] = "{npc:259023}: seu {item:5178}",
		["{npc:6176} camps in the east of {zone:1416}, north-east of {area:272}."] = "{npc:6176} acampa no leste das {zone:1416}, a nordeste de {area:272}.",
		["{npc:6176}: the {item:280696} and your weapon"] = "{npc:6176}: o {item:280696} e sua arma",
		["{quest:94789} and the Tempest's Weapons (Alliance)"] = "{quest:94789} e The Tempest's Weapons (Aliança)",
} end)()
t.guides["forever/class/shaman/call-of-air-horde"] = (function() return {
		["At 30 {npc:5892} in the {object:172957} sends you to {npc:5905} in {zone:1441}."] = "No nível 30, {npc:5892} no {object:172957} manda você a {npc:5905} em {zone:1441}.",
		["At 30 {npc:5906}, a shaman trainer in {zone:1456}, sends you to {npc:5905} in {zone:1441}."] = "No nível 30, {npc:5906}, um instrutor de xamã em {zone:1456}, manda você a {npc:5905} em {zone:1441}.",
		["Fly to {area:484}. {npc:5905} hides in a small cave in the canyon wall north-east of the post. Skyborne: your own {quest:1531} (96136) ends with her too."] = "Voe até {area:484}. {npc:5905} se esconde numa pequena caverna na parede do cânion a nordeste do posto. Nascido nos Céus: seu próprio {quest:1531} (96136) também termina com ela.",
		["The Lost Ones in the north of the {zone:1435} carry the Twisted Earth Totems."] = "Os Perdidos no norte do {zone:1435} levam os Totens da Terra Deturpados.",
		["The Maraudine centaurs of western {zone:1443} carry the Twisted Air Totems."] = "Os centauros Maraudinos do oeste de {zone:1443} levam os Totens do Ar Deturpados.",
		["The Mirefin murlocs of northern {zone:1445} carry the Twisted Water Totems."] = "Os murlocs Lamapina do norte do {zone:1445} levam os Totens da Água Deturpados.",
		["The Stonevault troggs in the south of the {zone:1418} carry the Twisted Fire Totems."] = "Os troggs da Abóbada de Pedra no sul de {zone:1418} levam os Totens do Fogo Deturpados.",
		["The steam pools"] = "As fontes de vapor",
		["The {item:5178} that lets you place air totems, then a weapon of your choice at 40."] = "O {item:5178}, que permite colocar totens de ar, e depois uma arma à sua escolha no nível 40.",
		["Twisted Air Totems"] = "Totens do Ar Deturpados",
		["Twisted Earth Totems"] = "Totens da Terra Deturpados",
		["Twisted Fire Totems"] = "Totens do Fogo Deturpados",
		["Twisted Water Totems"] = "Totens da Água Deturpados",
		["{area:1717} is a dungeon at the southern edge of the {zone:1413} (the arrow points at its entrance); {npc:4421} is its last boss. Bring a group."] = "{area:1717} é uma masmorra na borda sul de {zone:1413} (a seta aponta para a entrada); {npc:4421} é o último chefe. Leve um grupo.",
		["{item:212792}, from the {npc:216474}"] = "{item:212792}, da {npc:216474}",
		["{item:274463}, from {npc:4421}"] = "{item:274463}, de {npc:4421}",
		["{npc:4722} stands at {area:484}."] = "{npc:4722} fica em {area:484}.",
		["{npc:5905} hands you the {item:268582}: place them at the steam pools west of {area:484} and defeat the {npc:216474} they call. {quest:79366} is an elite quest: grouping up is advised."] = "{npc:5905} lhe entrega os {item:268582}: coloque-os nas fontes de vapor a oeste de {area:484} e derrote a {npc:216474} que eles chamam. {quest:79366} é uma missão de elite: é recomendado formar grupo.",
		["{npc:5905}: your {item:5178}"] = "{npc:5905}: seu {item:5178}",
		["{npc:6176} camps in the east of {zone:1416}, north-east of {area:272}."] = "{npc:6176} acampa no leste das {zone:1416}, a nordeste de {area:272}.",
		["{npc:6176}: the {item:213086} and your weapon"] = "{npc:6176}: a {item:213086} e sua arma",
		["{quest:1531} and the Tempest's Weapons (Horde)"] = "{quest:1531} e The Tempest's Weapons (Horda)",
} end)()
t.guides["forever/class/shaman/call-of-water-alliance"] = (function() return {
		["At 20 {npc:258098}, the shaman trainer in {zone:1455}, sends you to {npc:258043} in {zone:1432}."] = "No nível 20, {npc:258098}, o instrutor de xamãs em {zone:1455}, envia você a {npc:258043} em {zone:1432}.",
		["Fill the {item:265732} at the bottom of the waterfalls below {npc:258203}'s cave, where the fresh water meets the brackish."] = "Encha o {item:265732} no pé das cachoeiras abaixo da caverna de {npc:258203}, onde a água doce encontra a salobra.",
		["The blue waterskin"] = "O odre azul",
		["The brown waterskin"] = "O odre marrom",
		["The red waterskin"] = "O odre vermelho",
		["The {item:5177} that lets you place water totems, and {spell:5394} with it."] = "O {item:5177}, que permite colocar totens de água, e {spell:5394} junto.",
		["the {item:7810}, for {npc:258043}"] = "o {item:7810}, para {npc:258043}",
		["{area:71} pour out of {area:68} at the east end of Redridge. Fill the {item:265747} at their foot, where the Murloc Nightcrawlers gather."] = "{area:71} jorram de {area:68} no extremo leste de Cristarrubra. Encha o {item:265747} no pé delas, onde se reúnem os Reptantes Murloc.",
		["{area:919} lies outside {area:20}. Drink the {item:6637} there and defeat the {npc:5894} for its bracers, then place them and the {item:7811} on the {object:619896}. The {npc:5895} it calls forth gives you the {item:7813}."] = "{area:919} fica nos arredores de {area:20}. Beba a {item:6637} lá e derrote a {npc:5894} para pegar as braçadeiras; depois coloque-as junto com as {item:7811} no {object:619896}. A {npc:5895} invocada dá a você o {item:7813}.",
		["{npc:258043}'s burrow hut stands on the north-western edge of the loch, south of {area:146}."] = "A cabana-toca de {npc:258043} fica na margem noroeste do lago, ao sul de {area:146}.",
		["{npc:258043}: your {item:6637}"] = "{npc:258043}: sua {item:6637}",
		["{npc:258043}: {spell:5394} and your {item:5177}"] = "{npc:258043}: {spell:5394} e seu {item:5177}",
		["{npc:258203}'s family lives in a cave beneath the southern falls of the {zone:1437}."] = "A família de {npc:258203} mora numa caverna sob as cachoeiras do sul de {zone:1437}.",
		["{npc:258203}: take the boat from {area:150} to {area:442} (it stops in {area:271} on the way), then go south to {area:415}. Fill the {item:265772} in the lake around the town."] = "{npc:258203}: pegue o Barco de {area:150} para {area:442} (ele para em {area:271} no caminho), depois vá para o sul até {area:415}. Encha o {item:265772} no lago em volta da cidade.",
		["{npc:5895}, at the shrine"] = "{npc:5895}, no santuário",
		["{quest:94494} (Alliance)"] = "{quest:94494} (Aliança)",
} end)()
t.guides["forever/class/shaman/call-of-water-horde"] = (function() return {
		["At 20 {npc:5892} in the {object:172957} sends you to {npc:5901} in the {zone:1413}."] = "No nível 20, {npc:5892}, no {object:172957}, envia você a {npc:5901} nos {zone:1413}.",
		["At 20 {npc:5906}, a shaman trainer in {zone:1456}, sends you to {npc:5901} in the {zone:1413}."] = "No nível 20, {npc:5906}, instrutor de xamãs em {zone:1456}, envia você a {npc:5901} nos {zone:1413}.",
		["Fill the {item:7766} at the quilboar watering hole"] = "Encha o {item:7766} no bebedouro dos javaligs",
		["Fill the {item:7767} at the fountain"] = "Encha o {item:7767} na fonte",
		["Fill the {item:7768} at the {object:107045}"] = "Encha o {item:7768} em {object:107045}",
		["Fly to the {area:228}: the {object:113791} stands on the hill just south-west of it. Drink the {item:6637} there, beat the {npc:5894} for its bracers and place them in the brazier, then speak to the {npc:5895} and keep the {item:7813} for {npc:5901}."] = "Voe até {area:228}: o {object:113791} fica na colina logo a sudoeste. Beba a {item:6637} lá, derrote a {npc:5894} para pegar as braçadeiras e coloque-as no braseiro; depois fale com a {npc:5895} e guarde o {item:7813} para {npc:5901}.",
		["Take the zeppelin from {zone:1454} to {zone:1420} and travel south to {area:272}. The {object:107045} stands beside the inn."] = "Pegue o zepelim de {zone:1454} para {zone:1420} e viaje para o sul até {area:272}. {object:107045} fica ao lado da estalagem.",
		["The fountain stands in the middle of the {area:418}, in south-western {zone:1440}."] = "A fonte fica no meio das {area:418}, no sudoeste de {zone:1440}.",
		["The {item:5177} that lets you place water totems, and {spell:5394} with it."] = "O {item:5177}, que permite colocar totens de água, e com ele {spell:5394}.",
		["The {object:107045}"] = "{object:107045}",
		["The {object:113791}"] = "{object:113791}",
		["the {item:7810}, for {npc:5901}"] = "a {item:7810}, para {npc:5901}",
		["{npc:5899}'s hut stands on the ridge above the quilboar watering hole, south of {area:378}."] = "A cabana de {npc:5899} fica na crista acima do bebedouro dos javaligs, ao sul do {area:378}.",
		["{npc:5901} waits on the hill south of {area:392}."] = "{npc:5901} espera na colina ao sul de {area:392}.",
		["{npc:5901}: your {item:6637}"] = "{npc:5901}: sua {item:6637}",
		["{npc:5901}: {spell:5394} and your {item:5177}"] = "{npc:5901}: {spell:5394} e seu {item:5177}",
		["{quest:63} (Horde)"] = "{quest:63} (Horda)",
} end)()
t.guides["forever/class/shaman/darkreaver"] = (function() return {
		["200 Horde reputation"] = "200 de reputação com a Horda",
		["A {area:2057} fight at 60 for Horde reputation; Forever removed the {item:20134}."] = "Uma luta em {area:2057} no nível 60 por reputação com a Horda; o Forever removeu o {item:20134}.",
		["An {item:12800} comes from Thorium veins, a {item:18335} from the elites of the {zone:1422}, both rarely: buy them at the auction house if you can."] = "Um {item:12800} vem de veios de tório, um {item:18335} dos elites das {zone:1422}, ambos raramente: compre-os na casa de leilões se puder.",
		["At 58 {npc:13417}, the shaman trainer in the {object:172957}, asks for two rare diamonds."] = "No nível 58, {npc:13417}, o instrutor de xamã no {object:172957}, pede dois diamantes raros.",
		["Two diamonds"] = "Dois diamantes",
		["he hands you the {item:18746}"] = "ele lhe entrega o {item:18746}",
		["{area:2057} lies under {area:2298}, the island town in the south-east of the {zone:1422}. Use the {item:18746} in the heart of the {object:179746}'s basement, beat the spirits it calls, then {npc:14516}. All are elite: bring a group."] = "{area:2057} fica embaixo de {area:2298}, a cidade na ilha do sudeste das {zone:1422}. Use o {item:18746} no centro do porão do Grande Ossuário, derrote os espíritos que ele chama e depois {npc:14516}. Todos são elite: leve um grupo.",
		["{quest:7668} needs level 60."] = "{quest:7668} requer nível 60.",
} end)()
t.guides["forever/class/shaman/spirit-totem"] = (function() return {
		["At 50 {npc:13417}, the shaman trainer in the {object:172957}, sends you to {npc:6176}."] = "No nível 50, {npc:13417}, o instrutor de xamãs no {object:172957}, envia você a {npc:6176}.",
		["At 50 {npc:3032}, a shaman trainer in {zone:1456}, sends you to {npc:6176}."] = "No nível 50, {npc:3032}, instrutor de xamãs em {zone:1456}, envia você a {npc:6176}.",
		["Experience and gold"] = "Experiência e ouro",
		["Experience and gold at 50, ending in the {area:1417}; Forever removed the Classic item choice."] = "Experiência e ouro no nível 50, terminando no {area:1417}; o Forever removeu o item à escolha do Classic.",
		["In the {zone:1422}, the Venom Mist Lurkers drop the {item:20610} and the Diseased Black Bears the {item:20611} (about one kill in five each)."] = "Nas {zone:1422}, as Tocaieiras Rasterruças soltam o {item:20610} e os Ursos Pretos Doentes a {item:20611} (cerca de uma morte em cinco, cada).",
		["One each of {item:7069}, Fire, Earth and Water. The Exiles of Arathi Highlands drop them, one element each, about one kill in ten: Thundering (air), Burning (fire), Rumbling (earth) and Cresting (water). Or buy them at the auction house."] = "Um de cada: {item:7069}, Fogo, Terra e Água Elemental. Os Exilados do Planalto Arathi os soltam, um elemento cada, em cerca de uma morte em dez: Trovejantes (ar), em Chamas (fogo), Tonitruantes (terra) e Vagalhantes (água). Ou compre na Casa de Leilões.",
		["Spider eye and bear claw"] = "Olho de aranha e garra de urso",
		["The four elements"] = "Os quatro elementos",
		["The {area:1417}"] = "{area:1417}",
		["The {area:1417} ({area:1477}) lies under the {area:74}; the arrow points at its entrance. Gasher or {npc:5716} drop the {item:20606}, Hukku or Mijan the Blue, Zolo or Loro the Green: all six are elite trolls inside. Bring a group."] = "O {area:1417} ({area:1477}) fica sob o {area:74}; a seta aponta para a entrada. Talho ou {npc:5716} soltam a {item:20606}, Hukkah ou Mirran a azul, Zolo ou Lorro a verde: os seis são trolls elite lá dentro. Leve um grupo.",
		["{item:7067}: Rumbling Exiles"] = "{item:7067}: Exilados Tonitruantes",
		["{item:7068}: Burning Exiles"] = "{item:7068}: Exilados em Chamas",
		["{item:7069}: Thundering Exiles"] = "{item:7069}: Exilados Trovejantes",
		["{item:7070}: Cresting Exiles"] = "{item:7070}: Exilados Vagalhantes",
		["{npc:6176} camps in the east of {zone:1416}, north-east of {area:272}."] = "{npc:6176} acampa no leste de {zone:1416}, a nordeste de {area:272}.",
		["{quest:8412} and {quest:8413}"] = "{quest:8412} e {quest:8413}",
} end)()
t.guides["forever/class/warlock/enchanted-gold-bloodrobe"] = (function() return {
		["A rare cloth robe for your 30s, which {npc:6266} makes from the parts you bring her."] = "Um manto de tecido raro para seus 30 e poucos, que {npc:6266} faz com as partes que você trouxer.",
		["At 31 {npc:3326} in the {object:172960} sends you to {npc:6266} in {area:392}."] = "No nível 31, {npc:3326} na {object:172960} manda você até {npc:6266} em {area:392}.",
		["At 31 {npc:4563} in the {object:36082} sends you to {npc:6266} in {area:392}. The zeppelin from {zone:1420} flies to {zone:1411}."] = "No nível 31, {npc:4563} no {object:36082} manda você até {npc:6266} em {area:392}. O zepelim de {zone:1420} voa para {zone:1411}.",
		["At 31 {npc:461} in the {object:2164}, in the {object:2101}, sends you to {npc:6266} in {area:392}."] = "No nível 31, {npc:461} no {object:2164}, no {object:2101}, manda você até {npc:6266} em {area:392}.",
		["At 31 {npc:5172} in {zone:1455} sends you to {npc:6266} in {area:392}."] = "No nível 31, {npc:5172} em {zone:1455} manda você até {npc:6266} em {area:392}.",
		["Back to {npc:6266}"] = "De volta a {npc:6266}",
		["Back to {npc:6266} with the thread, the coal and a {item:6265}. Wait while she completes the robe, then speak to her again."] = "De volta a {npc:6266} com a linha, o carvão e um {item:6265}. Espere enquanto ela termina o manto, depois fale com ela de novo.",
		["Bring {npc:6266} a {item:5770}: tailors sew it from a pattern that drops; otherwise buy one at the Auction House. Her next errand needs a {item:3577}: smelted from {item:2776}, or from the Auction House."] = "Leve a {npc:6266} um {item:5770}: alfaiates o costuram com um molde que cai; senão, compre um na Casa de Leilões. A tarefa seguinte dela exige uma {item:3577}: fundida de {item:2776}, ou da Casa de Leilões.",
		["The Burning Exiles, fire elementals in western {zone:1417}, drop the coal."] = "Os Exilados em Chamas, elementais do fogo no oeste das {zone:1417}, deixam cair o carvão.",
		["The Hatefury satyrs of {area:603}, in north-eastern {zone:1443}, carry the blood; the Lesser Infernals of Mannoroc Coven, in the south, the stone."] = "Os sátiros Furiódio de {area:603}, no nordeste de {zone:1443}, carregam o sangue; os Infernais Menores da Ruínas de Mannoroc, no sul, a pedra.",
		["Vials of Hatefury Blood"] = "Ampolas de Sangue de Furiódio",
		["Wait for the robe"] = "Espere o manto",
		["{npc:2670} in {area:35} has the thread for you."] = "{npc:2670} em {area:35} tem a linha para você.",
		["{npc:2670} sells tailoring supplies in {area:35}. Bring him the {item:3577}."] = "{npc:2670} vende suprimentos de alfaiataria em {area:35}. Leve a ele a {item:3577}.",
		["{npc:6266} again"] = "{npc:6266} de novo",
		["{npc:6266} stands in the tower on the hill above {area:392}, beside {npc:6251}."] = "{npc:6266} fica na torre da colina acima de {area:392}, ao lado de {npc:6251}.",
		["{zone:1443} demons"] = "Demônios de {zone:1443}",
} end)()
