} end)()
t.guides["forever/collectibles/pets/black-tabby"] = (function() return {
		["The {npc:1920}, a rare spawn among the mages at {area:233} in southern {zone:1421}, drops it about 17% of the time in our data; the other {area:279} mages at {area:233} and around the {area:279} crater drop it at about 0.2%. Kill the mages until the Spellscribe appears. Alliance players buy it on the Auction House."] = "O {npc:1920}, um raro entre os magos de {area:233} no sul de {zone:1421}, o deixa cair em cerca de 17% das vezes nos nossos dados; os outros magos de {area:279} em {area:233} e em volta da cratera de {area:279} o deixam cair em cerca de 0,2%. Mate os magos até o Escriba aparecer. Jogadores da Aliança o compram na Casa de Leilões.",
} end)()
t.guides["forever/collectibles/pets/chicken-egg"] = (function() return {
		["Find a chicken at {npc:233}'s farm and type /chicken at it until it offers {quest:3861}. Buy {item:11109} from {npc:233}, go back, /cheer at the same chicken, then hand in the feed. The chicken lays an egg: loot it for your {item:11110} pet."] = "Encontre uma galinha na fazenda de {npc:233} e digite /chicken para ela até que ofereça {quest:3861}. Compre {item:11109} de {npc:233}, volte, use /cheer na mesma galinha e entregue a ração. A galinha bota um ovo: saqueie-o para obter seu mascote {item:11110}.",
		["Loot the {object:161513} the chicken lays"] = "Saqueie o {object:161513} que a galinha botar",
		["{item:11109}, from {npc:233}"] = "{item:11109}, de {npc:233}",
} end)()
t.guides["forever/collectibles/pets/condor-hatchling"] = (function() return {
		["{npc:14268} is a rare level 15-16 condor in south-eastern {zone:1432}; early kill counts give about 0.2% per kill, so expect many respawns."] = "{npc:14268} é um condor raro de nível 15-16 no sudeste de {zone:1432}; as primeiras contagens de abates dão cerca de 0,2% por abate, então espere muitos reaparecimentos.",
} end)()
t.guides["forever/collectibles/pets/dark-whelpling"] = (function() return {
		["Black whelps"] = "Dragonetes negros",
		["The Searing Whelps of the {area:511} in southern {zone:1445} (level 42) and the Scalding Whelps of eastern {zone:1418} (level 41) drop it about once in 900 kills in our data. The waypoint is the {area:511}; the {zone:1418} whelps are the same grind."] = "Os Dragonetes Carbonizantes do {area:511} no sul de {zone:1445} (nível 42) e os Dragonetes Escaldantes do leste das {zone:1418} (nível 41) o deixam cair cerca de uma vez em 900 abates em nossos dados. O ponto de rota é o {area:511}; os dragonetes das {zone:1418} são o mesmo farm.",
		["The {area:511}"] = "O {area:511}",
} end)()
t.guides["forever/collectibles/pets/disgusting-oozeling"] = (function() return {
		["Oozes drop the {item:20768}: the Vile Slimes, Large Vile Slimes and Devouring Oozes of Western Plaguelands, and the oozes of {zone:1448}, {zone:1449} and {zone:1423}, at about 0.07-0.09% per kill in our data. The waypoint is a {npc:1806} spawn in eastern {zone:1422}."] = "Gosmas derrubam a {item:20768}: os Visgos Torpes, Visgos Torpes Enormes e Gosmas Devoradoras das Terras Pestilentas Ocidentais, e as gosmas de {zone:1448}, {zone:1449} e {zone:1423}, com cerca de 0,07-0,09% por abate em nossos dados. O ponto de rota é um local de surgimento de {npc:1806} no leste de {zone:1422}.",
		["Open the {item:20768}"] = "Abra a {item:20768}",
		["Open the {item:20768} from your bags."] = "Abra a {item:20768} das suas bolsas.",
		["Vile Slimes, {zone:1422}"] = "Visgos Torpes, {zone:1422}",
} end)()
