		["{spell:3852} to 150"] = "{spell:3852} até 150",
} end)()
t.guides["forever/reputation/alterac-valley"] = (function() return {
		["Alterac Valley Reputation"] = "Reputação: Vale Alterac",
		["Exalted with the {faction:729} earns a Legacy Point."] = "Exaltado com {faction:729} rende um Ponto de Legado.",
		["Exalted with the {faction:730} earns a Legacy Point."] = "Exaltado com {faction:730} rende um Ponto de Legado.",
		["Full games that kill {npc:11946} after the towers fall pay the most."] = "Partidas completas que matam {npc:11946} depois da queda das torres dão mais.",
		["Full games that kill {npc:11948} after the towers fall pay the most."] = "Partidas completas que matam {npc:11948} depois da queda das torres dão mais.",
		["Keep winning {zone:1459}. More Booty! ({npc:13176}), {item:17306} for {npc:13236} (it summons {npc:13256}) and Alterac Ram Hides for the {npc:13441} all repeat."] = "Continue vencendo em {zone:1459}. Mais espólios! ({npc:13176}), {item:17306} para {npc:13236} (invoca {npc:13256}) e Pelegos de Carneiro de Alterac para o {npc:13441} são todas repetíveis.",
		["Keep winning {zone:1459}. More {quest:7223} ({npc:13257}), Storm Crystals for {npc:13442} (they summon {npc:13419}) and Frostwolf Hides for the {npc:13577} all repeat."] = "Continue vencendo em {zone:1459}. Mais {quest:7223} ({npc:13257}), Cristais de Tempestade para {npc:13442} (eles invocam {npc:13419}) e Pelegos dos Lobo do Gelo para {npc:13577} são todas repetíveis.",
		["The {faction:729} holds {area:2978} in the south of {zone:1459}. Destroying towers, taking graveyards and mines, and killing captains and generals all pay reputation to the whole team. Loot {item:17422} from fallen enemies for {npc:13176}. Forever's Legacy Diplomat perk increases reputation gains."] = "{faction:729} ocupa {area:2978}, no sul de {zone:1459}. Destruir torres, tomar cemitérios e minas e matar capitães e generais dão reputação ao time inteiro. Saqueie {item:17422} dos inimigos caídos para {npc:13176}. A vantagem de Legado Diplomata do Forever aumenta os ganhos de reputação.",
		["The {faction:730} holds {area:2959} in the north of {zone:1459}. Destroying towers, taking graveyards and mines, and killing captains and generals all pay reputation to the whole team. Loot {quest:7223} from fallen enemies for {npc:13257}. Forever's Legacy Diplomat perk increases reputation gains."] = "{faction:730} ocupa {area:2959}, no norte de {zone:1459}. Destruir torres, tomar cemitérios e minas e matar capitães e generais dão reputação ao time inteiro. Saqueie {quest:7223} dos inimigos caídos para {npc:13257}. A vantagem de Legado Diplomata do Forever aumenta os ganhos de reputação.",
		["{faction:729} to Exalted"] = "{faction:729} até Exaltado",
		["{faction:729} to Friendly"] = "{faction:729} até Respeitado",
		["{faction:729} to Honored"] = "{faction:729} até Honrado",
		["{faction:729} to Revered"] = "{faction:729} até Reverenciado",
		["{faction:730} to Exalted"] = "{faction:730} até Exaltado",
		["{faction:730} to Friendly"] = "{faction:730} até Respeitado",
		["{faction:730} to Honored"] = "{faction:730} até Honrado",
		["{faction:730} to Revered"] = "{faction:730} até Reverenciado",
		["{npc:12096}: Irondeep and {item:17542} from the mines"] = "{npc:12096}: Suprimentos dos Ferrofundo e {item:17542} das minas",
		["{npc:12097}: Coldtooth and {item:17522} from the mines"] = "{npc:12097}: Suprimentos de Dentefrio e {item:17522} das minas",
		["{npc:13176}: More Booty!"] = "{npc:13176}: Mais espólios!",
		["{npc:13236}: A Gallon of Blood"] = "{npc:13236}: Um galão de sangue",
		["{npc:13257}: More {quest:7223}"] = "{npc:13257}: Mais {quest:7223}",
		["{npc:13442}: Crystal Cluster"] = "{npc:13442}: Drusa de Cristal",
} end)()
t.guides["forever/reputation/arathi-basin"] = (function() return {
		["Arathi Basin Reputation"] = "Reputação: Bacia Arathi",
		["Exalted with the League of Arathor earns a Legacy Point."] = "Exaltado com A Liga de Arathor rende um Ponto de Legado.",
		["Exalted with {faction:510} earns a Legacy Point."] = "Exaltado com {faction:510} rende um Ponto de Legado.",
		["Keep playing {zone:1461}. On Call to Arms: {zone:1461} weekends the {npc:15350} in the capitals takes three Arathi Basin Marks of Honor for extra reputation."] = "Continue jogando {zone:1461}. Nos fins de semana de Chamado às Armas: {zone:1461}, o {npc:15350} nas capitais aceita três Marcas de Honra da Bacia Arathi por reputação extra.",
		["Keep playing {zone:1461}. On Call to Arms: {zone:1461} weekends the {npc:15351} in the capitals takes three Arathi Basin Marks of Honor for extra reputation."] = "Continue jogando {zone:1461}. Nos fins de semana de Chamado às Armas: {zone:1461}, o {npc:15351} nas capitais aceita três Marcas de Honra da Bacia Arathi por reputação extra.",
		["Keep playing {zone:1461}; wins with many bases held pay the most."] = "Continue jogando {zone:1461}; vitórias com muitas bases dominadas dão mais.",
		["League of Arathor to Exalted"] = "A Liga de Arathor até Exaltado",
		["League of Arathor to Friendly"] = "A Liga de Arathor até Respeitado",
		["League of Arathor to Honored"] = "A Liga de Arathor até Honrado",
		["League of Arathor to Revered"] = "A Liga de Arathor até Reverenciado",
		["{faction:509} fights for {zone:1461} from {area:320}. Their reputation comes from the battleground: the resources your team gathers pay it to everyone, so holding more bases for longer pays more. Queue at any battlemaster. Forever's Legacy Diplomat perk increases reputation gains."] = "{faction:509} luta por {zone:1461} a partir de {area:320}. A reputação vem do campo de batalha: os recursos que seu time junta dão reputação a todos, então manter mais bases por mais tempo dá mais. Entre na fila com qualquer mestre de batalha. A vantagem de Legado Diplomata do Forever aumenta os ganhos de reputação.",
		["{faction:510} fight for {zone:1461} from {area:321}. Their reputation comes from the battleground: the resources your team gathers pay it to everyone, so holding more bases for longer pays more. Queue at any battlemaster. Forever's Legacy Diplomat perk increases reputation gains."] = "{faction:510} lutam por {zone:1461} a partir de {area:321}. A reputação vem do campo de batalha: os recursos que seu time junta dão reputação a todos, então manter mais bases por mais tempo dá mais. Entre na fila com qualquer mestre de batalha. A vantagem de Legado Diplomata do Forever aumenta os ganhos de reputação.",
		["{faction:510} to Exalted"] = "{faction:510} até Exaltado",
		["{faction:510} to Friendly"] = "{faction:510} até Respeitado",
		["{faction:510} to Honored"] = "{faction:510} até Honrado",
		["{faction:510} to Revered"] = "{faction:510} até Reverenciado",
		["{npc:14983}'s The Battle for {zone:1461}! (assault every base) and Control Four Bases / Control Five Bases are one-time quests; {npc:14984} beside him takes Arathi Resource Crates."] = "A Batalha pela {zone:1461}! (ataque todas as bases) e Controlar quatro bases / Controlar cinco bases, de {npc:14983}, são missões únicas; {npc:14984}, ao lado dele, aceita Caixas de Recursos Arathi.",
		["{npc:15021}'s The Battle for {zone:1461}! (assault every base) and Take Four Bases / Take Five Bases are one-time quests; {npc:15022} beside him takes Arathi Resource Crates."] = "A batalha pela {zone:1461}! (ataque todas as bases) e Tome quatro bases / Tome cinco bases, de {npc:15021}, são missões únicas; {npc:15022}, ao lado dele, aceita Caixas de Recursos Arathi.",
		["{npc:15126} hands out one Defiler's care package by level"] = "{npc:15126} entrega um Kit de Sobrevivência do Profanador por nível",
		["{npc:15127} hands out one Arathor care package by level"] = "{npc:15127} entrega um Kit de Sobrevivência de Arathor por nível",
} end)()
t.guides["forever/reputation/argent-dawn"] = (function() return {
		["Argent Dawn Reputation"] = "Reputação: Aurora Argêntea",
		["Corruptor's Scourgestones and dungeons to Revered"] = "Pedras do Flagelo do Corruptor e masmorras até Reverenciado",
		["Dark Adepts and Shadowmages (level 58-60) drop Invader's Scourgestones here, along with Minion's stones and {item:14047}. Hand Invader's in 10 at a time and Minion's 20 at a time to {npc:11039} at {area:2268}. In Classic both stop giving reputation at Honored."] = "Adeptos das Trevas e Umbramantes (nível 58-60) deixam cair Pedras do Flagelo do Invasor aqui, além das do Lacaio e {item:14047}. Entregue as do Invasor de 10 em 10 e as do Lacaio de 20 em 20 a {npc:11039} em {area:2268}. No Classic, as duas param de dar reputação em Honrado.",
		["From Honored on, Corruptor's Scourgestones (one per turn-in) and Scourge kills in {area:2279} and {area:2057} carry the reputation. Corruptor's stones drop from the Scourge bosses there ({npc:1853}, {npc:10433}, Vectus) and from {npc:1852} and Putridius in {zone:1422}. Many dungeon runs pay off faster than any open-world farm."] = "A partir de Honrado, Pedras do Flagelo do Corruptor (uma por entrega) e mortes de Flagelo em {area:2279} e {area:2057} rendem a reputação. As do Corruptor caem dos chefes do Flagelo de lá ({npc:1853}, {npc:10433}, Vectus) e de {npc:1852} e Putrídius em {zone:1422}. Várias incursões em masmorras rendem mais rápido do que qualquer caçada em mundo aberto.",
		["Ghouls and skeletons all over {zone:1422} drop Minion's Scourgestones about half the time; this cluster is dense. Hand them in 20 at a time to any Argent Officer (Pureheart at {area:3197}, Garush at {area:152}, {npc:11039} at {area:2268}). Each turn-in also pays an {item:12844} for the Argent quartermasters."] = "Carniçais e esqueletos por todas as {zone:1422} deixam cair Pedras do Flagelo do Lacaio cerca de metade das vezes; este agrupamento é denso. Entregue-as de 20 em 20 a qualquer Oficial Argênteo (Cândida em {area:3197}, Garush em {area:152}, {npc:11039} em {area:2268}). Cada entrega também rende um {item:12844} para os intendentes da Aurora Argêntea.",
		["Invader's Scourgestones to Honored"] = "Pedras do Flagelo do Invasor até Honrado",
		["Keep running {area:2279} and {area:2057} and turning in every {item:12843} at {area:2268} until Exalted."] = "Continue fazendo {area:2279} e {area:2057} e entregando cada {item:12843} em {area:2268} até Exaltado.",
		["Minion's Scourgestones to Friendly"] = "Pedras do Flagelo do Lacaio até Amistoso",
		["Run {area:2279} (both wings) and {area:2057}, killing every Scourge you pass."] = "Faça {area:2279} (as duas alas) e {area:2057}, matando todo Flagelo pelo caminho.",
		["{faction:529} to Exalted"] = "{faction:529} até Exaltado",
		["{object:2160} starts out Neutral. Take the Commission from {npc:10839} at {area:152} and wear it: in Classic, Scourgestones only drop while the {quest:5401} trinket is equipped. Forever's Legacy Diplomat perk increases reputation gains."] = "{object:2160} começa em Neutro. Pegue a Ordem com {npc:10839} em {area:152} e equipe-a: no Classic, Pedras do Flagelo só caem enquanto o berloque {quest:5401} estiver equipado. A vantagem de Legado Diplomata do Forever aumenta os ganhos de reputação.",
		["{object:2160} starts out Neutral. Take the Commission from {npc:10840} at {area:3197} and wear it: in Classic, Scourgestones only drop while the {quest:5401} trinket is equipped. Forever's Legacy Diplomat perk increases reputation gains."] = "{object:2160} começa em Neutro. Pegue a Ordem com {npc:10840} em {area:3197} e equipe-a: no Classic, Pedras do Flagelo só caem enquanto o berloque {quest:5401} estiver equipado. A vantagem de Legado Diplomata do Forever aumenta os ganhos de reputação.",
		["{quest:5401} (Alliance)"] = "{quest:5401} (Aliança)",
		["{quest:5401} (Horde)"] = "{quest:5401} (Horda)",
} end)()
t.guides["forever/reputation/cenarion-circle"] = (function() return {
		["Abyssal Crests, Abyssal Signets and Abyssal Scepters are repeatable at {npc:15306} once their opening quests are done."] = "Escudos Abissais, Sinetes Abissais e Cetros Abissais podem ser entregues repetidamente a {npc:15306} depois de concluídas as missões iniciais.",
		["Back to {area:3425}"] = "De volta a {area:3425}",
		["Cenarion Circle Reputation"] = "Reputação: Círculo Cenariano",
		["Encrypted Twilight Texts repeats: {npc:15306} takes more texts again and again. The cultist camps are the place to farm them."] = "Textos Codificados do Crepúsculo se repete: {npc:15306} aceita mais textos repetidamente. Os acampamentos dos sectários são o lugar para coletá-los.",
		["Encrypted Twilight Texts to Friendly"] = "Textos Codificados do Crepúsculo até Amigável",
		["From here on, the {area:3454} raid and the Abyssal Council turn-ins (crests, signets, scepters) carry most of the reputation."] = "Daqui em diante, a raide {area:3454} e as entregas do Conselho Abissal (escudos, sinetes, cetros) rendem a maior parte da reputação.",
		["Keep farming the Twilight camps. Wearing the Twilight Trappings (the Twilight cultist set plus a Medallion of Station, from {npc:15282}'s Medallion of Station quest) lets you summon Abyssal Templars at the Wind Stones; their Abyssal Crests go to {npc:15306}."] = "Continue caçando nos acampamentos do Crepúsculo. Vestindo o conjunto de Sectário do Crepúsculo (Capucho, Dragonas e Veste de Sectário do Crepúsculo, mais o Medalhão de Posto do Sectário do Crepúsculo, da missão O medalhão de posto de {npc:15282}), você pode invocar templários abissais nas Wind Stones; os Escudos Abissais deles vão para {npc:15306}.",
		["Keep running the {area:3454} and turning in Abyssal Council insignia until Exalted."] = "Continue fazendo {area:3454} e entregando insígnias do Conselho Abissal até Exaltado.",
		["Twilight's Hammer cultists hold the camps in western {zone:1451}. {quest:8320} and Stonecallers mix here; any cultist can drop an {item:20404}. Every cultist kill also counts toward the {faction:609}. The Geolords count for {quest:8320} only if you are 60 and took it."] = "Sectários do Martelo do Crepúsculo dominam os acampamentos no oeste de {zone:1451}. {quest:8320} e Petrazes do Crepúsculo se misturam aqui; qualquer sectário pode derrubar um {item:20404}. Cada sectário morto também conta para {faction:609}. Os Geolordes do Crepúsculo só contam para {quest:8320} se você tiver nível 60 e tiver aceitado a missão.",
		["{area:3425} is the walled town in north-central {zone:1451}. Bor and {npc:15270} stand together inside. The {faction:609} starts out Neutral. Forever's Legacy Diplomat perk increases reputation gains."] = "{area:3425} é a cidade murada no centro-norte de {zone:1451}. Bor e {npc:15270} ficam juntos lá dentro. {faction:609} começa em Neutro. A vantagem de Legado Diplomata do Forever aumenta os ganhos de reputação.",
		["{faction:609} to Exalted"] = "{faction:609} até Exaltado",
		["{faction:609} to Honored"] = "{faction:609} até Honrado",
		["{faction:609} to Revered"] = "{faction:609} até Reverenciado",
		["{npc:15306}: Encrypted Twilight Texts"] = "{npc:15306}: Textos Codificados do Crepúsculo",
		["{quest:8320} needs level 60"] = "{quest:8320} exige nível 60",
} end)()
t.guides["forever/reputation/darkspear-trolls"] = (function() return {
		["Dark Adepts and Shadowmages (level 58-60) drop it here; every Scourge kill here also counts toward the {object:92525} (see that guide). The Auction House works too."] = "Adeptos das Trevas e Umbramantes (nível 58-60) deixam cair aqui; cada Flagelo morto aqui também conta para {object:92525} (veja esse guia). A Casa de Leilões também serve.",
		["Darkspear Trolls Reputation"] = "Reputação: Trolls Lançanegra",
		["Dunemaul ogres (level 45-48) drop it here. The Auction House works too."] = "Ogros Dunamalho (nível 45-48) deixam cair aqui. A Casa de Leilões também serve.",
		["Keep handing in {quest:7837} until {faction:530} is Exalted. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "Continue entregando {quest:7837} até ficar Exaltado com {faction:530}. {item:14047}: Adeptos das Trevas e Umbramantes (nível 58-60) em {zone:1423}, ou a Casa de Leilões.",
		["Keep handing in {quest:7837}, 20 {item:14047} at a time. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "Continue entregando {quest:7837}, 20 {item:14047} por vez. {item:14047}: Adeptos das Trevas e Umbramantes (nível 58-60) em {zone:1423}, ou a Casa de Leilões.",
		["Kolkar centaur (level 30-33) drop it here. The Auction House works too."] = "Centauros Kolkar (nível 30-33) deixam cair aqui. A Casa de Leilões também serve.",
		["Venture Co. Enforcers at the {area:381} (level 16-17) drop it here. The Auction House works too."] = "Seguranças da Empreendimentos S.A. em {area:381} (nível 16-17) deixam cair aqui. A Casa de Leilões também serve.",
		["{npc:14727} takes cloth for {faction:530} in the {object:172961}, {zone:1454}. The first donations of Wool, Silk, Mageweave and {item:14047} (60 cloth each) are done once and give the most reputation per cloth; after them, {quest:7837} repeats until Exalted. Exalted with another race's city lets you buy that race's mounts. Forever's Legacy Diplomat perk increases reputation gains."] = "{npc:14727} recebe tecido para {faction:530} em {object:172961}, {zone:1454}. As primeiras doações de Lã, Seda, Magitrama e {item:14047} (60 tecidos cada) são feitas uma vez só e dão mais reputação por tecido; depois delas, {quest:7837} se repete até Exaltado. Exaltado com a cidade de outra raça permite comprar as montarias dessa raça. A vantagem de Legado Diplomata do Forever aumenta os ganhos de reputação.",
		["{npc:14727}: {item:14047} delivered"] = "{npc:14727}: {item:14047} entregue",
		["{quest:7837} takes 20 {item:14047} per turn-in and repeats as often as you like. Bring {item:14047} in multiples of 20 and hand them all in at once, one turn-in after another. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "{quest:7837} pede 20 {item:14047} por entrega e se repete quantas vezes quiser. Traga {item:14047} em múltiplos de 20 e entregue tudo de uma vez, uma entrega após a outra. {item:14047}: Adeptos das Trevas e Umbramantes (nível 58-60) em {zone:1423}, ou a Casa de Leilões.",
		["{quest:7837} to Exalted"] = "{quest:7837} até Exaltado",
		["{quest:7837} to Honored"] = "{quest:7837} até Honrado",
		["{quest:7837} to Revered"] = "{quest:7837} até Reverenciado",
} end)()
